pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Gaps that can't even fit the smallest plausible next item are waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward a perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residual is already small relative to the mean.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (1.0 + progress);
    score += open_pressure * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins whose leftover deviates badly
    // from the fleet mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when this item would leave
    // a large dead gap in every existing bin.
    if bin_residual == bin_capacity {
        score = 45.0 - (item_size as f64);
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.35 * (progress - 0.5) * (progress - 0.5));

    // Non-linear coupling: squared normalized post-residual penalizes dead space,
    // weighted by stream progress (dead space matters more later)
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: very small residuals (tight fits) get a bonus via negative coupling
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Interaction with mean residual: prefer bins whose residual deviates favorably
    score += 0.25 * (mean_residual - pr) * (0.5 + progress);

    // Lookahead coupling: if next item fits in post residual, reward (smooth quadratic)
    if next_item_size > 0 {
        let fits_next = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
        let slack = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 9.0 * fits_next * slack * slack * (0.6 + 0.6 * progress);
        // Penalize blocking a large next item with near-full bin
        score += 5.0 * (1.0 - fits_next) * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus: smooth inverse coupling with fitting bins count
    if fitting_bins_count <= 1 {
        score -= 7.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr * cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.35 * (progress - 0.5) * (progress - 0.5));

    // Strong rewards for near-perfect fits (borrowed waste-minimization idea)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Non-linear coupling: squared normalized post-residual penalizes dead space
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: tight fits get a bonus
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Interaction with mean residual
    score += 0.25 * (mean_residual - pr) * (0.5 + progress);

    // Two-step lookahead: reward bins whose post residual chains the next item well
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let slack = pr - next_item_size as f64;
        if slack == 0.0 {
            score -= 45.0; // perfect 2-step chain
        } else if slack <= 10.0 {
            score -= 20.0;
        } else {
            let slackn = 1.0 - slack / cap;
            score -= 9.0 * slackn * slackn * (0.6 + 0.6 * progress);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize overshoot unless residual is dead space
        let overshoot = (next_item_size as f64 - pr).max(0.0);
        if pr > 15.0 {
            score += 0.5 * overshoot;
        }
        score += 5.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr * cap * (1.0 - progress);

    // New-bin candidate handling: reluctant by default, attractive when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress; // base reluctance, stronger late in stream
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (next_item_size > 0 && next_item_size as f64 > pr && pr > 30.0);
            if poor_fit {
                score -= 35.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of common
    // item sizes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residue, dead-space risk
    };
    score += harmonic_bonus;

    // Small post residuals are excellent (tight fit), but only if not zero-waste
    // blocking the next item. Dead zone: post_residual in (0..10) is fragile.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item almost fits but not quite, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= (20.0 - slack.min(20) as f64) * 0.5;
        } else {
            let over = next_item_size - pr;
            if over <= 10 {
                score += over as f64 * 1.5; // just-missed fit wastes this bin
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or current open bins are congested; otherwise
    // discourage opening new bins.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let congestion = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
        score += 45.0
            - fill_frac * 70.0
            - congestion * 5.0
            - (fitting_bins_count as f64) * 2.0;
        // Large items start fresh bins happily; small items should reuse.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Progress-based mild pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    // Penalize leaving residual far from mean (fragmentation spread).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.25 * (progress - 0.5) * (progress - 0.5));

    // Strong rewards for near-perfect fits (extended tier from best heuristic)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 14.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Non-linear coupling: squared normalized post-residual penalizes dead space
    score += 15.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: tight fits get a bonus
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Interaction with mean residual (asymmetric: above-mean is wasteful)
    let dev = pr - mean_residual;
    score += 0.3 * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Two-step lookahead: reward bins whose post residual chains the next item well
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let slack = pr - next_item_size as f64;
        if slack == 0.0 {
            score -= 50.0; // perfect 2-step chain
        } else if slack <= 10.0 {
            score -= 22.0;
        } else {
            let slackn = 1.0 - slack / cap;
            score -= 10.0 * slackn * slackn * (0.6 + 0.6 * progress);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize overshoot unless residual is dead space
        let overshoot = (next_item_size as f64 - pr).max(0.0);
        if pr > 12.0 {
            score += 0.55 * overshoot;
        }
        score += 4.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus (only for real bins, not the new-bin candidate)
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 28.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.06 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // New-bin candidate handling: reluctant by default, attractive when fits are poor
    if bin_residual == bin_capacity {
        score += 22.0 + 12.0 * progress; // base reluctance, stronger late in stream
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (next_item_size > 0 && next_item_size as f64 > pr && pr > 25.0)
                || (next_item_size > 0 && next_item_size as f64 > cap * 0.6 && pr > 20.0);
            if poor_fit {
                score -= 38.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.35 * (progress - 0.5) * (progress - 0.5));

    // Strong rewards for near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Non-linear coupling: squared normalized post-residual penalizes dead space
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: tight fits get a bonus
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Interaction with mean residual
    score += 0.25 * (mean_residual - pr) * (0.5 + progress);

    // Two-step lookahead: reward bins whose post residual chains the next item well
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let slack = pr - next_item_size as f64;
        if slack == 0.0 {
            score -= 45.0 + 3.0 * (fitting_bins_count.min(4) as f64); // perfect 2-step chain
        } else if slack <= 10.0 {
            score -= 20.0;
        } else {
            let snug = 1.0 - slack / pr.max(1.0);
            score -= 9.0 + 15.0 * snug * (0.6 + 0.6 * progress);
        }
        // double-chain bonus: post residual can hold next item twice
        if post_residual >= 2 * next_item_size {
            score -= 7.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize stranded residual
        let overshoot = (next_item_size as f64 - pr).max(0.0);
        if pr > 15.0 {
            score += 0.5 * overshoot;
        }
        score += 5.0 * (next_item_size as f64 / cap) * norm_pr;
        // stranded small residual relative to next item
        let stranded = pr / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        // dead-space band where next item overshoots
        if norm_pr > 0.33 && norm_pr < 0.57 {
            let os = overshoot / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * os;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
        if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr * cap * (1.0 - progress);

    // Waste-ratio bands
    if post_residual > 0 {
        let wr = norm_pr;
        if wr < 0.04 && fitting_bins_count <= 2 {
            score -= 11.0;
        } else if wr < 0.08 {
            score -= 12.0;
        } else if wr > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // alignment with mean residual
        let align = 1.0 - ((pr - mean_residual).abs() / cap);
        if align > 0.9 {
            score -= 5.0 * (align - 0.9) * 10.0;
        }
        if (pr - mean_residual).abs() < 3.0 {
            score -= 3.0;
        }
        if progress > 0.5 && pr <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: reluctant by default, attractive when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress; // base reluctance, stronger late in stream
        let lookahead_fits = next_item_size > 0 && next_item_size as f64 <= pr;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            let poor_fit = pr > 40.0 || (next_item_size > 0 && next_item_size as f64 > pr && pr > 30.0);
            if poor_fit {
                score -= 35.0;
            } else {
                let slack = (mean_residual - pr).max(0.0);
                score += 55.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
                if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                    score += 12.0;
                }
                if fitting_bins_count >= 3 {
                    score += 8.0;
                }
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    }

    // Late-stream squeeze: prefer tight residual bins
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is smaller than the smallest plausible item (<= ~10)
    // or too small to fit the lookahead item.
    if post_residual < 10 {
        score += 50.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward placements that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // (favor bins with tight fits); when few are open, mild exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Prefer bins whose residual is close to the mean (balanced usage),
    // penalize outliers relative to mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive if no open bin gives a tight fit
    // (i.e., current item is small relative to capacity and open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized by default, rewarded when fragmentation is high.
        score = 60.0 - 40.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no choice: open new bin
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: post residual with progress-dependent smoothing
    let mut score = pr * (1.0 + 0.25 * (progress - 0.5) * (progress - 0.5));

    // Fit-quality tiers: reward exact and near-exact fills
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual <= 3 {
        score -= 38.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 14.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Dead-space penalty: squared normalized residual, stronger late
    score += 16.0 * norm_pr * norm_pr * (0.4 + 0.9 * progress);

    // Cubic term: bonus for very tight fills
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Mean-residual deviation: above-mean residual is wasteful
    let dev = pr - mean_residual;
    score += 0.35 * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Two-step lookahead: reward bins that chain the next item well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 55.0;
            } else if slack <= 10.0 {
                score -= 24.0;
            } else {
                let slackn = 1.0 - slack / cap;
                score -= 11.0 * slackn * slackn * (0.6 + 0.6 * progress);
            }
        } else {
            let overshoot = nxt - pr;
            if pr > 12.0 {
                score += 0.6 * overshoot;
            }
            score += 4.0 * (nxt / cap) * norm_pr;
        }
    }

    // Three-step anticipation: if next item exactly exhausts residual, extra reward
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 8.0 * (1.0 - progress);
    }

    // Last-chance bin bonus (real bins only)
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion: many open bins -> consolidate aggressively
    score += 0.09 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // Waste-avoidance: penalize bins whose residual is too small for typical items
    if post_residual > 0 && post_residual < 12 && next_item_size as u32 > post_residual {
        score += 6.0;
    }

    // New-bin candidate: reluctant by default, attractive only on poor fits
    if bin_residual == bin_capacity {
        score += 24.0 + 14.0 * progress;
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (next_item_size > 0 && next_item_size as f64 > pr && pr > 25.0)
                || (next_item_size > 0 && next_item_size as f64 > cap * 0.6 && pr > 20.0)
                || item > cap * 0.85;
            if poor_fit {
                score -= 40.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // dead space penalty
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward leaving a gap that can still host typical items.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Prefer bins whose residual was already small (dense packing).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.15;

    // Open-bin pressure: discourage spreading into many bins unless fit is tight.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 20.0; // gap too small for next item: extra dead-space penalty
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 1.2;
        score += 15.0 - pressure + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if post_residual == bin_capacity {
            score += 5.0; // slightly discourage new bin when a decent fit exists
        }
    }

    // Mean residual coupling: if open bins are mostly full, prefer reusing them.
    if mean_residual < 20.0 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item exactly matches the post residual, strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }
    // Lookahead: if next item fits into post residual, mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - tight / bin_capacity as f64);
    }
    // Lookahead penalty: post residual too small for next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 150.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last chance: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Penalize bins whose residual deviates above the mean (prefer packing fuller bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    // Reward bins below mean residual (i.e., already fuller).
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Early stream: be more aggressive at filling bins tightly; late stream: accept fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when open bins are crowded or this is a huge item.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count == 0 { 0.0 } else { (open_bins_count as f64).ln() };
        let big_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items when many bins are open, bad early on.
        score = 60.0 + 40.0 * big_item - 15.0 * crowded + 50.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 500.0; // don't abandon the only fitting bin for a fresh one
        }
    }

    // Slight penalty for many open bins to encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: post residual with progress-dependent smoothing
    let mut score = pr * (1.0 + 0.25 * (progress - 0.5) * (progress - 0.5));

    // Fit-quality tiers: reward exact and near-exact fills (tightened)
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual <= 3 {
        score -= 42.0;
    } else if post_residual <= 5 {
        score -= 32.0;
    } else if post_residual <= 10 {
        score -= 16.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Dead-space penalty: squared normalized residual, stronger late
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.9 * progress);

    // Cubic term: bonus for very tight fills
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Mean-residual deviation: above-mean residual is wasteful (stronger)
    let dev = pr - mean_residual;
    score += 0.45 * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Two-step lookahead: reward bins that chain the next item well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 60.0;
            } else if slack <= 10.0 {
                score -= 26.0;
            } else if slack <= 20.0 {
                score -= 12.0;
            } else {
                let slackn = 1.0 - slack / cap;
                score -= 11.0 * slackn * slackn * (0.6 + 0.6 * progress);
            }
        } else {
            let overshoot = nxt - pr;
            if pr > 12.0 {
                score += 0.65 * overshoot;
            }
            score += 4.5 * (nxt / cap) * norm_pr;
        }
    }

    // Three-step anticipation: if next item exactly exhausts residual, extra reward
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 9.0 * (1.0 - progress);
    }

    // Last-chance bin bonus (real bins only)
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 32.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion: many open bins -> consolidate aggressively
    score += 0.11 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // Waste-avoidance: penalize bins whose residual is too small for typical items
    if post_residual > 0 && post_residual < 12 && next_item_size as u32 > post_residual {
        score += 7.0;
    }

    // Fragmentation guard: residual too small for the item's own size class
    if post_residual > 0 && post_residual < item * 0.5 && next_item_size as u32 > post_residual {
        score += 5.0 * (1.0 - progress);
    }

    // New-bin candidate: reluctant by default, attractive only on poor fits
    if bin_residual == bin_capacity {
        score += 26.0 + 14.0 * progress;
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (next_item_size > 0 && next_item_size as f64 > pr && pr > 25.0)
                || (next_item_size > 0 && next_item_size as f64 > cap * 0.6 && pr > 20.0)
                || item > cap * 0.85
                || (next_item_size > 0 && next_item_size as f64 > pr && fitting_bins_count <= 2 && pr > 15.0);
            if poor_fit {
                score -= 42.0;
            }
        }
    }

    score
}

