    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would be blocked by a small post-residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += 8.0 * (next_item_size as f64 - post_residual as f64).sqrt();
        }
    }

    // New-bin candidate handling: make fresh bins attractive only when existing
    // fits are poor (post_residual small) or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_penalty = if post_residual == bin_capacity { 0.0 } else { 0.0 };
        // score for new bin = residual(=capacity) minus bonuses; adjust with open bins pressure
        score -= 12.0 * (open_bins_count as f64).ln().max(0.0);
        score += 10.0 * progress;
        let _ = poor_fit_penalty;
    } else {
        // Existing bins: slight preference for fuller bins to consolidate.
        score -= 5.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Global mean residual coupling: when mean residual is high, prefer bins
    // whose post-residual stays near the mean (keeps future options open).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild preference to spread across bins when few are open (parallelism),
    // and to consolidate when many are open.
    if open_bins_count < 4 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
