    // Mild penalty for many open bins, smoothed by progress
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer only when item is small relative to residual
    if bin_residual == bin_capacity {
        score -= 5.0 * progress * (1.0 - item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into usable bands.
    // Class 0: post_residual == 0 (perfect fit) -> strongest reward.
    // Class 1: post_residual < 10 (below min item size) -> dead space, mild reward (bin is "closed").
    // Class 2: post_residual >= 10 -> reusable residual, keep moderate.
    if post_residual == 0 {
        score -= 40.0; // perfect packing
    } else if post_residual < 10 {
        score -= 12.0; // bin effectively sealed; small residual is fine
    } else {
        // Fraction-of-capacity harmonic penalty: residuals near half capacity
        // (50) are the most reusable; residuals just above 10 are worst.
        let frac = post_residual as f64 / cap;
        let half_dist = (frac - 0.5).abs();
        score += 18.0 * half_dist; // push toward half-capacity leftovers
        // Integer-division threshold: leftover must be able to host a "small" item
        if post_residual < 25 {
            score += 8.0; // awkward small leftover
        }
    }

    // Lookahead coupling: if the next item cannot fit in post_residual,
    // this placement creates dead space relative to the lookahead.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for lookahead: penalize proportionally, but forgive
            // near-perfect fits and sealed bins.
            if post_residual >= 10 {
                score += 10.0 * (next_item_size - post_residual) as f64 / cap * 10.0;
            }
        } else {
            // Next item still fits here: reward, scaled by tightness of that fit.
            let next_tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * next_tightness;
        }
        // Harmonic compatibility: item and next item in same quarter-class
        // suggests pairing them; reward keeping them apart if classes differ.
        let q = |x: u32| x / 25;
        if q(next_item_size) != q(item_size) && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline slightly above good fits,
    // so it only wins when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Congestion: many open bins -> favor filling existing ones harder.
    score -= 0.3 * open_bins_count as f64;
    // Gap between this residual and mean residual: prefer bins below mean
    // (i.e., fuller bins) to balance and close bins out.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1)
    // are pure waste, but gaps that cannot hold the NEXT item are especially bad.
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 60.0;
    } else if post_residual < 5 {
        // Tiny unusable sliver: penalize hard (it is dead space).
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap cannot host the lookahead item: dead space relative to future demand.
        score += 15.0 + 0.2 * (next_item_size - post_residual) as f64;
    } else {
        // Usable gap: mild reward proportional to its utility for the next item.
        if next_item_size > 0 {
            score -= 5.0 * (post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Reward tight fits relative to the item itself (waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new one (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // and mean residual is high (existing bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if post_residual >= 0 && (next_item_size == 0 || post_residual >= next_item_size) {
            score += 35.0; // discourage opening new bins by default
        }
        if next_item_size > 0 && fragmentation > 0.5 {
            score -= 10.0 * fragmentation; // allow escape hatch when bins are fragmented
        }
    }

    // Slight late-stream tightening: less tolerance for waste as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0; // perfect 2-step chain
            } else if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot fit here: penalize proportionally to overshoot,
            // unless post_residual is tiny (dead space anyway).
            let overshoot = (next_item_size - post_residual) as f64;
            if post_residual > 15 {
                score += 0.5 * overshoot;
            }
        }
    }

    // Compare post_residual to mean residual: leaving a bin near the mean is neutral,
    // leaving it far below mean (wasting a big gap) is penalized.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.abs().signum() * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor
    // and the next item is large (would waste space in any open bin).
    if bin_residual == bin_capacity {
        score += 20.0; // base reluctance to open new bins
        if fitting_bins_count >= 1 {
            if post_residual > 40 || (next_item_size > 0 && next_item_size > post_residual && post_residual > 30) {
                score -= 35.0; // poor fits elsewhere -> new bin becomes attractive
            }
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: late in the stream, packing tightness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).max(0.0) * (0.5 + progress);

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else {
            // Penalize leaving post-residual just below next item (dead space).
            let waste = post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs();
            score += 5.0 * (1.0 - waste / bin_capacity as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins deeper.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins with residuals near mean (balanced packing),
    // unless it's a new empty bin.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    } else {
        // New empty bin: only attractive when existing bins are fragmented
        // (high mean residual) or few bins fit the item.
        score += 25.0 + 0.2 * mean_residual - 10.0 * (fitting_bins_count as f64);
    }

    // Perfect closure bonus: filling a bin exactly is free.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr2 = fit_norm * fit_norm;
    let pr3 = pr2 * fit_norm;
    score += 12.0 * pr2 * (0.5 + progress);
    score -= 20.0 * pr3 * (1.0 - progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Reward tight fits, stronger later in the stream (smooth sigmoid-like)
    let tight = 1.0 - fit_norm;
    score -= tight * tight * (10.0 + 15.0 * progress);

    // Lookahead coupling: bonus if next item fits the post residual (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 8.0 * (1.0 - g) * (1.0 - g);
        } else {
            let g = (-gap) / cap;
            score += 6.0 * g * g;
        }
    }

    // Last-chance bin: strong reward to use it (smooth in fitting count)
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Mild penalty for proliferation of open bins (quadratic in count)
    score += 0.3 * (open_bins_count as f64) * (open_bins_count as f64) * 0.01;

    // New-bin candidate: penalize slightly unless current residuals are poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 15.0 - 20.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residual mod 10 buckets.
    let r = post_residual;
    let class = r % 10;
    // Residuals that are "harmonic" (divisible into small future items) are penalized less.
    let harmonic_bonus = match r {
        0 => -30.0,                       // perfect fit
        x if x % 20 == 0 => -8.0,
        x if x % 10 == 0 => -4.0,
        x if x % 5 == 0 => -1.0,
        _ => {
            // Odd fragments: penalize by distance to nearest multiple of 10.
            let d = class.min(10 - class) as f64;
            2.0 + d
        }
    };
    score += harmonic_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100 unknown,
    // but tiny slivers are risky). Scale by fraction of capacity.
    let tiny = (r > 0 && r < 10) as i32;
    if tiny == 1 {
        score += 15.0 * (1.0 - r as f64 / 10.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size <= r {
            // Fits, but leaves another residual; reward decays with leftover.
            let leftover = r - next_item_size;
            score -= 10.0 - 0.1 * leftover as f64;
        } else {
            // Next item cannot use this bin's remainder: slight penalty if residual stranded.
            score += 0.05 * (next_item_size - r).min(20) as f64;
        }
    }

    // Integer-division threshold on post_residual / capacity quarters.
    let quarter = (post_residual * 4) / bin_capacity.max(1);
    score += match quarter {
        0 => -6.0,           // <=25% left: nearly full, great
        1 => 0.0,
        2 => 1.5,
        _ => 3.0,            // >75% left: wasteful placement
    };

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should lose unless open bins are congested.
    if bin_residual == bin_capacity {
        // Base penalty so we only open new bins when it is genuinely better.
        score += 12.0;
        // More open bins with high mean residual -> congestion, opening is more attractive.
        let congestion = mean_residual / cap;
        score -= 10.0 * congestion;
        // Early in stream, opening bins is cheap; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
        // If next item is huge and current fit is tight, new bin helps.
        if next_item_size >= 70 && item_size >= 50 {
            score -= 4.0;
        }
    }

    // Mild preference to spread load when many bins are open and this fit is loose.
    if open_bins_count > 3 {
        score += 0.02 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else {
            score += 5.0; // dead space w.r.t. the known future
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; makes new-bin candidate less attractive.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when the item leaves a
    // large, usable residual and few bins can fit the item.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.6 * open_bins_count as f64;
        if post_residual >= 50 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits with small slack left
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to capacity
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // Penalize bins far from mean residual (avoid leaving outliers)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening new bins when stream is late
    // or many bins already open, unless residual would be perfect
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 300.0 - 150.0 * progress;
        if next_item_size == 0 {
            score += 100.0;
        }
    }

    // Mild preference to fill bins with few open alternatives
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: near-perfect fits get strongly favored.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tightness * tightness * tightness;

    // Dead-space penalty: residual too small to ever hold the smallest item (1..100 unknown, assume >=10-ish safe zone).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item cannot fit in the post residual, this placement
    // "burns" the bin's future unless it was a tight fit anyway.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Next item won't fit here; penalize proportionally, but less if this was a great fit.
            let waste = (next_item_size as f64 - post_residual as f64).min(60.0);
            score += 0.35 * waste;
        } else {
            // Next item chains nicely into this bin: reward chaining.
            let chain_eff = (next_item_size as f64) / (post_residual as f64);
            score -= 12.0 * chain_eff.min(1.0);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (new bin call has residual == capacity, high base score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Crowding pressure: many open bins with fat residuals -> prefer consolidating
    // into low-residual bins to reduce bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual < mean_residual {
        score -= 6.0 * crowding.min(4.0) * (0.5 + 0.5 * progress);
    } else {
        score += 4.0 * crowding.min(4.0) * (0.5 + 0.5 * progress);
    }

    // Late-stream consolidation: as stream progresses, be more conservative about
    // spreading items across bins; favor bins that will close out cleanly.
    if post_residual == 0 {
        score -= 20.0 * (0.3 + progress);
    }

    // Mild bias against opening new bins early when alternatives exist.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
