    let tightness = 1.0 - x;
    score -= 30.0 * tightness * tightness * tightness;

    // Stream progress coupling: later in the stream, waste is more costly
    score += 12.0 * progress * x * x;

    // Dead-space penalty: post-residual that cannot fit the next item,
    // smoothly scaled by how much of the next item is wasted
    if nx > 0.0 && pr < nx {
