    }

    // New-bin candidate: an empty bin should only win if no open bin fits well.
    // Give it a mild penalty so tight fits in open bins win, but keep it
    // competitive when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    // Mild penalty for proliferating bins when mean residual is already large
    score += 0.3 * ((open_bins_count as f64).ln() + 1.0) * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
