        let divisible_25 = (post_residual % 25 == 0) as f64;
        let divisible_50 = (post_residual % 50 == 0) as f64;
        score -= 6.0 * divisible_small + 4.0 * divisible_20 + 5.0 * divisible_25 + 8.0 * divisible_50;

        // Integer division thresholds: very small post_residual is dead space.
        if post_residual < 10 {
            score += 12.0; // unusable dead space
        } else if post_residual < 20 {
            score += 5.0;  // marginal
        }

        // Fraction of capacity remaining: quadratic penalty for mid-range waste.
        let frac = post / cap;
        score += 8.0 * frac * (1.0 - frac); // penalize mid residuals, reward near 0 or near-full reuse
    } else {
        score -= 15.0; // perfect fill: strongly favored
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 - 0.15 * slack as f64; // reward bins that can host the next item
        if slack == 0 {
            score -= 8.0; // exact two-item fill
        }
        // Harmonic class: post_residual - next_item divisible by 10 means likely future fit
        if slack % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: slight penalty, more so if it's large.
        score += 0.03 * next_item_size as f64;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer filling
    // existing bins, unless the fit is terrible elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item nearly fills a fresh bin, opening new is attractive.
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.8 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, be picky (tight fits matter more over a long stream).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (1.0 - post / cap);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.4 * open_bins_count as f64 * (post / cap);

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    if mean_residual > 0.0 {
        score += 0.05 * (post - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // scaled by how small the gap is (non-linear coupling).
    if post_residual > 0 && post_residual <= 12 {
        let dead = (13.0 - post_residual as f64) / 13.0;
        score += 90.0 * dead * dead;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 4 {
        score -= 15.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // (penalize opening new bins); scale pressure with stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap won't serve next item; mild penalty proportional to wasted space.
        score += 0.3 * post_residual as f64;
    }

    // Prefer bins whose residual is below the mean residual (more filled bins).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: opening a new bin is only attractive when no open bin fits well.
    // Base penalty grows with number of open bins that could fit the item.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        let desperation = if fitting_bins_count == 1 { 55.0 } else { 0.0 };
        score += 45.0 + 12.0 * escape - desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline; make it attractive only when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so an existing good fit beats a new bin.
        score += 25.0;
        // If no open bin fits (this call is the only option) it wins naturally.
        return score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // Perfect match: next item exactly fills this bin.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: reward closeness of match.
            let gap = post_residual as f64 - nxt;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize proportionally to wasted potential.
            let miss = nxt - post_residual as f64;
            score += 10.0 + 0.3 * miss;
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 0.0;
    }

    // --- Mean-residual relative positioning ---
    // Prefer bins whose post residual sits below the mean residual
    // (concentrate waste in few bins, keep others flexible).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (post_f - mean_residual);
    }

    // --- Last-chance bonus: sole bin that can take the item ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- Tightness reward: near-perfect fills ---
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // --- Early stream: be slightly conservative (keep bins balanced) ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), normalized
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Reward near-exact fits strongly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Lookahead: if next item fits in post_residual, big bonus for chaining
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item would fill this bin almost completely after chaining
        let chain_residual = post_residual - next_item_size;
        if chain_residual <= 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving dead space the next item cannot use
        score += (post_residual as f64).min(next_item_size as f64) * 0.5;
    }

    // Last chance: strongly favor using the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize spreading across many open bins when few alternatives fit
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Global state coupling: if mean residual is high, prefer filling bins with large residuals
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, be more open to new bins (exploration);
    // late in stream, consolidate into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, costly late
        score += progress * 30.0 - 10.0;
        // opening a new bin is fine if current item is large and open bins are fragmented
        score -= (open_bins_count as f64).ln() * 3.0;
    } else {
        // consolidation pressure grows with progress
        score -= progress * 8.0;
    }

    // Mild penalty for creating residuals in the awkward 1..10 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.35 * (progress - 0.5) * (progress - 0.5));

    // Non-linear coupling: squared normalized post-residual penalizes dead space,
    // weighted by stream progress (dead space matters more later)
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: very small residuals (tight fits) get a bonus via negative coupling
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Interaction with mean residual: prefer bins whose residual deviates favorably
    score += 0.25 * (mean_residual - pr) * (0.5 + progress);

    // Lookahead coupling: if next item fits in post residual, reward (smooth quadratic)
    if next_item_size > 0 {
        let fits_next = if next_item_size as f64 <= pr { 1.0 } else { 0.0 };
        let slack = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 9.0 * fits_next * slack * slack * (0.6 + 0.6 * progress);
        // Penalize blocking a large next item with near-full bin
        score += 5.0 * (1.0 - fits_next) * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus: smooth inverse coupling with fitting bins count
    if fitting_bins_count <= 1 {
        score -= 7.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr * cap * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // residue classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let useful = |r: u32| -> f64 {
        if r == 0 {
            6.0 // perfect fit: strongly reward
        } else if r % 10 == 0 {
            4.0
        } else if r % 25 == 0 {
            3.0
        } else if r % 5 == 0 {
            2.0
        } else {
            0.0
        }
    };
    score -= useful(pr);

    // Penalize small dead space (unusable slivers) more than large residuals.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or in a harmonic class.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 8.0;
        } else if pr >= next_item_size {
            let after_next = pr - next_item_size;
            score -= useful(after_next) * 0.5;
        } else {
            // next item cannot fit here: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or
    // the fit here would be poor (large post_residual).
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let poor_fit = (post_residual as f64) / cap;
        score -= 2.0 + 8.0 * crowded - 6.0 * (1.0 - poor_fit);
        // late in the stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    }

    // Prefer tighter bins overall: deviate from mean residual.
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    // Prefer bins whose residual class matches the item's size class (mod 10).
    if bin_residual % 10 == item_size % 10 && item_size <= bin_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothed with a non-linear polynomial in progress
    let mut score = pr * (1.0 + 0.35 * (progress - 0.5) * (progress - 0.5));

    // Strong rewards for near-perfect fits (borrowed waste-minimization idea)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Non-linear coupling: squared normalized post-residual penalizes dead space
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: tight fits get a bonus
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Interaction with mean residual
    score += 0.25 * (mean_residual - pr) * (0.5 + progress);

    // Two-step lookahead: reward bins whose post residual chains the next item well
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let slack = pr - next_item_size as f64;
        if slack == 0.0 {
            score -= 45.0; // perfect 2-step chain
        } else if slack <= 10.0 {
            score -= 20.0;
        } else {
            let slackn = 1.0 - slack / cap;
            score -= 9.0 * slackn * slackn * (0.6 + 0.6 * progress);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize overshoot unless residual is dead space
        let overshoot = (next_item_size as f64 - pr).max(0.0);
        if pr > 15.0 {
            score += 0.5 * overshoot;
        }
        score += 5.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion term: many open bins -> favor consolidation
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr * cap * (1.0 - progress);

    // New-bin candidate handling: reluctant by default, attractive when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress; // base reluctance, stronger late in stream
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (next_item_size > 0 && next_item_size as f64 > pr && pr > 30.0);
            if poor_fit {
                score -= 35.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization), scaled by item size:
    // perfect closure of a large residual is worth more than of a tiny one.
    let rel = post_residual as f64 / bin_capacity.max(1) as f64;
    if post_residual == 0 {
        score -= 60.0 + 40.0 * rel;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 12 {
        score -= 12.0 + 0.5 * (12 - post_residual) as f64;
    }

    // 2-step lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0; // perfect 2-step chain
            } else if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 12.0 * (1.0 - slack as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot fit here: penalize proportionally to overshoot,
            // unless post_residual is tiny (dead space anyway).
            let overshoot = (next_item_size - post_residual) as f64;
            if post_residual > 12 {
                score += 0.45 * overshoot;
            }
        }
    }

    // Compare post_residual to mean residual: leaving a gap far below the mean
    // wastes a big hole; leaving it far above the mean scatters space.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.max(0.0) - 0.12 * (-dev).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // but only if the fit is not absurdly poor relative to the residual.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        if waste <= (bin_capacity as f64 * 0.35) {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate logic: prefer opening a new bin only when fits are poor
    // and the next item is large (would waste space in any open bin).
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count >= 1 {
            // If the next item is huge and no open bin can chain it, a fresh bin
            // preserves capacity for it.
            let next_huge = next_item_size > 0 && next_item_size > bin_capacity * 3 / 5;
            if post_residual > 40 || next_huge
                || (next_item_size > 0 && next_item_size > post_residual && post_residual > 25) {
                score -= 35.0;
            }
        }
        // Late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // With many open bins, a fresh one is less costly to fill later.
        if open_bins_count > 8 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 32.0;
    } else if post_residual <= 10 {
        score -= 14.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 50.0; // perfect 2-step chain
            } else if slack <= 8 {
                score -= 24.0;
            } else if slack <= 25 {
                score -= 12.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot fit here: penalize proportionally to overshoot,
            // unless post_residual is tiny (dead space anyway).
            let overshoot = (next_item_size - post_residual) as f64;
            if post_residual > 12 {
                score += 0.6 * overshoot;
            } else if post_residual <= 4 {
                // tiny residual is nearly dead space: small bonus instead
                score -= 3.0;
            }
        }
    }

    // Residual-vs-mean coupling: leaving a gap near the mean is neutral,
    // wasting a big gap (far below mean) is penalized, tiny residual rewarded.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score -= 0.15 * (-dev);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 28.0;
    }

    // New-bin candidate evaluation: default reluctance, but open a fresh bin
    // when all open fits would strand a large gap and the next item is big.
    if bin_residual == bin_capacity {
        score += 22.0;
        if fitting_bins_count >= 1 {
            let poor_fit = post_residual > 40
                || (next_item_size > 0 && next_item_size > post_residual && post_residual > 25);
            if poor_fit {
                score -= 38.0;
            }
            // If the next item exactly consumes a fresh bin's capacity share
            // after placing the current item nowhere, prefer the new bin when
            // the current item is large (fresh bin keeps big-item alignment).
            if item_size >= 60 && next_item_size >= 60 && post_residual > 60 {
                score -= 15.0;
            }
        }
        // Late in the stream, be more conservative about opening new bins,
        // but ease off very slightly at the very end (leftover tail items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tail_bonus = if progress > 0.9 { 6.0 } else { 16.0 };
        score += tail_bonus * progress;
    }

    // Crowding pressure: when many bins compete for the same item, prefer
    // the tightest fits more aggressively (relative post_residual term).
    if fitting_bins_count > 3 {
        score += (post_residual as f64) * 0.05 * (fitting_bins_count.min(10) as f64) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
