    if post_residual > 0 && post_residual < item * 0.5 && next_item_size as u32 > post_residual {
        score += 5.0 * (1.0 - progress);
    }

    // New-bin candidate: reluctant by default, attractive only on poor fits
    if bin_residual == bin_capacity {
        score += 28.0 + 14.0 * progress;
