    score += 30.0 * fit_ratio * fit_ratio;

    // Harmonic classes: post_residual bucketed by integer division on 10s.
    let pr_class = post_residual / 10;
    let class_penalty = match pr_class {
        0 => -40.0,           // perfect or near-perfect closure
        1 => -10.0,           // small dead space, likely fillable (items >= 10)
        2 => 8.0,             // 20-29: moderately awkward
        3 => 15.0,            // 30-39: dead zone
        4 => 5.0,             // 40-49: half-bin, still useful
        5 => 0.0,             // 50-59: fine
        _ => -3.0,            // large residual, flexible
    };
    score += class_penalty;

    // Modulo arithmetic: residuals that are multiples of 10 align with item granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd residuals are harder to close exactly with integer items.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains, especially harmonic matches (next fits with small slack).
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_slack / bin_capacity as f64);
            if post_residual % 10 == next_item_size % 10 {
                score -= 8.0; // harmonic alignment: exact decimal-complement fit
            }
        } else {
            // Next item won't chain here; penalize proportionally to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    } else {
        // Last item: strongly prefer zero waste.
        score -= 50.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes
    // the residual; reward using it unless post_residual is tiny.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // near-closure, definitely use it
        }
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, demand tight fits.
        score += 4.0 * fit_ratio;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good early (stream is long) or when item is large
        // and would leave a nasty dead zone elsewhere.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkwardness = if post_residual > 0 && post_residual < 20 { 1.0 } else { 0.0 };
        score = 60.0 + 80.0 * progress - 30.0 * awkwardness - (item_size as f64) * 0.2;
        // With few open bins, prefer opening to build a portfolio.
        if open_bins_count < 3 {
            score -= 15.0;
        }
        // If mean residual across open bins is high, spreading is wasteful.
        if mean_residual > 40.0 {
            score += 15.0;
        }
    }

    // Mild regularization toward mean residual: prefer bins near the average state.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual with mild progress smoothing
    let mut score = pr * (1.0 + 0.25 * (progress - 0.5) * (progress - 0.5));

    // Strong rewards for near-perfect fits (sharpened ladder)
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual <= 4 {
        score -= 34.0;
    } else if post_residual <= 8 {
        score -= 18.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    } else if post_residual <= 25 {
        score -= 2.0;
    }

    // Non-linear dead-space penalty (squared normalized residual), reinforced
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Cubic term: punish large dead space harder late in stream
    score += 6.0 * norm_pr * norm_pr * norm_pr * progress;

    // Interaction with mean residual: leaving far above mean is wasteful
    let dev = pr - mean_residual;
    score += 0.35 * dev.max(0.0) - 0.12 * (-dev).max(0.0);

    // Two-step lookahead: reward bins that chain the next item well
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let slack = pr - next_item_size as f64;
        if slack == 0.0 {
            score -= 55.0; // perfect 2-step chain
        } else if slack <= 8.0 {
            score -= 26.0;
        } else {
            let slackn = 1.0 - slack / cap;
            score -= 12.0 * slackn * slackn * (0.6 + 0.6 * progress);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize overshoot unless dead space
        let overshoot = (next_item_size as f64 - pr).max(0.0);
        if pr > 10.0 {
            score += 0.6 * overshoot;
        }
        score += 4.5 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin bonus (scaled by tightness)
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion: many open bins -> consolidate into existing ones
    score += 0.07 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // New-bin candidate handling: reluctant by default, attractive when fits are poor
    if bin_residual == bin_capacity {
        score += 24.0 + 12.0 * progress; // base reluctance
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 38.0
                || (next_item_size > 0 && next_item_size as f64 > pr && pr > 24.0)
                || (next_item_size > 0 && next_item_size as f64 > cap * 0.6 && pr > 18.0)
                || (fitting_bins_count >= 3 && pr > 30.0);
            if poor_fit {
                score -= 40.0;
            }
        }
        // Early stream: slightly more willing to open bins to build variety
        if progress < 0.15 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual below the minimum item size (1) can never happen, but gaps
    // too small for typical items create effective dead space. Penalize gaps
    // smaller than a conservative "smallest plausible item" threshold.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty: gaps in the "awkward zone" (just above the smallest
    // item but below half a typical item) are also poor fits.
    if post_residual > 0 && post_residual < 25 {
        score += 20.0;
    }

    // Reward tight fits strongly.
    score -= (bin_residual - post_residual) as f64 / bin_capacity as f64 * 30.0;

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // over opening new ones (penalize the new-bin candidate implicitly since
    // its post_residual == bin_capacity is large, but add explicit pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 15.0 + open_bins_count as f64 * 3.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= open_bins_count as f64 * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item does NOT fit in post residual, mildly penalize.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mean residual coupling: if this bin's post residual is far below the mean
    // residual, it's becoming a tight bin — reward closing it down.
    if (post_residual as f64) < mean_residual {
