    score += 40.0 * (0.5 + progress) * poly;
    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64 / cap) * (1.0 - prn);
    score -= 25.0 * (0.3 + progress) * tightness;
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }
    // Lookahead: reward if next item fits post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }
    // Penalize deviation from mean residual among open bins
    score += 0.5 * (pr - mean_residual).abs();
    // New-bin candidate: keep neutral baseline
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 20.0 * (1.0 - progress) - 10.0 * poly;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
