    // Prefer bins with below-average residual (tighter bins filled first).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate logic:
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        // How many open bins could still host the next item (proxy: fitting count).
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            // Fresh bin gives the lookahead a clean home: strong attraction.
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            // Avoid opening bins that waste capacity the lookahead cannot use.
            score += 55.0;
