    }

    // Early-stream structural freedom, decaying with progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress < 0.25 {
        score -= 6.0 * (1.0 - progress / 0.25);
    }

    // Mid-stream: discourage opening new bins when many bins are already open
    // and the item is small enough to be squeezed somewhere.
    if bin_residual == bin_capacity && open_bins_count > 4 && item_size <= mean_residual as u32 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
