pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: post residual with mild progress smoothing
    let mut score = pr * (1.0 + 0.2 * (progress - 0.5) * (progress - 0.5));

    // Fit-quality tiers: reward exact and near-exact fills
    if post_residual == 0 {
        score -= 65.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Dead-space penalty: squared normalized residual, stronger late
    score += 16.0 * norm_pr * norm_pr * (0.4 + 0.9 * progress);

    // Mean-residual deviation: above-mean residual is wasteful
    let dev = pr - mean_residual;
    score += 0.4 * dev.max(0.0) - 0.12 * (-dev).max(0.0);

    // Two-step lookahead: snug chaining bonus (combined fine-fit + anticipation)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / pr.max(1.0);
            if pr - nxt == 0.0 {
