            let overshoot = nxt - pr;
            if pr > 12.0 {
                score += 0.6 * overshoot;
            }
            // stranded small residual: can't hold next item
            let stranded = pr / nxt.max(1.0);
            if stranded < 0.5 {
                score += 4.0 * (1.0 - stranded);
            }
            score += 4.0 * (nxt / cap) * norm_pr;
