pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: post residual with progress-dependent smoothing
    let mut score = pr * (1.0 + 0.25 * (progress - 0.5) * (progress - 0.5));

    // Fit-quality tiers: reward exact and near-exact fills
    if post_residual == 0 {
        score -= 75.0;
    } else if post_residual <= 3 {
        score -= 48.0;
    } else if post_residual <= 5 {
        score -= 36.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 7.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    }

    // Dead-space penalty: squared normalized residual, stronger late
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.9 * progress);

    // Cubic term: bonus for very tight fills
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Mean-residual deviation: above-mean residual is wasteful
    let dev = pr - mean_residual;
    score += 0.45 * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Two-step lookahead: reward bins that chain the next item well
    if nxt > 0.0 && nxt <= pr {
        let slack = pr - nxt;
        let snug = 1.0 - slack / pr.max(1.0);
        if slack == 0.0 {
            score -= 66.0;
        } else if slack <= 5.0 {
            score -= 36.0 + 6.0 * snug;
        } else if slack <= 10.0 {
            score -= 27.0;
        } else if slack <= 20.0 {
            score -= 13.0;
        } else {
            let slackn = 1.0 - slack / cap;
            score -= 11.0 * slackn * slackn * (0.6 + 0.6 * progress);
        }
        // Chainability: residual can still host another item after next
        if post_residual >= 2 * next_item_size {
            score -= 7.0;
        }
    } else if nxt > 0.0 {
        let overshoot = nxt - pr;
        if pr > 12.0 {
            score += 0.65 * overshoot;
        }
        score += 4.5 * (nxt / cap) * norm_pr;
        // Stranded small residual that next item cannot use
        let stranded = pr / nxt.max(1.0);
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        if pr < 15.0 {
            score += 4.0;
        }
    }

    // Three-step anticipation: exact exhaustion by next item
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Last-chance bin bonus (real bins only)
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 36.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion: many open bins -> consolidate aggressively
    score += 0.13 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // Waste-avoidance: residual too small for typical items
    if post_residual > 0 && post_residual < 12 && next_item_size as u32 > post_residual {
        score += 7.0;
    }

    // Fragmentation guard
    if post_residual > 0 && post_residual < item * 0.5 && next_item_size as u32 > post_residual {
        score += 5.0 * (1.0 - progress);
    }

    // Mean-residual alignment bonus (borrowed idea): residual near mean is reusable
    if post_residual > 0 && (pr - mean_residual).abs() < 3.0 {
        score -= 3.0;
    }

    // New-bin candidate: reluctant by default, attractive only on poor fits
    if bin_residual == bin_capacity {
        score += 28.0 + 14.0 * progress;
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (nxt > pr && pr > 25.0)
                || (nxt > cap * 0.6 && pr > 20.0)
                || item > cap * 0.85
                || (nxt > pr && fitting_bins_count <= 2 && pr > 15.0)
                || (item > cap * 0.5 && pr < item * 0.4 && fitting_bins_count <= 2)
                || (nxt > pr + cap * 0.3 && pr > 18.0);
            if poor_fit {
                score -= 46.0;
            } else {
                // No poor fit anywhere: opening fresh is expensive; penalize more
                // when open-bin pool is large and item is small (fits easily).
                score += 2.0 * open_bins_count.min(10) as f64;
                if nxt > 0.0 && nxt <= mean_residual {
                    score += 12.0;
                }
            }
        }
        // early stream with few bins: opening fresh is cheaper than fragmenting
        if progress < 0.15 && open_bins_count <= 3 && pr > 30.0 {
            score -= 12.0;
        }
        // late stream: prefer filling existing bins tightly
        if progress > 0.8 && pr < item {
            score += 10.0;
        }
    }

    score
}

