    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 55.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= open_bins_count as f64 * 2.0;

        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.08 {
            score -= 12.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }

        // Awkward mid-gap zone that next item overshoots slightly.
        if post_residual > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if waste_ratio > 0.33 && waste_ratio < 0.57 {
                score += 6.0 + 8.0 * overshoot;
            }
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
