pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize unusable small gaps.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }
    if post_residual > 0 && post_residual < 25 {
        score += 20.0;
    }

    // Reward tight fits.
    score -= (bin_residual - post_residual) as f64 / bin_capacity as f64 * 30.0;

    // Lookahead: snug fit for next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 40.0 + 0.35 * next_item_size as f64 + 15.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Zero residual is perfect closure.
    if post_residual == 0 {
        score -= 60.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 15.0 + open_bins_count.min(10) as f64 * 3.0 + 0.25 * slack;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
    } else {
        // Reward using existing bins.
        score -= open_bins_count as f64 * 2.0;

        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.08 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.0;
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
        if post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 3.0 {
            score -= 3.0;
        }
    }

    // Mean residual coupling: reward closing tight bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    score
