    }

    // Congestion consolidation
    score += 0.13 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // Waste avoidance for tiny residuals
    if post_residual > 0 && post_residual < 12 && next_item_size as u32 > post_residual {
        score += 7.0;
    }
    if post_residual > 0 && pr < item * 0.5 && next_item_size as u32 > post_residual {
        score += 5.0 * (1.0 - progress);
    }

    // Mean alignment bonus
    if post_residual > 0 && (pr - mean_residual).abs() < 3.0 {
        score -= 3.0;
    }
    let align = 1.0 - ((pr - mean_residual).abs() / cap);
    if align > 0.9 {
        score -= 5.0 * (align - 0.9) * 10.0;
    }

    // Very tight waste with scarce alternatives
    if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
        score -= 11.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = nxt > 0.0 && nxt <= pr;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            score += 55.0 + 0.25 * dev.max(0.0) + 2.0 * open_bins_count.min(10) as f64;
            if nxt > 0.0 && nxt <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if nxt > 0.0 && post_residual >= next_item_size && pr < 2.0 * nxt {
                score -= 6.0;
            }
        }
        // poor-fit override: open fresh when existing fits are bad
        let poor_fit = pr > 40.0
            || (nxt > pr && pr > 25.0)
            || (nxt > cap * 0.6 && pr > 20.0)
            || item > cap * 0.85
            || (nxt > pr && fitting_bins_count <= 2 && pr > 15.0)
            || (item > cap * 0.5 && pr < item * 0.4 && fitting_bins_count <= 2)
            || (nxt > pr + cap * 0.3 && pr > 18.0);
        if poor_fit {
            score -= 46.0;
        }
        if progress < 0.15 && open_bins_count <= 3 && pr > 30.0 {
            score -= 12.0;
        }
        if progress > 0.8 && pr < item {
            score += 10.0;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        // late stream: dump small items into nearly full bins
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.5 && post_residual > 0 && pr <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if waste_ratio > 0.6 && item > mean_residual {
            score += 6.0;
        }
        if fitting_bins_count == 1 && post_residual > 0 && nxt > 0.0 && pr < nxt {
            score -= 10.0;
        }
        if waste_ratio > 0.5 && nxt > 0.0 && nxt > waste_ratio * cap {
            score += 3.0 * (waste_ratio - 0.5) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small to hold any future item
    // (items can be as small as 1, so treat < next_item_size or very tiny gaps as waste).
    if post_residual > 0 {
        let unusable = post_residual < next_item_size || post_residual < 10;
        if unusable {
            // Harsh penalty scaled by how close we are to a perfect fill being wasted
            score += 40.0 + (post_residual as f64) * 1.5;
        } else {
            // Usable residual: reward tight fits proportionally
            score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
    } else {
        // Perfect fill: strong reward
        score -= 60.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the post residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so penalize it via
    // its large post_residual naturally, plus explicit pressure term.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64);
    }

    // Mild preference for bins with smaller residuals (best-fit coupling)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight tilt toward consolidation as the stream progresses
    score += 2.0 * (step_index as f64 / (total_items as f64).max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
