pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post == nxt {
            score -= 200.0; // perfect 2-chain
        } else if post > nxt {
            // still fits next item: mild reward, closer match = better
            score -= 30.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // dead space blocks next item: penalize by how close we came
            score += 40.0 * (nxt - post) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Penalize large waste relative to capacity
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Early in stream: allow opening new bins more freely
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if bin_residual == bin_capacity {
        // ---- NEW-BIN CANDIDATE ----
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 55.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
        }
        return score;
    }

    // ---- EXISTING BIN ----
    // Lookahead snug-fit reward: next item fills post residual tightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 40.0 + 0.35 * next_item_size as f64 + 15.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Dead-space shaping: reward near-zero residuals, penalize awkward gaps.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    let waste_ratio = post_residual as f64 / bin_capacity.max(1) as f64;

    // Tight-fit bonus, stronger when few bins can take the item.
    if waste_ratio < 0.04 && fitting_bins_count <= 2 {
        score -= 11.0;
    } else if waste_ratio < 0.08 {
        score -= 12.0;
    }

    // Large leftover with an item bigger than mean residual: bad placement.
    if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // Awkward mid-gap that the next item cannot use.
    let dead_space = waste_ratio;
    if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
        let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 6.0 + 8.0 * overshoot;
    }

    // Alignment with mean residual: bins whose residual matches the mean
    // are more likely to absorb future items.
    if post_residual > 0 {
        let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity.max(1) as f64);
        if align > 0.9 {
            score -= 5.0 * (align - 0.9) * 10.0;
        }
        if (post_residual as f64 - mean_residual).abs() < 3.0 {
            score -= 3.0;
        }
    }

    // Roomy leftover that can hold the next item twice: keep bin useful.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.0;
    }

    // Stranded micro-gap: post residual far smaller than next item.
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        if post_residual < 15 {
            score += 4.0;
        }
    }

    // Exact next-item match: excellent, stronger with few alternatives.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
    }

    // Two-fit potential: after placing, residual holds next item and more.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
        if two_fit && waste_ratio < 0.5 {
            score -= 2.5;
        }
        if post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
    }

    // Large dead space that next item cannot use.
    if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
        score += 3.0 * (dead_space - 0.5) * 10.0;
    }

    // Open-bin pressure: prefer existing bins when many are open.
    score -= open_bins_count.min(8) as f64 * 2.0;

    // Late stream: aggressively close bins with small residuals.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    // Last-chance bin: only existing bin that fits and next item won't
    // fit after — still prefer using it over a new bin.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 8.0 * next_fit;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if we waste large residual.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with residuals below the mean (consolidate emptier space usage).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be more conservative (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses; allow early exploration.
        score += 15.0 + 20.0 * progress;
        // If no open bin fits, new bin is necessary — soften penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference to keep number of open bins low when many are open.
    score += 0.2 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly.
    let mut score = norm_pr * norm_pr * 100.0 + norm_pr * 10.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, tight packing is critical.
    let progress_coupling = norm_pr * (0.5 + 2.5 * progress * progress);
    score += progress_coupling * cap;

    // Reward filling bins deeply (item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * fill_ratio * 30.0;

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize leaving residual that cannot fit the next item (smooth soft penalty).
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0) / cap;
        score += waste * waste * 40.0;
        // Reward residual that exactly accommodates the next item.
        let fit_gap = (pr - next_item_size as f64).abs() / cap;
        score -= (1.0 - fit_gap).max(0.0) * 8.0 * progress;
    }

    // Mild penalty for proliferating bins relative to mean residual state.
    let mr = mean_residual / cap;
    score += (open_bins_count as f64).ln() * (1.0 - mr) * 2.0;

    // New-bin candidate: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.5 - 20.0 * progress;
    }

    score
}

