    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (1.0 + progress);
    score += open_pressure * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize bins whose leftover deviates badly
    // from the fleet mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when this item would leave
    // a large dead gap in every existing bin.
    if bin_residual == bin_capacity {
        score = 45.0 - (item_size as f64);
        if next_item_size > 0 && item_size >= next_item_size {
