}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tight-fit preference: reward small post-residual
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Lookahead: strongly reward leaving space exactly usable by next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to wasted potential
        score += 4.0 + (next_item_size as f64) * 0.05;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // early stream: opening bins is cheap; late: consolidate
        score += 10.0 + 25.0 * progress;
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 6.0; // existing bins have plenty of room on average
        }
    } else {
        // penalize placing into a bin whose residual deviates far from mean (fragmentation control)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.03;
    }

    // penalize creating dead space smaller than the minimum item size (1..100 unknown dist)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // mild preference to fill bins with more residual when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * post_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
