    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_sq = progress * progress;

    // Smooth quadratic waste penalty: dead space hurts more as stream progresses
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste * (0.5 + progress);

    // Reward tight fits smoothly: exponential-ish decay via polynomial of fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio * (1.0 - prog_sq);

    // Penalize when this bin is the only fitting bin less aggressively late (last-chance value)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - progress * 0.7);

    // New empty bin candidate: penalize opening new bins early, less late
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 8.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Smooth coupling with mean residual: prefer bins near the mean residual (balance)
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev * dev;

    // Lookahead: reward leaving space close to next item size (smooth quadratic)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 * (1.0 - gap * gap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues near multiples of common
    // item sizes leave "reusable" gaps; residues in dead zones are penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead zone: too small for the smallest plausible item (<= 8).
        if pr <= 8 {
            score += 40.0; // unusable sliver
        }
        // Harmonic classes via modulo arithmetic on the residual.
        // Residuals divisible by common item granularities (2,4,5,10,20,25)
        // are more likely to be exactly consumed later.
        let mut div_hits = 0;
        for m in [2u32, 4, 5, 10, 20, 25, 50].iter() {
            if pr % m == 0 { div_hits += 1; }
        }
        score -= 6.0 * div_hits as f64;

        // Integer-division thresholds: classify residual into capacity fractions.
        let frac = pr as f64 / bin_capacity as f64; // 0..1
        if frac > 0.5 {
            score -= 15.0; // half-full or better residual: very reusable
        } else if frac > 0.25 {
            score -= 6.0;
        } else if frac > 0.1 {
            score += 8.0; // awkward quarter-ish gap
        }

        // Exact-fit coupling: if post_residual equals a plausible item size,
        // this bin is perfect for a future item.
        if pr >= 1 && pr <= 100 && (pr % 5 == 0 || pr % 10 == 0) {
            score -= 12.0;
        }
    } else {
        score -= 50.0; // perfect fit: best possible outcome
    }

    // --- Lookahead coupling (k=2): if the next item fits the post residual,
    // strongly reward; if next item is bigger than residual but this bin is
    // the last chance for the current item, weigh the trade-off.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // Bonus if post_residual is an exact harmonic match for next item.
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is reasonable early or when many bins are open
        // and mean residual is high (existing bins are cluttered).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let clutter = mean_residual / bin_capacity as f64;
        // Penalize new bin mildly; reward it when existing bins are fragmented.
        score += 30.0 - 25.0 * clutter - 10.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
    }

    // --- Mild pressure against bin sprawl.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };

    // Base: post residual with progress-dependent smoothing
    let mut score = pr * (1.0 + 0.25 * (progress - 0.5) * (progress - 0.5));

    // Fit-quality tiers: reward exact and near-exact fills (fine-grained)
    if post_residual == 0 {
        score -= 70.0;
    } else if post_residual <= 3 {
        score -= 46.0;
    } else if post_residual <= 5 {
        score -= 34.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    }

    // Dead-space penalty: squared normalized residual, stronger late
    score += 16.0 * norm_pr * norm_pr * (0.4 + 0.9 * progress);

    // Cubic term: bonus for very tight fills
    score -= 12.0 * norm_pr * norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Mean-residual deviation: above-mean residual is wasteful
    let dev = pr - mean_residual;
    score += 0.4 * dev.max(0.0) - 0.1 * (-dev).max(0.0);

    // Two-step lookahead: reward bins that chain the next item well
    if nxt > 0.0 && nxt <= pr {
        let slack = pr - nxt;
        if slack == 0.0 {
            score -= 62.0;
        } else if slack <= 5.0 {
            score -= 34.0;
        } else if slack <= 10.0 {
            score -= 24.0;
        } else if slack <= 20.0 {
            score -= 12.0;
        } else {
            let slackn = 1.0 - slack / cap;
            score -= 11.0 * slackn * slackn * (0.6 + 0.6 * progress);
        }
        // Multi-fit bonus: residual can host next item twice
        if next_item_size > 0 && pr >= 2.0 * nxt {
            score -= 7.0;
        }
    } else if nxt > 0.0 {
        let overshoot = nxt - pr;
        if pr > 12.0 {
            score += 0.6 * overshoot;
        }
        score += 4.2 * (nxt / cap) * norm_pr;
        // Stranded sliver: residual too small relative to next item
        let stranded = pr / nxt.max(1.0);
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
    }

    // Three-step anticipation: exact exhaustion by next item
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 12.0 * (1.0 - progress);
    }

    // Last-chance bin bonus (real bins only)
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 34.0 * (1.0 - norm_pr * norm_pr);
    }

    // Congestion: many open bins -> consolidate aggressively
    score += 0.10 * (open_bins_count as f64).ln().max(0.0) * pr * (1.0 - progress);

    // Waste-avoidance: residual too small for typical items
    if post_residual > 0 && post_residual < 12 && next_item_size as u32 > post_residual {
        score += 7.0;
    }

    // Fragmentation guard
    if post_residual > 0 && post_residual < item * 0.5 && next_item_size as u32 > post_residual {
        score += 5.0 * (1.0 - progress);
    }

    // Mean-residual alignment bonus (from best heuristic)
    if post_residual > 0 {
        let align = 1.0 - ((pr - mean_residual).abs() / cap);
        if align > 0.9 {
            score -= 5.0 * (align - 0.9) * 10.0;
        }
    }

    // New-bin candidate: reluctant by default, attractive only on poor fits
    if bin_residual == bin_capacity {
        score += 26.0 + 13.0 * progress;
        if fitting_bins_count >= 1 {
            let poor_fit = pr > 40.0
                || (nxt > pr && pr > 25.0)
                || (nxt > cap * 0.6 && pr > 20.0)
                || item > cap * 0.85
                || (nxt > pr && fitting_bins_count <= 2 && pr > 15.0)
                || (item > cap * 0.5 && pr < item * 0.4 && fitting_bins_count <= 2)
                || (nxt > pr + cap * 0.3 && pr > 18.0);
            if poor_fit {
                score -= 44.0;
            }
        }
        // early stream with few bins: opening fresh is cheaper than fragmenting
        if progress < 0.15 && open_bins_count <= 3 && pr > 30.0 {
            score -= 12.0;
        }
        // late stream: strongly prefer consolidating into open bins
        if progress > 0.85 && fitting_bins_count >= 1 {
            score += 18.0;
        }
        // many open bins and small item: keep using existing space
        if open_bins_count > 4 && item <= mean_residual {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest item (1..10) are pure waste. Penalize the
    // "unusable gap" band hardest; a residual of 0 is perfect.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        // Dead space: smaller gap = more wasted fraction, penalize strongly.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 25 {
        // Awkward medium gap: mildly penalize.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward bins whose residual tightly matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 25.0 - gap * 2.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        // Post residual unusable for the known next item: extra penalty.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already "cramped"; filling it further is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.3;
    }

    // New-bin candidate handling: a fresh empty bin should only win when
    // no open bin offers a decent fit. Give it a moderate baseline so it
    // beats only very poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits snugly into post_residual (tight, low waste)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // reward tight fits, penalize proportionally to leftover slack
        score -= 25.0 * (1.0 - slack / 40.0).max(0.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow in this bin: penalize dead space creation
        score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (denser packing)
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if no open bin is a decent fit
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // but if current bin would leave large dead space, new bin becomes competitive
        if post_residual > 25 {
            score -= (post_residual as f64 - 25.0) * 0.9;
        }
        // early in stream, allow opening bins more freely
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // many open bins with high mean residual: discourage new bins
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.4;
        }
    }

    // penalize very small unusable leftovers
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize awkward dead space (post residual too small to be useful later)
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else { 0.0 };
        score += 15.0 * dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // penalize leaving a residual that wastes capacity relative to next item
            let waste_gap = (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.15 * waste_gap;
        }
    }

    // New-bin candidate handling: make it moderately attractive only when open bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        // base penalty so open bins are preferred unless they're bad
        score += 35.0;
        score -= 0.5 * avg_fit_gap;
        // late in stream, prefer filling existing bins more strongly
        score += 30.0 * progress;
        // many open bins with large mean residual -> avoid opening more
        if mean_residual > item_size as f64 + 10.0 {
            score += 20.0;
        }
    }

    // Mild preference for bins with smaller residuals among fitting bins
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight bonus for using bins when many are open (consolidation)
    if open_bins_count > 5 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits via smooth cubic coupling of post_residual with capacity
    let tightness = 1.0 - (post / cap);
    score -= 14.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 16.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: reward if next item can also fit into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (nxt / post.max(1.0)));
        } else {
            // penalize creating residual that strands the next item, more so early on
            score += 4.0 * (1.0 - progress) * (1.0 - post / cap);
        }
    }

    // New-bin candidate: add a barrier so it only wins when open bins fit poorly;
    // barrier softens as the stream progresses (consolidate late, expand early)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 9.0 + 18.0 * progress;
    } else {
        score -= 4.0;
    }

    // Penalize residual far above the fleet mean (dead-space smoothing)
    score += 0.12 * (post - mean_residual);

    // Mild pressure against bin sprawl
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
