pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Harmonic class of post_residual: dead space that no future item can fill.
    // Items >= 10 (classic regime): residues < 10 are pure waste; residues that
    // are multiples of 10 are "reusable" classes.
    let residue_class = post_residual % 10;
    if post_residual < 10 {
        // Perfect-fill-ish bin: reward strongly.
        score -= 12.0;
    } else if residue_class == 0 {
        // Round residue: potentially reusable by a future item.
        score -= 2.5;
    } else {
        // Non-reusable dead space: penalize proportionally to how dead it is.
        score += residue_class as f64 * 0.6;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly bin: reward, more so for tighter chains.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 6.0 - chain_tightness * 0.05;
        } else {
            // Next item won't chain here; if residue is awkward, penalize a bit.
            if post_residual > 0 && post_residual < next_item_size {
                score += 1.5;
            }
        }
    }

    // Integer-division thresholds on post_residual: coarse capacity fractions.
    if post_residual <= bin_capacity / 4 {
        score -= 4.0; // nearly full bin, excellent
    } else if post_residual <= bin_capacity / 2 {
        score -= 1.0; // moderately full
    } else if post_residual > (3 * bin_capacity) / 4 {
        score += 3.0; // leaving a big hole
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items that would leave
        // an awkward residue elsewhere, or when open bins are already crowded.
        let item_fraction = item_size as f64 / bin_capacity as f64;
        let mut new_bin_bonus = 0.0;
        if item_fraction > 0.7 {
            new_bin_bonus += 5.0; // big item pairs well with a fresh bin
        }
        // If current open bins have small mean residual (well-filled), opening
        // a new bin is cheap; if mean residual is large, prefer reusing.
        new_bin_bonus -= (mean_residual - 30.0).max(0.0) * 0.15;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_bonus -= progress * 3.0;
        // Net: empty bin gets base score = capacity, plus adjustments.
        score = bin_capacity as f64 - new_bin_bonus;
    }

    // Mild pressure against many open bins with slack.
    score += (open_bins_count as f64).ln().max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
