pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=12) are poison; waste is dead capacity. Penalize hard.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 + (12 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        score += 12.0; // small but potentially usable gap
    } else {
        // Reward near-perfect fits (tight packing) proportionally
        score -= (bin_capacity as f64 - post_residual as f64) * 0.15;
    }

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Open-bins pressure: prefer already-open bins over opening new ones,
    // but the pressure must be weak enough that a bad fit in an open bin
    // (dead space) still loses to a fresh empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin candidate: mild penalty so existing decent fits win,
        // but no dead-space penalty applies since post_residual is large.
        score += 8.0 + open_bins_count as f64 * 0.5;
    } else {
        score -= 6.0; // bonus for reusing an open bin
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible, handled above).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward chaining; if next item would waste this residual, slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: bins far below the mean residual are better
    // targets for filling (they are already "committed" space).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, favor closing
    // out existing bins rather than proliferating new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: perfect match with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 800.0;
        } else if post_residual as f64 > nxt {
            score -= 200.0 * (nxt / post_residual as f64);
        } else {
            // Dead space the next item can't use: penalize proportionally.
            score += 150.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        }
    }

    // Compare residual against mean residual across open bins.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin early in the stream less, later more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if the next item fits in the post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward if next item nearly fills the residual too.
        let next_gap = post_residual - next_item_size;
        if next_gap <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for next item (dead space risk).
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are crowded
    // or the item is large and fits would be very loose.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 * mean_residual < item_size as f64 * 2.0;
        if crowded || (fitting_bins_count > 0 && (bin_residual - item_size) as f64 > mean_residual + 20.0) {
            score -= 20.0 + 30.0 * (1.0 - progress);
        } else {
            // Prefer reusing an existing bin early on.
            score += 35.0 + 25.0 * (1.0 - progress);
        }
    }

    // Global pressure: many open bins with large mean residual -> consolidate, penalize loose fits.
    if open_bins_count > 3 {
        let waste = (post_residual as f64 - mean_residual).abs();
        score += waste * 0.15;
    }

    // Reward placing large items into bins that would otherwise strand small residual.
    if item_size >= 60 && post_residual <= 15 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    let mut score = pr;

    // Non-linear coupling: reward tight fits more strongly as stream progresses
    let tight_reward = tightness.powi(3) * cap * (0.5 + progress);
    score -= tight_reward;

    // Penalize large dead space quadratically, scaled by mean residual divergence
    let dead = pr / cap;
    score += dead * dead * cap * 0.3;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.6 + 0.4 * progress);
    }

    // Lookahead coupling: bonus if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= cap * (1.0 - slack).powi(2) * 0.4;
        } else {
            score += cap * 0.2 * (1.0 - pr / nxt);
        }
    }

    // Mild penalty when bin residual deviates far from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.15;

    // Encourage consolidation: fewer open bins relative to progress is fine,
    // but penalize spreading when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues in [0,10) are near-unusable dead space.
    let dead = post_residual < 10;
    if dead {
        score -= 60.0; // filling to near-full is excellent
    } else if post_residual == 0 {
        score -= 120.0; // perfect fill
    } else {
        // Penalize post_residuals that no future item (min size 1) can use well:
        // classes by integer division: 10..25 hard to fill, 25..50 medium, 50+ easy.
        let class = post_residual / 25;
        score += match class {
            0 => 15.0,           // 10..24: awkward gap
            1 => 5.0,            // 25..49
            _ => 0.0,            // 50+: still useful
        };
        // Modulo-10 harmonic: multiples of 10 pair well with typical item sizes.
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead compatibility: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 40.0; // near-exact two-item chain
            } else {
                score -= (gap as f64).recip() * 10.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty for tight bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class
    // or when many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = (mean_residual - post_residual as f64).abs();
        // Base cost of a fresh bin, discounted if existing fit is terrible.
        score += 55.0 - 25.0 * frag / cap - 10.0 * progress;
        if dead || post_residual == 0 {
            score += 80.0; // never open new when we can fill a bin tightly
        }
    }

    // Prefer packing into bins with below-mean residual (balance conservation).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Hard penalty for unusable dead space: gaps too small for any item (min size 1..10 range unknown, use 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Moderate penalty for small-ish gaps that likely become dead space
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
        // But if this bin is the only fitting option, prefer reusing it
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the gap; penalize leaving it
        score += (post_residual as f64) * 0.3;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild stream progression: later in stream, be more conservative with new bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny unusable gaps penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Gaps that can't fit the lookahead item are waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        score += 25.0 + 10.0 * (1.0 - stranded);
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Exactly enough room for lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }
    // Lookahead fits snugly (within one extra next-item).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        score -= 25.0 + 15.0 * snug;
    }
    // Room for at least two more lookahead items.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (1.0 + progress);
    score += open_pressure * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize deviation from fleet mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= item_size;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score = 20.0 - item_size as f64; // open new bin early when lookahead fits
        } else if lookahead_fits {
            score = 35.0 - item_size as f64;
        } else {
            // Prefer existing bins when opening would strand capacity.
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score = 55.0 + 0.25 * slack + 2.0 * (open_bins_count.min(10) as f64);
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
        // Early stream: opening fresh bins is cheaper.
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
    } else {
        // Waste-ratio signals on existing bins.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.08 {
            score -= 12.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-range dead space that next item overshoots slightly: penalize.
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Alignment bonus near mean residual.
        if post_residual > 0 {
            let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity.max(1) as f64);
            if align > 0.9 {
                score -= 5.0 * (align - 0.9) * 10.0;
            }
        }
        // Late-stream squeeze: prefer filling bins tightly.
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // Half-mean or less leftover late: attractive target.
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0; // reward tight chains, decay with slack
    }
    // Post-residual too small for the next item: dead space penalty unless residual is tiny.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 10.0 {
            score -= 50.0 - waste * 5.0; // small crumbs are fine
        } else {
            score += waste * 0.5; // stranded capacity
        }
    }

    // Last chance: only this bin can fit the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild late-stream bias: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Slight bonus for filling bins deeply (low post-residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual.max(0.0) * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward small residual
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack * 0.2);
        } else {
            // Next item won't fit here; mild penalty scaled by overflow.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    } else {
        // Last item: maximize fill aggressively.
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits via tie-break pressure.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Prefer bins below mean residual (fills the emptier bins first, keeping tight bins for big items).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Time horizon: early in the stream, keep flexibility (penalize very small residuals);
    // late in the stream, prioritize closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let urgency = t * t;
    score -= urgency * (bin_capacity as f64 - post_residual as f64) * 0.3;
    score += (1.0 - t) * (post_residual as f64) * 0.2;

    // Many open bins: encourage consolidation into fewer bins.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (post_residual as f64) > bin_capacity as f64 * 0.5 && fitting_bins_count <= 1;
        if desperate {
            score -= 45.0;
        } else {
            score += 30.0; // keep items in open bins when reasonable fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
