pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits the post-residual, scaled smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (norm_pr - norm_next) * (1.0 - norm_next);
        score -= 20.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 10.0 * norm_next * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Penalize bins deviating from mean residual (keep residuals balanced)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate handling: penalize empty bins mildly early, more when tight fits exist elsewhere
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * progress * (1.0 - norm_item);
    }

    // Mild penalty for many open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common item
    // size classes (multiples of 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr == 0 {
        reusability += 40.0; // perfect fit, ideal
    } else {
        if pr % 10 == 0 { reusability += 8.0; }
        if pr % 20 == 0 { reusability += 6.0; }
        if pr % 25 == 0 { reusability += 5.0; }
        if pr % 50 == 0 { reusability += 4.0; }
        // Integer-division thresholds: how many "typical" items still fit
        let slots_small = pr / 20;
        reusability += (slots_small.min(5)) as f64 * 2.0;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain fit
        } else if pr >= next_item_size {
            let diff = pr - next_item_size;
            if diff % 10 == 0 { score -= 8.0; }
            score -= (10.0 - (diff as f64 / 10.0).min(10.0)) * 0.5;
        } else {
            // next item cannot use this bin's leftover at all
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating dead space below the minimum item size (1..100 range,
    // but typical small items ~10): leftover < 10 is nearly unusable.
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    // Progress-aware tightness: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= reusability * (0.5 + 0.5 * progress);

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    score -= (bin_residual - item_size) as f64 * 0.05 * (open_bins_count.min(20) as f64 / 20.0);

    // Slight bias toward bins whose residual deviates favorably from mean.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual waste otherwise).
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score = waste as f64 + 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can chain large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading into many bins when few fit.
    if fitting_bins_count == 1 {
        score -= 15.0; // last chance: strongly prefer using this bin
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless the item barely fits anywhere
    // or the fit into existing bins would create large dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 70 {
            score -= 10.0; // very large items: new bin is fine
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space relative to the next item
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
