pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chain match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight fits, penalize loose ones non-linearly
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 50.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter packing)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong incentive to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize creating tiny unusable dead space (below minimum item size 1..100 heuristic: < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Mild preference to fill existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new bin candidate: penalize more as stream progresses
        score += 30.0 + 40.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1200.0;
    }
    // Near-perfect match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward chains that can also hold a second copy of the next item.
        let double = post_residual >= 2 * next_item_size;
        score -= if double { 260.0 } else { 220.0 } - slack * 2.5;
    }
    // Post-residual too small for the next item: dead space penalty unless residual is tiny.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 10.0 {
            score -= 60.0 - waste * 5.0; // small crumbs are fine
        } else {
            score += waste * 0.6; // stranded capacity
        }
    }

    // Last chance: only this bin can fit the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 350.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Mild late-stream bias: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.25;

    // Slight bonus for filling bins deeply (low post-residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // New-bin candidate: attractive only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0
            && fitting_bins_count > 0
            && mean_residual > 0.0
            && mean_residual < (bin_capacity as f64) * 0.25;
        let base = if tight_fit_exists { 40.0 } else { 20.0 };
        score += base + mean_residual.max(0.0) * 0.1;
        // Early stream: opening bins is cheap; late stream: avoid fragmentation.
        if progress > 0.8 {
            score += 15.0 * (progress - 0.8) / 0.2;
        }
    }

    // Zero post-residual is ideal: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits non-linearly (squared dead-space penalty).
    score += (post_residual as f64 / cap) * (post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize leaving a residual that fits next_item_size badly —
    // ideal leftover is either 0 or something next item cannot use efficiently.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            // next item could fit here; leaving exactly enough is great,
            // leaving a bit more than nx wastes space.
            let slack = pr - nx;
            score -= 10.0 - slack.min(10.0) * 0.8;
        } else {
            // leftover too small for next item: mild penalty proportional to waste
            score += pr * 0.15;
        }
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // (poor fit likely elsewhere) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Base handicap for opening a new bin.
        let mut nb = 55.0;
        // Large items justify fresh bins; small items do not.
        nb -= (item_frac - 0.5).max(0.0) * 80.0;
        // Late in stream / many bins: consolidating matters more, raise handicap.
        nb += progress * 15.0 + (open_bins_count as f64).ln().max(0.0) * 5.0;
        score += nb.max(5.0);
    } else {
        // Prefer bins whose residual deviates from mean (harvest outliers first)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.1;
        // Slight preference for fuller bins when many are open.
        score += (open_bins_count as f64).sqrt() * 0.3;
    }

    // Time-horizon coupling: early on, be exploratory (favor diversity of residual
    // profiles by softening tight-fit pressure); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.25 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let snug = 1.0 - slack / post_residual.max(1) as f64;
            score -= 200.0 * snug;
            // residual can hold two more of next item: extra attractive
            if post_residual >= 2 * next_item_size {
                score -= 7.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 50.0 * (gap / cap).min(1.0);
            // stranded small residual that next item can't use
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
    }

    // Relative to mean residual
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space penalties, graded
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // New-bin candidate logic
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0; // allow opening a fresh bin when it's the only sensible option
        } else {
            score += 30.0 + 40.0 * progress + 2.0 * (open_bins_count.min(10) as f64);
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
    } else {
        score -= 20.0 * progress;
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio < 0.08 {
            score -= 12.0;
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 11.0;
        }
        // mid-range dead space that next item can't use: penalize
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // alignment with mean residual
        let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap);
        if align > 0.9 {
            score -= 5.0 * (align - 0.9) * 10.0;
        }
    }

    // Late-stream: squeeze residual tightly
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 4.0; // peaks mid-residual
    let mut score = pr - poly * cap * (0.35 + 0.65 * progress);

    // Penalize waste more as stream advances (less time to recover dead space)
    score += norm_pr * norm_pr * cap * progress * 1.2;

    // Reward tight fits
    score -= (1.0 - norm_pr) * 2.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 2.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr) / cap * 2.0;
    }

    // New-bin candidate: prefer it only when progress is low or fits are poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 4.0 - 6.0 * pressure - 3.0 * progress;
    }

    // Mild preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.1 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
