pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits post-residual tightly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 - 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 40.0 + 0.35 * next_item_size as f64 + 15.0 * snug;
        } else {
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: use the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Small dead-space handling: graded instead of flat penalty
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 25.0;
        } else if post_residual < 20 {
            score -= 8.0;
        }
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 55.0 + 0.25 * slack + 40.0 * progress + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
    } else {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio < 0.08 {
            score -= 12.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }

        // Penalize stranded space the next item can't use
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }

        // Reward residual that can host two more next-size items
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.0;
        }

        // Reward near-mean residual alignment
        if post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 3.0 {
            score -= 3.0;
        }

        // Tight two-fit check
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = post_residual >= 2 * next_item_size
                || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }

        // Endgame: squeeze remaining small items into tight residuals
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // exact-fit / near-exact fit bonus
        if pr <= 4 {
            score -= 40.0;
        }
        // residue classes that future items (1..=100) commonly fill well
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 80] {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
        // penalize awkward dead zones: small but not tiny leftovers
        if pr < 10 {
            score += 8.0; // unusable sliver
        } else if pr <= 25 {
            score -= 4.0; // still fillable by small items
        }
        // integer division threshold: leftover that can host a half-capacity item
        if pr >= bin_capacity / 2 {
            score -= 5.0;
        } else if pr >= bin_capacity / 4 {
            score -= 2.0;
        }
    } else {
        score -= 60.0; // perfect closure
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // harmonic match: leftover exactly fits next item
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0; // dead space that next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding: with many open bins, prefer tight packing over spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - progress);

    // Prefer bins below mean residual (tighter bins) early on
    score += 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are effectively unusable; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 2.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small but usable residuals are still risky: mild penalty scaled by gap tightness.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + pressure * 5.0;
    } else {
        score -= pressure.min(15.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement; if post residual cannot fit the next item
    // but next item is small, mild penalty for wasting the gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness measured against post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 40.0 + 0.35 * next_item_size as f64 + 15.0 * snug;
            // room for two more copies of next item
            if post_residual >= 2 * next_item_size {
                score -= 7.0;
            }
        } else {
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
            // stranded small dead space the next item overshoots
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
    }

    // Prefer bins with residual below mean
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping: tiny residuals are valuable only if next item matches
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 {
        score -= 8.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 35.0;
        } else if lookahead_fits && progress < 0.25 {
            score -= 18.0 * (1.0 - progress / 0.25);
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 55.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64 + 40.0 * progress;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
    } else {
        let waste_ratio = post_residual as f64 / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 11.0;
        } else if waste_ratio > 0.6 && (item_size as f64) > mean_residual {
            score += 6.0;
        }
        // mid-range dead space that next item overshoots
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // alignment with mean residual
        if post_residual > 0 {
            let align = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap);
            if align > 0.9 {
                score -= 5.0 * (align - 0.9) * 10.0;
            }
        }
        // late stream: close near-full bins aggressively
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact match bonus (chained fit is highly desirable).
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize creating dead space that cannot host the next item.
            let waste = next_item_size - post_residual;
            score += 8.0 + waste as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Prefer bins already below the mean residual (consolidating small residuals).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for keeping more bins closed when many are open.
    score += open_bins_count as f64 * 0.1;

    // Penalize very small unusable post-residuals (dead space < typical min item).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate: neutral baseline; only chosen if all open bins score worse.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize small post-residuals that become dead space (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty scaled by how much it misses.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).min(1.0);
    }

    // Global state: when many bins are open with high mean residual, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are fragmented and stream is early.
        score += 20.0 + 30.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if mean residual is small (existing bins nearly full), new bin is attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 45.0;
    } else {
        // Favor bins with residual below the mean (denser bins first).
        score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-1.0).min(1.0);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) - norm_post * progress * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_post;
    score -= tight * tight * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit even a small item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward residual that still accommodates next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress * norm_post;

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: perfect fits (residual 0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: residual that no plausible item (>=1) can use is fine,
    // but residual in awkward bands (just above small item sizes) is bad.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 40.0; // unusable sliver
    }

    // Modulo-class logic: residuals divisible by common item sizes (10,20,25,50)
    // are reusable -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 30.0; }
        else if post_residual % 25 == 0 { score -= 20.0; }
        else if post_residual % 20 == 0 { score -= 15.0; }
        else { score += 10.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0;
        } else {
            // next item can't fit here; penalize small post_residual more
            score += 25.0;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 100.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin when item is small,
    // reward when item is large and no good open bin exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 40.0;
        } else {
            score += 120.0 * (1.0 - frac);
        }
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Late stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
