pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1200.0;
    }
    // Near-perfect match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let double = post_residual >= 2 * next_item_size;
        // Snugness coupling: reward tight chains more aggressively.
        let snug = 1.0 - slack / post_residual.max(1) as f64;
        score -= (if double { 260.0 } else { 220.0 }) * (0.8 + 0.4 * snug) - slack * 2.5;
    }
    // Post-residual too small for the next item: dead space penalty unless residual is tiny.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 10.0 {
            score -= 60.0 - waste * 5.0; // small crumbs are fine
        } else {
            // Penalize stranded capacity proportional to how much the next item overshoots.
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += waste * 0.6 + 10.0 * overshoot;
        }
    }

    // Last chance: only this bin can fit the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 350.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Mild late-stream bias: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.25;

    // Slight bonus for filling bins deeply (low post-residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Zero post-residual is ideal: strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // New-bin candidate: attractive only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0
            && fitting_bins_count > 0
            && mean_residual > 0.0
            && mean_residual < (bin_capacity as f64) * 0.25;
        let base = if tight_fit_exists { 40.0 } else { 20.0 };
        score += base + mean_residual.max(0.0) * 0.1;
        // Early stream: opening bins is cheap; late stream: avoid fragmentation.
        if progress > 0.8 {
            score += 15.0 * (progress - 0.8) / 0.2;
        }
        // Early stream nudge: allow fresh bins when they will chain well.
        if progress < 0.25 && next_item_size > 0 && next_item_size <= item_size {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
    } else {
        // Dead-space band penalty: mid-sized leftover space is the worst outcome.
        let dead = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead > 0.25 && dead < 0.65 {
            let band = (dead - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Very low waste with scarce alternatives: strong reward.
        if dead < 0.04 && fitting_bins_count <= 2 {
            score -= 11.0;
        }
    }

    // Late stream: prefer closing bins with unusable crumbs.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
