pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize if next item cannot fit here either way (dead space trap)
        if next_item_size as f64 > post_residual as f64 {
            score += 12.0;
        }
        // Reward leaving room for next item even if not exact
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average (good fits)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small unusable post residual (dead space) unless it's near zero
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Slight preference for filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but a perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space relative to the smallest possible future item (1..100 interface).
        let dead_ratio = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * dead_ratio * dead_ratio;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (creates a chain of tight placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.05 * slack;
        } else {
            // Next item cannot use this bin's remainder; mild penalty scaled by waste.
            score += 0.02 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terribly wasteful).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin wastes all existing residual.
    // Penalize opening new bins in proportion to total open residual capacity,
    // unless open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let total_open_residual = mean_residual * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream: prefer filling existing bins; late: new bins are fine.
        score += 15.0 + 0.1 * total_open_residual - 10.0 * progress;
    }

    // Slight preference for bins below mean residual (balance the portfolio),
    // keeping mid-sized holes usable.
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.03 * deviation;

    // Fragmentation guard: remainder that no plausible item (>=1) fits well.
    if post_residual > 0 && post_residual < 5 {
        score -= 6.0; // tiny remainder is nearly a perfect fill anyway
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let snug = 1.0 - slack / post_residual.max(1) as f64;
        // reward tight chains, decay with slack; scale with next item size
        score -= 120.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        // two consecutive fits: keep capacity for repeated next items
        if post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
    }
    // Post-residual too small for the next item: dead space penalty unless residual is tiny.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 10.0 {
            score -= 50.0 - waste * 5.0; // small crumbs are fine
        } else {
            // stranded capacity: penalize proportionally to how much of next item it wastes
            let gap_ratio = next_item_size as f64 / waste;
            score += waste * 0.5 + 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
    }

    // Last chance: only this bin can fit the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild late-stream bias: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Slight bonus for filling bins deeply (low post-residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Exact-fill crumbs: post_residual == 0 is perfect, reward strongly.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
        // early stream: opening a bin is cheaper
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // mid-band dead space with unusable remainder for next item
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // leftover after next item nearly empty
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
        }
        // stranded unusable sliver relative to next item
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
