}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: post residual, non-linearly scaled
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Tight fits rewarded strongly (smooth polynomial in fit_ratio)
    score -= 30.0 * fit_ratio * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals too small for any future item
    let small_floor = 9.0;
    let dead = (small_floor - pr).max(0.0);
    score += 2.5 * dead * dead / cap * 10.0;

    // Lookahead coupling: prefer leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let covers = if pr >= nx { 1.0 } else { 0.0 };
        score -= 18.0 * covers * (1.0 - gap / cap);
        score += 8.0 * (1.0 - covers) * (nx / cap);
    }

    // Stream progress: early on, be pickier (penalize loose fits); later, consolidate
    let pickiness = (1.0 - progress) * (1.0 - progress);
    score += 20.0 * pickiness * pr_norm;
    score -= 10.0 * progress * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean residual coupling: avoid bins far from the fleet average (keeps residual distribution tight)
    score += 0.4 * (pr - mean_residual).abs();

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: exact fills (class 0) are gold.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes on post_residual (harmonic bands of capacity/8)
        let band = (post_residual % 8) as f64;
        score -= (8.0 - band) * 0.75; // prefer residuals near a class boundary

        // Integer-division thresholds: residual divisible by common item sizes
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }

        // Dead-space penalty: residual too small for the minimum item (1..100 interface)
        if post_residual < 10 && post_residual > 0 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 15.0 * (20.0 - pr) / 10.0;
        }

        // Lookahead coupling: does the residual land in a class usable by next item?
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 200.0; // chains perfectly
            } else if post_residual >= next_item_size {
                let slack = post_residual - next_item_size;
                score -= 20.0 + (slack as f64).min(30.0);
            } else {
                score += 25.0; // next item can't use this bin's leftover
            }
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Tight-fit reward relative to capacity fraction
    let fill_frac = isz / cap;
    score -= fill_frac * 30.0;

    // Mean residual coupling: prefer bins deviating below mean (consolidate)
    score += (mean_residual - pr) * 0.5;

    // Progress pressure: late in stream, prefer closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 15 {
        score -= 25.0 * progress;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = cap * 0.9 + pressure * 80.0 + (open_bins_count as f64) * 2.0
              - if next_item_size > 0 && next_item_size >= item_size { 15.0 } else { 0.0 };
    }

    score
}

