pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small, likely-unusable gap: penalize superlinearly.
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    } else {
        // Usable leftover: reward proportionally (tight fit preferred).
        score -= (post_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual was already small (compaction).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it early or when this bin is the last chance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized as bins accumulate.
        score += 10.0 + open_bins_count as f64 * 4.0 * (0.3 + progress);
    } else if fitting_bins_count == 1 {
        // Last chance: strongly prefer using this bin over a new one.
        score -= 40.0;
    }

    // Slight preference for bins below the mean residual (balancing).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, but penalize exact fills slightly less.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = post_residual - next_item_size;
        if match_gap == 0 {
            score -= 30.0; // perfect chain: this item leaves exactly the next item's size
        } else {
            score -= 15.0 * (1.0 - match_gap as f64 / (bin_capacity as f64));
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin's remainder; penalize wasted space proportionally.
        score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fitting bins exist, unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 10.0 + 0.3 * waste * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size && next_item_size >= 10 {
            score -= 8.0; // new bin can still chain with next item
        }
    }

    // Late in the stream: consolidate harder, avoid fragmenting residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is nearly consumed.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tight * tight;

    // Penalize large dead space, especially when it can't fit the average item.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let unusable = if next_item_size > 0 && next_item_size <= bin_capacity {
            if (next_item_size as f64) > dead { dead } else { 0.0 }
        } else {
            dead * 0.3
        };
        score += 1.8 * unusable;
        // Non-linear penalty for awkward residuals (mid-range waste).
        let frac = dead / bin_capacity as f64;
        score += 25.0 * frac * (1.0 - frac) * 4.0 * (1.0 - tight);
    }

    // Lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow gap.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: many open bins -> prefer consolidation into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln1p();
    score -= 3.0 * crowding * (1.0 - t);

    // Mean residual coupling: if this bin's residual is far above mean, it's a wasteful choice.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.15 * dev * dev.signum() * dev.abs().sqrt();

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and spreading is cheap.
    if bin_residual == bin_capacity {
        let spread_urge = (1.0 - t) * 10.0
            - (fitting_bins_count as f64) * 6.0
            - crowding * 4.0;
        // A new bin starts with residual = capacity - item_size, already in `score`;
        // adjust its base attractiveness.
        score += 18.0 - spread_urge;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // fresh bin likely useful for the lookahead too
        }
    }

    // Small dynamic time-horizon term: later in the stream, be greedier about tight fits.
    score -= 20.0 * t * (1.0 - res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaled by item size
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post.max(1.0);
            score -= (30.0 + 0.35 * next_item_size as f64) * (0.5 + 0.5 * snug);
            // room for a second copy of next item: strong keep-open signal
            if post_residual >= 2 * next_item_size {
                score -= 8.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // penalize stranded slivers the next item can't use
            let stranded = post / (next_item_size as f64).max(1.0);
            score += 50.0 * (gap / cap).min(1.0);
            if post_residual > 0 && stranded < 0.5 {
                score += 6.0 * (1.0 - stranded);
            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping: small leftovers are often usable, very tiny ones are not
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // tiny slivers: prefer consuming them now (post=0 gets -1000 anyway)
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 6.0;
    }

    // Mid-band dead space penalty when next item overshoots
    let dead = post / cap;
    if dead > 0.33 && dead < 0.57 && next_item_size > 0 && next_item_size > post_residual {
        let overshoot = (next_item_size - post_residual) as f64 / (next_item_size as f64).max(1.0);
        score += 6.0 + 8.0 * overshoot;
    }

    // New-bin decision: penalize more as stream progresses, unless lookahead fits and bins are scarce
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            score += 30.0 + 40.0 * progress + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
        }
    } else {
        score -= 20.0 * progress;
        // near-perfect fills get extra reward when bins are scarce
        if post_residual > 0 && dead < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    // Endgame: squeeze hard
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post <= mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize wasted residual, non-linearly (quartic-ish growth of dead space).
    let mut score = pr * (1.0 + (pr / cap).powi(3));

    // Smooth coupling: residual waste matters more as the stream progresses.
    score += 12.0 * progress * (pr / cap) * (pr / cap);

    // Reward tight fits (small post_residual) with a smooth decay term.
    score -= 10.0 * (-(pr / cap)).exp();

    // Lookahead: reward leaving space that can hold the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let snug = 1.0 - ((pr - ns) / cap).powi(2);
            score -= 8.0 * snug.max(0.0);
        } else {
            // Penalize residuals that strand the next item, smoothly.
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: make it attractive early, and when the fit is poor;
    // discourage it late when open bins exist and fit well.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap).powi(2);
        score -= 20.0 * (1.0 - progress) * (1.0 - poor_fit);
        score += 5.0 * progress;
    }

    // Mild pressure to consolidate: prefer bins below mean residual (tighter bins).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
