        // if many open bins can fit, new bin is wasteful
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // if a perfect-ish fit exists elsewhere (post_residual small), new bin should lose
        if post_residual <= 10 {
            score += 40.0;
        }
    }

    // Prefer consolidating into bins below mean residual (tighter bins first)
    let mr = mean_residual;
    if (bin_residual as f64) < mr {
        score -= 6.0;
    } else if (bin_residual as f64) > mr * 1.5 {
        score += 4.0;
    }

    // Integer-division threshold: bins whose residual is in the "one more medium item" band
    let band = bin_residual / 25; // 0..4 harmonic quartile of remaining space
    match band {
        0 => score -= 10.0, // nearly full: use it now
        1 => score -= 2.0,
        2 => score += 0.0,
        _ => score += 5.0,  // too empty, save for bigger items
    }

    // Slight preference for fewer open bins when many are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A residual that cannot fit the minimum item (1..100 unknown, use conservative
    // small-gap band) is wasted capacity; the smaller the gap, the worse.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 4.0;
    }

    // Reward tight fits: exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty scaled by how much of the bin is left as a sliver
    // relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    if dead_frac > 0.0 && dead_frac < 0.15 {
        score += (0.15 - dead_frac) * 200.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones (penalize new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 0.8;
    } else {
        score -= pressure * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score -= 10.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in leftover: leftover becomes dead space for lookahead.
        score += 8.0;
    }

    // Prefer bins whose residual is already below mean (filling down the mean).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 20.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 220.0 * snug + 0.35 * next_item_size as f64;
            let leftover = post_residual - next_item_size;
            if leftover as f64 <= 0.05 * cap {
                score -= 5.0 * (1.0 - leftover as f64 / (0.05 * cap));
            }
            // leftover close to mean residual keeps the bin reusable
            let lr = leftover as f64 / cap;
            if lr < 0.5 && (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.25 {
                score -= 3.5;
            }
            // two-fit lookahead
            if post_residual >= 2 * next_item_size {
                score -= 8.0;
            }
        } else {
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 40.0 * gap_ratio.min(1.0);
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping (borrowed from best: small residuals are valuable)
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 26.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0;
    }

    // Stranded-space penalty
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        let unusable = dead_space - (next_item_size as f64 / cap);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
    }

    // Mid-band dead space penalty (awkward ~half-empty residuals)
    if dead_space > 0.25 && dead_space < 0.65 && next_item_size > post_residual {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }
    // wide mid-band penalty even when next fits
    if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size <= post_residual {
        score += 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            // a fresh bin whose post-residual snugly hosts next item is ok
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        score -= 20.0 * progress;
        // Very tight post-fit reward when bins are scarce
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // reward residuals that leave a useful remainder near mean residual
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
        }
        // large waste with big item: penalize extra when open bins few
        if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0 + 4.0 * (fitting_bins_count.min(3) as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is the best possible outcome: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward bins whose post_residual can host the NEXT item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Chain of two perfect fits.
            score -= 900.0;
        } else if post_residual >= next_item_size {
            // Next item fits; smaller leftover slack is better (tight packing).
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack_after_next * 0.8;
        } else {
            // Next item won't fit in this bin after placement: penalize wasted
            // dead space relative to the next item's size.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Penalize leaving residuals that are unlikely usable (small but nonzero).
    if post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when no
    // open bin offers a decent fit. Penalize new-bin use when the fit here
    // is good (post_residual small relative to mean_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 300.0;
        // If existing bins are fragmented (high mean residual), new bin is
        // relatively more acceptable: reduce the penalty.
        score -= mean_residual * 1.2;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 120.0;
    }

    // Mild preference for filling bins that are already low on space,
    // keeping large residuals available for larger future items.
    score += (bin_residual as f64 / bin_capacity as f64) * 30.0;

    // Slight nudge toward bins below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness weighting
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        } else {
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space bands
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    let waste_ratio = post_residual as f64 / cap;
    if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
        score -= 12.0;
    }
    // Reward bins that can fit next item twice
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
    }
    // Stranded small leftover that next item cannot use
    if post_residual > 0 && next_item_size > post_residual && post_residual < 15 {
        score += 6.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless lookahead fits into it and it is scarce
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 37.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 30.0 + 40.0 * progress + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
    } else {
        score -= 20.0 * progress;
    }

    // Late-stream: keep tiny residuals alive
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to bin capacity
    let tightness = post_residual as f64 / bin_capacity as f64; // 0 = perfect fit
    score += 25.0 * tightness * tightness; // quadratic penalty for wasted space

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 25.0 * progress;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - next_fit_quality);
    }
    // If next item would NOT fit post residual but would fit a fresh bin, penalize slightly
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Compare against mean residual across open bins:
    // placing into a bin with residual far below mean is a good consolidation
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / mean_residual;
        score -= 10.0 * dev; // larger residual than mean => slightly favored (uses big holes)
    }

    // Many open bins: encourage filling existing bins rather than spreading
    if open_bins_count > 1 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or when bins are scarce
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0; // no alternative, must open
        }
        // If item is large relative to capacity, a fresh bin is more attractive
        new_bin_cost -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is huge and nothing fits it later, fresh space helps
        if next_item_size > 0 && next_item_size as f64 > 0.8 * bin_capacity as f64 {
            new_bin_cost -= 15.0;
        }
        score += new_bin_cost;
        // Give fresh bin a slight edge for near-perfect large items
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // Small time-horizon jitter to break ties deterministically
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: post residual, non-linearly coupled with stream progress.
    // Early on, prefer tight fills (low post_residual); late, tolerate slack less.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth quadratic penalty on small-but-nonzero dead space (unusable slivers),
    // scaled by how much of the bin the item already consumes.
    let dead = post / cap;
    score += 12.0 * dead * dead * (1.0 - dead) * (0.5 + fit_ratio);

    // Reward exact-ish fits smoothly.
    score -= 6.0 * (1.0 - dead).powi(3) * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - gap / cap) * (0.5 + 0.5 * next_ratio);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Slight preference for filling bins with larger residuals relative to the mean,
    // keeping the bin population balanced via a smooth interaction term.
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap) * (1.0 - progress);

    // Mild penalty on opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus (harmonic class: post_residual in low residues)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into
    // "useful" residue classes (multiples of common item sizes) are preferred.
    let r = post_residual;
    if r % 10 == 0 {
        score -= 8.0; // residual aligns with decimal-grid item sizes
    } else if r % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0; // awkward residual, penalize
    }

    // Integer-division threshold: classify residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = r as f64 / cap;
    if frac < 0.1 {
        score -= 5.0; // nearly full bin: good packing density
    } else if frac > 0.6 {
        score += 6.0; // wasting a mostly-empty bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 500.0;
        } else if next_item_size <= r {
            // next item fits: reward proportional to tightness of the follow-up fit
            let slack = (r - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            // harmonic class of the follow-up residual
            let r2 = r - next_item_size;
            if r2 % 10 == 0 { score -= 6.0; }
            if r2 == 0 { score -= 200.0; }
        } else {
            // next item won't fit here: penalize mildly, more if this is the last fitting bin
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor, non-linear)
    let dev = (r as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev.abs();

    // Stream progression: early on, be more willing to keep bins flexible
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.25 {
        score += 0.15 * r as f64; // keep larger residuals available early
    } else {
        score -= 0.05 * r as f64; // later: consolidate aggressively
    }

    // New-bin candidate: make it moderately attractive only when it beats
    // poor fits; default slightly worse than a tight existing fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if current open bins are all crowded, allow opening
        if mean_residual < 0.25 * cap {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized (non-linear "dead zone" penalty).
    let dead_threshold = 12.0 + 0.08 * (bin_capacity as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits strongly (post_residual near zero).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when fit is poor; mildly penalize using open bins when many exist
    // with high mean residual spread.
    score += open_bins_count as f64 * 0.15;

    // If mean residual is large, open bins have room; prefer consolidating there
    // (subtract from open bins relative to new-bin candidate which has max residual).
    if bin_residual < bin_capacity {
        score -= mean_residual * 0.10;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving residual just barely too small for next item.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate: discourage opening new bins early in the stream,
    // encourage late when open bins are fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
