pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item's size (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0; // but allow fresh bin if it perfectly chains
        }
    }

    // Slight preference late in the stream for compacting
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 18.0;
            // Extra reward if next item nearly fills the remaining space.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // Next item won't fit here; penalize more if it's a big leftover gap.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 {
                score += 4.0 * gap / bin_capacity as f64;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Last-chance bin bonus: only bin that fits the item — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Compare against mean residual: placing into a bin with residual close to item
    // is good; placing into a much-larger-residual bin wastes the big bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer fuller bins (small residual) mildly, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * bin_residual as f64;

    // When many bins are open, encourage consolidating into existing bins
    // rather than opening new ones; when few are open, new bins are cheaper.
    let new_bin_penalty = 8.0 * (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus consolidation pressure.
        score += 20.0 + new_bin_penalty;
        // But if the item is huge relative to typical residuals, a fresh bin is fine.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 15.0;
        }
        // Late in the stream, avoid spawning bins for small items.
        if progress > 0.7 && item_size < 40 {
            score += 10.0;
        }
    }

    // Slight preference to keep open_bins_count from exploding mid-stream.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
