pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis
    let mut score = pr * (1.0 + 0.004 * pr);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, residual space becomes more precious.
    let tightness = (pr / cap).powi(3);
    score += 60.0 * progress * tightness;
    score -= 25.0 * (1.0 - progress) * (1.0 - tightness);

    // Lookahead: reward bins whose post_residual can host the next item,
    // scaled by how much slack remains after that hypothetical placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * (1.0 - chain) * (1.0 + progress);
    } else if next_item_size > post_residual {
        // Dead space relative to the next item grows costly as stream advances
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 22.0 * gap * gap * (0.5 + progress);
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty for leaving residual far from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * progress;

    // Prefer filling bins among many open ones (consolidation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (pr / cap);

    // New-bin candidate: neutral-ish baseline, only attractive when current
    // placements would create bad dead space late in the stream
    if bin_residual == bin_capacity {
        score = cap * (1.05 - 0.35 * progress) + 10.0 * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 (or
    // matching common item sizes) are "usable" classes; odd/prime-ish
    // residuals are dead space. Penalize non-harmonic residuals.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit
    } else {
        let class_bonus = match r % 10 {
            0 => 8.0,
            5 => 4.0,
            _ => 0.0,
        };
        score -= class_bonus;
        // Penalize residuals that cannot fit the smallest plausible item (1..=100 range, use 10 as typical floor)
        if r < 10 {
            score += 25.0;
        }
        // Modulo-based dead-space penalty: residual mod small harmonics
        score += 0.5 * ((r % 7) as f64) + 0.3 * ((r % 13) as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if post_residual is too small for next item but next
    // item could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r {
            score -= 0.4 * (next_item_size as f64);
        } else {
            score += 0.3 * ((next_item_size - r) as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Fraction-of-capacity harmonics: reward placements leaving residuals in
    // "quarter" classes (25/50/75), which pair well with mid-size items.
    let q = r % 25;
    if q == 0 && r > 0 {
        score -= 6.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Prefer denser packing when many bins are open (consolidate).
    score += 0.05 * open_bins_count as f64;

    // Slight drift toward exploiting existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress;

    // New-bin candidate: make an empty bin only attractive when the item is
    // large relative to residual classes of open bins (i.e., poor fits dominate).
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 55.0;
        // but if the item is huge, a fresh bin is fine
        score -= 0.5 * item_size as f64;
    }

    score
}

