pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 20.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            let leftover = post_residual - next_item_size;
            if leftover as f64 <= 0.05 * cap {
                score -= 5.0 * (1.0 - leftover as f64 / (0.05 * cap));
            }
            // closeness of leftover to mean residual: keeps future fits flexible
            let closeness = 1.0 - ((leftover as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        } else {
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 40.0 * gap_ratio.min(1.0);
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 26.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0;
    }

    // Two-fit lookahead: reward residuals that can host the next item twice
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
    }

    // exact-fit for next item within one step
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
    }

    // Stranded-space penalty
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        let unusable = dead_space - (next_item_size as f64 / cap);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
        if post_residual < 15 {
            score += 4.0;
        }
    }

    // Mid-band dead space penalty (awkward ~half-empty residuals)
    if dead_space > 0.25 && dead_space < 0.65 && next_item_size > post_residual {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // New-bin candidate logic
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            // fresh bin whose post-residual can host next item once (not twice): mild reward
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        score -= 20.0 * progress;
        // Very tight post-fit reward when bins are scarce
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        // late-stage: prefer leaving no tiny unusable residual
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // reward residuals that leave a useful remainder near mean residual
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
        // dead-space overshoot penalty in mid band
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (small dead space is exponentially valuable)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 30.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // prefer bins where next item leaves little residual after the 2nd placement
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 10.0 {
                score -= 50.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 40.0 + overshoot * 0.5;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.8; // favor below-average-residual (fuller) bins

    // Last-chance bonus: only bin that fits, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist that fit well
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 - 40.0 * progress; // early stream: new bins cheap; later: prefer reuse
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // opening a new bin is attractive if item is large and no bin leaves a good residual
        if item_size >= bin_capacity / 2 && post_residual < 20 {
            score -= 90.0;
        }
    }

    // Mild penalty for leaving residuals in the "dead zone" (11..30) that rarely fit future items
    if post_residual > 10 && post_residual < 30 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that can never be reused by typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).max(0.0);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 0.6 * (mean_residual - post_residual as f64);

    // Mild penalty for opening a new bin, relaxed over time or when few bins fit the item.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = 30.0 - 12.0 * progress - 2.0 * (open_bins_count as f64);
    if bin_residual == bin_capacity {
        score -= new_bin_bonus.max(-10.0);
    } else {
        score += 2.0;
    }

    // Prefer bins whose residual deviates favorably from mean (below-mean residual = fuller bin).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with a non-linear (quartic) waste curve
    // so mid-range residuals are penalized disproportionately.
    let mut score = pr * (1.0 + 2.0 * x * x * (1.0 - x));

    // Smooth coupling with stream progress: early on, waste matters slightly less
    // (bins can still be topped up later); late in the stream, waste is nearly fatal.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Tight fits are excellent: reward small post residual non-linearly.
    let tightness = (1.0 - x).powi(3);
    score -= 12.0 * tightness * (item_size as f64 / cap);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (otherwise we open a new bin and strand this residual forever).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - x);
    }

    // If the next item would fit perfectly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward, stronger as the fit gets snugger.
        let nx = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * nx * nx;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize leaving a stranded gap,
        // especially when the gap is small-to-mid sized (hard to reuse later).
        let gap = next_item_size as f64 - pr;
        score += 0.15 * gap * (1.0 - x);
    }

    // New-bin candidate: it should generally lose to decent fits, but win when
    // no open bin fits well. Penalize opening a bin proportionally to how many
    // bins are already open and how much mean residual capacity exists.
    if bin_residual == bin_capacity {
        let mean_fill = (cap - mean_residual).max(0.0) / cap;
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt() - 10.0 * mean_fill;
        // Late in the stream, opening a fresh bin is fine since leftovers rarely fill.
        score -= 10.0 * progress;
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 20.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            let leftover = post_residual - next_item_size;
            let leftover_ratio = leftover as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            // closeness of leftover to mean residual: keeps future fits flexible
            let closeness = 1.0 - ((leftover as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        } else {
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 26.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0;
    }

    // Two-fit lookahead: reward residuals that can host the next item twice
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
    }

    // exact-fit for next item within one step
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
    }

    // Stranded-space penalty
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        let unusable = dead_space - (next_item_size as f64 / cap);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
        if post_residual < 15 {
            score += 4.0;
        }
    }

    // Mid-band dead space penalty (awkward ~half-empty residuals)
    if dead_space > 0.25 && dead_space < 0.65 && next_item_size > post_residual {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // New-bin candidate logic
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            // fresh bin whose post-residual can host next item once (not twice): mild reward
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        score -= 20.0 * progress;
        // Very tight post-fit reward when bins are scarce
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        // late-stage: prefer leaving no tiny unusable residual
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // reward residuals that leave a useful remainder near mean residual
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
        // dead-space overshoot penalty in mid band
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // combined: exact next-item match strongly favored when bins are plentiful
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        // avoid leaving residuals just below the next item: near-miss shaping
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..100, so classify leftover
    // by which item-size classes it can still admit.
    let can_fit_next = next_item_size > 0 && post_residual >= next_item_size;
    if can_fit_next {
        // Reward leaving room for the lookahead item: the tighter the fit
        // for the NEXT item, the better (small next-post residual).
        let next_post = post_residual - next_item_size;
        score -= 30.0 + 0.5 * (next_item_size as f64) - 0.3 * (next_post as f64);
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize dead space, scaled by
        // how "wasted" the remainder is relative to capacity quarters.
        let quarter = bin_capacity / 4;
        let dead_class = post_residual % quarter.max(1);
        score += 10.0 + 0.4 * (dead_class as f64);
    }

    // Integer-division threshold classes on post_residual (harmonic bands).
    let band = post_residual / 10;
    match band {
        0 => score -= 25.0,   // near-perfect fit: excellent
        1 => score -= 8.0,    // good fit
        2 | 3 => score += 3.0,
        4..=6 => score += 6.0,
        _ => {}               // large residual: neutral (still roomy)
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening bins unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow opening when the item would leave a very awkward remainder
        // in every open bin (post_residual tiny but nonzero is fine though).
        if post_residual == 0 {
            score -= 100.0; // fresh bin exactly consumed by item
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Early stream: be slightly conservative, keep big residuals around.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Prefer filling bins when many are open (reduce bin count pressure).
    score -= 0.2 * (open_bins_count as f64).min(20.0);

    // Tie-break toward bins below mean residual (consolidate emptier bins).
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
