pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are pure waste.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    // Very tiny slivers (<10) are effectively unusable regardless of lookahead.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to bin size).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // When multiple bins fit, mild preference to consolidate into emptier bins.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate (empty bin): penalize unless current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + pressure;
        // Opening fresh is attractive only if the item is large relative to capacity.
        score -= 0.3 * item_size as f64;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // Dead space confirmed by lookahead: escalate penalty.
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
