pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches
    // the next item size (perfect chain), penalize mismatches.
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        score += diff * 0.9;
        // Exact match bonus: next item fills this bin completely.
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 40.0;
        }
        // Chain bonus: post_residual can fit next item with small waste.
        if post_residual as f64 >= next {
            score -= (post_residual as f64 - next).min(20.0) * 0.5;
        } else {
            // Dead space the next item cannot use.
            score += (next - post_residual as f64) * 0.6;
        }
    }

    // Tight-fit reward: low post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize bins with residuals far above mean residual (hoarded space)
    // unless this is the only fitting bin.
    if fitting_bins_count > 1 {
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    } else {
        // Last-chance bin: strong reward to use it rather than open new bin.
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // forced to open a new bin
        } else {
            // Prefer open bins unless all fits are terrible.
            let best_possible_waste = if next > 0.0 { (post_residual as f64 - next).abs() } else { post_residual as f64 };
            score += 30.0 + best_possible_waste * 0.2;
            // Late in the stream, avoid opening new bins even more.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 15.0;
        }
    }

    // Slight preference to fill bins with larger items early.
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
