pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item exactly matches the post residual, strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }
    // Lookahead: if next item fits into post residual, mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - tight / bin_capacity as f64);
    }
    // Lookahead penalty: post residual too small for next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 150.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last chance: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Penalize bins whose residual deviates above the mean (prefer packing fuller bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    // Reward bins below mean residual (i.e., already fuller).
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Early stream: be more aggressive at filling bins tightly; late stream: accept fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when open bins are crowded or this is a huge item.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count == 0 { 0.0 } else { (open_bins_count as f64).ln() };
        let big_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items when many bins are open, bad early on.
        score = 60.0 + 40.0 * big_item - 15.0 * crowded + 50.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 500.0; // don't abandon the only fitting bin for a fresh one
        }
    }

    // Slight penalty for many open bins to encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead synergy: next item fits exactly into post_residual -> strong bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // New-bin candidate (empty bin) handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
