    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure: prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let size = item_size as f64;

    // Base: prefer small post_residual (tight fit), scaled by capacity.
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, dead space is cheaper; late, it is costly.
    let post_norm = post / cap;
    let coupling = post_norm * post_norm * (0.5 + 1.5 * progress) * cap;
    score += 0.35 * coupling;

    // Reward high fill ratio (small residual relative to item size).
    let fill = size / (bin_residual as f64).max(1.0);
    score -= 8.0 * fill * fill * (1.0 + progress);

    // Smooth penalty if post_residual is dangerously small but nonzero (wasted capacity).
    let tiny = (1.0 - post_norm).min(1.0);
    if post > 0 {
        score += 2.0 * tiny * tiny * post_norm;
    }

    // Lookahead: reward if the next item fits in the post residual, penalize otherwise.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 3.0 * (1.0 - (next / cap)) * (0.5 + progress);
        } else {
            score += 1.5 * (next / cap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Slight preference to reuse crowded bins when many are open.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Mild attraction toward bins with residuals near the mean (keeps bin profile balanced).
    score += 0.1 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish base; make it slightly attractive early, less late.
    if bin_residual == bin_capacity {
        score -= 2.0 * (1.0 - progress);
        score += 4.0 * progress;
    }

    score
}

