    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small harmonics) are preferred.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect fit: best possible outcome
    } else {
        // modulo arithmetic on post_residual: residue classes mod 5, mod 10
        let m5 = pr % 5;
        let m10 = pr % 10;
        let mut pen = 0.0;
        if m5 == 0 { pen -= 4.0; } else { pen += m5 as f64 * 0.8; }
        if m10 == 0 { pen -= 3.0; }
        // integer-division thresholds: leftover divisible by common item sizes
        if pr >= 10 && pr % 10 == 0 { pen -= 2.0; }
        if pr >= 20 && pr % 20 == 0 { pen -= 1.5; }
