    // or into a harmonic class of it.
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            let slack = post_residual - next_item_size;
            score -= 6.0;
            if slack == 0 { score -= 10.0; }
            else if slack % 10 == 0 { score -= 3.0; }
            else if slack < 10 { score += slack as f64 * 0.6; }
        } else {
            // leftover can't host next item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave unusable dead space or no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead = post_residual < 10 && next_item_size > 0 && post_residual < next_item_size;
