        score += open_bins_count as f64 * 0.5;
    }

    // Slight preference for bins below mean residual (fill emptier bins first
    // keeps large residuals concentrated for big future items).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    score
}

