    // Consolidation pressure.
    score += 2.0 * open_bins_count as f64;

    // Late-stream cleanup: avoid stranding unusable residuals.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // ---- New-bin candidate branch ----
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        return score;
    }

    // ---- Lookahead synergy: next item snug in post_residual ----
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // ---- Post-residual quality bands ----
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
    let dead_space = waste_ratio;

    if waste_ratio < 0.08 {
        score -= 13.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // Mid-band dead space that next item cannot use: penalize.
    if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
        let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 6.0 + 8.0 * overshoot;
    }

    // Room for two more of the next item: good reservoir.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
    }

    // Stranded sliver smaller than half the next item.
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
    }

    // Near-exact next-item fit.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
    }

    if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
        score -= 12.0;
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Two-fit potential with mean-residual check.
    if next_item_size > 0 && post_residual >= 2 * next_item_size || (next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= mean_residual) {
        if waste_ratio < 0.5 {
            score -= 2.5;
        }
    }

    // Unusable leftover beyond next item's need.
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
        let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
    }

    // Smooth mid-band curvature penalty.
    if dead_space > 0.25 && dead_space < 0.65 {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // Residual close to mean residual: predictable future fit.
    if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
        let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
        if closeness > 0.8 {
            score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
        }
    }

    // Leftover after placing next item nearly empty: excellent.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
    }

    // ---- Fitting-bin scarcity and consolidation ----
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // ---- Open-bins pressure ----
    score += pressure * 2.0;
    if bin_residual != bin_capacity && open_bins_count > 4 && item_size <= mean_residual as u32 {
        score -= 4.0;
    }

    // ---- Late-stream adjustments ----
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < ~15) are pure waste — penalize heavily.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 200.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if next item fits exactly in the post residual, big reward;
    // if next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > post_residual {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // pushing us to open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins (penalize opening new ones); with few bins, opening is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let new_bin_penalty = 55.0 + 40.0 * pressure * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty for wasted capacity relative
        // to mean residual across open bins.
        score += new_bin_penalty + (mean_residual / bin_capacity as f64).max(0.0) * 30.0;
    }

    // Mild preference for bins whose residual is close to the item (best-fit core).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post residual equals next item size -> perfect packing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item fits snugly into the post residual (small slack).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: mild penalty scaled by wasted potential.
    else if next_item_size > 0 {
        score += 8.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let post = post_residual as f64;
    if post < mean_residual {
        score -= (mean_residual - post).min(40.0) * 0.35;
    } else {
        score += (post - mean_residual).min(40.0) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space (< 10) that likely becomes unusable.
    if post > 0 && post < 10.0 {
        score += 12.0;
    }

    // New-bin candidate: make it unattractive unless item is huge relative to best open fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 60.0 };
        score = bin_capacity as f64 * 1.5 + pressure - (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving residual too small for the next item,
    // but reward residuals that can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // bin stays useful for the lookahead item
        } else {
            // Dead space for the next item: penalize proportionally to how close it is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when existing bins are all poor fits (large waste) or late in stream.
    if bin_residual == bin_capacity {
        let mut open_penalty = 60.0;
        // If the best alternative would waste a lot, opening is more attractive.
        let poor_alt = (mean_residual - item_size as f64).max(0.0);
        open_penalty -= 0.4 * poor_alt;
        // Early in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        open_penalty += 20.0 * (1.0 - progress);
        // Many open bins: discourage adding more.
        open_penalty += 2.0 * open_bins_count as f64;
        score += open_penalty.max(0.0);
    } else {
        // Mild preference for fuller bins among open candidates.
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Slight penalty for very small leftovers that are hard to use (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it grows and as stream progresses.
    let waste_norm = post / cap;
    score += 1.5 * waste_norm * waste_norm * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 8.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (-gap / 20.0).exp();
    } else {
        // Last item: fully closing a bin is ideal.
        score -= 10.0 * (1.0 - waste_norm);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer deferring new bins early; allow later when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = cap * (1.0 + 0.3 * (1.0 - progress)) - 5.0 * fragmentation * fragmentation;
    }

    // Mild penalty for many open bins relative to mean residual (fragmentation pressure).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Two-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0; // exact chain match: near-perfect two-step fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let snug = 1.0 - slack / post_residual.max(1) as f64;
            score -= 180.0 + 120.0 * snug;
            // after placing next item, residual still large enough to be useful
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // penalize stranding potential proportional to gap
            score += 40.0 + 60.0 * (gap / cap).min(1.0);
            // small stranded residue below next item is worse if tiny
            if post_residual < 8 {
                score += 40.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            // open a fresh bin only when nothing fits well and next item chains
            score -= 100.0;
        } else {
            score += 60.0 + 60.0 * progress + 2.0 * open_bins_count.min(12) as f64;
            // if next item is large and no open bin will hold it, opening early is fine
            if next_item_size as f64 > mean_residual && fitting_bins_count == 0 {
                score -= 25.0;
            }
        }
    } else {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // reward near-exact fills of existing bins
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio < 0.05 {
            score -= 20.0;
        } else if waste_ratio > 0.5 && next_item_size > 0 && next_item_size > post_residual {
            // this bin would strand >50% while next item doesn't fit
            score += 12.0 * (waste_ratio - 0.5);
        }
        // --- mutation: fine-grained residual refinement (combined features) ---
        // reward residues that can still hold the mean-sized item twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // penalize stranding a residue smaller than half the next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
        // mid-band dead-space quadratic penalty (worst zone ~45% waste)
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
            let band = (waste_ratio - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // leftover after next item nearly empty: strong bonus
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
        }
        // residue matching mean residual closely: good for future flexibility
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // endgame: squeeze tight fills when nearly done
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // mid-stream: prefer residues at or below half the mean
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse for small residues.
    let post = post_residual as f64;
    let pr_frac = post / cap;

    // Exact-fit reward: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the post residual into harmonic bands via integer division thresholds.
    let class = post_residual / 10; // 0..10 classes
    match class {
        0 => score -= 50.0,          // tiny residue: nearly full, great
        1 => score -= 25.0,          // 10-19
        2 => score -= 10.0,          // 20-29
        3 => score -= 4.0,           // 30-39
        4 => score += 2.0,           // 40-49: awkward half-full
        5 => score += 6.0,           // 50-59
        6 => score += 10.0,          // 60-69
        7 => score += 14.0,          // 70-79
        8 => score += 18.0,          // 80-89
        9 => score += 22.0,          // 90-99
        _ => score += 30.0,          // near-empty placement, wasteful
    }

    // Modulo coupling: residues that are multiples of common item sizes are reusable.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // divisible by 10: likely reusable by next item
    } else if m >= 7 {
        score += 3.0; // awkward remainder
    }

    // Lookahead: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain perfect fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // harmonic bonus if next fits leaving a multiple-of-10 residue
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 12.0; // next item cannot use this residue
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if nothing fits well (residues all small), opening may win:
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 70.0;
        }
        if post_residual == 0 { score += 500.0; } // never open new for exact fit elsewhere
    }

    // Progress-based tightening: later in stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr_frac * 20.0;

    // Prefer bins with below-mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps nonlinearly.
    // Gaps below the minimum item size (1..10) are pure waste; gaps that cannot
    // hold a meaningful item are heavily penalized.
    if post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 60.0 + (20 - post_residual) as f64 * 8.0;
    } else if post_residual < 40 {
        score += (40 - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward fitting the item snugly relative to residual (tight fit).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 40.0 + open_bins_count as f64 * 5.0;
    } else {
        // Reward using existing bins, stronger when few fitting bins remain.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }
        score -= 10.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving
    // that exact space; otherwise penalize leaving a gap the next item nearly fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 5.0 {
                score -= 40.0; // next item fits almost perfectly
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            if miss < 10.0 {
                score += miss * 4.0; // near miss: wasted gap
            }
        }
    }

    // Slight pressure toward bins with below-average residual (denser bins),
    // keeping spread of residuals tight.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small for the next item are pure waste.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead synergy: snug placement for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        // Two-of-the-same-item potential.
        if post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Leftover after next item nearly vanishes.
        let leftover = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
        if leftover < 0.05 {
            score -= 5.0 * (1.0 - leftover / 0.05);
        }
    } else if next_item_size > 0 {
        // Dead space confirmed by lookahead: escalate penalty proportionally.
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate (empty bin): decide when a fresh bin beats a poor fit.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 45.0 + pressure + 0.25 * slack + 0.1 * open_bins_count.min(10) as f64;
            score -= 0.3 * item_size as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
    } else {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead: perfect chain fit (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual too small for the next item: penalize dead space relative to next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
        // Extra penalty if the dead space is unusable for typical items (small leftover)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Post-residual larger than next item: mild reward proportional to leftover utility
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0;
    }

    // Compare against mean residual: bins already tighter than average are good targets
    let diff = mean_residual - post_residual as f64;
    score += diff * 0.3;

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize unless item is large or few fitting bins
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 60 || (fitting_bins_count <= 1 && open_bins_count > 0) {
            score -= 45.0;
        }
    }

    // Tight fits generally preferred
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fills (small post_residual relative to capacity).
    score -= 15.0 * (1.0 - post / cap);

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Residual remains usable by the next item: reward chaining,
            // strongest when the next item fills it almost exactly.
            score -= 8.0 * (nxt / post);
        } else {
            // Dead space: next item cannot use what's left. Penalize
            // proportionally to how much space is stranded.
            score += 0.5 * post * (1.0 - post / nxt);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += 0.08 * open_bins_count as f64;

    // Slight drift with stream progression: later in the stream, be a bit
    // more tolerant of imperfect fits to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * (mean_residual / cap);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can hold the item: opening a new bin is mandatory.
            score = -1000.0;
        } else {
            // Base penalty for opening a new bin; slightly higher for small
            // items (which leave large, awkward residuals in fresh bins).
            score = 100.0 + 0.15 * (cap - item_size as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
