pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, smoothly warped
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: as stream advances, tolerate larger residuals less
    let warp = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= warp;

    // Penalty for post_residual that cannot fit any plausible next item (dead space)
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        gap / cap
    } else {
        0.0
    };
    score += 25.0 * dead * dead;

    // Reward perfect-ish fits
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_pr;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Alignment with mean residual: prefer bins below mean residual (tighter)
    score += 0.5 * (pr - mean_residual);

    // New-bin candidate: smooth aversion unless current bins are very fragmented
    if bin_residual == bin_capacity {
        score = 40.0 + 5.0 * progress - 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
