pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fills (0) and tiny residuals are best.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else if pr <= 30 {
        score -= 2.0;
    } else {
        // large dead space penalty, modulated by modulo class
        let class = pr % 10;
        let class_bonus = match class {
            0 => 0.0,           // round residual: reusable for multiples of 10
            5 => 3.0,           // half-class: reusable for half items
            _ => 7.0,           // awkward class
        };
        score += (post / cap) * 30.0 + class_bonus;
    }

    // Lookahead coupling: residual that exactly fits the next item is very valuable.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0;
            } else {
                score += (slack as f64) * 0.25;
            }
        } else {
            // next item cannot use this residual at all: residual is dead weight
            score += 10.0;
        }
        // integer-division threshold: residual divisible by next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 6.0;
        }
    } else {
        // last item: prefer filling existing bins hard
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is penalized unless residual waste
    // in existing bins would be severe.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (mean_residual / cap).clamp(0.0, 1.0);
        let base = 55.0 + 40.0 * waste_pressure;
        // late in stream, avoid opening bins for small items
        let item_frac = item_size as f64 / cap;
        let late_penalty = progress * (1.0 - item_frac) * 25.0;
        score = base + late_penalty;
    }

    // Slight preference to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Tie-break: tighter fit (smaller bin_residual - item_size gap already in post)
    // plus deterministic harmonic jitter on item class.
    let item_class = (item_size % 10) as f64;
    score += item_class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap below minimum item size -> pure dead space
        score += (10.0 - pr) * 8.0;
    } else if pr >= 10.0 && pr < 20.0 {
        // only tiny items could fit; soft penalty
        score += (20.0 - pr) * 1.5;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * 12.0;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 6.0;
        } else {
            // next item won't fit here; slight penalty for leaving a gap it could have used
            if next_item_size <= bin_residual {
                score += 2.0;
            }
        }
    }

    // Open-bin pressure: discourage scattering across many open bins when
    // alternatives exist, but encourage using nearly-full bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if fitting_bins_count > 1 {
        score += pressure * 1.2;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer an existing good fit; make a fresh bin
    // attractive only when the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // neutral base for a new bin; becomes competitive when existing fits are bad
        score = bin_capacity as f64 * 0.55 - (mean_residual - pr).abs() * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 8.0; // next item pairs well with a fresh bin
        }
    } else {
        // placing into a bin whose residual deviates far from mean is slightly worse
        score += (mean_residual - bin_residual as f64).abs() * 0.15;
    }

    // Slight late-stream conservatism: pack tighter as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(6);
        // Perfect chain: this bin will be exactly filled by the next item.
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Penalize leaving a gap the next item cannot use at all.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer bins whose fill keeps residuals balanced/tight.
    let res_f = post_residual as f64;
    score += 0.3 * (res_f - mean_residual).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize large dead space that nothing (min size 1) can later use productively;
    // scale with stream progress so late stream favors tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let waste = res_f - res_f.sqrt() * 2.0;
    score += progress * waste.max(0.0);

    // Slight preference for fuller bins (smaller post_residual already in base score,
    // add non-linear tightening).
    score -= 20.0 * (1.0 - res_f / bin_capacity as f64).powi(3);

    // New-bin candidate: keep it neutral-to-slightly-high unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

