    // Strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize dead space that cannot fit typical small items (min size 1..10 band).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving large residual anyway.
            score += 0.1 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        // If mean residual across open bins is close to item size, existing bins fit well -> avoid new bin.
        if mean_residual >= item_size as f64 {
            score += 80.0 - 0.5 * avg_fit_gap;
        } else {
            score += 10.0; // nothing fits well; new bin is reasonable
        }
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Few open bins -> new bin less costly.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is below mean residual (denser bins) when they fit.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild consolidation pressure: fewer open bins is better late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer placing larger items into bins with larger residuals (avoid wasting big gaps on small items).
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth non-linear coupling: post_residual weighted by progress polynomial
    let progress_weight = 0.5 + 0.5 * progress * (2.0 - progress);
    score += progress_weight * pr * pr * bin_capacity as f64 * 0.3;

    // Reward tight fits (fit_ratio near 1) with smooth term
    score -= (fit_ratio * fit_ratio) * 15.0;

    // Penalize dead space relative to mean residual smoothly
    let dead = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dead * (1.0 + progress);

    // Last-chance bin bonus (smooth via fitting count)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.05 * gap;
    }

    // Mild penalty on many open bins, smoothed
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize slightly so we prefer reusing unless fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - fit_ratio) + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
