pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: residual is an exact divisor-friendly chunk (perfect fit zones).
    let pr = post_residual;
    let harmonic = if pr == 0 {
        -1000.0 // perfect fit: overwhelming reward
    } else {
        let r = pr % 10;
        let div3 = pr % 3;
        let div5 = pr % 5;
        // small prime-friendly residuals are more likely reusable by future items
        let reuse_bonus = match r {
            0 => -8.0,
            1 | 9 => -2.0,
            2 | 8 => -1.0,
            5 => -3.0,
            _ => 0.0,
        } + if div3 == 0 { -1.5 } else { 0.0 }
            + if div5 == 0 { -1.0 } else { 0.0 };
        reuse_bonus
    };
    score += harmonic;

    // Integer-division thresholds on post_residual: penalize dead space bands.
    let quarter = bin_capacity / 4;
    if pr > 0 && pr < quarter {
        score += 12.0; // tiny unusable sliver
    } else if pr >= quarter && pr < bin_capacity / 2 {
        score -= 3.0; // medium leftover, quite reusable
    }

    // Coupling with next item: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= pr {
            let fit_frac = next_item_size as f64 / pr as f64;
            score -= 10.0 * fit_frac; // good chaining
            // harmonic coupling: next item divisible into residual cleanly
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (residual == capacity means brand-new bin).
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // penalize opening new bins mildly, more when many bins already open
        score += 20.0 + 2.0 * open_pressure;
        // but if mean residual across open bins is small (fragmented), new bin helps
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
        // late in stream, prefer closing out with new bins slightly more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Prefer fuller bins: tighter fit fraction reward.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 8.0 * fill;

    // Mean-residual alignment: bins far from the mean residual are less attractive.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
