pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on post_residual (favor tight fits)
    let mut score = 4.0 * pr_norm * pr_norm + 2.0 * pr_norm;

    // Smooth non-linear coupling with stream progress:
    // later in the stream, prioritize even tighter fits (steeper penalty).
    score *= 1.0 + 1.5 * progress * pr_norm;

    // Cubic interaction: mid-stream, mildly tolerate medium residuals
    let mid = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score -= 0.8 * mid * (1.0 - pr_norm).powi(3);

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.2 * (1.0 - pr_norm);
    } else if next_item_size > 0 {
        // penalize leaving space that next item can't use
        score += 0.5 * pr_norm * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        // more competing bins -> slight penalty to prefer diversity
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual alignment: prefer bins deviating below mean residual (tighter)
    let mr_norm = mean_residual / cap;
    score += 0.6 * (pr_norm - mr_norm) * (1.0 + progress);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 0.8 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Two-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let snug = 1.0 - slack / post_residual.max(1) as f64;
            score -= 180.0 + 120.0 * snug + 0.35 * next_item_size as f64;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            } else {
                // after next item, leftover nearly empty: strong bonus
                let leftover_ratio = slack as f64 / cap;
                if leftover_ratio < 0.05 {
                    score -= 5.0 * (1.0 - leftover_ratio / 0.05);
                }
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 + 60.0 * (gap / cap).min(1.0);
            if post_residual < 8 {
                score += 40.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else {
            score += 60.0 + 60.0 * progress + 2.0 * open_bins_count.min(12) as f64;
            if next_item_size as f64 > mean_residual && fitting_bins_count == 0 {
                score -= 25.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // early stream: fresh bins are cheap
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
            // late stream: prefer existing bins strongly
            if progress > 0.75 && fitting_bins_count >= 1 {
                score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
            }
        }
    } else {
        score -= 25.0 * progress;
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio < 0.05 {
            score -= 20.0;
        } else if waste_ratio > 0.5 && next_item_size > 0 && next_item_size > post_residual {
            score += 12.0 * (waste_ratio - 0.5);
        }
        // reward residues that can hold next item twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // penalize stranding a residue smaller than half the next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            // unusable dead space relative to next item
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // mid-band dead-space quadratic penalty
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
            let band = (waste_ratio - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // residue near mean residual: future flexibility
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // endgame squeeze
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // mid-stream: prefer small residues
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        // very tight fit with few alternatives: extra pull
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "usable" classes (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by 10 (classic size quantum) -> very reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Class B: post_residual in dead zone (1..10) is nearly unusable -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit bonus (harmonic zero class).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling with next item: if the next item fits exactly in post_residual,
    // strongly reward; if it fits, mildly reward; if not, penalize tightness.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // Harmonic compatibility: next item leaves a clean class again.
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 4.0; }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 9.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 * (mean_residual / cap);
        // Open new bin only when mean residual across open bins is small.
        score += 30.0 - 25.0 * (1.0 - mean_residual / cap) - 5.0 * progress;
        let _ = pressure;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / cap) * 10.0;
    } else {
        // Prefer bins that are already fairly full (small residual fraction).
        score += (bin_residual as f64 / cap) * 4.0;
    }

    // Mild preference for using fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 10.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 20 {
        score += 15.0 * (20.0 - pr) / 20.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 30.0 * (1.0 - pr / bin_capacity as f64).powi(4);

    // Open-bin pressure: prefer spreading across fewer bins when fits are good.
    score += 3.0 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if it enables a perfect next fit
    // (i.e., current fit is poor but next item exactly fills a fresh bin).
    if bin_residual == bin_capacity {
        let base = 55.0;
        let next_exact = next_item_size as f64 >= bin_capacity as f64 - item_size as f64
            && next_item_size > 0
            && next_item_size as f64 <= bin_capacity as f64;
        if next_exact {
            score = base - 30.0;
        } else {
            score = base + 5.0 * open_bins_count as f64;
        }
    }

    // Lookahead: reward leaving space exactly matching the next item.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - diff / bin_capacity as f64);
    }

    // Mild stream-progression dampening of exploration later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1200.0;
    }
    // Near-perfect match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let snug = 1.0 - slack / (post_residual.max(1) as f64);
