        if progress > 0.8 {
            score += 15.0 * (progress - 0.8) / 0.2;
        }
        // Early stream: allow a fresh bin when it can chain the next item perfectly.
        if progress < 0.25 && next_item_size > 0 && next_item_size == item_size {
            score -= 8.0 * (1.0 - progress / 0.25);
