            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // early stream: fresh bins are cheap
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
            // late stream: prefer existing bins strongly
            if progress > 0.75 && fitting_bins_count >= 1 {
                score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
            }
        }
        if progress < 0.25 && open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        score -= 25.0 * progress;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // reward residues that can hold next item twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // penalize stranding a residue smaller than half the next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // near-exact next-item fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // mid-band dead-space quadratic penalty
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
            let band = (waste_ratio - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // residue near mean residual: future flexibility
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // endgame squeeze
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // mid-stream: prefer small residues
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        // very tight fit with few alternatives: extra pull
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // small stranded residue guard
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        // two-fit check
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with a slight super-linear penalty
    // on medium dead space (hard to fill later).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the leftover.
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 18.0 * fill;
        } else {
            // Next item cannot use this leftover: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // very large (so the fresh bin will be tightly packed) or many bins
    // are already open and residuals are low (fragmented state).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        let fragmentation = if mean_residual < item_size as f64 { 12.0 } else { 0.0 };
        let many_open = (open_bins_count as f64).min(20.0) * 0.4;
        score += 30.0 - large_item_bonus - fragmentation + many_open;
        // Early in the stream, opening bins is cheap; later, conserve.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Reward packing into bins that are already partially filled
        // (closing bins out reduces open-bin count).
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Global pressure: when mean residual across open bins is high,
    // prefer placements that reduce it (already handled by post_residual),
    // but add a tie-breaker coupling mean_residual with post_residual.
    score += 0.05 * (mean_residual - pr).max(0.0) * -1.0;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residual leftover (1..=10) is nearly a perfect fit too.
    if post_residual > 0 && post_residual <= 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr
        - 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr
        + 20.0 * norm_pr * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: late in the stream, tighten packing (penalize waste more)
    let tighten = 1.0 + 1.5 * progress * progress;
    score *= tighten;

    // Perfect fit reward (smooth bump around zero post residual)
    let fit_bump = (-norm_pr * 18.0).exp();
    score -= 25.0 * fit_bump;

    // Lookahead coupling: reward leaving room for the next item smoothly
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let gap = (pr - nis).abs();
        let gap_norm = gap / cap;
        score += 10.0 * gap_norm * gap_norm * cap - 8.0 * (-(pr - nis).abs() / 20.0).exp();
    }

    // Last-chance bin: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins whose residual deviates from mean (fragmentation pressure), smoothly
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // Mild penalty for spreading across many open bins
    score += 0.6 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 520.0 + 20.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            let leftover = post_residual - next_item_size;
            let leftover_ratio = leftover as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            // closeness of leftover to mean residual: keeps future fits flexible
            let closeness = 1.0 - ((leftover as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
            // NEW: reward residuals that remain above next item size after two placements
            if leftover >= next_item_size {
                score -= 3.5;
                if (leftover - next_item_size) as f64 <= mean_residual {
                    score -= 2.0;
                }
            }
        } else {
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 26.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0;
    }

    // Two-fit lookahead: reward residuals that can host the next item twice
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
    }

    // exact-fit for next item within one step
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
    }

    // Stranded-space penalty
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        let unusable = dead_space - (next_item_size as f64 / cap);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
        if post_residual < 15 {
            score += 4.0;
        }
    }

    // Mid-band dead space penalty (awkward ~half-empty residuals)
    if dead_space > 0.25 && dead_space < 0.65 && next_item_size > post_residual {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // NEW: harmonic fit metric — reward when post_residual is a near multiple of next_item_size
    if next_item_size > 1 && post_residual > 0 {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
