        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
        // MUTATION: fine-grained snugness gradient — reward residual tightness
        // proportional to how close post_residual is to the next item, scaled by scarcity
        if next_item_size > 0 && post_residual >= next_item_size {
            let snug2 = 1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if snug2 > 0.7 {
                score -= 3.5 * snug2 * (1.0 + 0.5 * (fitting_bins_count.min(4) as f64) / 4.0);
            }
        }
        // MUTATION: residual fragmentation guard — penalize residuals that are
        // neither usable by the next item nor close to a small dead remainder
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let frag = post_residual as f64 / mean_residual.max(1.0);
            if frag > 0.4 && frag < 1.0 {
                score += 5.0 * (frag - 0.4);
            }
        }
        // MUTATION: lookahead chain bonus — residual able to fit next item twice
        // AND leave a remainder near mean residual keeps packing chains alive
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let rem = post_residual - 2 * next_item_size;
            if (rem as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.3 {
                score -= 4.0;
            }
        }
        // MUTATION: late-stream consolidation — when few items remain, strongly
        // prefer bins whose post_residual is tiny, avoiding stranded slivers
        if progress > 0.9 && post_residual > 0 && post_residual < 6 {
            score -= 10.0 * (progress - 0.9) / 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via integer division thresholds.
    // Class 0: post_residual == 0 (perfect closure) -> strong reward.
    // Class 1: post_residual <= 10 (near-perfect) -> reward.
    // Class 2: post_residual divisible by small item quantum (usable sliver) -> mild reward.
    // Class 3: awkward remainder -> penalize.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 6.0;
    }

    // Harmonic compatibility: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size < post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 7.0;
        } else if next_item_size > post_residual {
            // leftover unusable for next item; penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist (empty-bin candidate gets a bias).
    if bin_residual == bin_capacity {
        score += 45.0;
        // But allow new bin if it enables near-exact pairing with next item.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() <= 2.0 {
            score -= 55.0;
        }
    }

    // Stream phase: later in stream, be greedier about closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual <= 20) as i32 as f64;

    // Mean residual coupling: when open bins are already slack, discourage more slack.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Density reward: prefer filling large fraction of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    score
}

