        // Very tight fit with few alternatives.
        if dead_space < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // Late-stream pressure: finish off partial bins.
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
