    // New-bin candidate logic with lookahead awareness.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        score -= 0.3 * item_size as f64;
    } else {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
    }

    // Late-stream urgency: squeeze into small leftovers near the end.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small leftovers are dead space
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize post_residuals that fall into "dead" classes (too small for typical items)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 15.0;
        } else if post_residual <= 35 {
            score += 5.0;
        }
    }

    // Modulo-harmonic coupling: residuals divisible by common item sizes are reusable
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 6.0 * (d as f64) / 10.0;
        }
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: reward, especially tight chains
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.2 * slack;
            if slack == 0.0 {
                score -= 50.0; // perfect chain
            }
        } else {
            // next item won't fit here; penalize leaving a big awkward residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = if item_size > bin_capacity / 2 { 1.0 } else { 0.0 };
        score = score.max(0.0) + 5.0 - 60.0 * urgency - 20.0 * big_item;
        // discourage opening new bins when mean residual across open bins is large
        score += 0.5 * mean_residual.max(0.0);
    }

    // Progress-based nudge: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - frac);

    // Mild preference for bins tighter than average
    score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..~30) can use are pure waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 2.0 } else if post_residual < 40 { 1.0 } else { 0.0 };
        score += dead * (post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, avoid fragmenting; with few, keep things flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (1.0 + 0.5 * (1.0 - progress));

    // New-bin candidate: only attractive when current bin leaves a bad gap or next item needs space.
    if bin_residual == bin_capacity {
        let gap_bad = post_residual > 0 && post_residual < 10;
        let next_fits_gap = next_item_size > 0 && next_item_size <= post_residual && next_item_size > bin_residual.saturating_sub(item_size);
        if !gap_bad && !next_fits_gap {
            score += 30.0 + 10.0 * pressure;
        } else {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Prefer bins tighter than average (fill fullest bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small for the next item are waste.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
