    if bin_residual == bin_capacity && progress < 0.25 {
        score -= 6.0 * (1.0 - progress / 0.25);
    }
    if bin_residual == bin_capacity && open_bins_count > 4 && item_size <= mean_residual as u32 {
        score += 10.0;
    }
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
        score -= 4.0;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small leftover afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_left = post_residual - next_item_size;
        score -= 25.0 - (two_step_left as f64) * 0.5;
    } else if next_item_size > 0 {
        // Dead space: next item cannot reuse the leftover.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        if crowded || (next_item_size > 0 && post_residual < next_item_size) {
            score -= 15.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Early in stream: slightly favor filling existing bins to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would be blocked by a small post-residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            score += 8.0 * (next_item_size as f64 - post_residual as f64).sqrt();
        }
    }

    // New-bin candidate handling: make fresh bins attractive only when existing
    // fits are poor (post_residual small) or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_penalty = if post_residual == bin_capacity { 0.0 } else { 0.0 };
        // score for new bin = residual(=capacity) minus bonuses; adjust with open bins pressure
        score -= 12.0 * (open_bins_count as f64).ln().max(0.0);
        score += 10.0 * progress;
        let _ = poor_fit_penalty;
    } else {
        // Existing bins: slight preference for fuller bins to consolidate.
        score -= 5.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
