    score += 6.0 * awkward;

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if post >= nxt { 1.0 } else { 0.0 };
        let gap = (post - nxt).abs() / cap;
        score -= 10.0 * fits * (1.0 - gap) * (0.4 + 0.6 * progress);
        // Penalize post residual just barely below next item size
