    // New-bin candidate: mild penalty so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        // But allow opening when item is large relative to capacity
        score -= 12.0 * (item_size as f64 / cap);
    }

    // Slight reward for larger items placed (heavier items should go into open bins)
    score -= 2.0 * (item_size as f64 / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
