pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is a small
    // "harmonic" residue (divisible into common item sizes) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward residuals that are reusable: divisible by common sizes 10..20.
    let mut harmony: f64 = 0.0;
    for d in [10u32, 15, 20, 25, 30, 40, 50].iter() {
        if pr >= *d && pr % d == 0 {
            harmony += 12.0 * (cap / (*d as f64)).ln().max(1.0);
        }
    }
    score -= harmony;

    // Penalize dead space: post_residual too small for any plausible item (1..=100
    // unknown distribution, but tiny slivers < 10 are usually wasted).
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Fraction-of-capacity thresholds: keep bins whose fill fraction crosses
    // nice fractions (1/2, 3/4) — they pair well with complement items.
    let fill = (bin_capacity - pr) as f64 / cap;
    if (fill - 0.5).abs() < 0.05 || (fill - 0.75).abs() < 0.05 || (fill - 0.9).abs() < 0.05 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item exactly fits post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= 15.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            score += 5.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening when
    // existing bins would create large dead space or when many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (mean_residual - prf).max(0.0);
        score += 25.0 - 20.0 * progress - waste_pressure.min(20.0) + open_bins_count as f64;
        if item_size > 60 {
            score -= 10.0; // big items start fresh bins more readily
        }
    }

    // Tight fits are always good: reward small post_residual generally.
    score -= 20.0 * (1.0 - prf / cap);

    // Mild regularization against bin sprawl.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // are wasted space. Penalize gaps in (0, 10) heavily (unusable zone),
    // and mildly penalize gaps that only fit tiny items.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            score += 18.0 * (1.0 - (post_residual - 10) as f64 / 10.0);
        }
    }
    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage scattering items
    // across many bins when consolidation is possible.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins whose residual is close to what is needed (tight fit),
    // scaled relative to mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.25 * tightness.max(-50.0).min(50.0);

    // Lookahead: if next item would fit in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // next item won't fit here; dead space likely
    }

    // New-bin candidate: only open a new bin when no existing bin offers
    // a decent fit (e.g. item barely fits nowhere or all fits are wasteful).
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with stream progression and open bins.
        score += 55.0 + 0.8 * open_bins_count as f64
            + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // Allow new bin if item would leave a very tight fit elsewhere
        // (handled implicitly since existing-bin scores rise with dead space).
    }

    score
}

