    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 18.0; // unusable sliver
    } else if post_residual <= 30 {
        score -= 8.0; // still usable by small items
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // competition: normalize tightness advantage among many candidates
        score -= 6.0 * fit_ratio;
    }

    // Lookahead coupling: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 10.0 * (1.0 - nxt / bin_capacity as f64);
        } else if post_residual > 0 && (post_residual as f64) < nxt {
            score += 12.0 * (1.0 - post_residual as f64 / nxt);
        }
