        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into fuller bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        let gap = mean_residual - post_residual as f64;
        score += 0.15 * gap;
        score -= 5.0 * (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * progress;
