            || (item_size as f64 / bin_capacity as f64) > 0.75
            || (next_item_size as f64 / bin_capacity as f64) > 0.9;
        if desperate {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 40.0 + 25.0 * (1.0 - progress);
        }
    }

    // Mild time-varying exploration term (deterministic, bounded).
    let phase = ((step_index as f64) * 0.37).sin();
    score += 2.0 * phase * (1.0 - fit_ratio);

    score
}

