pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "perfect fits"
    // for common item classes (divisible cleanly by capacity fractions).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure — best possible outcome
    } else {
        // Residuals divisible by 10 or 20 pair well with typical item sizes.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }

        // Dead-space penalty: small, awkward residuals (< 10) are unusable.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Harmonic band penalty: residuals in "valley" ranges rarely match items.
        let band = (pr / 10) % 5;
        score += band as f64 * 1.5;
    }

    // Lookahead coupling: does post_residual exactly admit the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // guaranteed chain placement
        } else if pr >= next_item_size {
            score -= 6.0;
            // Harmonic: next item leaves another clean class
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 4.0; }
            if npr == 0 { score -= 20.0; }
        } else {
            score += 10.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly prefer using the final fitting bin
    // over opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 { score += 15.0; } // unless it creates dead space
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
