pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold any plausible future item (>= 1..100)
    // is dead space; the smaller the gap, the worse the waste ratio.
    let dead_threshold = 12.0_f64.min(post_residual as f64);
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 3.0;
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Tight fit reward: item fills most of the bin's remaining space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Lookahead coupling: if the next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }
    // If next item would leave this bin's residual dead anyway, slight penalty.
    if next_item_size > 0 && next_item_size > post_residual as u32 && post_residual < 12 {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize new-bin tendency.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.15 * (1.0 + progress);

    // Mean residual alignment: bins far below mean residual have more room;
    // prefer placing into bins whose residual is close to item needs
    // (i.e., avoid dumping into the emptiest bins when a tight fit exists).
    let res_gap = (bin_residual as f64 - mean_residual).abs();
    score += res_gap * 0.02;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when current fit is very poor
    // (large dead space created). Base penalty keeps new bins from opening casually.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if item is large and would leave big dead space elsewhere,
        // new bin becomes relatively better.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

