        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // sliver guards: penalize opening new bin when an open bin leaves a tiny unusable sliver
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        score -= 20.0 * progress;
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            let rem_ds = leftover as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
        // refined dead-space valley: reward residual bands matching next-item multiples
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // penalize mid-band dead space more sharply when few bins fit the item
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // reward residuals close to a small fraction of mean residual (tight compaction)
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: nonlinear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Reward bins that are already fairly full (low residual before placement).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Partially reusable leftover: mild bonus proportional to how little is left after both.
            let after2 = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after2 as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize creating stranded space.
            score += 6.0 * waste_frac;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with large mean residual -> discourage new-bin hoarding;
    // if this is the empty new-bin candidate, penalize it when open bins are plentiful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, opening new bins is worse.
        score += 10.0 * progress;
        // If mean residual across open bins is large, definitely avoid a new bin.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Mild bonus for bins whose residual is close to mean residual (keeps balance).
    score -= 2.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty, softened early in the stream
    let mut score = pr * (1.0 + norm_pr * (0.5 + progress));

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (t * t) + norm_pr * (1.0 - t) * (1.0 - t);
    score += 10.0 * coupling;

    // Penalize bins whose residual is far below the mean residual (wasted small space)
    score += (mean_residual - pr).abs() * 0.05 * (0.3 + t);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: penalize opening fresh bins unless residual is tiny
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * t - 0.5 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by its residue class modulo 10.
    let residue = post_residual % 10;
    let div = post_residual / 10;

    // Residues that are "harmonically useful" (small leftovers that pair with
    // typical item sizes) get rewarded; awkward residues get penalized.
    match residue {
        0 => score -= 12.0,             // perfectly aligned leftover
        2 | 3 | 7 => score -= 5.0,      // flexible mid-range residues
        1 | 9 => score += 4.0,          // nearly aligned but wasteful
        _ => score += 2.0,              // odd residues 4,5,6,8
    }

    // Integer-division thresholds: dead space below the smallest useful item
    // (assume ~10) is a penalty, scaled by how deep the dead zone is.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward bins whose leftover lies in a "sweet band" via div thresholds.
    if div >= 1 && div <= 4 {
        score -= 6.0; // leftover 10..49: still usable for mid items
    }
    if div >= 5 && div <= 7 {
        score -= 9.0; // leftover 50..79: highly reusable
    }

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 30.0; // perfect next-item fit
        } else if diff > 0 && (diff as u32) < 10 {
            score -= 14.0; // near-perfect next fit
        } else if diff < 0 {
            score += 8.0; // next item won't fit here
        }
        // Modulo harmony: if (post_residual - next_item) stays on a good class
        if diff > 0 && ((diff as u32) % 10) == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad
    // dead space or mean residual is already tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 15.0 + mean_residual * 0.15 + open_bins_count as f64 * 1.5 + progress * 10.0;
        score += penalty;
        // If this item would perfectly fill a fresh bin fraction, soften.
        if item_size % 10 == 0 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter (fuller) bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps (too small for any item >= 1..=10 range)
    // are heavily penalized since they can never be recovered.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving gaps that just barely fail to fit the lookahead item
    // (would force future items elsewhere).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins / spreading).
    let obp = open_bins_count as f64;
    score += 0.15 * obp * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // unless open-bin pressure is low (early stream) or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let new_bin_penalty = 18.0 + 20.0 * progress + 0.3 * obp;
        // Exception: large items relative to mean residual may justify a new bin.
        let escape = if (item_size as f64) > mean_residual + 15.0 { 22.0 } else { 0.0 };
        score += new_bin_penalty - escape;
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (balanced packing), avoid outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for tighter bins overall (small residual before placement).
    score += 0.08 * (bin_capacity - bin_residual) as f64 / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match gets strong bonus; near match gets graded bonus
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 4.0;
        } else if diff <= 15.0 {
            score -= 20.0 - diff * 0.8;
        } else {
            // Large mismatch: penalize creating dead space relative to next item
            score += diff * 0.3;
        }

        // If next item fits into post_residual, mild reward; else penalty
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Compare against mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual - 15.0 {
        // Creating much less residual than average = tight fit, good
        score -= 10.0;
    } else if pr > mean_residual + 20.0 {
        // Leaving more slack than average = poor consolidation
        score += (pr - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless few alternatives or item is large
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = if item_size >= 60 { 1.0 } else { 0.0 };
        score += 30.0 - pressure * 45.0 - large_item * 10.0;
    }

    // Late in stream: prefer closing bins tightly (small post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever fit future items
    // (min item assumed small, but waste below ~15 is rarely reusable).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 30.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for leaving a mid-size gap
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Make empty bins moderately expensive.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early in the stream, opening bins is cheap; later it is costly.
        let openness = 10.0 + 40.0 * progress;
        score += openness;
        // If many bins are open and mean residual is fragmented, opening a fresh
        // bin is more attractive.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        score -= mean_residual / bin_capacity as f64 * 8.0;
    }

    // Prefer using bins with below-average residual (keep fragmentation low):
    // fill the emptiest-feeling bins first.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild preference for balancing across bins when few bins are open.
    if open_bins_count < 3 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Near-miss sliver guard: open bin would leave a barely-unusable gap.
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item can't use it.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Residual can hold the next item at least twice: good consolidation.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
        // Near-exact next-item fit band.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
        }
        // Leftover after placing next item stays small: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        // Unusable gap beyond next item's needs.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // Dead-space valley around 2x multiples of next item.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Sharper mid-band penalty when few bins fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Small residuals close to mean: keep them.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post residual (smaller is better)
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (low post_residual) are rewarded more strongly.
    let tightness = 1.0 - norm_pr * norm_pr; // high when post_residual small
    score -= 12.0 * tightness * (progress * progress + 0.5 * progress);

    // Penalize dead space quadratically when it cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 20.0 * gap * gap * (1.0 + progress);
        } else {
            // reward leaving room exactly for the lookahead item (perfect pairing)
            let diff = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - diff * diff).max(0.0);
        }
    }

    // Last-chance bonus: only one fitting bin left, prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64 * (norm_pr * norm_pr);

    // Penalize bins far from mean residual (fragmentation smoothing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: neutral-ish, slightly penalized so it's chosen only
    // when all open bins fit poorly (large residuals there dominate score).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and 20
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;

    // Reward post_residuals that are "harmonically clean" (multiples of 10/20):
    // these leave space most likely to be exactly filled by future items.
    if r10 == 0 {
        score -= 4.0;
        if r20 == 0 { score -= 3.0; }
    } else if r10 <= 2 || r10 >= 8 {
        // near-multiple residues are still decent
        score -= 1.0;
    } else {
        // awkward residues (3..7) create dead space risk
        score += 2.0 + (r10 as f64 - 5.0).abs();
    }

    // Perfect fit: absolutely prefer
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does post_residual exactly or closely fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 50.0;
            } else if gap <= 5 {
                score -= 10.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // next item cannot use this bin's remainder: slight penalty scaled by tightness
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when a tight fit exists
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins whose residual is small (tight bins)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate handling: only open a new bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin; cheaper late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 - 10.0 * progress;
        // If item is large and would leave a harmonically clean residual in a fresh bin,
        // opening a new bin becomes attractive.
        let fresh_post = bin_capacity - item_size;
        if fresh_post % 10 == 0 { score -= 6.0; }
        if next_item_size > 0 && fresh_post >= next_item_size && (fresh_post - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
        // Never open a new bin when a perfect fit exists in an open bin
        // (handled implicitly since perfect-fit scores are far below 60).
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small gaps (0..=15) is
    // nearly unusable by future items (min item size 1..100 unknown, but
    // typical items are >=10). Penalize heavily if gap is small but nonzero.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-exact fits (small positive post_residual is good if it is
    // not dead space, i.e., large enough to still be usable).
    if post_residual == 0 {
        score -= 120.0; // perfect fill
    } else if post_residual >= 20 {
        score -= 10.0; // still usable residual
    }

    // Lookahead coupling: strongly reward bins where the next item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // current item leaves a terrible fit elsewhere. Penalize the fresh bin
    // by remaining capacity plus open-bin pressure.
    if bin_residual == bin_capacity {
        score = 40.0 + (bin_capacity as f64) * 0.5;
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += (open_bins_count as f64) * 0.4;

    // Mean-residual alignment: prefer bins whose residual is below the mean
    // (fill the emptier-tail bins to consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Late-stream conservatism: as the stream progresses, avoid leaving
    // medium residuals that accumulate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);

    // Lookahead: snug fit of the next item into post_residual is the strongest signal.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fill is gold; tiny residuals are nearly useless.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward relative to capacity.
    let tightness = 1.0 - dead_space;
    score -= 12.0 * tightness * tightness;

    if bin_residual == bin_capacity {
        // NEW-BIN candidate: penalize unless the item would leave a near-miss sliver.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // near-miss sliver: next item just barely cannot use the leftover
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            } else if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
        }
    } else {
        // Existing bin: waste-ratio bands.
        if dead_space < 0.08 {
            score -= 13.0;
        } else if dead_space > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Dead-space valley: reward residuals matching next-item multiples.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Confirmed stranded space by lookahead.
        if next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        // Residual leaves room for at least two more next-items.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Leftover after placing next item is a tiny fraction of capacity.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        // Near-exact next-item match.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        // Mid-band dead space with few alternatives.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Residual close to mean residual and small.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure grows with progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Late-stream behavior: consolidate aggressively near the end.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted dead space quadratically (small leftovers are hard to fill).
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;
    } else {
        // Perfect fit is excellent.
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: leftover exactly (or nearly) matches next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * gap;
        } else {
            // Next item won't fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.25 * shortfall;
        }
        // Bonus if the next item would perfectly fill this bin's leftover.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (better fill candidates).
    score += 0.2 * ((post_residual as f64) - mean_residual);

    // Slight preference for reusing existing bins over opening new ones:
    // penalize the fresh-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow opening a new bin when item leaves a very awkward leftover
        // in existing bins (post_residual small but nonzero).
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Late in the stream, be more conservative: favor tight fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
