        // Fragmentation penalty scaled by dead space.
        if post_residual > 0 && next_item_size > post_residual {
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        // Tiny unusable residual guard.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable slivers are bad
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0; // usable pocket for small items
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; slight penalty for large leftovers
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a bin is costly; only attractive when
    // the current item fits poorly everywhere else or bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.5;
        // Penalize new bins generally, less so early in the stream or on poor fits.
        score += 18.0 + 30.0 * (1.0 - progress);
        if poor_fit {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            // new bin can host current + next item pair
            score -= 20.0;
        }
    } else {
        // Mild bonus for keeping bin population low.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global state coupling: prefer bins whose residual deviates favorably
    // from the mean (consolidate space in bins that are already half-empty).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Prefer filling bins that are already mostly full (best-fit pressure).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty on wasted space, amplified by stream progress
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * tightness * tightness;

    // Lookahead: penalize if post_residual is awkward for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 2.5 * (gap / cap) * (gap / cap);
        // Reward if next item fits exactly-ish
        if post >= nxt {
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        }
    } else {
        // Last item: strongly prefer minimal residual
        score += 3.0 * norm_post;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Prefer bins with below-mean residual (consolidate fullness)
    let mean_norm = mean_residual / cap;
    score += 2.0 * (norm_post - mean_norm) * (1.0 + progress);

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * (1.0 - (fitting_bins_count as f64).recip());
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 1e-9 {
            score -= 5.0;
        }
    }

    // Mild pressure to keep open bin count low early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
