pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: exact fill (post_residual == 0) is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward near-perfect fits: residual within small harmonic bands.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Penalize dead space that is unusable for typical items (post_residual < 10
    // is a trap only if not zero, but small residuals are still useful for tiny items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // slight extra penalty for tiny useless slivers
    }

    // Dead-space penalty scaled by fraction of capacity wasted.
    let waste_frac = post_residual as f64 / cap;
    score += 20.0 * waste_frac * waste_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill;
        } else {
            // next item cannot use this residual: penalize large residuals mildly
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is costly; only attractive
    // when open bins are crowded or mean residual is very low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score = 0.35 * cap + 0.1 * mean_residual + 10.0 * crowding + 30.0 * (1.0 - progress);
        // If no open bin can fit, new bin is the only option; make it dominant.
        if fitting_bins_count == 0 {
            score -= 10000.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= 0.05 * (item_size as f64);

    score
}

