pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the new residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item fits too, but leaves a further residual: mild reward
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use the residual: penalize dead space
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare residual to mean residual across open bins: prefer bins with
    // less residual (tighter bins get filled first), penalize outliers.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize creating very small unusable residuals (< 10, minimum item size),
    // unless they match the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // New-bin candidate: prefer reusing an existing bin unless the fit is bad.
    if bin_residual == bin_capacity {
        // Base preference for opening new bins when many bins are open
        // and the fit is poor; make new bin slightly unattractive by default.
        score += 40.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pair fits perfectly in a fresh bin: make new bin attractive
            score -= 100.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Reward reuse of open bins, more so when many are open.
        score -= 10.0 + open_bins_count as f64 * 0.5;
    }

    score
}

