            }
            // sliver guards: penalize opening new bin when an open bin leaves a tiny unusable sliver
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            // NEW: suppress new-bin opening when an open bin's residual is a near-multiple of the next item
            if next_item_size > 0 && post_residual > 0 {
                let r = post_residual as f64 / next_item_size.max(1) as f64;
                let k = r.round();
                if k >= 1.0 && (r - k).abs() < 0.08 && post_residual >= next_item_size {
                    score += 10.0 * (1.0 - (r - k).abs() / 0.08);
                }
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        // NEW: stronger early-stream compaction — discourage fresh bins while many open bins remain usable
        if open_bins_count >= 2 && next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 6.0;
        }
    } else {
        score -= 20.0 * progress;
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            let rem_ds = leftover as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
        // refined dead-space valley: reward residual bands matching next-item multiples
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // penalize mid-band dead space more sharply when few bins fit the item
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // reward residuals close to a small fraction of mean residual (tight compaction)
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // NEW: endgame exactness — reward bins whose post-residual exactly matches the next item late in the stream
        if progress > 0.7 && next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0 * (progress - 0.7) / 0.3;
        }
        // NEW: when many bins can fit the item, mildly prefer the emptiest-feeling (largest residual) so small bins stay for small items
        if fitting_bins_count >= 4 && post_residual > 0 && item_size as f64 <= mean_residual {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Near-miss sliver guard: open bin would leave a barely-unusable gap.
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // Mutation: stronger new-bin resistance when many bins fit and mean
            // residual is large enough to absorb future items.
            if fitting_bins_count >= 2 && next_item_size as f64 <= mean_residual * 0.9 {
                score += 6.0 + 2.0 * (fitting_bins_count.min(6) as f64);
            }
            // Mutation: resist opening new bins mid-stream for small items.
            if progress < 0.6 && item_size <= 30 && fitting_bins_count >= 1 {
                score += 5.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item can't use it.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Residual can hold the next item at least twice: good consolidation.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            } else {
                // fragility penalty for near-miss residuals.
                let frag = 1.0 - stranded;
                score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            }
        }
        // Near-exact next-item fit band.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
            // endgame exact-fill bonus.
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        // Leftover after placing next item stays small: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            // two-fit consolidation bonus.
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            if post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // Unusable gap beyond next item's needs.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            if post_residual < 15 {
                score += 4.0;
            }
        }
        // Dead-space valley around 2x-3x multiples of next item.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Sharper mid-band penalty when few bins fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Mid-band quadratic dead-space penalty.
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Residual close to mean and usable by next item: reward.
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Small residuals close to mean: keep them.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Large dead space the next item cannot consume.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // Mutation: reward bins whose residual is a tight multiple of the item,
        // packing toward near-full closure.
        if next_item_size > 0 && post_residual > 0 {
            let mult = post_residual as f64 / item_size.max(1) as f64;
            if mult > 0.9 && mult < 1.4 {
                score -= 3.0;
            }
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: squared waste penalty scaled down.
    score += 0.5 * (post * post) / cap;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap * gap);
        } else {
            // next item won't fit here; mildly penalize leaving awkward space
            score += 3.0 * (1.0 - post / cap);
        }
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let bad_fit = if fitting_bins_count >= 1 {
            let best_post = // approximate: compare with mean residual
                mean_residual - item_size as f64;
            if best_post >= 0.0 && best_post <= waste { 1.0 } else { 0.0 }
        } else { 0.0 };
        score += 15.0 - 20.0 * bad_fit;
        // early stream: allow new bins more freely
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - t);
    }

    // Prefer filling bins with lower residuals among many open bins (consolidation).
    if open_bins_count > 1 {
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 2.0 * rel;
    }

    // Dead space guard: residual too small for typical future items (min size 1..100 unknown, assume 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: post residual, smoothed by progress
    let mut score = post;

    // Non-linear coupling: post_residual interacts with progress
    score += 40.0 * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 25.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt) * (0.5 + progress);
        } else {
            score -= 6.0 * (post - nxt) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.4 + 0.6 * progress);
    }

    // Mild penalty for fragmenting many-bin states
    score += 1.5 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * post_norm;

    // Mean residual divergence penalty
    score += 3.0 * (post - mean_residual).abs() / cap;

    // New-bin candidate: slightly discourage unless residual advantage is large
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter / eighth of capacity remains.
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..8 harmonic band
    match class as u32 {
        0 => score -= 40.0,          // near-perfect fill
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 4.0,
        4 => score += 2.0,           // half-empty: mediocre
        5 => score += 8.0,
        6 => score += 14.0,
        7 => score += 20.0,          // nearly untouched bin
        _ => score += 26.0,
    }

    // Integer-division thresholds: dead space that no plausible item (1..100) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit the post residual exactly / well?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 55.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
            // harmonic band of the chained residual
            let chain_class = ((post - nxt) / cap * 8.0).floor();
            score -= (8.0 - chain_class) * 3.0;
        } else {
            score += 18.0; // next item breaks this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming: fresh bin is fine
        }
    }

    // Tightness reward: item consuming a large fraction of the bin residual.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_frac * fit_frac;

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // Mean residual context: prefer bins below mean residual (denser bins).
    score += 0.5 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let bins = open_bins_count as f64;
    let progress = if total_items > 1 {
        step_index as f64 / (total_items as f64 - 1.0)
    } else {
        0.0
    };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: best-fit preference (smaller leftover -> lower score).
    let mut score = post;

    // ---- Strict dead-space avoidance ----
    // Perfect fit: dominant reward, this bin should almost always win.
    if post_residual == 0 {
        score -= 2.5 * cap;
    }

    // Lookahead couplings (only meaningful when a next item exists).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item will perfectly seal this bin: huge reward.
            score -= 1.5 * cap;
        } else if post_residual >= next_item_size {
            // Gap remains usable by the next item: moderate reward.
            score -= 0.2 * cap;
        } else if post_residual > 0 {
            // Gap is dead for the lookahead item: penalize the shortfall.
            score += (nxt - post) * 1.2;
        }
    }

    // Absolute sliver zone: tiny nonzero gaps are probable permanent waste.
    // Quadratic ramp: the smaller (more unusable) the gap, the harsher the penalty.
    let sliver = 6.0f64;
    if post > 0.0 && post < sliver {
        let t = (sliver - post) / sliver;
        score += t * t * 0.6 * cap;
    }

    // ---- Open-bins pressure ----
    if is_new_bin {
        // Cost of opening a new bin: fixed cost + pressure growing with the
        // number of already-open bins + late-stream consolidation pressure,
        // discounted for large items that legitimately warrant a fresh bin.
        score += 0.55 * cap + 1.5 * bins + 0.35 * cap * progress - 0.25 * item;
    } else {
        // Reward using existing bins; pressure grows with open-bin count.
        score -= 0.8 * bins;

        // Last-chance bin: strongly prefer it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 0.6 * cap;
        }

