pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward bins where the lookahead item also fits (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving a residual too small to be useful for the next item.
        let waste = (post_residual as f64) / (next_item_size as f64);
        if waste < 1.0 {
            score += 10.0 * (1.0 - waste);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin acceptable if it's a perfect fit for the item or few fitting bins.
        if item_size == bin_capacity {
            score -= 1000.0;
        } else {
            score += 30.0 + 3.0 * open_bins_count as f64;
            // If many bins fit the item, opening new is bad.
            if fitting_bins_count > 1 {
                score += 20.0 * (fitting_bins_count as f64 - 1.0);
            }
            // If the item is large, a fresh bin leaves a useful residual equal to item_size.
            if item_size >= 50 {
                score -= 15.0;
            }
        }
    } else {
        // Reward using open bins when their residual is close to the item (best-fit flavor).
        let slack = (bin_residual - item_size) as f64;
        score += 5.0 * (slack / bin_capacity as f64);
        // Slight bonus for consolidating into bins with below-mean residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // later, prioritize closing out bins (small residuals) aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    // Mild penalty proportional to how much this placement diverges from mean residual,
    // encouraging balanced residual distribution across bins.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Near-miss sliver guard: open bin would leave a barely-unusable gap.
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // NEW: opening a bin early in the stream is cheap; late in the stream it wastes capacity.
            if progress > 0.6 {
                score += 10.0 * (progress - 0.6) / 0.4;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item can't use it.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Residual can hold the next item at least twice: good consolidation.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            } else {
                let frag = 1.0 - stranded;
                score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            }
        }
        // Near-exact next-item fit band.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        // Leftover after placing next item stays small: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            if post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // Unusable gap beyond next item's needs.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            if post_residual < 15 {
                score += 4.0;
            }
        }
        // Dead-space valley around 2x-3x multiples of next item.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Sharper mid-band penalty when few bins fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Mid-band quadratic dead-space penalty.
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Residual close to mean and usable by next item: reward.
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Small residuals close to mean: keep them.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Large dead space the next item cannot consume.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // NEW: when many bins fit the item, prefer the one whose post_residual best matches
        // the mean residual (keeps future fits predictable); penalize outliers.
        if fitting_bins_count > 2 && post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0);
            if dev > 0.5 {
                score += 2.0 * (dev - 0.5).min(1.0);
            }
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;
    let nf = (norm_pr * std::f64::consts::PI).sin();

    // base: post residual, smoothly warped by progress
    let mut score = pr * (1.0 + 0.5 * progress * fill);

    // non-linear coupling: penalize mid-range residuals more as stream progresses
    score += 12.0 * progress * nf * nf * (1.0 - fill);

    // reward tight fits, stronger late in stream
    score -= 18.0 * fill * fill * (0.5 + progress);

    // lookahead coupling: smooth polynomial interaction with next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni) / cap;
        if diff >= 0.0 {
            score -= 10.0 * (1.0 - diff * diff) * (0.3 + 0.7 * progress);
        } else {
            score += 8.0 * diff * diff * cap / 100.0;
        }
    }

    // last-chance bonus (smooth, non-piecewise)
    let fc = fitting_bins_count as f64;
    score -= 6.0 * (1.0 / fc) * (1.0 + progress);

    // mild penalty for many open bins with high mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "useful" sizes (small, or common item sizes) get rewards.
    let pr = post_residual;
    let mod16 = pr % 16;
    let mod10 = pr % 10;

    // Small residuals are dead space: penalize heavily but reward near-perfect fits.
    if pr > 0 && pr <= 10 {
        score += 30.0; // tiny dead space is nearly unusable
    } else if pr <= 25 {
        score -= 5.0; // tight packing good
    }

    // Harmonic reward: residuals divisible by common item sizes are reusable
    if pr > 0 {
        if mod10 == 0 { score -= 12.0; }
        else if mod16 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 3 == 0 { score -= 2.0; }
        else { score += 4.0; } // awkward residual
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 20.0;
        // Harmonic bonus: next item leaves another nice residual
        let next_post = pr - next_item_size;
        if next_post % 10 == 0 { score -= 6.0; }
        if next_post == 0 { score -= 15.0; }
    } else if next_item_size > 0 {
        // next item won't fit here after placement
        score += 10.0;
        // but if residual is small dead space anyway, less harm
        if pr <= 10 { score -= 8.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early / when few bins open
