pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item is extremely valuable.
        if diff == 0.0 {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward tightness of the match.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize proportionally to wasted lookahead.
            score += 40.0 + 0.5 * diff;
        }
    } else {
        // Last item: pure tightness packing.
        score -= 30.0;
    }

    // Compare post_residual against mean residual of open bins.
    // Leaving more than the mean residual wastes space relative to the fleet.
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless the fit is terrible (post_residual large) and a new bin
    // could serve the next item well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 180.0
            - 0.9 * (post_residual as f64 - mean_residual).max(0.0)
            - if next_item_size > 0 && next_item_size <= post_residual { 120.0 } else { 0.0 };
        score += new_bin_penalty.max(-50.0);
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // Reward tight fits directly.
    score -= 0.6 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

