pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in a
    // "reusable" residue class (small remainders that future items can fill)
    // are rewarded; dead-space classes are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fraction of capacity wasted after placement.
        let waste_frac = pr / cap;
        // Dead-space penalty grows super-linearly for unusable slivers.
        if pr < 10 {
            score += 60.0 * (10.0 - pr) as f64;
        } else {
            score += 25.0 * waste_frac * waste_frac;
        }
    }

    // Modulo classes on post_residual: leftovers that are multiples of common
    // item granularities (10, 20, 25) pair well with future items.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd, prime-hostile leftovers are penalized.
    if post_residual % 10 != 0 && post_residual % 5 != 0 {
        score += 6.0;
    }

    // Integer-division threshold: classify post_residual into coarse buckets.
    let bucket = post_residual / 20; // 0..=5
    score -= match bucket {
        0 => 15.0,           // 0..19: nearly full, great
        1 => 8.0,            // 20..39
        2 => 3.0,            // 40..59
        3 => 0.0,            // 60..79 neutral
        _ => -2.0,           // mostly empty bin, keep it flexible
    } as f64;

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // this is a two-step perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let after2 = post_residual - next_item_size;
            // Harmonic class of the two-step residual.
            if after2 % 10 == 0 {
                score -= 20.0;
            }
            score += after2 as f64 * 0.25;
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover is stranded.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 150.0 - 100.0 * pressure
            - (open_bins_count as f64).ln().max(0.0) * 5.0
            + if next_item_size > item_size { 10.0 } else { 0.0 };
    }

    // Stream progression: late in the stream, consolidation matters more —
    // penalize spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal gap: usable only for tiny items, mildly wasteful.
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to capacity is good,
    // but only when the gap remains usable (>= 10) or exactly zero.
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual >= 10 {
        // Prefer leaving a gap that can accommodate a typical next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
        // Smooth preference for tighter usable fits.
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid forcing
    // a new bin unless the dead-space penalty above dominates.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already small on average; encourage consolidation.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln() * 4.0;
