    score += post * (1.0 - progress) * (1.0 - tightness) * 0.8;
    score -= post * progress * tightness * 1.5;

    // Reward bins whose post_residual could host the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild diversity pressure: when many bins are open, prefer filling existing ones
    score += open_bins_count as f64 * 0.15 * fit_ratio;

    // Pull toward mean residual to keep bin states balanced (smooth quadratic)
    score += 0.05 * (post - mean_residual) * (post - mean_residual) / cap;

    // New-bin candidate: neutral baseline so it only wins when fits are poor
