            }
            // near-miss sliver that next item barely cannot use
            if gap <= 12 {
                score += 3.0 + 0.4 * (12.0 - gap);
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_space = post_residual as f64 / cap;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else {
            score += 60.0 + 60.0 * progress + 2.0 * open_bins_count.min(12) as f64;
            if next_item_size as f64 > mean_residual && fitting_bins_count == 0 {
                score -= 25.0;
            }
            // penalize extra when an open bin leaves only a tiny unusable sliver
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
        }
    } else {
        score -= 25.0 * progress;
        let waste_ratio = dead_space;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.5 && next_item_size > 0 && next_item_size > post_residual {
            score += 12.0 * (waste_ratio - 0.5);
        }
        // mid-band dead space with next item not fitting: penalize overshoot
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // residual matching multiples of next item: keep the chain alive
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // near-exact closeness to mean residual
        if next_item_size > 0 && post_residual >= next_item_size {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // tiny residual below mean threshold: keep it tight
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
    }

    // Endgame: prefer exact fills when stream nearly exhausted
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "nice" modular classes.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals that are multiples of 25 or 10 pair well with
        // common item sizes drawn from an unknown distribution.
        let pr = post_residual;
        if pr % 25 == 0 {
            score -= 30.0;
        } else if pr % 10 == 0 {
            score -= 18.0;
        } else if pr % 5 == 0 {
            score -= 8.0;
        }

        // Integer-division dead-space threshold: residuals below 10 are nearly unusable
        // for items in [1,100] (except exact 1..9 items) -> penalize heavily.
        if pr < 10 {
            score += 40.0;
        } else if pr < 25 {
            score += 12.0;
        }

        // Lookahead coupling: does next_item_size divide / match the post_residual class?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 120.0; // perfect chain
            } else if pr >= next_item_size {
                // next item fits here too: reward, scaled by how snug the pair is
                let slack = (pr - next_item_size) as f64;
                score -= 60.0 - 0.4 * slack;
            } else {
                // next item cannot use this residual: penalize small residuals more
                score += 15.0 + 0.3 * (next_item_size - pr) as f64;
            }
            // Harmonic gcd bonus: residual sharing a divisor with next item packs later
            let g = gcd(pr, next_item_size);
            if g > 1 {
                score -= 4.0 * g as f64;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current bin fits badly. Make empty-bin baseline moderately high but let it
    // win when all fits are terrible.
    if bin_residual == bin_capacity {
        score = 75.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0;
        }
    }

    // Spread pressure: when many bins are open with high mean residual, prefer
    // consolidating into fuller bins (small post_residual).
    score += 0.05 * mean_residual * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Early stream: be slightly greedy toward tight fits to build dense bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

