pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer minimal post_residual (tight packing)
    score += post_residual as f64;

    // Strict dead-space penalty: residuals too small for any plausible item (1..=100) are wasted
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable gap: heavily penalize
            score += 40.0;
        } else if post_residual < 25 {
            score += 12.0;
        } else if post_residual < 50 {
            score += 3.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward if lookahead item exactly fits the post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // lookahead can't use this gap: mild penalty scaled by dead space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; favor tighter fills
    score += (open_bins_count as f64) * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins with residual close to item need (below mean = fuller bin)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: neutral base score; only attractive if all open bins are bad fits
    if bin_residual == bin_capacity {
        // Opening new bin is penalized more when few bins are open (early stream),
        // and slightly less late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 10.0 * progress;
        // If current bin would leave a big unusable gap, new bin becomes attractive
        if post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // NEW: pair-aware consolidation — reward bins whose post-residual can host
    // next item plus a typical follow-up (item_size-sized) companion.
    let pair_fit = next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 >= item_size as f64 * 0.9;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Near-miss sliver guard: open bin would leave a barely-unusable gap.
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // NEW: if the fresh bin would be filled tightly by the next item,
            // opening it is cheap; soften the penalty proportionally.
            if next_item_size > 0 && post_residual >= next_item_size {
                let fill = next_item_size as f64 / bin_capacity.max(1) as f64;
                if fill > 0.55 {
                    score -= 10.0 * (fill - 0.55);
                }
            }
        }
        // NEW: opening a new bin late in the stream is riskier — extra penalty.
        if progress > 0.7 {
            score += 6.0 * (progress - 0.7) / 0.3;
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item can't use it.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Residual can hold the next item at least twice: good consolidation.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // NEW: pair-fit bonus (next + current-size companion both fit).
        if pair_fit {
            score -= 4.0;
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            } else {
                let frag = 1.0 - stranded;
                score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            }
        }
        // Near-exact next-item fit band.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        // Leftover after placing next item stays small: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            // two-fit consolidation bonus.
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            if post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // Unusable gap beyond next item's needs.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            if post_residual < 15 {
                score += 4.0;
            }
        }
        // Dead-space valley around 2x-3x multiples of next item.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Sharper mid-band penalty when few bins fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Mid-band quadratic dead-space penalty.
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Residual close to mean and usable by next item: reward.
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Small residuals close to mean: keep them.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Large dead space the next item cannot consume.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // NEW: when few bins can host the current item, favor the tightest one
        // even harder — avoid scattering items across many partially-filled bins.
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
            score -= 3.0 * tight * (fitting_bins_count.min(5) as f64);
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual small).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (-diff / 20.0).exp();
        // Penalize post_residual slightly larger than next item (dead space chain).
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 8.0;
        }
    }

    // Prefer bins with residuals below the mean (compact the tight bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly, but relax early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 - 6.0 * progress;
    }

    // Slight preference for opening fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
