    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Late-stream adaptations.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward small residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty proportional to waste potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize spreading across too many open bins relative to mean residual.
    if open_bins_count > 0 {
        let ratio = mean_residual / bin_capacity as f64;
        if ratio < 0.3 {
            // bins are mostly full: opening a new bin is relatively attractive
            score += 3.0 * (0.3 - ratio);
        } else {
            score -= 2.0 * (ratio - 0.3);
        }
    }

    // New-bin candidate handling: empty bin starts with raw residual = capacity;
    // make it attractive only when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base mild penalty so existing good fits win.
        score += 5.0;
        // If this is a large item and few bins fit it, opening fresh is fine.
        if item_size >= 60 {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        // If many open bins already have big residuals, prefer reusing them.
        if mean_residual > 0.5 * bin_capacity as f64 {
            score += 4.0;
        }
    }

    // Slight preference for filling fuller bins earlier in stream.
    let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill_fraction;

    score
}

