        score -= 6.0;
    }
    // Dead-space classes: tiny leftovers (1..9) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this leftover; penalize proportionally to wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when current fit is bad.
    if bin_residual == bin_capacity {
