        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 - 20.0 * progress;
        // If the item would leave a nice harmonic leftover in a fresh bin, encourage it.
        if item_size % 10 == 0 {
