    score -= 24.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // unusable sliver below min item size
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many alternatives: slight penalty to prefer the best-fit among them.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: penalize leaving residual that blocks the next item poorly,
    // reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // bonus if next item fills leftover nearly exactly
            let nxt_left = post_residual - next_item_size;
            if nxt_left < 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Global state coupling: when many open bins with high mean residual,
    // encourage consolidation into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 1.5 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize more when mean residual is large or many bins open.
        score += 0.08 * mean_residual + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; late, avoid fragmentation.
        score += 10.0 * (1.0 - progress);
    }

    // Mild time horizon shaping: as stream ends, prefer tight packing in open bins.
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Pair-aware consolidation — reward bins whose post-residual can host
    // next item plus a typical follow-up (item_size-sized) companion.
    let pair_fit = next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 >= item_size as f64 * 0.9;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Near-miss sliver guard: open bin would leave a barely-unusable gap.
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
                // gen85: scale new-bin penalty with how many open bins could still take the next item
                score += 2.0 * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // If the fresh bin would be filled tightly by the next item,
            // opening it is cheap; soften the penalty proportionally.
            if next_item_size > 0 && post_residual >= next_item_size {
                let fill = next_item_size as f64 / bin_capacity.max(1) as f64;
                if fill > 0.55 {
                    score -= 10.0 * (fill - 0.55);
                }
            }
        }
        // Opening a new bin late in the stream is riskier — extra penalty.
        if progress > 0.7 {
            score += 6.0 * (progress - 0.7) / 0.3;
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item can't use it.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Residual can hold the next item at least twice: good consolidation.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Pair-fit bonus (next + current-size companion both fit).
        if pair_fit {
            score -= 4.0;
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            } else {
                let frag = 1.0 - stranded;
                score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            }
        }
        // Near-exact next-item fit band.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        // Leftover after placing next item stays small: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            // Two-fit consolidation bonus.
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            if post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // Unusable gap beyond next item's needs.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            if post_residual < 15 {
                score += 4.0;
            }
        }
        // Dead-space valley around 2x-3x multiples of next item.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Sharper mid-band penalty when few bins fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Mid-band quadratic dead-space penalty.
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Residual close to mean and usable by next item: reward.
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Small residuals close to mean: keep them.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Large dead space the next item cannot consume.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // When few bins can host the current item, favor the tightest one
        // even harder — avoid scattering items across many partially-filled bins.
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
            score -= 3.0 * tight * (fitting_bins_count.min(5) as f64);
        }
        // gen85: deeper dead-space valley refinement — reward residuals that leave room for a second copy of the next item
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        // gen85: penalize residual straddling the mean without fitting the next item (likely trapped dead space)
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate moderate residuals (bins can still be filled).
    // Late in the stream: penalize residuals super-linearly (less time to recover).
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress * progress);
    score += 40.0 * coupling;

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let tight = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 12.0 * tight * (1.0 + progress);
        } else {
            // Penalize wasted capacity relative to lookahead when residual too small.
            let gap = nxt - post_residual as f64;
            score += 4.0 * (gap / bin_capacity as f64) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Penalize spreading across many open bins; reward consolidation.
    let open_pressure = (open_bins_count as f64 / (total_items as f64).sqrt().max(1.0)).min(2.0);
    score += 6.0 * open_pressure * norm_pr;

    // Compare against mean residual: bins far below mean residual are less attractive
    // unless they are near-full (small post_residual), giving smooth differentiation.
    let mean_gap = mean_residual - pr;
    score += 3.0 * (mean_gap / bin_capacity as f64).tanh();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        score = 0.9 * bin_capacity as f64 + 30.0 * waste * waste + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

