                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            // gen90: fresh bin as donor when residual matches mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
        }
        // parent's size-based attraction, retained
        score -= 0.3 * item_size as f64;
    } else {
