pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, best possible outcome
    } else if pr < 10 {
        score += 30.0; // tiny dead space, unusable for min-size items
    } else {
        // Harmonic classes: mod 5, mod 10, mod 20 structure of leftover
        let m5 = pr % 5;
        let m10 = pr % 10;
        let m20 = pr % 20;
        score -= match m5 {
            0 => 8.0,
            _ => 0.0,
        };
        score -= match m10 {
            0 => 6.0,
            _ => 0.0,
        };
        score -= match m20 {
            0 => 4.0,
            _ => 0.0,
        };
        // Integer-division thresholds: leftover divisible into large chunks
        let q = pr / 20;
        score -= q as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // exact harmonic match between next item and leftover class
        if pr % next_item_size == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this leftover: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when current bins fit badly
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // penalize new bin when existing bins are roomy and fit well
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size > 50 {
            score -= 5.0; // big next item makes a fresh bin more valuable
        }
        let _ = pressure;
    }

    // Waste ratio: penalize leftover relative to what item consumed
    if item_size > 0 {
        score += (pr as f64 / item_size as f64) * 3.0;
    }

    // Stream progression: early on, be more tolerant of fragmentation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Many open bins: prefer consolidating into existing ones
    score += (open_bins_count as f64) * 0.05;

    // Mean residual coupling: bins far from mean residual are slightly penalized
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (10 - post_residual.min(&10)) as f64 / 10.0;
    }
    if post_residual > 0 && post_residual < item_size {
        // Gap too small for even the smallest future item (>=1) is dead space.
        score += 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tight fit reward relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Lookahead: if next item fits the post residual exactly, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score += 15.0; // would create new dead space
        } else if next_item_size > post_residual {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    score += (open_bins_count as f64) * 1.5 * (1.0 - fit_ratio);

    // New-bin candidate handling: only attractive when current bins are fragmented
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        } else if mean_residual < 25.0 || fragmentation < 5.0 {
            score -= 10.0;
        } else {
            score += 25.0 + mean_residual * 0.3; // prefer filling existing bins
        }
        // Late in stream, new bins are less costly to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild preference for bins with residual near mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > post_residual {
            // dead space for the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // next item fits but leaves another residual
            let next_post = post_residual - next_item_size;
            score += next_post as f64 * 0.3;
        }
    }

    // Penalize small unusable residuals (dead space) relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // but if the item fits nearly perfectly in an empty bin, encourage it
        if (bin_capacity - item_size) as f64 <= mean_residual {
            score -= 60.0;
        }
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Progress-aware: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.1;

    // Mild penalty for scattering across many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    let pair_fit = next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 >= item_size as f64 * 0.9;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
                // gen92: scale new-bin penalty with scarcity AND tightness of the fleet
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // gen92: a fresh bin is a good donor when next item matches mean residual
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                let fill = next_item_size as f64 / bin_capacity.max(1) as f64;
                if fill > 0.55 {
                    score -= 10.0 * (fill - 0.55);
                }
            }
        }
        if progress > 0.7 {
            score += 6.0 * (progress - 0.7) / 0.3;
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        if pair_fit {
            score -= 4.0;
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            } else {
                let frag = 1.0 - stranded;
                score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            if post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
            // gen92: reward residuals that leave room for a second copy of next item
            if post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            if post_residual < 15 {
                score += 4.0;
            }
            // gen92: penalize residual straddling the mean without fitting the next item
            if post_residual as f64 > mean_residual * 1.15 {
                score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // gen92: avoid overshooting into a wide gap beyond next item's size band
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
            score -= 3.0 * tight * (fitting_bins_count.min(5) as f64);
        }
    }

    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that likely can't fit future items.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += (1.0 - usable) * (post_residual as f64) * 0.35;
        // Lookahead: bonus if the next item fits exactly in the post residual.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (less packed) slightly, to balance load.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more conservative about filling bins tightly;
    // late in the stream, prioritize minimizing bins now.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so when good alternatives exist
    // or when the item is small relative to capacity.
    if bin_residual == bin_capacity {
        let alt_exists = fitting_bins_count > 0;
        let small_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 + 20.0 * (1.0 - small_item) + if alt_exists { 8.0 } else { 0.0 };
        // Late in the stream, opening a new bin is less costly.
        score -= 6.0 * progress;
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: tight fits rewarded more strongly as stream progresses.
    let norm_pr = pr / cap; // 0..1
    let tight_reward = (1.0 - norm_pr).powi(3) * (30.0 + 40.0 * progress);
    score -= tight_reward;

    // Penalize post-residuals that are small-but-unusable for typical items
    let dead = (norm_pr * (1.0 - norm_pr) * 4.0).powi(2); // peaks near 0.5 residual
    score += dead * 8.0;

    // Lookahead: reward leaving space that fits next item, penalize blocking it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 6.0 + 10.0 * snug * (0.5 + progress);
        } else {
            score += 4.0 + 6.0 * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly, less when open bins are fragmented
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 + 10.0 * fragmentation - 8.0 * progress;
    } else {
        // Prefer bins with residual close to mean (balance load) via quadratic coupling
        let dev = (pr - mean_residual) / cap;
        score += dev * dev * 10.0;
    }

    // Mild preference for bins with less residual overall
    score += 0.05 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it decomposes into likely future item sizes.
    // Class 0: divisible by 10 (perfect harmonic) -> strong reward.
    // Class 1: odd/awkward remainders -> penalty.
    let harmonic_class = post_residual % 10;
    match harmonic_class {
        0 => score -= 12.0,
        1 | 9 => score += 6.0,
        2 | 8 => score += 3.0,
        3 | 7 => score -= 1.0,
        _ => {}
    }

    // Integer-division threshold: post_residual bucketed into decades.
    let decade = post_residual / 10;
    if decade == 0 {
        score -= 8.0; // near-perfect fill
    } else if decade <= 2 {
        score += 2.0; // small but awkward residual
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Harmonic pairing: next item leaves another harmonic residual?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use this residual; penalize wasting space.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
        if post_residual % 10 == 0 {
            score -= 5.0; // fresh bin is fine if item is harmonic (multiple of 10)
        }
    }

    // Progress scaling: late in stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Many open bins: discourage spreading, favor bins below mean residual (tighter).
    if open_bins_count > 0 && bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is positive but too small to be useful for
    // typical future items (assume min useful item size ~10, with a margin).
    if post_residual > 0 && post_residual < 12 {
        score += 200.0;
    } else if post_residual < 25 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Pressure from number of open bins: discourage spreading across too many
    // open bins; prefer filling existing bins when many are already open.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward;
    // if the next item would waste the post residual, penalize slightly.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 20.0;
        } else if (post_residual as f64) < next_item_size as f64 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps a balanced set of residuals for future flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // New-bin candidate handling: an empty bin gets a moderate baseline
    // penalty so it is only chosen when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward post_residual that exactly/nearly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-diff / 15.0).exp(); // strong reward for perfect chain match
        // Penalize leaving a residual that the next item cannot use at all.
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
        // Reward leaving a residual the next item fits with room to spare being wasted.
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        if slack_after_next > 0.0 {
            score += 0.3 * slack_after_next; // leftover after chaining is less valuable
        }
    } else {
        // Last item: any residual is dead space; prefer filling as much as possible.
        score += 20.0 * tightness;
    }

    // Relative to mean residual: bins with residual below mean are precious; penalize
    // wasting them on loose fits, reward using them when fit is tight.
    if post_residual as f64 > mean_residual {
        score += 5.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that would become nearly empty-capacity.
        score += 2.0 * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // New-bin candidate: opening a fresh bin should only win if all open fits are bad.
    if bin_residual == bin_capacity && item_size > 0 {
        // Neutral baseline, plus a penalty that grows with how many bins could fit.
        score += 10.0 + 3.0 * fitting_bins_count as f64;
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If next item is large, a fresh bin is more flexible.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Lookahead coupling: reward if the post residual can host the next item,
    // penalize residuals that are "almost but not quite" useful for next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (pr - nr) / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize near-misses more
            let gap = nr - pr;
            score += 10.0 + 0.5 * gap as f64 * (gap as f64 / nr).min(1.0);
        }
        // residual that fits neither current nor next item is dead weight
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize spreading across many open bins; favor consolidating load
    // when the mean residual is large (bins are mostly empty).
    let cap = bin_capacity as f64;
    let fill_ratio = (bin_residual as f64) / cap; // fraction still free
    if fill_ratio > 0.7 && open_bins_count > 3 {
        score += 8.0 * (open_bins_count as f64 - 3.0).min(10.0);
    }

    // Global state: if mean residual is high, prefer filling emptier bins less
    // (keep big residuals for future big items); if mean residual is low,
    // prefer dumping into bins with small residual.
    let mr = mean_residual / cap;
    if mr > 0.5 {
        score += 10.0 * (fill_ratio - mr);
    } else {
        score += 10.0 * (mr - fill_ratio).max(0.0) * 0.5;
    }

    // Time horizon: early in the stream, be conservative about opening new bins
    // (long horizon ahead -> keep flexibility); late in the stream, allow
    // opening new bins since fewer items remain to be disrupted.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, discounted late in the stream
        let base = 30.0 - 20.0 * progress;
        // opening a new bin is attractive if no open bin fits well
        score = base + (post_residual as f64);
        if fitting_bins_count == 0 { score -= 10.0; }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 0.0;
        }
        // late stream: new bins are cheap
        if progress > 0.8 { score -= 10.0; }
    } else {
        // existing bin: slight bonus for using bins early (keeps bin count low)
        score += 5.0 * (1.0 - progress);
    }

    // Small tie-break noise-free coupling on step index to diversify behavior.
    score += 0.01 * ((step_index % 7) as f64) * (post_residual as f64 / cap);

    score
}

