    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let capacity_f = bin_capacity as f64;
    let residual_f = bin_residual as f64;
    let post_f = post_residual as f64;
    let item_f = item_size as f64;

    // Fill ratio of this placement: higher fill => stronger reward
    let fill = item_f / capacity_f; // in (0,1]
    // Smooth polynomial coupling of fill with progress: later items reward tight packing more
    let fill_reward = (fill * fill * (1.0 + 2.0 * progress)) * capacity_f * 0.6;
    score -= fill_reward;

    // Penalize dead space non-linearly: small post_residual is good, mid-range is worst
    let post_norm = post_f / capacity_f;
    let dead_penalty = (post_norm * (1.0 - post_norm)) * capacity_f * 0.5;
    score += dead_penalty;

    // Exact-fit bonus (post_residual near zero), amplified by progress
    let exact_bonus = (1.0 - post_norm).powi(6) * capacity_f * (0.8 + 1.2 * progress);
    score -= exact_bonus;

    // Lookahead coupling: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_f <= post_f {
            let chain_fit = 1.0 - (post_f - next_f) / capacity_f;
            score -= chain_fit * capacity_f * (0.3 + 0.4 * progress);
        } else {
            // Penalize leaving residual that next item cannot use, scaled by wasted gap
            let gap = (next_f - post_f) / capacity_f;
            score += gap * capacity_f * 0.25;
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer using it
    if fitting_bins_count == 1 {
        score -= capacity_f * (0.7 + 0.5 * progress);
    }

    // Mild penalty when many bins are open and residual is high (encourage consolidation)
    let open_norm = open_bins_count as f64;
    let consolidation = (residual_f / capacity_f) * (open_norm / (open_norm + 5.0)) * capacity_f * 0.3;
    score += consolidation;

    // Deviation from mean residual: prefer bins below mean residual (tighter bins)
    let mean_dev = (residual_f - mean_residual) / capacity_f;
    score += mean_dev * capacity_f * 0.15;

    // New-bin candidate handling: opening a new bin is penalized early, allowed late
    // or when nothing fits well; smooth sigmoid-like gate on progress
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let open_gate = 1.0 / (1.0 + (-8.0 * (progress - 0.5)).exp());
    // Base cost of a new bin decreases as stream progresses
    let new_bin_cost = capacity_f * (1.2 - 0.9 * open_gate);
    // If existing bins would leave large dead space, new-bin becomes more attractive
    let escape = (post_norm * post_norm) * capacity_f * 0.9;
    score += is_new_bin * (new_bin_cost - escape);

    // Smooth quadratic interaction between post_residual and progress for fine tuning
    score += (post_norm * post_norm) * (1.0 - progress) * capacity_f * 0.2;

    score
}

