pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1

    // Penalize residuals in "dead zones" that few item sizes can fill.
    // Classes via integer division thresholds on post_residual.
    let class = post_residual / 10; // harmonic class 0..10
    let class_penalty = match class {
        0 => -30.0,                       // perfect fit
        1 => -12.0,                       // 1..9: nearly unusable but tiny waste
        2 => 8.0,                         // 10..19: awkward
        3 => 4.0,
        4 => 0.0,                         // 30..39: many items fit
        5 => -3.0,
        6 => 2.0,
        7 => 6.0,                         // 70..79: only large items fit
        8 => 3.0,
        9 => 1.0,
        _ => -20.0,                       // empty/new bin class
    };
    score += class_penalty;

    // Modulo arithmetic: residuals that are multiples of common item sizes are valuable
    let m = post_residual % 10;
    if m == 0 { score -= 5.0; }
    else if m >= 7 { score += 2.0; }

    // Lookahead coupling: reward if next item fits exactly or well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let fill = nx / pr.max(1.0);
            score -= 10.0 * fill; // prefer bins where next item fills much of leftover
        } else {
            score += 5.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in stream or with many open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = c + 15.0;
        new_bin_score -= 10.0 * progress;
        new_bin_score -= 2.0 * open_bins_count as f64;
        // if mean residual is large, opening new bin is wasteful
        new_bin_score += 0.5 * (mean_residual - 25.0).max(0.0);
        score = new_bin_score;
    } else {
        // Prefer bins tighter than the mean residual (good consolidation)
        score += 0.3 * (mean_residual - pr);
        // Slight preference for fewer open bins
        score += 0.05 * open_bins_count as f64;
    }

    // Nonlinear squash on very small residuals to strongly prefer near-perfect fits
    if post_residual <= 5 {
        score -= 20.0 * (6.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 20.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and discourage opening new ones.
    score += open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more strongly as open bins accumulate,
        // but relax slightly early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + open_bins_count as f64 * 3.0 - progress * 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // Next item cannot use the gap: mild penalty proportional to gap size.
        score += (post_residual as f64) * 0.3;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

