pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (post_residual small).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leftover that is too small to matter.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 25.0 * (10.0 - dead);
            }
            // If next item fits better in a fresh bin, prefer opening one.
            let wasted = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.3 * wasted;
        }
    } else {
        // Last item: maximize fill.
        score += post_residual as f64;
    }

    // Penalize bins whose residual is far below mean (fragmented), reward above-mean residual usage.
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * mean_residual;
    }

    // Slight preference early in stream to keep bins consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Penalize dead space that is too small to be useful (below min item size 1 -> use 10 heuristic floor).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0;
    } else if dead >= 10.0 && dead < 30.0 {
        score += 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // If this bin's residual exactly chains with next item, extra reward.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // Final item: pure tight fit matters.
        score -= post_residual as f64 * 0.5;
    }

    // Time horizon: later in stream, prefer filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (item_size as f64 / bin_capacity as f64);

    // Global state: many open bins -> prefer consolidation into low-residual bins.
    if open_bins_count > 3 {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Prefer bins with residual close to item size (minimal waste).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 20.0 / (1.0 + gap * 0.1);

    // New-bin candidate: penalize mildly unless current fit is poor or bin is empty.
    if bin_residual == bin_capacity {
        // Empty bin baseline: competitive only when item is large or few fitting bins.
        score += 18.0;
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    // Early stream: tolerate large residuals; late stream: penalize them quadratically
    score += pr_norm * pr_norm * (0.5 + 2.0 * progress) * bin_capacity as f64;

    // Cubic dead-space penalty for residuals too small to ever be useful
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * dead * 50.0 * (1.0 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= (bin_capacity as f64 / (1.0 + pr)) * (1.0 + 0.5 * progress);

    // Lookahead coupling: penalize leaving a residual that barely fails next item,
    // reward leaving a residual that exactly accommodates it
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 8.0 * (-gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating open bins when many are open
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    // Favor bins whose residual deviates from the mean (balance preservation)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 60.0 * (1.0 - scarcity) + 25.0 * progress;
    }

    score
}

