pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division bands
    let residue = post_residual % 10;
    let band = post_residual / 10; // 0..=10

    // Penalize awkward dead space: small nonzero residues are hard to fill
    if residue > 0 && residue < 5 {
        score += (5 - residue) as f64 * 2.5;
    }
    // Reward post_residual that lands on "nice" harmonic fractions of capacity
    let nice = [0u32, 10, 20, 25, 33, 50, 66, 75, 100];
    let is_nice = nice.contains(&post_residual);
    if is_nice { score -= 12.0; }

    // Coupling with lookahead: reward exact pairing post_residual == next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
            // harmonic bonus if next item leaves another nice residue
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Tight-fit reward: filling the bin nearly exactly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.85;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing potential in fresh bin
            score -= (item_size + next_item_size) as f64 * 0.3;
        }
    }

    // Late in the stream: prefer consolidating into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Prefer bins with below-mean residual (keep a spread of partial bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild penalty per open bin to discourage proliferation
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open and residual is low.
        score += 15.0 + 8.0 * pressure;
        // If next item could fill this bin's leftover, opening may still be worth it.
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 10.0;
        } else if next_item_size > 0 && next_item_size <= post_residual + item_size {
            score -= 5.0;
        }
    } else {
        // Slight preference to consolidate into bins with low mean residual.
        score += 0.05 * (mean_residual - post_residual as f64).abs();
        // If next item fits the post residual, this placement sets up a chain.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
        // Penalize leaving gaps the next item cannot use but are above tiny threshold.
        if next_item_size > post_residual && post_residual >= 10 {
            score += 6.0;
        }
    }

    // Late in the stream, prefer closing bins out (reduce waste).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: strong reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Pair-aware consolidation: post-residual can host next item plus companion.
    let pair_fit = next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 >= item_size as f64 * 0.9;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
