            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // Fresh bin filled tightly by next item: soften penalty.
            if next_item_size > 0 && post_residual >= next_item_size {
                let fill = next_item_size as f64 / bin_capacity.max(1) as f64;
                if fill > 0.55 {
                    score -= 10.0 * (fill - 0.55);
                }
            }
            // gen97: scale new-bin penalty with scarcity AND tightness of the fleet.
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            // gen97: next item matching mean residual — fresh bin is a good donor.
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
        }
        // Opening a new bin late in the stream is riskier — extra penalty.
        if progress > 0.7 {
            score += 6.0 * (progress - 0.7) / 0.3;
        }
