        }
        // Large dead space the next item cannot consume.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // Tightest-bin preference when several bins fit.
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
            score -= 3.0 * tight * (fitting_bins_count.min(5) as f64);
        }
        // gen97: reward residuals that leave room for a second copy of the next item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        // gen97: penalize residual straddling the mean without fitting the next item.
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // gen97: overshoot into a wide gap — penalize residuals far above next item size.
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space too small for the smallest possible item is wasted.
    if post_residual > 0 && post_residual < 1 {
        score += 500.0;
    }

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * gap;
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize residuals that cannot fit the next item (stranded space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless nothing better exists.
    if bin_residual == bin_capacity {
        score += 250.0 + open_bins_count as f64;
        // Late in the stream, closing out bins matters less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
    }

    // Mild preference for keeping many open bins consolidated early.
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

