            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream endgame adjustments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Perfect fit gets a big discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: leaving residual that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver given item sizes >= 1... keep mild
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover gap
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Avoid consuming a large-residual bin with a small item when other bins fit.
    if bin_residual > item_size {
        let waste = (bin_residual - item_size) as f64;
        if waste > mean_residual {
            score += 0.35 * (waste - mean_residual);
        }
    }

    // Global pressure: many open bins -> favor consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * pressure.min(3.0);
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // current fits are poor (post_residual large relative to item).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        // Base slight handicap so decent existing fits win.
        score += 15.0;
        // But if this item would leave a very roomy bin (small item into fresh bin
        // is wasteful) penalize; if item is large, fresh bin is fine.
        if item_size >= 70 {
            score -= 30.0;
        } else if item_size <= 30 {
            score += 20.0 * (1.0 - poor_fit);
        }
        // Late in the stream, discourage proliferating bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * t;
        // If many bins already open and mean residual is high, prefer reusing them.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild tie-breaker: prefer bins with residual close to item size.
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

