            }
        }
    }

    // Late-stream behavior: endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.6 * progress) - 0.8 * norm_pr * norm_pr * (1.0 - progress);

    let mut score = poly * cap;

    // Reward near-perfect fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 6.0 * gap * gap * (1.0 - 0.5 * progress);
        let next_fit = (next_item_size as f64 - pr).abs() / cap;
        score -= 4.0 * (1.0 - next_fit) * (1.0 - next_fit);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: prefer it only when existing residuals are large
    if bin_residual == bin_capacity {
        score = 25.0 + 30.0 * (1.0 - progress) - 20.0 * (mean_residual / cap);
        if fitting_bins_count <= 1 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group "good" dead space levels.
    let pr = post_residual;
    let class = pr % 10;
    // Classes 0 (perfect) and small residues (1..=5) are more reusable than mid-range (6..=9).
    match class {
        0 => score -= 8.0,
        1..=5 => score -= 2.0 + (5 - class) as f64,
        _ => score += 1.5 + (class - 5) as f64 * 0.5,
    }

    // Fractional capacity thresholds on post_residual.
    let frac = post_residual as f64 / cap;
    if frac < 0.10 {
        score -= 5.0; // nearly full bin: excellent closure
    } else if frac < 0.20 {
        score -= 2.0;
    } else if frac > 0.60 {
        score += 3.0; // wasteful large leftover
    }

    // Lookahead: reward if next item fits exactly in post_residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            // Reward scaled by how much of the leftover the next item consumes.
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 6.0 * fill;
            // Modulo harmony: next item leaves a class-0 residue too.
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 2.0; // leftover unusable for next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 7.0;
    } else if fitting_bins_count > 2 {
        score += 1.0; // many alternatives: be pickier
    }

    // New-bin candidate handling: penalize opening a bin when good fits exist,
    // but allow it when residual is tiny/dead space would be created.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 10.0 * progress;
        // Opening a bin is fine if the item is huge and would leave bad residue elsewhere.
        if item_size >= 60 && post_residual >= 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big stream: fresh bins useful
        }
        if fitting_bins_count == 1 {
            score += 15.0; // don't abandon the last-chance bin
        }
    }

    // Mild preference for filling bins below the current mean residual (balance).
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

