pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step matches: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near matches (next item almost fills the bin after current placement)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        } else {
            // dead space relative to lookahead item
            score += 0.15 * gap;
        }
    }

    // Penalize small unusable dead space (waste), scaled by item tightness
    if post_residual > 0 {
        score += 0.3 * (post_residual as f64).powf(0.7);
    } else {
        score -= 15.0; // perfect fill
    }

    // Reward tight fits relative to mean residual across open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 5.0 * (mean_residual / bin_capacity as f64 - tightness).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize so it's chosen only when fits are bad
        score += 40.0 + 20.0 * progress;
        // but allow new bin if next item is huge and no good fit exists
        if next_item_size > 0 && next_item_size >= 70 && post_residual == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for bins with larger residuals when many bins are open
    score -= 0.05 * (bin_residual as f64) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;

    // Lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny residuals are still usable.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Pair-aware consolidation: post-residual can host next item + companion.
    let pair_fit = next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) as f64 >= item_size as f64 * 0.9;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE logic.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Near-miss sliver guard.
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // Fresh bin tightly filled by next item: soften penalty.
            if next_item_size > 0 && post_residual >= next_item_size {
                let fill = next_item_size as f64 / bin_capacity.max(1) as f64;
                if fill > 0.55 {
                    score -= 10.0 * (fill - 0.55);
                }
            }
            // gen88: scale new-bin penalty with scarcity AND fleet tightness.
            if next_item_size > 0 && next_item_size > post_residual {
                let tight_fleet = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight_fleet) * fitting_bins_count.min(5) as f64;
            }
            // gen88: fresh bin is a good donor when next item matches mean residual.
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
        }
        // Opening a new bin late in the stream is riskier.
        if progress > 0.7 {
            score += 6.0 * (progress - 0.7) / 0.3;
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item can't use it.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Residual can hold the next item at least twice: good consolidation.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Pair-fit bonus.
        if pair_fit {
            score -= 4.0;
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            } else {
                let frag = 1.0 - stranded;
                score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            }
        }
        // Near-exact next-item fit band.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        // Leftover after next item stays small: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            if post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // Unusable gap beyond next item's needs.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
            if post_residual < 15 {
                score += 4.0;
            }
        }
        // Dead-space valley around 2x-3x multiples of next item.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Sharper mid-band penalty when few bins fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Mid-band quadratic dead-space penalty.
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Residual close to mean and usable by next item: reward.
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Small residuals close to mean: keep them.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Large dead space the next item cannot consume.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * bin_capacity as f64 {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        // Favor the tightest bin when multiple bins can host the item.
        if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let tight = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
            score -= 3.0 * tight * (fitting_bins_count.min(5) as f64);
        }
        // gen88: reward residuals leaving room for a second copy of next item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        // gen88: penalize residual straddling the mean without fitting next item.
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // gen88: avoid overshooting into a wide gap beyond next item's band.
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
    }

    // Late-stream endgame consolidation.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tight = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize leaving a large unusable gap.
            score += 0.35 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    } else {
        // Last item: prefer minimal waste.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 0.05 * item_size as f64;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer tightest fit, small bonus pressure.
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins whose residual is already small relative to the mean
    // (consolidate waste into few bins).
    let resid_f = post_residual as f64;
    let dev = resid_f - mean_residual;
    score += 0.08 * dev;

    // Penalize very small post-residuals only if they become dead space
    // that no plausible item (>= 1) could use; tiny gaps are fine.
    if resid_f > 0.0 && resid_f < 10.0 {
        score -= 2.0; // nearly-full bin is a good outcome
    }

    // New-bin candidate handling: opening fresh bins is cheap early,
    // expensive late in the stream.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * t + 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins that are already partially filled
    // (avoid scattering across many bins).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 3.0 * fill;

    // Late in the stream, be more conservative: favor tighter fits.
    score += 4.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: penalize residual, but weight depends on progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear coupling: squared normalized residual interacting with progress
    score += 20.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize bins whose residual deviates from the mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next;
        // Slight penalty if post residual is just barely too small for next item
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 6.0 * gap * gap;
    }

    // Mild penalty on opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * fitting_bins_count as f64;
        // But allow new bins more freely early in the stream
        score -= 8.0 * (1.0 - progress);
    }

    // Dampen bin proliferation preference via open bin count interaction
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
