    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // near-miss new-bin penalties
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            // scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            // fresh bin as donor when residual matches mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // gen105: if some open bin's post-fit residual would still hold next item,
            // opening a fresh bin is wasteful — penalize more aggressively.
            if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count >= 1 {
                let roomy = mean_residual >= next_item_size as f64;
                if roomy {
                    score += 10.0 + 0.3 * next_item_size as f64;
                }
            }
            // gen105: early stream — avoid opening bins too eagerly.
            if progress < 0.3 && fitting_bins_count >= 2 {
                score += 6.0 * (0.3 - progress) / 0.3;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Mid-band dead space penalty when next item won't fit.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Two copies of next item fit: strong bonus.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        // Stranded sliver relative to next item.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        // Near-miss band: residual just above next item.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // Tiny waste with scarce alternatives.
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // Small unusable residual.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        // Exact match with next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        // Leftover after placing next item is tiny.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        // Reward residuals that leave room for a second copy of the next item
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        // Residual well below mean: compact but nearly dead — mild reward.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // closeness of post-fit residual to mean residual is a good donor state
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Unusable capacity given next item size.
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // Wide gap band penalty.
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // Ratio bands that leave a good follow-up residual.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Scarcity + confirmed dead space.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // Residual straddling mean without fitting next item.
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // Overshoot into a wide gap.
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen105: compact-fill bonus — reward very small item into large residual only
        // if the leftover still beats mean residual (keeps donor quality high).
        if item_size <= 10 && post_residual > 0 && next_item_size > 0 && (post_residual as f64) < mean_residual * 0.6 {
            score += 3.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: harmonic classes of post_residual
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 40.0; // near-perfect: dead space minimal
    } else if post_residual <= 20 {
        score -= 20.0;
    } else {
        // penalize post_residual that nothing can fill (next item can't use it)
        if next_item_size > 0 && next_item_size > post_residual {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Harmonic class: post_residual modulo 10 — small residues of awkward classes penalized
    let cls = (post_residual % 10) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }
    score += cls * 0.3;

    // Lookahead synergy: next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 50.0;
        } else if gap <= 10.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - gap / cap);
        }
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave big dead space
    if bin_residual == bin_capacity {
        score = 100.0 + post; // base penalty; a new bin is a last resort
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // late in stream, prefer packing into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference to fill bins with low residual relative to mean
    score -= (mean_residual - post) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        // Penalty grows as the gap shrinks (smaller gap = worse).
        let severity = (dead_threshold - post_residual + 1) as f64;
        score += 25.0 * severity;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (item occupies most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += 3.0 * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small miss), mildly penalize leaving that gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    // (large dead space would result) or no bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual <= dead_threshold;
        if bad_fit || fitting_bins_count == 0 {
            score -= 35.0;
        } else {
            // Discourage opening new bins when a reasonable fit exists.
            score += 20.0 + 2.0 * mean_residual * 0.1;
        }
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;

    // Lookahead snugness: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 40.0 + 0.3 * next_item_size as f64 + 15.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportionally to stranded gap.
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 8.0 + 12.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny slivers are near-waste: reward consuming them (they vanish).
        score -= 22.0;
    } else if post_residual < 20 {
        score -= 7.0;
    }

    // Tightness reward relative to capacity.
    let tightness = 1.0 - dead_space;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 28.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate (empty bin): usually penalize, unless lookahead fits well.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 35.0;
        } else if lookahead_fits {
            score -= 18.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 55.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 12.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // gen106: scale new-bin penalty with fleet tightness and scarcity.
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = (1.0 - mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
        }
    } else {
        // Waste-ratio bands for open bins.
        let waste_ratio = dead_space;
        if waste_ratio < 0.08 {
            score -= 12.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Residual that leaves room for a second copy of next item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && waste_ratio < 0.45 {
            score -= 2.0 + 2.0 * (0.45 - waste_ratio);
        }
        // Penalize residuals straddling mean without fitting next item.
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // Overshoot into a wide gap is bad.
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if over > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // Post-next-item leftover that is itself nearly dead.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            let lr = leftover as f64 / cap;
            if lr < 0.05 {
                score -= 5.0 * (1.0 - lr / 0.05);
            }
        }
        // Unusable gap confirmed by lookahead.
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // gen106: endgame squeeze — late in the stream, aggressively fill open bins.
        if progress > 0.8 && post_residual > 0 && post_residual >= item_size {
            score -= 6.0 * (progress - 0.8) / 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
