        }
    } else {
        score -= 25.0 * progress;
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio < 0.05 {
            score -= 20.0;
        } else if waste_ratio > 0.5 && next_item_size > 0 && next_item_size > post_residual {
            score += 12.0 * (waste_ratio - 0.5);
        }
        // mid-band dead space with next item not fitting: overshoot penalty
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // avoid residuals straddling mean while stranding next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // second copy of next item fits: reward
        if next_item_size > 0 && post_residual >= 2 * next_item_size && waste_ratio < 0.45 {
            score -= 1.5 + 2.0 * (0.45 - waste_ratio);
        }
        // unusable remainder beyond next item
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // near-mean residual target band
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
    }

    // late-stream endgame: keep residues usable
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack that still accommodates the next item is valuable.
            score -= 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64 + post_residual as f64));
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64 / (bin_capacity as f64);
            score += 22.0 * waste;
        }
    }

    // Perfect fit bonus: exact fill.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid unnecessary bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // It should only win when existing fits are poor. Make the empty bin
    // attractive when the current item is large and would leave a big
    // unusable hole in an existing bin, or when open bins are already tight.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins well; small items should use existing bins.
        score -= 10.0 * fill_ratio * fill_ratio;
        // If existing bins are tight on average, a fresh bin is more appealing.
        score -= 8.0 * (1.0 - mean_residual / bin_capacity as f64);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 * progress;
    }

    // Prefer bins whose residual is below the mean (tighter than average),
    // encouraging consolidation of space into fewer, fuller bins.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * mean_gap;

    // Mild penalty for very small resulting residuals (<10) that are hard to reuse,
    // unless it's a perfect fit situation already rewarded.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Early stream: encourage keeping residuals flexible (moderate post_residual),
    // late stream: prioritize immediate packing efficiency.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let flexibility = 1.0 - ((post_residual as f64 - bin_capacity as f64 * 0.5).abs() / (bin_capacity as f64 * 0.5));
    score -= 6.0 * (1.0 - progress) * flexibility;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial penalty on residual fraction, growing with stream progress
    score += progress * 40.0 * norm_pr * norm_pr;
    score += (1.0 - progress) * 10.0 * norm_pr * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= progress * 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead coupling: penalize if post_residual cannot fit next item but barely misses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // next item can still fit: mild reward, stronger if snug
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 8.0 * snug * snug;
        } else {
            // dead space relative to next item: penalize proportionally to waste
            let waste = (pr - nx) / cap;
            score += 20.0 * waste * waste + 10.0 * waste;
        }
    }

    // Penalize bins whose residual deviates badly from the mean residual (imbalance)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for proliferating many open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // New-bin candidate: keep it attractive only when residual would be large
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
        score += 30.0 * norm_pr * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets reward "clean" residuals
    let pr = post_residual as u32;
    let class = pr % 10;
    // Dead-space penalty: residuals too small for typical items are wasted
    if pr < 10 {
        score += 40.0; // unusable sliver
    } else if pr < 20 {
        score += 12.0 + (10 - class) as f64;
    } else {
        // reward residuals that align with common size classes (multiples of 10)
        if class == 0 {
            score -= 6.0;
        } else if class <= 3 {
            score += 3.0;
        }
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // residual is reusable by next item: reward proportionally
            score -= 8.0 * (next_item_size as f64 / cap);
            // harmonic bonus if next item exactly matches residual class
            if pr % 10 == next_item_size % 10 && pr != next_item_size {
                score -= 3.0;
            }
        } else {
            score += 6.0; // residual likely dead for next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 - 0.25 * item_size as f64;
        // but if item is huge and would leave tiny residual elsewhere, new bin is fine
        if item_size as f64 > 0.8 * cap {
            score -= 25.0;
        }
    }

    // Mild pressure toward tight bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Prefer bins tighter than the mean residual (good packing)
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    }
    // Reward leaving a gap that can fit the (known) next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize large waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Open-bins pressure: with many open bins, favor filling existing ones.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0)) ;
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    // Early stream: be slightly more open to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with the next item size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect follow-up fit
        } else if post_residual >= next_item_size {
            // next item fits here: reward tighter matches
            score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // next item would not fit: penalize wasted potential
            score += 10.0 + 0.2 * diff;
        }
    }

    // Penalize small unusable dead space (post_residual below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);
    score -= 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when current bins are very full
    // or the item is large and would leave tiny dead space elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 20.0 - 0.15 * crowded - 5.0 * progress;
        if item_size >= 70 {
            score -= 10.0; // large items start fresh bins happily
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Perfect fit gets a huge discount.
    if post_residual == 0 {
        score -= 250.0;
    }

    // Penalize residuals too small for the smallest possible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 90.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0;
        } else {
            score += 25.0;
        }
        // Coupling: post-residual close to next item size is ideal.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 20.0 / (1.0 + gap);
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Penalize when many bins can fit the item but we pick a loose one.
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Time horizon: early in the stream, be conservative (favor new bins over waste);
    // late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Encourage balancing residual distribution: prefer bins with residual below mean
    // (fill the emptier bins first to consolidate full ones).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 0.4 * item_size as f64;
        // Late in stream, avoid opening bins.
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr;

    // Quadratic coupling: penalize large residuals non-linearly as stream progresses
    let prog_sq = progress * progress;
    score += 40.0 * norm_pr * norm_pr * (0.5 + prog_sq);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 30.0 * fit * (1.0 - norm_pr) * (0.3 + progress);

    // Dead-space penalty: residuals too small for any plausible item
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 25.0 * dead * (0.5 + progress);

    // Mean-residual deviation coupling (smooth cubic in normalized residual)
    let dev = norm_pr - mean_residual / cap;
    score += 15.0 * dev * dev * dev * cap * 0.01;

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor bins whose post-residual can host next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 12.0 * (next_item_size as f64 / cap) * (0.5 + progress);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize early, reward when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 10.0 * (1.0 - progress) - 15.0 * frag * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues that commonly combine with
    // typical item sizes (1..100) are more reusable. Class by integer division
    // into harmonic bands of 10, with special handling for small residues.
    let band = post_residual / 10; // 0..=9
    let harmonic_bonus: f64 = match band {
        0 => -50.0,                          // tiny residue (1-9): nearly dead space
        1 => -12.0,                          // 10-19: fits common small items
        2 => -20.0,                          // 20-29
        3 => -18.0,                          // 30-39
        4 => -22.0,                          // 40-49
        5 => -25.0,                          // 50-59
        6 => -20.0,                          // 60-69
        7 => -16.0,                          // 70-79
        8 => -12.0,                          // 80-89
        _ => -8.0,                           // 90-99: nearly full, low reuse value
    };
    score += harmonic_bonus;

    // Modulo arithmetic: residues divisible by 5 or 10 are "harmonic" with
    // typical item sizes and thus more reusable.
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 7.0;
    }

    // Dead-space penalty: residue too small for the smallest plausible item
    if post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward this bin (enables a perfect follow-up fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mildly penalize creating a residue
            // that is useless for the known next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    // Avoid opening a new bin when this placement is acceptable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and open bins are crowded. Base penalty scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let base = 40.0 + 35.0 * crowd + 20.0 * progress;
        // If item is large (>50), a fresh bin is more attractive since it
        // leaves a big reusable residue (100 - item).
        let large_item_discount = if item_size > 50 { 25.0 } else { 0.0 };
        score += base - large_item_discount;
        // If next item is also large, opening a fresh bin is better
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild preference toward bins tighter than the mean (best-fit flavor)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;

    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 20.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            let leftover = post_residual - next_item_size;
            let leftover_ratio = leftover as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let closeness = 1.0 - ((leftover as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        } else {
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
    }

    score += 0.5 * (bin_residual as f64 - mean_residual);

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Dead-space shaping
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 26.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0;
    }

    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
    }

    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        let unusable = dead_space - (next_item_size as f64 / cap);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
        if post_residual < 15 {
            score += 4.0;
        }
        let frag = 1.0 - stranded;
        score += 3.0 * frag * (1.0 + 0.5 * dead_space);
    }

    if dead_space > 0.25 && dead_space < 0.65 && next_item_size > post_residual {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual > 0 {
                let r = post_residual as f64 / next_item_size.max(1) as f64;
                let k = r.round();
                if k >= 1.0 && (r - k).abs() < 0.08 && post_residual >= next_item_size {
                    score += 10.0 * (1.0 - (r - k).abs() / 0.08);
                }
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if open_bins_count >= 2 && next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 6.0;
        }
    } else {
        score -= 20.0 * progress;
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            let rem_ds = leftover as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if progress > 0.7 && next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0 * (progress - 0.7) / 0.3;
        }
        if fitting_bins_count >= 4 && post_residual > 0 && item_size as f64 <= mean_residual {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen108: chain anticipation — reward residuals that after placing the item
        // leave a gap closely matching the next item again (repeatable fills)
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual - next_item_size;
            let chain_gap = (chain as f64 - next_item_size.max(1) as f64).abs();
            if chain_gap <= 3.0 && dead_space < 0.35 {
                score -= 2.5 + 1.5 * (3.0 - chain_gap);
            }
            if chain > 0 && chain < next_item_size && chain < 8 {
                score += 2.0 + 0.5 * (8 - chain) as f64;
            }
        }
        // gen108: scarcity-aware snugness
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let snug = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if snug < 0.25 {
                score -= 3.0 * (1.0 - snug / 0.25);
            }
        }
        // gen108: fleet-balance term against piling into large-residual bins
        if open_bins_count >= 6 && dead_space > 0.55 && next_item_size > 0 && next_item_size <= post_residual {
            score += 1.0 + 0.02 * open_bins_count as f64;
        }
        // gen108 new: reward near-exact fill when the bin is one of few fitting
        // and the leftover would be reusable by the mean-residual stream
        if fitting_bins_count <= 3 && post_residual > 0 && post_residual as f64 <= mean_residual {
            score -= 1.5;
        }
        // gen108 new: penalize leaving residuals just below small-item thresholds
        // (slivers 1..4 wide are rarely reusable)
        if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < next_item_size as f64 && post_residual < 15.0 {
        score += 25.0; // gap too small even for the next item
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: favor bins that keep mean residual healthy.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Late-stream tightening: avoid waste as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Aggressive 2-step lookahead: reward post_residual that matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Perfect match: post_residual exactly equals next item -> big reward.
            let match_err = (pr - nxt) / bin_capacity as f64;
            score -= (1.0 - match_err) * 12.0;
            // Extra reward if next item would fit perfectly, leaving zero residual.
            if pr == nxt {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit in the leftover: penalize dead space,
            // scaled by how much space is wasted relative to capacity.
            score += (nxt - pr) / bin_capacity as f64 * 10.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Compare against mean residual: bins with residual far from mean that
    // end up with tiny post_residual are good consolidation targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.05;
    score += dev * 0.02;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when no open bin offers a decent fit (post_residual
    // small relative to next item need). Penalize opening new bins when
    // plenty of open bins exist and the fit elsewhere is reasonable.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all open bins.
        score += open_bins_count as f64 * 3.0;
        // But if item is huge relative to typical residual, new bin may be best.
        if (item_size as f64) > mean_residual {
            score -= (item_size as f64 - mean_residual) * 0.3;
        }
        // Early in stream, allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Slight preference to keep many open bins from proliferating:
    // favor bins that are already fairly full.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // gen109: fresh bin as donor for the *next two* items — strong lookahead
            if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
                score -= 9.0;
            }
            // gen109: don't open a new bin late in the stream when open bins can still absorb
            if progress > 0.6 && fitting_bins_count >= 2 {
                score += 10.0 + 12.0 * progress;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen109: fine-grained snugness — residual within a few units of item size is prime
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 4 {
                score -= 6.0 + 1.2 * (4 - slack) as f64;
            } else if slack <= 10 {
                score -= 2.0 + 0.5 * (10 - slack) as f64;
            }
        }
        // gen109: penalty when post_residual lands in a dead zone relative to the fleet's mean
        if post_residual > 0 && next_item_size > 0 && post_residual as f64 > mean_residual * 2.0 && next_item_size as f64 > mean_residual {
            score += 3.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward gap zone
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            score += 10.0;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // but allow it when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        score += 35.0
            - 0.15 * open_bins_count as f64
            + 0.10 * (post_residual as f64 - mean_residual).abs();
        if fitting_bins_count == 1 && poor_fit > 40.0 {
            score -= 55.0; // nothing fits well; open fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 30 {
            score -= 12.0; // fresh bin chains well with next item
        }
    }

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, just finish bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.12 * post_residual as f64;
    score -= progress * 0.05 * mean_residual;

    // Global pressure: many open bins -> prefer filling existing ones.
    score += 0.08 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, moderate residuals are fine (bins may be filled later);
    // late in the stream, dead space becomes costly, so penalize super-linearly.
    let prn = pr / cap;
    let coupling = prn * prn * (0.5 + 2.0 * progress) + prn * prn * prn * (1.0 + 3.0 * progress * progress);
    score += coupling * cap * 0.35;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tightness = 1.0 - prn;
    score -= tightness * tightness * cap * (0.15 + 0.25 * progress);

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gapn = gap / cap;
        // Smooth penalty growing with mismatch; exact match (gap=0) gives max bonus.
        score += gapn * cap * (0.4 + 0.4 * progress);
        // Extra reward if next item fits at all in this bin after placement.
        if nxt <= pr {
            score -= 0.5 * (1.0 - gapn);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin (unless post residual is huge).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * (1.0 - prn);
    }

    // Slight penalty when many bins are open and residual is large (fragmentation pressure).
    let open_f = open_bins_count as f64;
    score += 0.05 * prn * open_f.sqrt() * (0.5 + progress);

    // Divergence from mean residual: prefer bins close to the mean to keep balance,
    // with smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 0.6 * dev * dev * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral-ish baseline; only attractive when all fits are bad.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) + 0.1 * prn * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // gen110: a fresh bin is attractive when it can host the next item AND a
            // follow-up copy, i.e. capacity >= 2*next, especially under scarcity.
            if next_item_size > 0 && next_item_size as f64 * 2.0 <= cap {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score -= 4.0 + 10.0 * scarcity * (1.0 - progress);
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen110: two-copy lookahead with scarcity weighting — prefer bins where the
        // next item AND its successor-sized copy both fit when alternatives are few.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // gen110: penalize leaving a residual just below the next item (wasted sliver)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);

    // ---- Harmonic class of the post-placement residual ----
    // Partition residual space into octiles of the capacity; the lowest
    // classes (nearly closed bins) are favored, mid classes are awkward.
    let oct = (bin_capacity / 8).max(1);
    let class = post_residual / oct;

    // Perfect closure: bin completely filled.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead zone: leftovers so small they are unlikely to be reused later.
    if post_residual > 0 && post_residual <= 3 {
        score += 4.0 + 4.0 * progress;
    }

    // Class shaping on top of the linear best-fit base.
    match class {
        0 => score -= 3.0,
        1 => score -= 1.0,
        2 | 3 => score += 1.0,
        4 | 5 => score += 0.5,
        _ => {}
    }

    // Decade alignment: residuals on the 10-grid pair cleanly with
    // decimal-grained item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post_residual >= nxt {
            let slack = post_residual - nxt;
            if slack == 0 {
                score -= 18.0; // perfect two-item chain
            } else if slack <= 3 {
                score -= 7.0;  // chain leaving a negligible tail
            } else {
                score -= 2.5;  // generic chainability
            }
        } else if bin_residual >= nxt && fitting_bins_count > 1 && !is_new_bin {
            // This placement destroys a spot the lookahead item could use.
            score += 5.0;
            if item_size < nxt {
                score += 3.0; // the follower is bigger: preserving its spot matters more
            }
        }
    }

    // ---- Last chance: this is the sole open bin that fits the item ----
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0;
    }

    // ---- New-bin candidate penalty ----
    // Opening a fresh bin is wasteful while open bins hold slack; relax the
    // penalty as bins fill up and as the stream matures.
    if is_new_bin {
        score += 10.0
            + 35.0 * mean_frac
            + 2.0 * (open_bins_count as f64).sqrt()
            + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers (< 10, or below typical item floor) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // creates gap that next item cannot use
        }
    }

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 0.3;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin pairs well with upcoming large item
        }
    }

    // Prefer tightest bins overall: deviation from mean residual.
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits leaving minimal slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 2.0 * (1.0 - slack_after_next as f64 / post_residual.max(1) as f64);
    }

    // Dead space: next item cannot use the leftover.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize tiny unusable residuals (wasted space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in stream: tighten packing, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 {
        // dead space that likely can never be used again is very costly
        let dead_risk = if post_residual < 20 { 1.0 } else { 0.0 };
        score += 35.0 * dead_risk;
    }

    // Lookahead: bonus if next item fits exactly into post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item fits leftover
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving large leftovers that tempt bad splits
            score += 8.0;
        }
    } else {
        // last item: any bin that fits is fine; strongly prefer filling existing bins
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity) should score high
    // (i.e., be chosen) only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by global state
        let mut open_cost = 45.0;
        // cheaper to open new bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        open_cost *= 0.6 + 0.8 * progress;
        // if many bins are open with lots of slack, discourage opening another
        open_cost += 0.5 * (open_bins_count as f64).ln().max(0.0);
        open_cost += 0.15 * (mean_residual - post_residual as f64).max(0.0);
        // if no other bin fits (fitting_bins_count == 0 among open bins means this
        // call is the only fallback), make new bin attractive
        if fitting_bins_count == 0 {
            open_cost -= 60.0;
        }
        score += open_cost;
    }

    // Mild preference for bins whose residual is close to item_size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Slight tie-break toward bins with residuals near mean (avoid fragmenting outliers)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 8.0 * fit * fit * cap * prog_poly;      // penalize dead space more late in stream
    score -= 6.0 * fit * (1.0 - fit) * cap * (1.0 - prog_poly); // reward tight fits early

    // Penalize opening a new bin when other bins fit, more strongly as stream progresses
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 * (1.0 + prog_poly) * (fitting_bins_count as f64);
    }

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - fit);
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - pr / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += 2.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" residue classes (multiples of 10/25/50) are more reusable.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit is always excellent
    } else {
        let class_bonus = if post % 50 == 0 {
            25.0
        } else if post % 25 == 0 {
            15.0
        } else if post % 10 == 0 {
            10.0
        } else if post % 5 == 0 {
            5.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Dead-space penalty: tiny unusable leftovers are bad.
        if post < 10 {
            score += 30.0;
        }

        // Harmonic match with lookahead item (k=2): reward residuals that
        // can exactly or nearly host the next item.
        if next_item_size > 0 && next_item_size <= post {
            let slack = post - next_item_size;
            if slack == 0 {
                score -= 45.0;
            } else if slack <= 5 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
            // modulo coupling: next item in same harmonic class as residual
            if post % 10 == next_item_size % 10 {
                score -= 5.0;
            }
        } else if next_item_size > post {
            // this bin cannot host the next item: mild penalty scaled by gap
            let gap = (next_item_size - post) as f64;
            score += gap * 0.15;
        }

        // Integer-division threshold on residual fraction of capacity.
        let frac = post as f64 / bin_capacity as f64;
        let band = (frac * 4.0) as u32; // quarter bands
        match band {
            0 => score += 8.0,   // nearly full: fine, little waste left
            1 => score -= 6.0,   // 25-50% free: attractive
            2 => score -= 3.0,
            _ => {}              // mostly empty: keep as-is
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open
    // bins are congested (few fitting bins, high mean fill).
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64) * 1.5
            - mean_residual * 0.3
            + (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight global pressure: prefer tightening bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: fewer open bins -> prefer existing bins; many open bins -> allow new bins.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item would be blocked by this placement, penalize slightly.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_residual {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline with mild bias so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * mean_residual;
    }

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step lookahead match (next item exactly fills this bin).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Soft reward: next item still fits comfortably after this placement.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.5;
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize leaving tiny unusable residuals (dead space), scaled by progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + 20.0 * progress;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin is unusable
    // or the new bin offers a better 2-step plan.
    if bin_residual == bin_capacity {
        let mut penalty = 80.0 + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 50.0;
        }
        if post_residual < item_size.min(next_item_size.max(1)) {
            penalty -= 0.0; // fresh bin still has full residual anyway
        }
        score += penalty;
    }

    // Mild preference for filling existing bins more fully early in the stream.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / cap;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Two-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 - 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let snug = 1.0 - slack / post_residual.max(1) as f64;
            score -= 180.0 + 120.0 * snug + 0.35 * next_item_size as f64;
            // after placing next item, residual still large enough to be useful
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            }
            // leftover after chaining next item: reward tiny leftovers
            let leftover = post_residual - next_item_size;
            let leftover_ratio = leftover as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 25.0 * (1.0 - leftover_ratio / 0.05);
            }
            // residual close to mean after chain: good donor
            let closeness = 1.0 - ((leftover as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 20.0 * (closeness - 0.8);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // penalize stranding potential proportional to gap
            score += 40.0 + 60.0 * (gap / cap).min(1.0);
            // small stranded residue below next item is worse if tiny
            if post_residual < 8 {
                score += 40.0;
            }
            // fragility: residual far below next item in a dead bin
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            // unusable remainder
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }
    // mid-band dead space penalty (wasted capacity that next item can't use)
    if post_residual > 0 && dead_space > 0.25 && dead_space < 0.65 {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }
    // reward residuals that leave room for a second copy of next item
    if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && dead_space > 0.05 {
        score -= 1.5 + 2.0 * (0.45 - dead_space);
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            // open a fresh bin only when nothing fits well and next item chains
            score -= 100.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 60.0 + 60.0 * progress + 0.25 * slack + 2.0 * open_bins_count.min(12) as f64;
            // if next item is large and no open bin will hold it, opening early is fine
            if next_item_size as f64 > mean_residual && fitting_bins_count == 0 {
                score -= 25.0;
            }
            // gen112: scale new-bin penalty with scarcity AND tightness of the fleet
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            // gen112: near end of stream, avoid opening fresh bins
            if progress > 0.8 {
                score += 8.0 * (progress - 0.8) / 0.2;
            }
        }
    } else {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // reward near-exact fills of existing bins
        let waste_ratio = dead_space;
        if waste_ratio < 0.05 {
            score -= 20.0;
        } else if waste_ratio > 0.5 && next_item_size > 0 && next_item_size > post_residual {
            // this bin would strand >50% while next item doesn't fit
            score += 12.0 * (waste_ratio - 0.5);
        }
        // gen112: late stream — grab nearly-fitting small residues aggressively
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // gen112: tight waste with few alternatives is valuable
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // gen112: penalize residuals straddling the mean that can't host next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize dead space that no future item can plausibly fill.
    let dead = post_residual as f64;
    if next_item_size > 0 && (next_item_size as f64) > dead {
        score += dead * 0.35; // unusable gap penalty
    } else if next_item_size > 0 {
        // Reward leaving exactly room for the next item.
        let gap = (dead - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / bin_capacity as f64).powi(3);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer keeping flexibility, mild penalty for wasteful use.
        score += 0.8 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins with residual below the mean (consolidate small leftovers).
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // Time horizon modulation: early stream, encourage opening bins for large items;
    // late stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more later in the stream.
        score += 20.0 * (1.0 - progress) + 3.0 * (open_bins_count as f64).sqrt();
        if item_size > 60 && progress < 0.4 {
            score -= 8.0; // big items early deserve fresh bins
        }
    } else {
        score -= 5.0 * progress;
    }

    // Avoid leaving residuals in the awkward 30..50 range (hard to fill).
    if dead >= 30.0 && dead <= 50.0 {
        score += 4.0 * (1.0 - (dead - 40.0).abs() / 10.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted space, with non-linear (quadratic) growth for large residuals
    let mut score = pr * (1.0 + 0.9 * pr_norm * pr_norm);

    // Smooth coupling: residual waste matters more as stream progresses
    score += 6.0 * pr_norm * pr_norm * progress * cap * 0.1;

    // Reward tight fits: smooth bonus decaying with post_residual
    score -= 14.0 * (-pr_norm * 7.0).exp();

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n) / cap;
        score += 5.0 * gap * gap;
        score -= 3.0 * (-(gap.abs()) * 5.0).exp();
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into bins with low residual (smooth)
    let mean_norm = mean_residual / cap;
    score += 4.0 * (pr_norm - mean_norm) * (pr_norm - mean_norm) * (open_bins_count.min(20) as f64);

    // New-bin candidate: make it attractive only when post_residual is huge (item is small)
    // i.e., penalize new bin unless the fit is very loose in existing bins
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 0.9 * pr_norm * pr_norm) + 10.0 * (1.0 - progress) - 20.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins are grouped by
    // post_residual / 10 decile (capacity 100 -> 10 classes).
    let post_class = post_residual / 10;
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size + 9) / 10 };

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when the harmonic class of the leftover exactly matches
    // the class of the next item (leftover is a "harmonic" of next size).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_class == next_class {
            score -= 12.0;
        } else if post_residual >= 2 * next_item_size {
            score -= 6.0;
        } else {
            score -= 3.0;
        }
    }

    // Penalize dead space: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Penalize leaving a residual in an "awkward" class (1..9 mod 10 range
    // with small value): modulo-arithmetic awkwardness.
    let awkward = post_residual % 10;
    if post_residual > 0 && awkward != 0 && post_residual < 30 {
        score += (awkward as f64) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * (open_bins_count as f64);
    }

    // Prefer filling bins below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance: gaps too small for the next item are waste.
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + 15.0 * (1.0 - next_item_size as f64 / (post_residual.max(1) as f64)).clamp(0.0, 1.0);
        if gap <= 6.0 {
            score += 9.0 + 1.5 * (6.0 - gap);
        } else if gap <= 12.0 {
            score += 3.0 + 0.4 * (12.0 - gap);
        }
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
    }

    // Lookahead synergy: next item fits snugly into the residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        if post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
        // room for a second copy of the next item
        if post_residual >= 2 * next_item_size && dead_space < 0.45 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
    }

    // Exact fit is gold; tiny slivers strongly penalized.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - dead_space;
    score -= 25.0 * tightness * tightness;

    // Waste-ratio bands.
    if dead_space < 0.08 {
        score -= 13.0;
    } else if dead_space > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }
    if dead_space > 0.25 && dead_space < 0.65 {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }
    if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
        score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
        }
        score -= 0.3 * item_size as f64;
        // fresh bin as donor when residual matches mean
        if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
            score -= 5.0;
        }
    } else {
        // gen113: prefer consolidating into bins whose residual matches the next item band
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // gen113: penalize residual straddling the mean without fitting the next item
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // gen113: unusable space beyond next item's needs
        if post_residual > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // gen113: overshoot into a wide gap
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen113: two-fit ratio bands
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // gen113: exact next-item match bonus scaled by scarcity
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
        }
    }

    // Endgame pressure: late in the stream, avoid opening new bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Reward tight fits (item occupies most of the bin's free space).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly or well in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            score += 8.0; // next item won't fit here; dead space likely
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; only attractive
    // if all existing residuals are poor fits (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && fit_ratio > 0.7 {
            score += 30.0; // existing bin fits well; don't open a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
