    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        score += 70.0;
        // allow new bin when item is large and lookahead is large
        if item_size >= 50 && next_item_size >= 50 {
            score -= 90.0;
        }
    }

    // Slight preference for filling bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            score += 6.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when there are many open bins with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_slack = mean_residual / cap;
        score += 30.0 + 25.0 * avg_slack + 15.0 * (open_bins_count as f64).ln();
        // Late in the stream, opening new bins is more wasteful.
        score += 10.0 * progress;
        // If next item is large, a fresh bin may still be attractive.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    } else {
        // Slight preference for bins with residual near mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / cap;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual < 10 {
        score -= 22.0; // tiny residue is nearly perfect: reward instead of penalize
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Two-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 650.0 + 30.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            let snug = 1.0 - slack / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 120.0 * snug;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            }
            // leftover after next item lands: tiny leftover is great
            let leftover_ratio = slack as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 + 60.0 * (gap / cap).min(1.0);
            // fragment penalty scaled by dead space
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            if post_residual < 8 {
                score += 30.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
