            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen115: two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // gen115: penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // gen115: late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of common
    // item sizes is more reusable than arbitrary remainders.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo classes: post_residual divisible by 10/20/25 is "harmonic" and reusable.
    let harmonic = if post_residual > 0 {
        match post_residual % 10 {
            0 => {
                if post_residual % 50 == 0 { 0.0 }
                else if post_residual % 20 == 0 { 2.0 }
                else { 4.0 }
            }
            5 => 6.0,
            _ => {
                // penalize awkward remainders more as they grow
                (post_residual % 10) as f64 * 0.8
            }
        }
    } else {
        -30.0 // perfect fit is always excellent
    };
    score += harmonic;

    // Integer-division thresholds on post_residual: classify into usable slots.
    let slot = post_residual / 10; // 0..10 slots
    let slot_f = slot as f64;
    // Dead space below 10 is useless; penalize heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Slots that can host the smallest item (>=10) are valuable; reward mildly.
    score -= slot_f * 1.5;

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + (next_item_size as f64) * 0.15;
            // extra reward if next item also harmonically divides the post space
            if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot class
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is poor.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // base penalty to prefer reusing open bins
        score += 30.0;
        // large items justify fresh bins more; small items should pack into scraps
        score -= (item_size as f64) * 0.2;
        // as stream progresses, allow more new bins (avoid hoarding scraps early)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 12.0;
        // if open bins are on average nearly full, new bin is fine
        score -= (mean_residual / cap).max(0.0).min(1.0) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight fits: reward small post_residual relative to item size (good density).
    let fill_ratio = (item_size as f64) / cap;
    score -= fill_ratio * 6.0;

    // Waste fraction coupling: penalize post_residual as fraction of capacity, nonlinearly.
    let waste_frac = post / cap;
    score += waste_frac * waste_frac * 14.0;

    // Mean-residual context: if this bin is much tighter than average, favor it.
    let rel = (bin_residual as f64) - mean_residual;
    score += rel * 0.05;

    // Mild pressure to keep open bin count low late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);

    // Lookahead synergy: next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Dead-space ladder.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Waste-ratio bands.
    let waste_ratio = dead_space;
    if post_residual > 0 {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    // Stranded slivers relative to next item.
    if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
    }

    // Two-fit bonus: residual leaves room for a second copy of next item.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
    }

    // Exact-match with next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        if waste_ratio < 0.1 {
            score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
        }
    }

    // Near-fit band.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
    }

    // Leftover after placing next item nearly empty.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
        let rem_ds = leftover_ratio;
        if rem_ds > 0.02 && rem_ds < 0.12 {
            score -= 4.0 * (1.0 - rem_ds / 0.12);
        }
    }

    // Mid-gap band penalty.
    if dead_space > 0.25 && dead_space < 0.65 {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let miss = next_item_size - post_residual;
                if miss <= 6 {
                    score += 9.0 + 1.5 * (6 - miss) as f64;
                } else if miss <= 12 {
                    score += 3.0 + 0.4 * (12 - miss) as f64;
                }
            }
            let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
            if next_item_size > 0 && next_item_size > post_residual {
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Late-stream adjustments.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space disproportionately
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits strongly
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        score += (next_item_size as f64 - post_residual as f64).abs() * 0.3;
    }

    // Pull score toward mean residual alignment: avoid bins far from mean
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // New bin candidate: neutral baseline with slight penalty so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0; // perfect closure of a bin
    } else {
        // Penalize dead space non-linearly: residuals below 10 are nearly useless.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual > 50 {
            score -= 10.0; // large residual keeps flexibility
        }
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
            // reward tightness of the lookahead fit
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: placing into a bin with residual above mean
    // (a "loose" bin) is preferable; a below-mean bin is precious.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or fits are poor.
    if bin_residual == bin_capacity {
        let openness = (step_index as f64 / (total_items.max(1) as f64).max(1.0)).min(1.0);
        // Base penalty so open bins are preferred for tight fits...
        score += 40.0;
        // ...but a fresh bin is good for large items or when few bins fit the item.
        if item_size > 60 || fitting_bins_count == 0 {
            score -= 55.0;
        }
        if open_bins_count > 0 && next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0 * (1.0 - openness); // early stream: fresh bins stay flexible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement: reward high fill.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score -= 15.0; // near-perfect closure is excellent
    } else if post_residual > 0 {
        // Waste that is large but still usable is mildly penalized.
        score += 0.15 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for stranding residual.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Large items are fine in fresh bins.
        score -= 0.4 * item_size as f64;
        // If many bins are open and mean residual is high, prefer reusing them.
        score += 0.3 * open_bins_count as f64 + 0.5 * mean_residual;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer packing into bins whose residual is already small (tight packing),
    // scaled by global mean residual to avoid over-tightening early.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for bins with residual close to item (perfect-fit seeking).
    score += 0.5 * (bin_residual as f64 - item_size as f64).abs().powf(1.2) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, slack is acceptable.
    let tightness = pr / cap; // 0..1
    let progress_weight = 0.35 + 0.65 * progress;
    score += progress_weight * (tightness * tightness) * cap * 0.5;

    // Penalize dead space that no plausible item can use: quadratic in (cap - pr gap)
    let dead = if pr > 0 && pr < 10 { (10.0 - pr) * (10.0 - pr) } else { 0.0 };
    score += dead;

    // Lookahead: reward leaving room for the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        let closeness = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= 6.0 * fits_next * closeness * closeness;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate penalty: opening a bin is costly unless residual would be well usable
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * (1.0 - tightness) * (1.0 - tightness) * progress;
    }

    // Slight preference for bins below mean residual (consolidating space)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via modulo classes
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -40.0,                                  // perfect fit
        x if x < 10 => 25.0 + x as f64,              // unusable sliver
        x if x % 10 == 0 => -12.0,                   // harmonic decade residual
        x if x % 5 == 0 => -6.0,
        _ => 4.0,
    };
    score += class_penalty;

    // Integer-division threshold: how many "typical" small items still fit
    let slots = pr / 10;
    score -= (slots as f64) * 3.0;

    // Lookahead coupling: reward if next item fits post residual exactly or harmonically
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;                            // perfect lookahead fit
        } else if next_item_size <= pr {
            score -= 8.0;
            if pr % next_item_size == 0 && next_item_size >= 10 {
                score -= 6.0;                         // divides evenly: harmonic packing
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.5; // next item won't fit here
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current residuals are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_bad = mean_residual / cap;
        score += 20.0 - 30.0 * avg_bad + 10.0 * progress;
        if item_size >= 70 {
            score -= 15.0; // big item likes fresh bin
        }
    }

    // Prefer tightest fit overall: normalize residual pressure
    score += (post_residual as f64 / cap) * 10.0;

    // Penalize spreading across many open bins slightly
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Two-step lookahead with snugness scaling (combined with best-heuristic weights)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 120.0 * snug + 0.35 * next_item_size as f64 + 17.0 * snug;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            } else {
                let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
                if leftover_ratio < 0.05 {
                    score -= 5.0 * (1.0 - leftover_ratio / 0.05);
                }
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let gap_ratio = gap / next_item_size.max(1) as f64;
            score += 40.0 + 60.0 * (gap / cap).min(1.0) + 8.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
            if post_residual < 8 {
                score += 40.0;
