        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // refined dead-space valley: reward residual bands matching typical next-item multiples
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && waste_ratio > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && waste_ratio > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // penalize mid-band dead space more sharply when few bins fit the item
        if waste_ratio > 0.3 && waste_ratio < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // reward residuals that leave room for a second copy of the next item
        if next_item_size > 0 && post_residual >= 2 * next_item_size && waste_ratio < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - waste_ratio);
        }
        // penalize residual straddling the mean without fitting the next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // target residuals near the next item's size band — avoid overshooting into a wide gap
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && waste_ratio > 0.4 {
                score += 2.0 + 3.0 * (waste_ratio - 0.4);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps < 10 that can hold nothing).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that few items can fit.
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // over starting new bins (penalize the empty new-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + 6.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // If next item would leave an even tighter fit, slight reward.
    if next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) < 10 {
        score -= 10.0;
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - tightness);

    // Slight preference toward bins with below-mean residual (balance spreading).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

