    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) already favored.

    // 2-step lookahead: strongly reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportionally to how well next item fits, decaying with slack.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow; penalize dead space relative to next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Compare post_residual against mean residual: creating below-average residual
    // (tight packing) is good; leaving above-average residual is wasteful.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr < mean_residual {
            score -= 0.5 * (mean_residual - pr);
        } else {
            score += 0.3 * (pr - mean_residual);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current bin
    // would leave a large awkward residual and the next item is big.
    if bin_residual == bin_capacity {
        let awkward = (bin_capacity - item_size) as f64;
        let next_pressure = if next_item_size > 0 && next_item_size > bin_capacity - item_size { 20.0 } else { 0.0 };
        // Fresh bin starts attractive only if this placement wastes little and lookahead is bad.
        score = 40.0 + awkward * 0.2 - next_pressure;
    }

    // Late-stream tightening: as stream progresses, penalize loose fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

