            score -= 1.5 + 2.0 * (0.45 - waste_ratio);
        }
        // penalize residual straddling the mean without fitting the next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // target residuals near the next item's size band — avoid overshooting into a wide gap
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && waste_ratio > 0.4 {
                score += 2.0 + 3.0 * (waste_ratio - 0.4);
            }
        }
        // gen117: compaction bonus — post-residual that still fits the mean residual tightly
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() <= 2.0 {
            score -= 3.0;
        }
        // gen117: when the item leaves a residue exactly reusable by the next item plus a small margin
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) <= 4 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
