pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= 3.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys a bin that could host the next item.
            score += 10.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer consolidation into existing bins over new bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: make fresh empty bins moderately attractive
    // only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, discourage opening new bins.
        score += progress * 20.0;
    }

    // Coupling with global mean residual: bins far below mean residual are
    // "loose" — prefer filling them to balance the pool.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), with smooth polynomial shaping
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 30.0;

    // Smooth interaction: tight fits become more valuable as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= progress * tightness * tightness * 25.0;

    // Penalize dead space that is too small for typical future items (smooth trough)
    let dead = norm_pr * (1.0 - norm_pr);
    score -= dead * 10.0;

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 3.0;
    }

    // Lookahead: reward residual that can still host the next item (smoothly)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let next_norm = next_item_size as f64 / cap;
        score -= fits_next * (1.0 - next_norm) * (10.0 + 15.0 * progress);
        score += (1.0 - fits_next) * norm_pr * 8.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 4.0;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 12.0;

    score
