    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit is ideal
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }

        // Dead-space penalty for tiny unusable residuals
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }

        // Integer-division threshold: residual class relative to next item
        if next_item_size > 0 {
            if pr >= next_item_size {
                // can also host the next item: reward chaining
                score -= 6.0;
                // extra reward if next item divides cleanly into remaining space
                if (pr % next_item_size.max(1)) == 0 {
                    score -= 6.0;
                }
                // reward if post residual is an integer multiple of half next size
                if next_item_size > 0 && pr % ((next_item_size / 2).max(1)) == 0 {
