    }

    // New-bin candidate: only attractive when no good open option exists.
    // Penalize opening a new bin mildly; the reward scales with how full the stream is.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + 30.0 * progress;
