        }
        // open a new bin if next item is large and would fit better in a fresh bin
        if next_item_size > 0 && next_item_size > item_size {
            score -= 20.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    // Small tie-breaker based on how tightly the item fills the bin
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
