            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual > 0 {
                let r = post_residual as f64 / next_item_size.max(1) as f64;
                let k = r.round();
                if k >= 1.0 && (r - k).abs() < 0.08 && post_residual >= next_item_size {
                    score += 10.0 * (1.0 - (r - k).abs() / 0.08);
                }
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // gen119: a fresh bin is a good donor when post_residual exactly matches next item
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 6.0;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if open_bins_count >= 2 && next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 6.0;
        }
    } else {
        score -= 20.0 * progress;
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            let rem_ds = leftover as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if progress > 0.7 && next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0 * (progress - 0.7) / 0.3;
        }
        if fitting_bins_count >= 4 && post_residual > 0 && item_size as f64 <= mean_residual {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen119: chain anticipation — reward residuals that after placing the item
        // leave a gap closely matching the next item again (repeatable fills)
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual - next_item_size;
            let chain_gap = (chain as f64 - next_item_size.max(1) as f64).abs();
            if chain_gap <= 3.0 && dead_space < 0.35 {
                score -= 2.5 + 1.5 * (3.0 - chain_gap);
            }
            if chain > 0 && chain < next_item_size && chain < 8 {
                score += 2.0 + 0.5 * (8 - chain) as f64;
            }
        }
        // gen119: scarcity-aware snugness
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let snug = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if snug < 0.25 {
                score -= 3.0 * (1.0 - snug / 0.25);
            }
        }
        // gen119: fleet-balance term against piling into large-residual bins
        if open_bins_count >= 6 && dead_space > 0.55 && next_item_size > 0 && next_item_size <= post_residual {
            score += 1.0 + 0.02 * open_bins_count as f64;
        }
        // gen119: reward near-exact fill when the bin is one of few fitting
        if fitting_bins_count <= 3 && post_residual > 0 && post_residual as f64 <= mean_residual {
            score -= 1.5;
        }
        // gen119: penalize leaving residuals just below small-item thresholds
        if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Penalize gaps that can only fit tiny items relative to observed item scale.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += pressure * 20.0 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean-residual coupling: bins deviating below mean residual are well-packed.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: opening a fresh bin is only attractive when the current item
    // would leave a bad gap in every open bin, or when few bins are open early on.
    if bin_residual == bin_capacity {
        let bad_gap = post_residual > 0 && post_residual < 10;
        if bad_gap && fitting_bins_count >= 1 {
            score += 30.0; // keep item in an open bin anyway
        } else if open_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 15.0 + 5.0 * (open_bins_count as f64).min(10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.87;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild quadratic penalty
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next fills bin exactly
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // reward close-but-not-exact chain fits, decaying with gap
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // penalize leaving a tiny useless gap (<10 unusable)
            if gap > 0.0 && gap < 10.0 {
                score += 25.0;
            }
        }
        // next item doesn't fit here: slight penalty proportional to leftover dead space
        let dead = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.05 * dead;
    } else {
        // last item: strongly prefer fullest packing
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current residuals are large/poor fits
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && next_item_size < post_residual { 0.0 } else { 1.0 };
        score += 35.0 - 0.4 * mean_residual + 20.0 * poor_fits;
        // early stream: new bins are cheap to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
    }

    // Slight preference for consolidating among many open bins
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post-residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as u32 - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty if it creates fragmentation.
        score += 8.0;
    }

    // Prefer filling bins with large residual when many bins are open (reduce bin count pressure).
    score += (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.5;

    // Compare against mean residual: prefer bins that deviate toward tighter usage.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins (keep flexibility);
    // late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper to open early, expensive late.
        score = 25.0 + 80.0 * progress - (item_size as f64) * 0.1;
        if fitting_bins_count == 1 {
            score += 120.0; // avoid opening when a unique fitting bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
    } else {
        // Late stream: reward using existing bins more.
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in stream, tolerate larger residuals; late, penalize dead space harder.
    let w = 1.0 + 2.0 * progress * progress; // quadratic ramp in progress
    score += w * (x * x) * cap;

    // Cubic interaction: residual squared times progress-weighted penalty
    score += 0.5 * (x * x * x) * cap * (1.0 + progress);

    // Reward bins whose residual matches the next item smoothly (Gaussian-like coupling)
    if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        score -= 30.0 * (-d * d * 50.0);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight penalty for opening new bins when many are open and mean residual is large
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // but allow new bin late in stream if residual would be tiny
        score -= 40.0 * progress * (1.0 - x);
    }

    // Mean-residual coupling: prefer bins near the mean residual (keeps spread low)
    score += 0.2 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
