                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // gen120: mid-stream dead-space penalty scaled by residual variance proxy.
        if progress < 0.8 && dead_space > 0.45 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 2.0 + 4.0 * (dead_space - 0.45);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        let class_bonus = match pr % 10 {
            0 => 6.0,
            5 => 3.0,
            2 | 4 | 6 | 8 => 1.5,
            _ => 0.0,
        };
        score -= class_bonus;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr > 0 && pr < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let gap = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap).max(0.0);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the fit into
    // existing bins would be terrible (large post_residual).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.15 * mean_residual;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins relative to mean residual.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use
    // are heavily penalized. Treat gaps below ~10% of capacity as waste.
    let dead_threshold: f64 = bin_capacity as f64 * 0.10;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If the leftover gap can still fit the (smaller) next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate has bin_residual == bin_capacity and will
    // therefore receive this penalty, making it win only when it truly fits.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 3.0;
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Progress coupling: late in the stream, tightness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Prefer bins whose residual is close to the item (tight but valid fits).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    // Penalize bins far from the mean residual (fragmentation signal).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
