pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bins whose post_residual is small relative to mean residual.
    let mean_res = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let tightness = (post_residual as f64) - mean_res;
    score += 0.5 * tightness;

    // Lookahead: reward bins whose post_residual exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect 2-step match: post_residual == next_item_size is ideal.
        let match_reward = 30.0 / (1.0 + gap * gap * 0.05);
        score -= match_reward;
        // Penalize leaving residual too small for the next item (dead space).
        if (post_residual as u64) < (next_item_size as u64) {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: strongly prefer minimal waste.
        score += 0.8 * (post_residual as f64);
    }

    // Last chance: if this is the only fitting bin, penalize opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new empty bin when decent alternatives exist,
    // unless the item is huge and no bin fits tightly.
    if bin_residual == bin_capacity {
        let waste_here = bin_capacity as f64 - item_size as f64;
        let waste_open = if fitting_bins_count > 0 {
            // approximate best open-bin waste via mean residual
            (mean_res - item_size as f64).max(0.0)
        } else {
            waste_here
        };
        if waste_open < waste_here {
            score += 40.0 + 0.3 * waste_here;
        } else {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but perfect fill is best.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Penalize leaving dead space that likely no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual > 80 {
        score += 10.0; // huge leftover = wasted bin
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
        // but avoid wasting a near-empty last-chance bin on a tiny item
        if item_size < bin_capacity / 8 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; leaving large post_residual is less useful
            score += 0.1 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).abs();
        }
    } else {
        // last item in stream: prefer fullest packing
        score -= 30.0;
    }

    // Global state: with many open bins, prefer consolidating into emptier bins.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Time horizon: early in the stream, be more liberal with opening bins
    // (keep residuals large for flexibility); late in stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.2 * post_residual as f64;
    score += progress * 0.3 * post_residual as f64;

    // Slight preference for existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

