            score -= 6.0 * (1.0 - after_next as f64 / cap);
        } else {
            // next item won't fit here; penalize wasting space that blocks nothing anyway,
            // but slightly reward leaving room for a future small item.
            score += 4.0;
            if post_residual >= 10 {
                score -= 2.0;
            }
        }
    }

