        // If mean residual of open bins is small (poor total space), new bin is fine.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 15.0;
        }
        // If many bins can fit, discourage opening a new one.
        if fitting_bins_count > 2 {
            new_bin_cost += 12.0;
        }
        // If lookahead item is large and current item is small, opening fresh bin is good.
