        } else if pr > nxt {
            // Next item fits with some slack left; mild reward proportional to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional to wasted potential.
            score += 8.0 + diff * 0.15;
