pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste penalty (quadratic in leftover).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize creating small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for leaving odd gaps.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in stream, be conservative about filling bins tightly
    // (keep flexibility); late in stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * fit_ratio;

    // Global state: if mean residual is high (lots of slack spread around),
    // discourage opening/using bins that leave big leftovers; encourage consolidation.
    if mean_residual > (bin_capacity as f64) * 0.5 {
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // is a decent fit, or when open bins are nearly full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheap to open early (more future flexibility), expensive late.
        score -= 25.0 * (1.0 - progress);
