        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If next item is large, fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Prefer bins with low residual overall (fill fuller bins first).
    score += 0.1 * bin_residual as f64;

    // Mild penalty for bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

