pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 0.5;

    // Strong reward when the leftover exactly matches the next item (perfect 2-chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover can still host the next item: mild reward proportional to closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Leftover too small for next item: dead-space penalty, worse for tiny leftovers.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste.min(40.0);
    }

    // Penalize post-residuals below the smallest plausible item (unusable slivers).
    if post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: bins already much tighter than average are valuable
    // targets; loose bins should absorb the item.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the current item is
    // large and would leave a well-shaped residual in a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 18.0;
        // Early in the stream, opening bins is fine; late, prefer filling existing bins.
        new_bin_penalty *= 1.0 + progress;
        // A fresh bin leaves residual = capacity - item_size; if that residual is a
        // plausible next-item size, opening a new bin is attractive.
        if next_item_size > 0 && post_residual.abs_diff(next_item_size) <= 5 {
            new_bin_penalty -= 25.0;
        }
        // Don't open new bins when plenty of fitting bins exist.
        if fitting_bins_count > 2 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fills are ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small post-residuals that are too small for likely future items
        // (dead space). Items range 1..=100; residuals below ~10 are near-wasted.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 2.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits: prefer leaving a good leftover (small, usable leftover).
            score -= 10.0 * (1.0 - (pr - next) / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += (next - pr) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, tie-break toward larger residuals (better fits stand out
        // via post_residual already), slight penalty to spread usage.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a new bin is wasteful unless existing bins
    // are crowded or the fit is terrible.
    if bin_residual == bin_capacity {
        // Baseline: new bin scores slightly worse than a decent fit.
        score += 15.0;
        // But if the item is large relative to mean residual, existing bins are poor
        // hosts; reduce the new-bin penalty.
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 25.0;
        }
        if fit_ratio > 0.7 {
            score -= 10.0;
        }
        // Early in the stream, accumulating open bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Having many open bins already: discourage more.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Global state coupling: prefer bins whose residual is below the mean residual
    // (drain the tighter bins first), keep loose bins available for small items.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.2;

    // Mild preference for using fuller bins as the stream progresses (first-fit flavor).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Penalize large unusable residuals smoothly
    score += 25.0 * norm_pr * norm_pr * norm_pr;

    // Prefer bins whose residual matches the next item (lookahead fit)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let diff = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - diff) * (1.0 - diff);
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when bin diverges from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // Slight new-bin preference late in stream for tight fits
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds.
    // Dead-space classes: [0,10) excellent, [10,25) ok, [25,50) poor, [50,100) terrible.
    let post = post_residual as u32;
    if post == 0 {
        score -= 40.0; // perfect fit
    } else if post < 10 {
        score -= 15.0;
    } else if post < 25 {
        score -= 4.0;
    } else if post < 50 {
        score += 8.0;
    } else {
        score += 20.0; // large dead space
    }

    // Penalize wasting a nearly-full bin when the item leaves a residual
    // that no plausible future item can use (small odd remainders).
    let waste_class = post % 10; // harmonic modulo class
    if waste_class != 0 && post < item_size {
        score += 3.0 * (10 - waste_class) as f64;
    }

    // Reward using bins whose residual closely matches item size (best-fit sharpening).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Last chance: only one bin fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge relative
    // to capacity or existing bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        // open new bin only if mean residual is low (bins nearly full) or item big
        let threshold = 0.35 + 0.3 * progress;
        if pressure < threshold || item_size as f64 > 0.8 * cap {
            score -= 12.0;
        } else {
            score += 30.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 20.0;
        } else if next_fit < 10 {
            score -= 8.0;
        } else {
            score -= 2.0;
        }
    }

    // Prefer spreading across many open bins when they are mostly full.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;

    // Lookahead snugness: reward post_residual that closely hosts the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; near-zero residuals are still good.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when lookahead fits and fleet is scarce.
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // gen128: scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // Confirmed dead space by lookahead: escalate penalty.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / next_item_size.max(1) as f64;
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            let leftover_ratio = leftover as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            let rem_ds = rem as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // gen128: reward residuals hosting two copies of next item
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        // gen128: penalize residuals straddling the mean without fitting next item
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // gen128: avoid overshooting into wide gaps beyond the next item
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
    }

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Endgame tuning: late-stream, prefer closing bins tightly; avoid opening fresh bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (or for the known next item) are wasted — penalize them hard.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        score += 40.0 + (min_useful - post_residual) as f64;
    }

    // Reward tight fits (near-perfect packing) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening a new bin is cheaper so new-bin is less penalized.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: mildly penalized, but attractive if it avoids dead space.
        score -= 3.0 + pressure * 2.0;
    } else {
        score -= 1.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual early (balance), reversed late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (2-step lookahead: post residual matches next item)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    if post_residual == 0 {
        score -= 150.0;
    }

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Prefer bins with residual below the mean (tighter packing)
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0 + 40.0 * progress;
        // but allow a new bin if current item is huge and next is huge too
        if item_size >= 70 && next_item_size >= 70 {
            score -= 100.0;
        }
    }

    // Mild penalty for very small post residual (wasted sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: reward small post residuals nonlinearly
        let tight = 1.0 / (1.0 + post_residual as f64);
        score -= 60.0 * tight * tight;
    }

    // Penalize dead space that no plausible future item can use
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasting large residuals
            score += 15.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last chance: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Prefer bins below mean residual (keep residuals balanced) mildly
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Discourage opening new bins when open bins fit reasonably and stream is late
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty that tight fits / last chance can overcome
        score += 80.0 + 120.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // new bin useful for large upcoming items
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    // Late stream: consolidate aggressively, penalize leaving medium residuals
    if progress > 0.7 && post_residual > 20 && post_residual <= 50 {
        score += 25.0 * progress;
    }

    // Mild preference for larger residual bins early (spread load)
    score -= 0.1 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize post residual, with mild super-linear growth (dead space matters more).
    let mut score = pr + 0.0035 * pr * pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (bins are fresh); late, squeeze bins harder.
    let prog_term = progress * (1.0 - progress);           // peaks mid-stream
    score -= 12.0 * prog_term * (cap - pr) / cap;          // reward fuller bins mid-stream
    score += 8.0 * progress * progress * pr / cap;         // penalize residual more later

    // Reward tight fits: normalized fill ratio, quadratically.
    let fill = 1.0 - pr / cap;
    score -= 6.0 * fill * fill;

    // Lookahead: if next item fits in the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx).max(0.0);
        let compat = 1.0 - fit_next / cap;
        score -= 4.0 * compat * compat * (nx / cap);
    } else {
        // Last item: strongly prefer minimal residual.
        score += 5.0 * pr / cap;
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        // Many alternatives: mildly penalize consuming a scarce small-residual bin.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * (1.0 - fill);
    }

    // New-bin candidate handling: compare against mean residual of open bins.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Opening a new bin is attractive when open bins are already tight on average,
        // or when the item is large (poor fit anywhere).
        let tightness = 1.0 - mean_residual / cap;
        score -= 9.0 * tightness * tightness;
        score -= 5.0 * (it / cap);
        // Early stream: fresh bins are cheap; late stream: prefer consolidation.
        score += 10.0 * progress;
    } else {
        // Prefer bins whose residual is below mean (consolidate waste into few bins).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * dev - 1.5 * dev;
    }

    // Mild penalty for bin sprawl.
    score += 0.15 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small to ever fit typical items (<= 10 min size, or <= next item)
    if post_residual < 10 {
        score += 100.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 12.0;
    }

    // Perfect / near-perfect fits rewarded
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Harmonic class of post_residual modulo capacity fractions (C=100 -> classes of 10)
    let class = post_residual % 10;
    match class {
        0 => score -= 8.0,           // aligned residual, easy to fill later
        1..=3 => score -= 2.0,       // small slivers, mildly useful
        4..=6 => score += 3.0,       // awkward middle class
        _ => score += 1.0,           // large-ish slivers
    }

    // Integer-division threshold: post_residual / 10 as fill-progress measure
    let tenths = post_residual / 10;
    score -= (tenths as f64) * 0.5; // prefer bins that stay relatively full

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // New-bin candidate: only attractive when residuals across open bins are large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let threshold = 40.0 + 30.0 * progress + (open_bins_count as f64).sqrt() * 5.0;
        if mean_residual > threshold {
            score -= 25.0;
        } else {
            score += 30.0;
        }
    }

    // Mild preference for tighter bins as stream progresses
    score *= 1.0 - 0.1 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance pressure: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += open_pressure;

    // New-bin candidate: penalize opening a new bin unless the fit is
    // genuinely bad elsewhere (empty-bin residual == capacity).
    if bin_residual == bin_capacity {
        score += 45.0 + open_pressure;
        // Opening a new bin is acceptable if item is large relative to residual
        // and current bin would leave a big dead gap.
        if post_residual < 15 {
            score -= 55.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 50.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 20.0;
        } else if post_residual < next_item_size {
            // dead space that the next item cannot use
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Progress: late in the stream, be slightly more conservative about
    // opening new bins (fewer future chances to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / (bin_capacity as f64));
        } else {
            // next item cannot follow here: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // last item: only tightness matters
        score -= 20.0 * tightness;
    }

    // Relative-to-mean coupling: bins with residual below mean are more "shaped";
    // reward placing into them when the fit is decent, penalize dumping into fat bins.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 8.0 * (mean_residual - resid) / bin_capacity as f64;
    } else {
        score += 5.0 * (resid - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless this is a large item
    // with no good fit available (post_residual small relative to capacity is fine
    // for a fresh bin only when item is big).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a bin costs ~one bin of wasted space potential; penalize so that
        // only clearly-better fits in open bins beat it.
        score += 70.0 + 25.0 * (1.0 - item_frac) + 15.0 * (1.0 - progress);
        // But if next item chains perfectly with the leftover, soften it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Penalize bins with already-small residual (fragmented bins).
    if bin_residual < item_size * 2 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // More fitting bins => this bin less critical; slight penalty to spread load.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: if mean residual is high, prefer filling fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (mean_residual - post_residual as f64) > 0.0 {
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    // Time horizon: early on, be picky (penalize mediocre fits); later, be greedy.
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate: only attractive when no good fit exists or item is large.
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 || (fitting_bins_count <= 1 && post_residual == 0) {
            score -= 20.0;
        } else {
            score += 30.0; // discourage opening new bins when fits exist
        }
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.9 * t * t + 0.5 * t * t * t;
    score *= poly;

    // Penalize large dead space more as stream progresses (quadratic coupling)
    score += (pr * pr) / cap * (0.2 + 0.8 * t);

    // Reward tight fits: small post residual gets subtracted bonus
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (1.0 + t);

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap) * (0.5 + t);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * t;
    }

    // Penalize bins far from mean residual (fragmentation of residual distribution)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild penalty for opening new bins when many already open
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // fresh bin attractive only when it can host next item AND a follow-up copy.
            if next_item_size > 0 && next_item_size as f64 * 2.0 <= cap {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score -= 4.0 + 10.0 * scarcity * (1.0 - progress);
            } else {
                score += 6.0;
            }
            // in the late stream, opening a fresh bin is nearly always wasteful.
            if progress > 0.8 {
                score += 10.0 + 30.0 * (progress - 0.8) / 0.2;
            }
            // guard against opening fresh bins when a good residual band exists.
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            // gen131: fresh-bin penalty scaled by how well existing residuals match next item.
            if next_item_size > 0 && fitting_bins_count >= 1 {
                let match_quality = 1.0 - ((mean_residual - next_item_size as f64).abs() / next_item_size.max(1) as f64).clamp(0.0, 1.0);
                score += 3.0 * match_quality * fitting_bins_count.min(6) as f64;
            }
            // gen131: early-stream fresh bins are cheaper to open (fleet growth is expected).
            if progress < 0.15 {
                score -= 3.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // gen131: combined fine-grained residual fitting + lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
            if rem >= next_item_size as f64 {
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // gen131: chain-fit coupling — residual that can host next item AND matches the
        // fleet's mean residual band is a strong compaction candidate.
        if next_item_size > 0 && post_residual >= next_item_size {
            let band_match = 1.0 - ((post_residual as f64 - mean_residual).abs() / cap).clamp(0.0, 1.0);
            if dead_space < 0.35 {
                score -= 1.5 + 2.5 * band_match;
            }
        }
        // gen131: penalize residuals that strand space larger than mean residual but
        // smaller than the next item (dead zone between fleet state and lookahead).
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual && post_residual < next_item_size {
            let dead_zone = (post_residual as f64 - mean_residual) / (next_item_size.max(1) as f64);
            score += 2.0 + 4.0 * dead_zone;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity/10 classes
    let class = post_residual / (bin_capacity / 10).max(1);
    let class_bonus = [0.0, -8.0, -6.0, -4.0, -2.0, 0.0, 2.0, 4.0, 6.0, 10.0];
    score += class_bonus[(class as usize).min(9)];

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic pairing: does next_item_size fit exactly or near-exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= 12.0 - (pair_waste as f64) * 0.15;
        if pair_waste == 0 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: dead space penalty scaled by class
        score += (post_residual as f64) * 0.1;
    }

    // Integer-division threshold on post_residual: small fragments are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are crowded
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fill)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild progression scaling: tighter packing later in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

