    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Penalize residual gaps that can't fit the known next item: dead space
    // relative to the lookahead demand.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

