            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen132: two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // gen132: penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // gen132: late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // gen132: combine fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
            if rem >= next_item_size as f64 {
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // gen132: triple-copy anticipation — a bin that can absorb three next-items is a superb host.
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 3.0 + 0.02 * next_item_size as f64;
        }
        // gen132: reward near-perfect residual matching the next item when fleet is tight.
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 4 && fitting_bins_count >= 2 {
                score -= 2.0 + 0.5 * (4 - gap) as f64;
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post-residual (tight fit), normalized
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post-residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 30.0 + gap * 0.5;
        }
    } else {
        // Last item: prefer exact fill
        if post_residual == 0 {
            score -= 150.0;
        }
    }

    // Reward bins tighter than the mean residual (consolidation)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize dead space: post-residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable fragment
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { (item_size + next_item_size).min(bin_capacity) } else { item_size };
        let efficiency = best_possible as f64 / bin_capacity as f64;
        score = (1.0 - efficiency) * 80.0 + 10.0;
        // discourage proliferation of open bins early
        score += open_bins_count as f64 * 2.0;
    }

    // Mild late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
