pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover, with non-linear polynomial in post_residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: residual penalty grows with stream progress
    score += 25.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 20.0 * progress * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - progress * 0.5);
    }

    // Penalize deviation from mean residual (prefer balanced bins)
    score += 0.5 * (pr - mean_residual).abs();

    // Mild pressure against opening too many bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap; // 0..1

    // Dead-space penalty: residuals that are "awkward" (small but nonzero)
    // classes: [1..10] = near-dead, [11..30] = awkward, [31..60] = usable, [61..] = roomy
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 25.0; // tiny dead space: wasted bin capacity
    } else if post_residual <= 30 {
        score += 8.0; // awkward zone
    } else if post_residual <= 60 {
        score -= 4.0; // usable for mid items
    } else {
        score -= 10.0; // roomy leftover
    }

    // Modulo harmonic classes on post_residual: multiples of 5 and 10 pair well
    // with integer item sizes drawn from typical streams
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain-perfect fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 15.0; // next item nearly fills leftover
            } else if slack <= 30 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
            // harmonic class of slack
            if slack % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use the leftover: penalize proportionally to wasted class
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 12.0;
            } else if gap <= 30 {
                score += 5.0;
            } else {
                score += 1.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    // Opening a new bin is only good when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // but if current bin would leave heavy dead space, new bin becomes attractive
        let dead = if post_residual > 0 && post_residual <= 10 { 40.0 } else { 0.0 };
        score -= dead;
        // early in stream, opening bins is cheaper; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // many open bins with high mean residual -> prefer reusing
        score += 0.05 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score += 8.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
