    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    let min_future: f64 = 10.0;
    if (post_residual as f64) < min_future && post_residual > 0 {
        // Perfect fit is ideal; tiny dead space is heavily penalized.
        score += 40.0 + (min_future - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits (small but nonzero post_residual is good
    // only if it's truly tiny; otherwise wasted).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (creates a perfect two-item packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere,
    // mildly penalize (avoid blocking the lookahead).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Tightness reward: fraction of the residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Open-bin pressure: prefer filling existing bins when many are open,
    // so we don't proliferate bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when
    // no open bin offers a decent fit. Make the empty bin expensive.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3 + open_bins_count as f64 * 2.0;
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (smaller residual than average => closer to full => use it).
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

