        score -= 30.0;
    }

    // Reward tight fits relative to mean residual across open bins
    let tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score -= 0.5 * tightness.max(-30.0).min(30.0);

    // Penalize creating unusable dead space (small but nonzero residual)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        let pressure = (step_index as f64 / total_items.max(1) as f64).max(0.0);
