            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // combine fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
            if rem >= next_item_size as f64 {
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // reward bins whose post-fit residual matches the mean residual band closely
        // (these are most likely to be filled by future items).
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        // gen134: scarcity-aware snugness — with few fitting bins, prefer the bin
        // whose post-fit residual best matches the mean residual of the fleet.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            let band2 = ((post_residual - next_item_size) as f64 - mean_residual).abs() / mean_residual.max(1.0);
            score -= 4.0 * (1.0 - band2.min(1.0)) / fitting_bins_count.max(1) as f64;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize very small dead space that nothing else can use later? Actually
    // small post_residual is good; penalize large post_residual mildly extra.
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).sqrt();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // here is poor or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If this bin can't even fit well, opening new is fine.
        if post_residual as f64 > 0.5 * cap {
            score -= 20.0;
        }
        // Fewer open bins => cheaper to open a new one.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0;
        } else if nxt > post_residual as f64 && (bin_residual as f64) >= nxt {
            // Next item would prefer this bin's residual as-is; slight penalty
            // for consuming space the next item needs.
            score += 4.0;
        }
        // If post residual is too small for typical future items, add dead-space penalty.
        if post_residual < 10 && post_residual > 0 {
            score += 6.0;
        }
    }

    // Global state: high mean residual means bins are loose; prefer using them
    // rather than opening new ones.
    score -= 0.15 * mean_residual;

    // Time horizon: late in the stream, be more conservative about opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

