pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: post-residual, slightly compressed non-linearly to smooth
    // differences between small residual values.
    let mut score = pr + 8.0 * (pr / cap).powi(2) * cap / 100.0;

    // Reward tight fits: the smaller the post-residual relative to item,
    // the better. Smooth polynomial coupling.
    let tightness = 1.0 - pr / (item + 1.0);
    score -= 22.0 * tightness.max(0.0).powi(3) * (1.0 + progress);

    // Penalize residuals that are too large to be useful for typical items:
    // smooth dead-space penalty via logistic-like term.
    let dead = (pr - 0.5 * cap) / (0.25 * cap);
    score += 14.0 * (1.0 / (1.0 + (-dead).exp())) * (0.5 + progress);

    // Lookahead: if next item fits exactly into post-residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 18.0 * (-gap / 20.0).exp() * (1.0 - progress * 0.5);
        // Penalize if post-residual cannot fit next item but is close (wasted potential)
        if pr < next_item_size as f64 {
            score += 6.0 * (1.0 - pr / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: only fitting bin; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild preference for filling bins when many are open (avoid bin proliferation).
    score -= 2.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr / cap);

    // Alignment with mean residual: prefer bins whose post-residual approaches
    // the mean (keeps residual distribution uniform, easier future fits).
    score += 4.0 * ((pr - mean_residual) / cap).powi(2);

    // New-bin candidate handling: empty bin has high post-residual; make it
    // attractive only when no open bin offers a decent fit (progress-aware).
    if bin_residual == bin_capacity {
        score = pr - 12.0 * (1.0 - progress) + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // modulo small divisors. Residuals that are multiples of common item sizes
    // (or near multiples) are more likely to be filled later.
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Reward if next item fits exactly or nearly in the post residual.
    if nis > 0 {
        let diff = pr - nis;
        if diff == 0 {
            score -= 30.0; // perfect chain
        } else if diff > 0 && diff <= 10 {
            score -= 15.0 - diff as f64; // near-perfect chain
        } else if diff < 0 {
            score += (diff.abs() as f64) * 0.5; // next item cannot fit here
        }
        // Modulo harmonic bonus: post_residual divisible by next item size
        if nis > 0 && pr % nis.max(1) == 0 && pr > 0 {
            score -= 6.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Penalize small awkward dead space that few item sizes can use.
    if pr > 0 && pr < 10 {
        score += 12.0; // dead zone
    }

    // Integer-division threshold classes on post_residual.
    let class = pr / 20; // 0..5 harmonic class
    score += match class {
        0 => 4.0,  // 0-19: nearly useless
        1 => 1.0,  // 20-39
        2 => 0.0,  // 40-59
        3 => -1.0, // 60-79
        4 => -2.0, // 80-99: very usable
        _ => -3.0, // full-ish
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else. Base new-bin score is post_residual
    // (large, = capacity - item). Add a mild penalty so open bins with decent
    // fits win, but relax when many bins are open and mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual);
        score += 20.0 + 30.0 * (1.0 - progress) - crowding.min(20.0);
    } else {
        // Prefer tighter bins: reward small pre-residual usage.
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Mean residual coupling: when average residual is large, slight penalty
    // for leaving this bin with big residual (fragmentation tendency).
    score += (post_residual as f64 - mean_residual) * 0.08;

    score
}

