    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fit
        } else if post_residual >= next_item_size {
            // next item fits here: reward closeness, penalize large leftover slack
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            score += 0.3 * gap; // but keep some pressure for tight fits
        } else {
            // next item will NOT fit here: penalize proportionally to wasted potential
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (tight bins)
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent,
    // unless the item is large relative to residual (poor fit case)
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral-ish base, penalize when many open bins fit well
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // fresh bin also serves next item -> mild penalty
        }
    }

    // Progression-aware tie-breaking: later in stream, prefer tighter packs
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild penalty for very small dead space creation (fragmentation avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

