            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // gen137: combined fine-grained residual fitting + lookahead anticipation —
        // reward bins whose post-fit leftover still accommodates the next item snugly,
        // with a chain bonus when the leftover is itself near the mean residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - ((rem - next_item_size as f64) / cap);
                score -= 2.0 + 3.0 * snug2;
                // chain: leftover can host next item again → strong compaction signal
                if rem >= 2.0 * next_item_size as f64 {
                    score -= 2.5;
                }
            } else {
                // leftover below next item but close to mean residual: likely filled later
                let band = (rem - mean_residual).abs();
                if band < 4.0 {
                    score -= 3.0 * (1.0 - band / 4.0);
                }
            }
        }
        // reward bins whose post-fit residual matches the mean residual band closely
        // (these are most likely to be filled by future items).
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        // penalize mid-range dead space when the fleet is tight on capacity.
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        // reward post-fit residual that exactly matches the mean residual
        // (predictable future fill), scaled by remaining stream length.
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        // gen137: compaction pressure when many open bins exist — prefer the bin
        // whose post-fit residual is smallest (drains partial bins first).
        if open_bins_count > 4 && post_residual > 0 {
            score -= 1.5 * (1.0 - dead_space);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward (gen137: strengthened to attack dead space directly).
    let tightness = 1.0 - waste_ratio;
    score -= 16.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // fresh bin attractive only when it can host next item AND a follow-up copy.
            if next_item_size > 0 && next_item_size as f64 * 2.0 <= cap {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score -= 4.0 + 10.0 * scarcity * (1.0 - progress);
            } else {
                score += 6.0;
            }
            // in the late stream, opening a fresh bin is nearly always wasteful.
            if progress > 0.8 {
                score += 10.0 + 30.0 * (progress - 0.8) / 0.2;
            }
            // guard against opening fresh bins when a good residual band exists.
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            // if any open bin's post-fit residual would still chain the next item,
            // opening a fresh bin loses that chain — penalize harder.
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // gen137: fresh bin must also promise low dead space relative to fleet mean.
            if next_item_size > 0 && (cap - next_item_size as f64) > mean_residual * 1.3 {
                score += 4.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // combine fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
            if rem >= next_item_size as f64 {
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // reward bins whose post-fit residual matches the mean residual band closely
        // (these are most likely to be filled by future items).
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        // penalize mid-range dead space when the fleet is tight on capacity.
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        // reward post-fit residual that exactly matches the mean residual
        // (predictable future fill), scaled by remaining stream length.
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        // gen137: combined feature — dead-space-aware snugness. Prefer bins whose
        // post-fit leftover chains the next item AND keeps total dead space low;
        // penalize bins whose leftover would strand a large unusable gap.
        if next_item_size > 0 && post_residual > 0 {
            let rem = post_residual as f64;
            if rem >= next_item_size as f64 {
                let leftover = rem - next_item_size as f64;
                let chain_quality = 1.0 - (leftover - mean_residual).abs() / cap;
                score -= 2.5 * chain_quality.max(0.0) * (1.0 - dead_space);
            } else {
                let stranded_gap = rem / cap;
                if stranded_gap > 0.12 {
                    score += 3.0 * stranded_gap * (1.0 - progress);
                }
            }
        }
        // gen137: global dead-space tax scaled by stream progress — compaction
        // matters more as the stream advances.
        if dead_space > 0.5 {
            score += (dead_space - 0.5) * 6.0 * (0.5 + progress);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of capacity fractions
    let pr = post_residual as u32;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let residue_class = pr % (bin_capacity / 10).max(1);

    // Penalize dead space by harmonic class: residuals in awkward classes are worse
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr < eighth {
        score -= 15.0; // near-perfect sliver, nearly unusable anyway
    } else if pr < quarter {
        score += 12.0; // dead zone: too small for typical items
    } else if pr % 2 == 0 {
        score -= 4.0; // even class slightly favored
    } else {
        score += 3.0;
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // chain perfect fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize more if we leave large residual
            score += 6.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidation (favor filling existing bins over new ones)
    if open_bins_count > 3 {
        if bin_residual == bin_capacity {
            score += 20.0; // penalize new-bin candidate
        } else {
            score -= 5.0 * (open_bins_count as f64).ln().max(1.0);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Stream progression: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - pr as f64 / cap);

    // Integer-division threshold bonus on post_residual
    if pr / eighth == 0 && pr > 0 {
        score -= 10.0;
    }
    let _ = residue_class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure loss; residuals below the typical item
    // scale are likely dead weight. Penalize sharply in the "dead zone".
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Wasted sliver: heavy penalty proportional to how close to zero.
        score += 30.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= item_size / 4 {
        score -= 8.0;
    } else if post_residual <= item_size / 2 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            // Next item won't fit here: post residual is terminal dead space.
            score += 5.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones and prefer filling existing bins; when few bins are open, allow
    // new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln1p() * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize under bin pressure so it only wins
        // when no open bin offers a decent fit.
        score += 12.0 + 4.0 * pressure;
    } else {
        // Filling an existing bin relieves pressure.
        score -= 2.0 + 0.5 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Alignment with mean residual: bins whose residual after placement
    // deviates far above the mean accumulate fragmented space.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score -= 0.1 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // next item fits exactly-ish here later
            score -= 30.0 * (1.0 - gap / 100.0);
        } else {
            // post residual too small for next item: dead space penalty scaled by gap
            score += 0.4 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity && bin_residual != 0 {
        score += 20.0;
        if fitting_bins_count > 0 && post_residual as f64 <= mean_residual + 20.0 {
            score += 30.0;
        }
    }

    // Early in stream, be more open to new bins for flexibility
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, especially if no future item can use it.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.6 * dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward residual that exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // Next item won't fit here; penalize slightly more when many bins remain open.
            score += 2.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Global balance: prefer bins whose residual is below the mean residual
    // (use up fuller bins first, keep large residuals for future items).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more conservative about fragmenting
    // space; late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.25 * post_residual as f64;
    score -= progress * 8.0 * fit_ratio;

    // Prefer opening new bins only when item is small relative to a fresh bin
    // and many bins are already open (avoid unbounded bin proliferation).
    if bin_residual == bin_capacity {
        let small_item = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - small_item) + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // If no open bin fits at all, new bin is necessary: make it attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear fit quality: tight fits strongly rewarded
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let fit_quality = (1.0 - norm_post).powf(3.0); // in (0,1], 1 = perfect fill
    score -= 25.0 * fit_quality;

    // Penalize dead space non-linearly: residuals too small to fit anything
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 15.0 * dead * (1.0 + progress);

    // Lookahead coupling: if next item fits exactly into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (1.0 - lookahead_gap).powf(2.0);
    } else if next_item_size > post_residual {
        // next item can't use this residual: mild penalty scaled by wasted potential
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins when others exist, more so late in stream
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 20.0 + 25.0 * (1.0 - progress);
        } else {
            score -= 10.0;
        }
    }

    // Divergence from mean residual: prefer bins whose residual is near the mean
    // (keeps bin population homogeneous, easier future packing)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Smooth pressure term: many open bins -> prefer filling existing ones
    let pressure = (open_bins_count as f64).ln_1p() / 10.0;
    score += pressure * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes mod 10 / mod 25
    let r = post_residual;
    let class10 = (r % 10) as f64;
    let class25 = (r % 25) as f64;

    // Reward residuals that are "clean" multiples of small divisors (usable slots)
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 4.0;
    }
    // Penalize awkward tiny dead space
    if r > 0 && r < 10 {
        score += 12.0;
    }
    score += class10 * 0.4 + class25 * 0.2;

    // Perfect fit is best
    if r == 0 {
        score -= 40.0;
    }

    // Lookahead: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // chain placement possible: reward proportionally to how snugly it fits
            let snug = 1.0 - ((r - next_item_size) as f64) / cap;
            score -= 8.0 + 14.0 * snug;
            // harmonic coupling: next item also lands on a clean class
            if (r - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize if we wasted a good residual
            score += 6.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: keep fresh bins neutral-ish, slightly penalized
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream, be more frugal with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Prefer bins below mean residual (fill the emptier ones first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // fresh bin attractive only when it can host next item AND a follow-up copy.
            if next_item_size > 0 && next_item_size as f64 * 2.0 <= cap {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score -= 4.0 + 10.0 * scarcity * (1.0 - progress);
            } else {
                score += 6.0;
            }
            // in the late stream, opening a fresh bin is nearly always wasteful.
            if progress > 0.8 {
                score += 10.0 + 30.0 * (progress - 0.8) / 0.2;
            }
            // guard against opening fresh bins when a good residual band exists.
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            // if any open bin's post-fit residual would still chain the next item,
            // opening a fresh bin loses that chain — penalize harder.
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // gen139: a fresh bin is only worth opening if its residual is a multiple
            // of the next item (predictable chain); otherwise punish harder.
            if next_item_size > 0 && next_item_size <= post_residual {
                let rem = post_residual % next_item_size.max(1);
                if rem != 0 {
                    score += 4.0;
                } else {
                    score -= 3.0;
                }
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // combine fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
            if rem >= next_item_size as f64 {
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // reward bins whose post-fit residual matches the mean residual band closely.
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        // penalize mid-range dead space when the fleet is tight on capacity.
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        // reward post-fit residual that exactly matches the mean residual.
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        // gen139: dead-space floor term — residuals in the awkward 0.15–0.35 band
        // rarely get filled later; push score up so tighter bins win.
        if dead_space >= 0.15 && dead_space < 0.35 && post_residual > 0 {
            let depth = 1.0 - (dead_space - 0.15) / 0.2;
            score += 2.0 + 3.0 * depth * (1.0 - progress);
        }
        // gen139: residual-divisibility lookahead — a post-fit residual that is an
        // exact multiple of the next item promises perfect future chaining.
        if next_item_size > 1 && post_residual >= next_item_size {
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 2.5;
            } else if rem < 4 {
                score += 1.5;
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual that no plausible item can use is waste.
    let dead = post_residual > 0 && post_residual < 10; // absolute unusable sliver
    if dead {
        score += 40.0;
    }

    // Post-residual too small for the lookahead item (k=2) is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, a new empty bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 10.0 + 6.0 * pressure;
    } else {
        score -= 2.0 * pressure;
    }

    // Prefer bins whose residual deviates below the mean (consolidating emptier space).
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 4.0 * (mean_residual - resid) / bin_capacity as f64;
    } else {
        score += 2.0 * (resid - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect/near-perfect match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for next item is ideal: post_residual == next_item_size.
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect closure: item consumes bin entirely now.
        if post_residual == 0 {
            score -= 60.0;
        }
        // Dead space too small for any item (min size 1): penalize hard.
        if post_residual > 0 && post_residual < 1 {
            score += 25.0;
        }
        // Residual too small for the next item while next item fits elsewhere pattern:
        // penalize residuals that can't hold the next item if they're smallish.
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // If placing here leaves exactly room for next item plus margin, mild bonus.
        if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 6.0;
            }
        }
    } else {
        // Last item: strongly prefer exact closure.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Relative-to-mean coupling: bins with residual above mean are "fresher";
    // filling them is cheaper than destroying tight bins.
    let r = post_residual as f64;
    if r < mean_residual {
        score += 0.5 * (mean_residual - r);
    } else {
        score -= 0.3 * (r - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in stream or with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 20.0 * progress;
        // If next item matches a fresh full bin perfectly, opening is attractive.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 5.0;
        }
    }

    // Prefer consolidating into bins that are already tight.
    score += 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty for many open bins to encourage closing them out.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;

    // Lookahead synergy: next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // gen139: fresh bin attractive only when it can host next item AND a follow-up copy.
            if next_item_size > 0 && next_item_size as f64 * 2.0 <= cap {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score -= 4.0 + 10.0 * scarcity * (1.0 - progress);
            } else {
                score += 6.0;
            }
            // gen139: late stream — opening a fresh bin is nearly always wasteful.
            if progress > 0.8 {
                score += 10.0 + 30.0 * (progress - 0.8) / 0.2;
            }
            // gen139: guard against opening fresh bins when a good residual band exists.
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            // gen139: if any open bin's post-fit residual would still chain the next item,
            // opening a fresh bin loses that chain — penalize harder.
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // gen139: discourage fresh bins when the item itself is small and could top off
            // an existing residual band near mean_residual.
            if next_item_size > 0 && (next_item_size as f64 - mean_residual).abs() < 6.0 {
                score += 4.0 + 0.5 * (6.0 - (next_item_size as f64 - mean_residual).abs());
            }
            // gen139: fresh-bin penalty grows with stream length remaining (more future fill chances).
            if (1.0 - progress) > 0.5 {
                score += 2.0 * ((1.0 - progress) - 0.5) * 4.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen139: two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // gen139: penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // gen139: late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // gen139: fine-grained residual fitting combined with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // gen139: reward bins whose post-fit residual matches the mean residual band closely
        // (these are most likely to be filled by future items).
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        // gen139: penalize mid-range dead space when the fleet is tight on capacity.
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        // gen139: reward post-fit residual that exactly matches the mean residual
        // (predictable future fill), scaled by remaining stream length.
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        // gen139-new: three-copy chain lookahead — bins that can host the next item twice
        // plus still leave a mean-sized residual are prime consolidation targets.
        if next_item_size > 0 && post_residual >= 3 * next_item_size {
            score -= 2.0 + 0.5 * fitting_bins_count.min(4) as f64;
        }
        // gen139-new: reward residual-parity with next_item when the leftover after placement
        // is itself a plausible future item size (near mean_residual) — fine-grained chaining.
        if next_item_size > 0 && post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() < 2.0 {
                score -= 2.5 + 1.0 * (2.0 - (leftover as f64 - mean_residual).abs());
            }
        }
        // gen139-new: penalize residuals that are large but just miss fitting the next item —
        // these fragments are hard to fill later unless scarce options exist.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual * 1.3 && fitting_bins_count > 2 {
            score += 3.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight * tight) * (1.0 - tight);

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 90.0;
    }

    // Penalize post-residuals that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer new bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_item = (item_size as f64 + nxt_look(next_item_size)) / 2.0;
        // New bin attractive if mean residual of open bins is small relative to item.
        let scarcity = mean_residual / (item_size as f64).max(1.0);
        score -= 30.0 * scarcity * (1.0 - progress);
        // Penalize opening new bins when open bins are plentiful and roomy.
        score += 10.0 * (open_bins_count as f64).sqrt() * (1.0 - scarcity.min(1.0));
        // Slight late-stream conservatism: fewer new bins near the end.
        score += 40.0 * progress * (avg_item / 100.0);
    }

    // Mild penalty for bins whose residual is far below the mean (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling already-open bins as stream progresses.
    if bin_residual < bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    score
}

#[inline]
fn nxt_look(n: u32) -> f64 {
    if n == 0 { 0.0 } else { n as f64 }
}

