pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty: residuals that are too small to be useful later
    if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 8.0; // only tiny items fit
    } else if post_residual <= 30 {
        score += 3.0;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Harmonic class: integer division thresholds on post_residual
    let class = post_residual / 10; // 0..=10 classes
    match class {
        0 => score -= 5.0,
        1 => score += 2.0,
        2 => score += 4.0,
        3 => score += 1.0,
        4 => score -= 2.0, // half-full bins are valuable
        5 => score -= 4.0,
        6 => score -= 2.0,
        _ => {}
    }

    // Modulo arithmetic on post_residual: values divisible by 10 align with
    // the classic item-size grid, making future packing easier.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: penalize leaving residual that cannot host next item
