                score -= 15.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 4.0 * (1.0 - slack / cap).min(1.0);
            }
        } else {
            // leftover smaller than next item: dead space relative to lookahead
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current bin would be badly fragmented or this is a poor fit overall.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when mean residual of open bins is already tight/fragmented
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 60.0 - 20.0 * fragmentation - 10.0 * progress;
        if post_residual >= 40 {
            score += 25.0; // plenty of room left in open bins: avoid new bin
        }
        if next_item_size > 0 && next_item_size >= post_residual && post_residual < 30 {
            score -= 15.0; // next item won't fit open bins anyway
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are fine, but residuals that only fit tiny items
    // while wasting most of a bin are penalized heavily.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Unusable micro-gap: nearly full bin is actually GOOD (tight fit),
        // so a tiny residual is a small bonus, not a penalty.
        score -= 20.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Mid-range dead space: hard to fill, penalize non-linearly.
        score += 25.0 + 1.5 * (30.0 - pr);
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly prefer this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * (next_item_size as f64 / post_residual as f64) * 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of open bins when
    // residuals are still large (mean residual high).
    let mean_frac = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score += 10.0 * open_bins_count as f64 * mean_frac * 0.1;
    }

    // New-bin candidate handling: an empty bin is attractive when the
    // current item is large and open bins would be left with bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 - 10.0 * progress;
        // Make new bin attractive if item is huge (leaves big clean residual
        // in a fresh bin for future items).
        if item_size >= 60 {
            score -= 20.0;
        }
        // If next item is large too, fresh bin is good for pairing.
        if next_item_size >= 50 && item_size + next_item_size as u32 <= bin_capacity {
            score -= 15.0;
        }
        // If many bins are open with low mean residual, adding a new bin
        // is fine (score lowered slightly).
        if open_bins_count > 3 && mean_frac < 0.25 {
            score -= 10.0;
        }
    }

    score
}

