    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize large dead space relative to typical future item sizes.
    let expected_item = if total_items > 0 { 50.0 } else { 50.0 };
    if post_residual > 0 && (post_residual as f64) < expected_item * 0.25 {
        score += 12.0; // tiny sliver residual is wasted space
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for hogging this bin
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if fullness > mean_fullness {
            score -= 10.0 * (fullness - mean_fullness);
        } else {
            score += 8.0 * (mean_fullness - fullness);
        }
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open new bins when no good fit exists.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + 20.0;
        // Early in stream or many items remaining: new bins are cheaper.
        score -= 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large items coming, fresh bin useful
        }
    }

    // Late stream: favor closing out bins (low post residual weighted more).
    score += score * 0.1 * progress;

    score
}

