pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that can't hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This bin wastes space the next item could have used.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer existing bins for good fits.
        score += 15.0 + fit_ratio * 20.0;
        // If the item is huge relative to capacity and fits poorly elsewhere,
        // opening a fresh bin is attractive.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Few open bins and large mean residual -> reuse bins.
        score += 0.3 * open_bins_count as f64;
        if mean_residual > item_size as f64 + next_item_size as f64 {
            score += 12.0;
        }
    } else {
        // Slightly favor bins with residuals near the mean (keeps balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild penalty for very small post_residual that's nonzero (fragmentation).
    if post_residual > 0 && post_residual <= 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap; // normalized post residual in [0,1]

    let mut score = r;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer filling bins loosely (favor small post_residual less strongly);
    // late in the stream, tighten packing (heavily penalize large post_residual).
    let progress_weight = 0.35 + 1.65 * progress * progress; // smooth, in [0.35, 2.0]
    score *= progress_weight;

    // Non-linear dead-space penalty: post residual that is too small to be useful is bad,
    // but only smoothly — penalize residuals just below typical small item sizes.
    let dead = ((30.0 - r).max(0.0) / 30.0).powi(3);
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Perfect-fit reward: smooth bonus when post residual approaches zero.
    score -= 20.0 * (1.0 - norm_r).powi(4);

    // Lookahead coupling: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= r {
        let snug = 1.0 - ((r - next_item_size as f64) / cap);
        score -= 12.0 * snug * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item cannot use this residual: mild penalty scaled by wasted space
        score += 4.0 * norm_r;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: discourage spreading; prefer bins with below-average residual
    // (i.e., fuller bins) via smooth interaction with mean_residual.
    let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).powi(2);
    score += 8.0 * crowding * (r - mean_residual) / cap;

    // New-bin candidate: keep it neutral-to-slightly-attractive only when no good fit exists;
    // penalize opening new bins smoothly as more bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * crowding - 20.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small divisors create
    // "dead-space classes" that are hard to fill later.
    let pr = post_residual;
    if pr > 0 {
        // Residuals that are not multiples of common item sizes tend to waste.
        let dead_penalty = match pr % 10 {
            0 => -4.0,   // perfectly harmonic: very reusable
            5 => -1.5,   // half-class: decent
            2 | 8 => 1.0,
            4 | 6 => 2.0,
            1 | 3 | 7 | 9 => 3.5, // awkward residues
            _ => 0.0,
        };
        score += dead_penalty;

        // Tiny unusable slivers are pure waste.
        if pr < 10 {
            score += (10 - pr) as f64 * 0.8;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 25.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain-friendly: reward proportionally to how snugly it fits.
            let snug = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 + 8.0 * snug;
            // Harmonic bonus if next item's residue class composes well.
            if (pr % next_item_size.max(1)) == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; penalize bins that leave mid-range gaps.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when the
    // item is large relative to capacity and existing residuals are poor.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin: proportional to wasted space if item goes here.
        score = (bin_capacity - item_size) as f64 + 10.0;
        // Large items justify new bins; small items should reuse open bins.
        if frac > 0.7 {
            score -= 12.0 * frac;
        }
        // If existing bins are fragmented (high mean residual) a new bin is fine.
        if mean_residual > 30.0 {
            score -= 5.0;
        }
        // Late in stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If this is the only option, make it attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer tighter existing bins: scale with fullness of the bin.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 6.0 * fullness;
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

