        // gen144: penalize mid-range dead space when the fleet is tight on capacity.
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        // gen144: reward post-fit residual matching the mean residual, scaled by remaining stream.
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        // gen144-new: chain-fit bonus — if after fitting this item AND the next item the
        // leftover still matches the mean residual (a likely future item), reward strongly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem2 = post_residual - 2 * next_item_size;
            if rem2 > 0 && (rem2 as f64 - mean_residual).abs() < 2.0 {
                score -= 4.0 * (1.0 - (rem2 as f64 - mean_residual).abs() / 2.0);
            }
        }
        // gen144-new: penalize residuals that are neither small (fillable) nor chainable —
        // these stranded mid-band residuals are the main source of dead space.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
            && post_residual as f64 > mean_residual * 1.2 {
            score += 3.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever be useful
    // (below the minimum plausible item footprint) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward tight fits: small post_residual relative to item size is good.
    if item_size > 0 {
        score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // consolidating into existing bins; few open bins -> new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: an empty bin is only attractive when the current bin
    // would leave a large, awkward gap or when mean residual is already low.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 20.0;
        // Attractive if existing bins are too full to host future items well.
        score -= 15.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 12.0;
        }
    } else {
        // Existing bin: slightly reward if post_residual can host next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize leaving a gap just below the next item's size (dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is close to item size (waste minimization).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fits the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: subtract heavily to strongly favor this bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but not perfectly: reward proportional to how tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: penalize wasted chain potential,
            // scaled by how much the leftover exceeds the mean residual (dead space).
            let dead = post_residual as f64 - mean_residual;
            if dead > 0.0 {
                score += 0.5 * dead;
            }
            // Mild penalty if next item is large and would need a fresh bin anyway.
            if next_item_size > post_residual && post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: bins with residual far below mean are
    // "tight" bins; placing here when post_residual stays small is good.
    let mean_post = mean_residual - item_size as f64;
    if (post_residual as f64) < mean_post {
        score -= 0.3 * (mean_post - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_post);
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer a new bin only if no open bin offers a good (near-exact) fit.
        // If the current item leaves a large unmatchable residual and the next
        // item is big, opening fresh is attractive.
        if next_item_size > 0 && next_item_size > item_size && post_residual < next_item_size {
            score -= 10.0;
        } else {
            // Otherwise penalize opening a new bin when open bins exist.
            if open_bins_count > 0 {
                score += 15.0 + 0.5 * post_residual as f64;
            }
        }
    }

    // Slight preference for filling older bins as the stream progresses,
    // encouraging bin consolidation over time.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

