pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic suppression for small post_residual.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: penalize residuals that cannot host the next item (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
        } else {
            // Reward residuals that leave room for the next item.
            score -= 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the current
    // fit is very poor or the stream is early and we want diversity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 40.0;
        let base_cost = 55.0;
        let diversity_bonus = 12.0 * (1.0 - progress); // early stream: allow new bins
        let crowding = (open_bins_count as f64).ln() * 2.0;
        score += base_cost - diversity_bonus + crowding;
        if poor_fit && fitting_bins_count > 0 {
            score -= 30.0; // prefer a fresh bin when all fits would leave big holes
        }
    }

    // Mild preference for filling bins below the current mean residual
    // (balances residual distribution across open bins).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Late-stream urgency: consolidate into existing bins as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * (1.0 + progress);

    let mut score = pr + poly * 30.0;

    // Reward tight fits more strongly as the stream progresses
    score -= fill * fill * (10.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.5 + 2.0 * progress);
        } else {
            score -= 2.0 * (1.0 - (nxt / pr).min(1.0));
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Align with global residual mean (prefer bins near mean residual)
    score += (pr - mean_residual).abs() * 0.3;

    // New-bin candidate: mildly discouraged unless residual waste would be large
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: prefer bins whose post-fit residual chains the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.0 + 1.5 * tight) * fitting_bins_count.min(5) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 1.5 {
                score -= 5.0;
            }
            // gen145: fresh bin attractive only when it can host next item AND a follow-up copy.
            if next_item_size > 0 && next_item_size as f64 * 2.0 <= cap {
                let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
                score -= 4.0 + 10.0 * scarcity * (1.0 - progress);
            } else {
                score += 6.0;
            }
            // gen145: in the late stream, opening a fresh bin is nearly always wasteful.
            if progress > 0.8 {
                score += 10.0 + 30.0 * (progress - 0.8) / 0.2;
            }
            // gen145: guard against opening fresh bins when a good residual band exists.
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            // gen145: if an open bin's post-fit residual would still chain the next item,
            // opening a fresh bin loses that chain — penalize harder.
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // gen145: penalize fresh bins when item could double-stack in an existing bin.
            if next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.5 {
                score += 4.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover_ratio;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen145: two-copy lookahead with scarcity weighting.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        // gen145: penalize leaving a residual just below the next item (wasted sliver).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        // gen145: late-stream compaction — strongly prefer filling existing bins.
        if progress > 0.8 {
            score -= 6.0 * (progress - 0.8) / 0.2;
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // gen145: combine fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            let snug2 = 1.0 - (rem - next_item_size.min(post_residual - next_item_size) as f64).abs() / cap;
            if rem >= next_item_size as f64 {
                score -= 2.0 + 3.0 * snug2;
            }
        }
        // gen145: reward bins whose post-fit residual matches the mean residual band closely.
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        // gen145-new: penalize mid-range dead space when the fleet is tight on capacity.
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        // gen145-new: reward post-fit residual that exactly matches the mean residual.
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        // gen145-mut: triple-copy lookahead — a residual that fits the next item three times
        // is a strong donor; reward scaled by stream remaining.
        if next_item_size > 0 && post_residual >= 3 * next_item_size && (1.0 - progress) > 0.4 {
            score -= 2.0 + 2.0 * (1.0 - progress);
        }
        // gen145-mut: avoid creating residuals that no plausible item can use —
        // if post-fit residual is far below the mean residual, it will strand.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            let strand_gap = next_item_size as f64 - post_residual as f64;
            if strand_gap > mean_residual.max(1.0) * 0.6 {
                score += 3.0;
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalty: leftover too small for typical items (1..100 unknown, but small
    // leftovers < eighth are nearly unusable). Penalize quadratically within the band.
    if post < eighth {
        score += (eighth - post) as f64 * 2.5;
    }

    // Harmonic sweet spots: post_residual exactly divisible into capacity fractions
    // (0, quarter, half, three-quarters) means future items can tile the space cleanly.
    let harmonics = [0u32, eighth, quarter, 2 * quarter, 3 * quarter, bin_capacity / 2];
    for h in harmonics.iter() {
        if post == *h {
            score -= 6.0;
        }
    }

    // Modulo-16 classes on post_residual: reward leftovers that are multiples of common
    // item granularities (16 divides nicely into many integer size streams).
    if post % 16 == 0 && post > 0 {
        score -= 2.0;
    } else if post % 10 == 0 && post > 0 {
        score -= 1.0;
    }

    // Integer-division threshold: post_residual / next_item_size tells how many
    // lookahead items still fit. Reward generous counts.
    if next_item_size > 0 {
        let fits_next = post / next_item_size.max(1);
        score -= (fits_next.min(4)) as f64 * 3.0;
        // Perfect tiling: next item exactly fills the remainder.
        if next_item_size == post {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins would leave ugly scraps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream or when
        // open bins are crowded (low mean residual relative to item).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        let mut new_bin_cost = 14.0 - 6.0 * progress;
        if crowded && open_bins_count > 0 {
            new_bin_cost -= 8.0;
        }
        // A fresh bin for this item leaves (capacity - item) residual: score it
        // by how harmonically that residual sits.
        let fresh = bin_capacity - item_size;
        let mut fresh_score = fresh as f64;
        if fresh % 16 == 0 { fresh_score -= 3.0; }
        if fresh < quarter { fresh_score -= 4.0; } // big item in fresh bin = little waste
        score = new_bin_cost + fresh_score * 0.35;
        return score;
    }

    // Tight-fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 5.0;
    } else if fill_ratio > 0.6 {
        score -= 2.0;
    }

    // Penalize bins whose residual is far below mean (fragmented bins) mildly.
    if (bin_residual as f64) < mean_residual * 0.5 && post > 0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (next item or anything >= 10) are wasted space.
    let min_useful = next_item_size.max(10) as f64;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        // Dead space penalty: the smaller the gap relative to usefulness, the worse.
        score += 40.0 * (min_useful - post_residual as f64) / min_useful;
    }

    // Reward tight fits: low post_residual relative to bin capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // If next item would NOT fit in post-residual, this bin's remaining space
    // is likely dead (unless large enough for other items) - mild penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Penalize the new bin proportionally to aggregate open capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 4.0 * open_bins_count as f64 + 10.0 * mean_residual / bin_capacity as f64;
        // Early in the stream, slightly cheaper to open bins (build diversity).
        score -= 20.0 * (1.0 - progress);
        // If the item fits poorly everywhere else, new bin becomes attractive:
        // that case is signaled by large post_residual on existing bins being
        // penalized already; also if no other bin fits well.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // Reward using existing bins when there are many open bins (consolidation).
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.2 * ((bin_residual - item_size) as f64);

    score
}

