pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how much the next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item can't use the leftover: penalize large dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize bins far from the mean residual (avoid fragmenting outliers),
    // unless this bin is already a good fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev * (1.0 - tight);

    // Early in the stream: prefer filling existing bins less aggressively
    // (keep flexibility); later: consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // When many bins are open, encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: make it less attractive than a decent fit,
    // but attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

