                score -= 1.5 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64);
            }
        }
        // gen147: discourage creating residuals that neither fit next item nor stay small.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
