            }
        }
        // gen149: combined fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly,
        // scaled by how early we are in the stream (future value of a donor slot).
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
