        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // gen150: compaction coupling — prefer bins whose post-fit residual is closest to a
        // multiple of the next item size, sharpened when the fleet has many fitting bins.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress) * (1.0 + 0.2 * fitting_bins_count.min(5) as f64);
            }
        }
        // gen150: penalize bins whose residual can never be reused unless near zero.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // gen150: mid-stream compaction — prefer residuals keeping the fleet mean low.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // gen150: near-miss gaps strand unusable space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen150: two-step lookahead — when the residual after placing the current item can
        // still host the next item AND the mean residual, strongly prefer it (chained fits
        // close bins faster and reduce dead space across the stream).
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem as f64 >= mean_residual && rem >= 1 {
                score -= 3.5 * (1.0 - progress).max(0.3);
            }
        }
        // gen150: prefer bins whose post-fit residual stays a usable fraction of capacity
        // rather than a stranded sliver, when several bins compete.
        if fitting_bins_count >= 2 && post_residual > 0 && post_residual < 12 && dead_space > 0.1 {
            score += 2.0 + 0.3 * (12 - post_residual) as f64;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead synergy: fit now AND leave room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
            if progress > 0.8 {
                score += 8.0 * (progress - 0.8) / 0.2;
            }
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // fresh bin competes only if the fleet cannot chain two items ahead.
            if next_item_size > 0 && post_residual >= 2 * next_item_size {
                score += 9.0;
            }
            // early stream — fresh bins are cheap insurance against fragmentation.
            if progress < 0.25 && next_item_size > 0 && item_size as f64 > mean_residual {
                score -= 4.0;
            }
            // when the fleet is fragmented (many open bins), a fresh bin is wasteful.
            if open_bins_count > 6 {
                score += 3.0 + 0.5 * (open_bins_count.min(14) as f64);
            }
            // gen150: fresh bin must beat the fleet's best achievable leftover; if some
            // open bin can chain the next item snugly, a fresh bin loses its appeal.
            if next_item_size > 0 && mean_residual >= next_item_size as f64 {
                let fleet_chain = (mean_residual - next_item_size as f64).abs() / cap;
                if fleet_chain < 0.1 {
                    score += 5.0 + 20.0 * (0.1 - fleet_chain);
                }
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            if leftover_ratio > 0.02 && leftover_ratio < 0.12 {
                score -= 4.0 * (1.0 - leftover_ratio / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // combined fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - (rem - next_item_size as f64).abs() / cap;
                score -= 2.0 + 3.0 * snug2;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // compaction coupling — when several bins fit, prefer the one whose
        // post-fit residual is closest to a multiple of the next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // penalize bins whose residual can never be reused (residual < smallest
        // plausible item) unless it is near zero — force closure of dead tails.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // mid-stream compaction — prefer bins whose post-fit residual keeps the
        // fleet's mean residual low, so future items of typical size still fit.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // discourage leaving residuals that are just barely below the next item
        // (near-miss gaps) — these strand space that no future item can use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen150: two-step lookahead — reward bins whose post-fit leftover can
        // absorb the next item AND still leave room for a typical follow-up item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            let typical = mean_residual.max(1.0);
            if rem as f64 >= typical * 0.7 {
                let snug = 1.0 - ((rem as f64 - typical) / cap).abs();
                score -= 2.5 + 4.0 * snug.max(0.0);
            }
        }
        // gen150: penalize oversized leftover tails that strand more than half a
        // typical item of dead space when the fleet is already fragmented.
        if next_item_size > 0 && post_residual > next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem > typical_tail(mean_residual) && open_bins_count > 4 {
                score += 1.5 + 2.0 * ((rem / typical_tail(mean_residual)) - 1.0).min(2.0);
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

fn typical_tail(mean_residual: f64) -> f64 {
    (mean_residual * 0.9).max(3.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_mod = post_residual % (bin_capacity / 4).max(1);
    let pr_mod10 = post_residual % 10;

    // Penalize post-residuals that fall into "dead zone" classes:
    // small non-zero residues (1..10) are nearly unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harmonic sweet spots: residuals divisible by 25 or 20 fit common size classes
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize residues in (10, 20) — too small for most items, wasteful
    if post_residual > 10 && post_residual < 20 {
        score += 25.0;
    }
    // Exact fit is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    } else if next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is very full
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * open_bins_count as f64;
    }

    // Waste-relative normalization: penalize score proportional to wasted fraction
    score += 0.5 * (pr / c) * (pr / c) * 20.0;

    // Progress coupling: later in the stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - pr / c);

    // Mean residual alignment: prefer bins whose post-residual is near mean
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev;

    // Modulo-class tiebreak on residual mod 10 (harmonic granularity)
    score -= (10 - pr_mod10) as f64 * 0.3;

    // Small tiebreak on modulo-4 class
    score -= pr_mod as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in the small "unusable" band (1..=12)
    // are the worst outcome — nothing typical fits there later.
    if post_residual >= 1 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 4.0;
    }
    // Medium dead space (13..=25) is mildly bad too.
    else if post_residual > 12 && post_residual <= 25 {
        score += 10.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, consolidation is cheap anyway.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score -= pressure;

    // Lookahead: if the next item exactly fills the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: small leftover after chain is good
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: leftover is dead
            score += 8.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; prefer bins with residual close to item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Early stream: slightly favor new bins to build a diverse pool;
    // late stream: consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if it beats poor fits.
        score += 20.0 - 15.0 * progress;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if next item fills the post-residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0;
        } else if next_item_size as u32 <= post_residual {
            // next item fits into the leftover: good chaining
            score -= 120.0 / (1.0 + diff as f64 * 0.15);
        } else {
            // next item cannot use the leftover: penalize wasted space
            score += (next_item_size as f64 - post_residual as f64).min(50.0) * 0.6;
        }
    }

    // Compare residual against mean residual across open bins.
    let res = post_residual as f64;
    if res > mean_residual + 30.0 {
        score += (res - mean_residual) * 0.4;
    } else if res < mean_residual - 20.0 {
        score -= (mean_residual - res) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bins would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste_threshold = 60.0;
        if score > waste_threshold {
            score -= 200.0; // opening a fresh bin beats a wasteful placement
        } else {
            score += 100.0; // keep using open bins when fits are decent
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Tightness bonus: prefer bins that were already partially filled.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    if post_residual == 0 {
        score -= 62.0;
    }

    // Lookahead: next item fits snugly
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact lookahead fit
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Room for two copies of next item
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
    }

    // Stranded small residuals that can't fit next item
    if post_residual > 0 && next_item_size > post_residual {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        if post_residual < 15 {
            score += 4.0;
        }
        // residual straddling the mean without fitting next item
        if post_residual as f64 > mean_residual * 1.15 {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
    }

    // Post-fit leftover near zero
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
        let rem_ds = leftover_ratio;
        if rem_ds > 0.02 && rem_ds < 0.12 {
            score -= 4.0 * (1.0 - rem_ds / 0.12);
        }
    }

    // Wide gaps beyond next item
    if next_item_size > 0 && post_residual > next_item_size {
        let over = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if over > 1.5 && dead_space > 0.4 {
            score += 2.0 + 3.0 * (dead_space - 0.4);
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // scale new-bin penalty with fleet tightness
            let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
            score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
        score -= 0.3 * item_size as f64;
    }

    // Late-stream: close out existing space
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    // Drift coupling: keep donor slots alive when fleet is tight
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if drift < 0.35 {
            score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
        }
    }

    // Discourage residuals that neither fit next item nor stay small
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
        score += 3.0 + 4.0 * (dead_space - 0.55);
    }

    // Very small residual bonus
    if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
        score -= 12.0;
    } else if waste_ratio < 0.08 {
        score -= 13.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the placement.
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * fill;

    // Penalize post_residual that becomes dead space: small leftovers
    // that no typical item can use are worse than moderate ones.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let deadness = if pr < 10.0 { 1.0 } else { 0.0 };
        score += 8.0 * deadness * (1.0 - pr / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly
    // (large post_residual relative to item) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.6 * cap;
        score += if poor_fit { -10.0 } else { 10.0 + 5.0 * progress };
    }

    // Lookahead coupling: if the next item could fit into the post_residual,
    // reward this placement (chaining two items in one bin).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
        // Next item won't fit here anyway; mild penalty if we strand tiny space.
        score += 2.0 * (pr / cap) * (1.0 - pr / (next_item_size as f64).max(1.0));
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into fuller bins (higher fill) to reduce spread.
    if open_bins_count > 1 {
        let spread = (mean_residual - pr).abs();
        score += 0.5 * spread / cap;
        score -= 2.0 * (1.0 - pr / cap) * (mean_residual / cap);
    }

    // Time horizon: early in the stream, keep bins flexible (penalize very
    // small post_residual less, allow moderate leftovers); late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);

    // Lookahead: next item fits into post_residual -> strong reward scaled by snugness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny slivers are nearly as good (they close a bin).
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            // Scale new-bin penalty with fleet tightness.
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // Late-stream fresh bins are expensive.
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
        // Large items open fresh bins more readily.
        score -= 0.3 * item_size as f64;
    } else {
        // OPEN BIN BRANCH
        let waste_ratio = (post_residual as f64) / (bin_capacity as f64);

        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }

        // Wide dead-space bands that the next item cannot use.
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }

        // Residual can host the next item at least twice.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual && dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }

        // Stranded slivers the next item can't use.
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
            if dead_space > 0.55 {
                score += 3.0 + 4.0 * (dead_space - 0.55);
            }
        }

        // Keep a donor slot alive when the fleet is tight.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }

        // Near-exact lookahead match with scarcity bonus.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }

        // Leftover barely above next item -> tiny residual, great.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            let leftover_ratio = leftover as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            let rem_ds = leftover as f64 / bin_capacity.max(1) as f64;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
            let two_fit = leftover as u32 >= next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }

        // Residual near mean residual keeps fleet balanced.
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }

        // Small residuals below a fraction of mean residual are efficient closers.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }

        // Multi-item lookahead ratios.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }

        // Scarce fitting + unusable residual.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }

        // Penalize overshooting into a wide gap beyond the next item.
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }

        // Unusable gap beyond next item's footprint.
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
    }

    // Late-stream endgame: close bins aggressively, resist opening new ones.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.9 * norm_pr + 0.35 * norm_pr * norm_pr);
    let mut score = pr * (0.5 + 1.2 * progress) + 30.0 * poly * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual), stronger as stream advances
    score -= 45.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Dead-space penalty: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0 * (10.0 - pr as f64);
    }

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) as f64;
            score -= 35.0 * (-slack / 20.0).exp();
        } else {
            score += 12.0 * (n - pr).min(30.0) / 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: discourage spreading, prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // New-bin candidate: penalize mildly unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - cap * 0.5).abs();
        score += 20.0 - fragmentation.min(50.0) * 0.3;
    }

    score
}

