pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "dead" (small)
    // get penalized; residuals that can host future items get rewarded.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible into clean capacity fractions -> good fit
    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Dead-space penalty: tiny unusable leftovers (1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling with next item (lookahead): reward if next item fits exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let left = post_residual - next_item_size;
            score -= 8.0;
            if left < 10 {
                score += 10.0; // would create new dead space
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / cap;
        score = cap * 0.45 + tight * 40.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open
        }
        if fitting_bins_count == 1 {
            score += 10.0; // a lone fitting bin should usually be used
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Lookahead synergy: next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold; tiny slivers are near-waste.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Multi-item capacity: residual that can hold next item twice is valuable.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 {
        score -= 7.5 + 2.0 * (0.45 - dead_space);
    }

    // Drift control: keep post_residual near next item size when fleet is tight.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if drift < 0.35 {
            score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
        }
    }

    // Residual that cannot fit next item and is large: stranded space.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded = post_residual as f64 / next_item_size.max(1) as f64;
        if stranded < 0.5 {
            score += 5.0 * (1.0 - stranded);
        }
        if dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        if post_residual as f64 > mean_residual * 1.15 {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
    }

    // Mid-band dead-space penalty (awkward gaps).
    if dead_space > 0.25 && dead_space < 0.65 {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // Overshoot far beyond next item in wide gap.
    if next_item_size > 0 && post_residual > next_item_size {
        let over = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if over > 1.5 && dead_space > 0.4 {
            score += 2.0 + 3.0 * (dead_space - 0.4);
        }
    }

    // Waste-ratio signals.
    let waste_ratio = dead_space;
    if waste_ratio < 0.08 {
        score -= 13.0;
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 12.0;
        }
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // Exact-match with lookahead.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * fitting_bins_count.min(4) as f64;
    }

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // Scale new-bin penalty with fleet tightness.
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // Fresh bin as donor when residual tracks the mean.
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // Late-stream fresh bins are expensive.
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
    } else {
        // Near-mean residual closeness bonus.
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // Leftover barely above next item is ideal donor state.
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover < 0.05 {
                score -= 5.0 * (1.0 - leftover / 0.05);
            }
        }
        // Fragments smaller than next item.
        if post_residual > 0 && next_item_size > post_residual {
            let frag = 1.0 - post_residual as f64 / next_item_size.max(1) as f64;
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        // Small residuals below 35% of mean are decent.
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Post-next-item remainder in the sweet spot.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem_ds = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        // Ratio bands for multi-slot residuals.
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // Scarce-fleet dead-space with no next fit.
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
    }

    // Late-stream endgame adjustments.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if no plausible future item (>=1..~item_size range) can use it.
    let dead_threshold = 9.0; // items are >=1, but small gaps rarely reusable
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit is gold
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (favor bins with low residual usage); when few bins, opening is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * (bin_residual as f64 - mean_residual) * 0.05;
    score += pressure * 2.0;

    // New-bin candidate handling: only attractive when item barely fits anywhere
    // or open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if fitting_bins_count <= 1 || avg_fullness > 0.8 {
            score -= 5.0; // allow opening when desperate
        } else {
            score += 30.0; // discourage wasteful new bins
        }
    }

    // Lookahead: if next item fits snugly in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            score -= 3.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 2.0; // next item can't use this bin anyway
        }
    }

    score
}

