}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny slivers are waste
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Global state: when many bins are open, prefer consolidating into existing bins
    let open_penalty = open_bins_count as f64 * 0.5;
    score += open_penalty * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // later, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive later
        let base = 40.0 + 260.0 * progress;
        score = base + post_residual as f64 * (0.5 + progress);
    } else {
        score -= 60.0 * progress; // late stream: favor existing bins
    }

    score
}

