    score += 4.0 * dev * dev;

    // Last-chance bonus: smoothly reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: reward leaving space for the next item (smooth quadratic)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs() / cap;
        score += 5.0 * gap * gap;
        if pr >= ns && pr - ns <= 10.0 {
            score -= 4.0;
        }
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
