        score = 40.0 + 30.0 * waste_ratio - 20.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= post_f {
            score += 20.0; // fresh bin could chain, but only mildly attractive
        }
    }

    score
}

