    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize large residuals more aggressively as the stream matures (dead space compounds late).
    score += 120.0 * norm_pr * norm_pr * (0.4 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= 60.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

