        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // gen155: mid-stream compaction — prefer bins whose post-fit residual keeps the
        // fleet's mean residual low, so future items of typical size still fit.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // gen155: discourage leaving residuals that are just barely below the next item
        // (near-miss gaps) — these strand space that no future item can use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen155: two-step lookahead — reward bins whose post-fit residual can host the
        // next item AND still leave room for a typical item afterwards.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem > 0 && rem as f64 >= mean_residual * 0.8 {
                score -= 3.0 * (1.0 - ((rem as f64 - mean_residual * 0.8) / mean_residual.max(1.0)).clamp(0.0, 1.0)) * (1.0 - progress);
            }
        }
        // gen155: penalize residuals slightly above the next item that waste the gap.
        if next_item_size > 0 && post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap > 0 && (gap as f64) < mean_residual * 0.15 {
                score += 2.0;
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest future item (1..100 unknown, but small gaps < 10 are dead
    // under the stated range; gaps below a typical minimum are near-dead).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // fully wasted space
    } else if (post_residual as f64) < dead_threshold * 2.5 {
        score += 12.0; // risky small gap
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Penalize leaving a gap that exactly teases but doesn't fit the
    // lookahead item (would be dead for the next step too).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing bins; few open bins -> opening new bins is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (1.0 - fill_ratio);

    // New-bin candidate handling: neutral baseline; only attractive when
    // open-bin pressure is high or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 8.0 * pressure - 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host item + lookahead pair
        }
    }

    // Slight stream-progression term: later in stream, be more frugal.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    score
}

