    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (small residuals are hard to fill; large residuals are flexible).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr);
    }

    // Lookahead: strongly reward bins whose post-residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 2.0 * ((next_item_size - post_residual) as f64 / 20.0).min(3.0);
        }
    }

