            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // gen149: combined fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - (rem - next_item_size as f64).abs() / cap;
                score -= 2.0 + 3.0 * snug2;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // gen149: compaction coupling — prefer residuals close to a multiple of next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // gen149: penalize unusable dead tails.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // gen149: mid-stream compaction — keep fleet mean residual low.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // gen149: near-miss gaps strand space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen156: hard compaction coupling — reward bins whose post-fit residual
        // exactly equals the next item size (perfect two-item chain ahead).
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let chain_gap = (post_residual - 2 * next_item_size) as f64;
            if chain_gap < 2.0 {
                score -= 4.0 * (1.0 - chain_gap / 2.0) * (1.0 - progress);
            }
        }
        // gen156: dead-space ratio shaping — strongly penalize residuals in the
        // awkward 0.5–0.75 band that neither chain nor close out.
        if dead_space >= 0.5 && dead_space <= 0.75 && post_residual > 0 {
            score += 2.5 + 4.0 * (dead_space - 0.5);
        }
        // gen156: reward near-closure residuals (< 8% of capacity) more aggressively
        // when the stream is past halfway.
        if post_residual > 0 && waste_ratio < 0.08 && progress > 0.5 {
            score -= 4.0 * (1.0 - waste_ratio / 0.08);
        }
        // gen156: when many bins fit, prefer the one with the smallest post_residual
        // deviation from the fleet mean (keeps future typical items placeable).
        if fitting_bins_count >= 3 && post_residual > 0 {
            let dev2 = ((post_residual as f64) - mean_residual).abs();
            if dev2 < 4.0 {
                score -= 2.0 * (1.0 - dev2 / 4.0);
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, quadratically (dead space is worse the larger it is)
    let mut score = pr as f64 * (1.0 + 0.8 * x * x);

    // Smooth stream-progress coupling: early on, prefer tight fills less aggressively;
    // later, tighten more (dead space late is costlier since fewer chances to reuse).
    let progress_gain = 1.0 + 1.5 * t * t;
    score *= progress_gain;

    // Reward near-perfect fits with a smooth bonus term (subtract when x small)
    score -= 12.0 * (1.0 - x).powi(6) * (1.0 + t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth gate)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_gate = 1.0 / (1.0 + gap * gap * 0.05);
        score -= 10.0 * fit_gate;
    } else if next_item_size == 0 {
        // last item: just minimize residual
        score = pr as f64;
    }

    // Penalize leaving residuals that no typical item (>=1) can use — dead space
    if pr < 1.0 {
        score -= 5.0; // perfect fill
    }

    // Mild penalty for scattering across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: neutral baseline so it competes fairly; slightly discourage
    // early stream when open bins fit well, encourage late when bins are fragmented.
    if bin_residual == bin_capacity {
        score = cap - pr + 15.0 * (1.0 - t) + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 25.0; // don't open a new bin when an existing one is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
