pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let cls = post_residual / quarter; // 0..4 harmonic class

    // Penalize dead space in low classes (very small residuals are wasted)
    match cls {
        0 => score += 12.0,
        1 => score += 4.0,
        2 => score -= 2.0,
        3 => score -= 5.0,
        _ => score -= 8.0,
    }

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // complementary harmonic: post_residual % next_item_size small => good chaining
            let r = post_residual % next_item_size;
            score -= (next_item_size - r) as f64 * 0.3;
            if r == 0 { score -= 10.0; }
        } else {
            // next item cannot fit here; large post_residual less useful
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Integer-division threshold on post_residual vs half capacity
    if post_residual >= half {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when open bins have poor fit
    if bin_residual == bin_capacity {
        // neutral-ish baseline; penalize when many bins open already
        score += 5.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= half {
            score -= 10.0; // big next item -> fresh bin attractive
        }
    }

    // Progress-based mild regularization
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Slight preference toward bins tighter than mean residual
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Two-step lookahead with snugness scaling (combined with best-heuristic weights)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            } else {
                let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
                if leftover_ratio < 0.05 {
                    score -= 5.0 * (1.0 - leftover_ratio / 0.05);
                }
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
            if post_residual < 8 {
                score += 40.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let waste_ratio = post_residual as f64 / cap;
    let dead_space = waste_ratio;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            // scale new-bin penalty with scarcity AND tightness of the fleet
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // fresh bin as donor when its residual tracks the mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // early stream: fresh bins are cheap
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
            // late stream: prefer existing bins strongly
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
        if progress < 0.25 && open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
    } else {
        score -= 25.0 * progress;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // reward residues that can hold next item twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // penalize stranding a residue smaller than half the next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // near-exact next-item fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // exact next-item match: strong pull scaled by scarcity
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        // mid-band dead-space quadratic penalty
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
