pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space in the "unusable small gap" zone (1..=10) is the worst outcome:
        // almost nothing can ever fill it.
        if post_residual < 10 {
            score += 500.0 * (10.0 - post_residual as f64);
        }
        // Moderate gaps (10..=20) are only usable by small items; penalize softly.
        else if post_residual < 20 {
            score += 50.0 * (20.0 - post_residual as f64) / 10.0;
        }
        // Large residual chunks stay reusable; slight reward for keeping them big.
        else {
            score -= 5.0;
        }
    }

    // --- Lookahead coupling (k=2): prefer bins whose leftover fits the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement: leftover can host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * slack;
            if post_residual == next_item_size {
                score -= 200.0; // exact two-item chain, ideal
            }
        } else {
            // Leftover becomes dead space for the upcoming item.
            score += 80.0;
        }
    }

    // --- Tightness bonus: fraction of bin consumed ---
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 100.0 * fill;

    // --- Open bins pressure: when many bins are open, consolidate harder ---
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual != bin_capacity {
        // Reward using existing bins proportionally to open-bin count.
        score -= 20.0 * pressure;
    } else {
        // Opening a new bin: penalize more when many bins already open,
        // unless this is a forced last-chance situation.
        score += 60.0 + 25.0 * pressure;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // --- Mean residual context: bins far below mean residual are underused; prefer them ---
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // --- Slight early-stream aggression: fill bins fully early on ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward (gen157: sharpened)
    if post_residual == 0 {
        score -= 1400.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Two-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            } else {
                let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
                if leftover_ratio < 0.05 {
                    score -= 5.0 * (1.0 - leftover_ratio / 0.05);
                }
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
            if post_residual < 8 {
                score += 40.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let waste_ratio = post_residual as f64 / cap;
    let dead_space = waste_ratio;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            // scale new-bin penalty with scarcity AND tightness of the fleet (gen157: sharper)
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (3.0 + 2.5 * tight) * fitting_bins_count.min(6) as f64;
            }
            // fresh bin as donor when its residual tracks the mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // early stream: fresh bins are cheap
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
            // late stream: prefer existing bins strongly (gen157: earlier onset)
            if progress > 0.55 {
                score += 7.0 * (progress - 0.55) / 0.45;
            }
        }
        if progress < 0.25 && open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        // gen157: late-stream fresh bins are expensive when any open bin could serve
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
    } else {
        score -= 25.0 * progress;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // reward residues that can hold next item twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // penalize stranding a residue smaller than half the next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // near-exact next-item fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // exact next-item match: strong pull scaled by scarcity
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        // mid-band dead-space quadratic penalty
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
            let band = (waste_ratio - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // residue near mean residual: future flexibility
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // endgame squeeze
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // mid-stream: prefer small residues
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        // very tight fit with few alternatives: extra pull
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // small stranded residue guard
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        // two-fit check
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
        // leftover after placing next item lands in a tight, reusable band (gen157: wider band)
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem_ds = (post_residual - next_item_size) as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.15 {
                score -= 4.0 * (1.0 - rem_ds / 0.15);
            }
        }
        // dead-space overshoot penalty when next item cannot use residue
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // large dead space that next item cannot fill
        if waste_ratio > 0.5 && next_item_size > 0 && next_item_size as f64 > waste_ratio * cap {
            score += 3.0 * (waste_ratio - 0.5) * 10.0;
        }
        // fragment penalty scaled by dead space
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * waste_ratio);
        }
        // reward very small residues relative to mean (compaction)
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // refined dead-space valley: reward residual bands matching typical next-item multiples
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && waste_ratio > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && waste_ratio > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // penalize mid-band dead space more sharply when few bins fit the item
        if waste_ratio > 0.3 && waste_ratio < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // gen157: reward residuals that leave room for a second copy of the next item
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        // gen157: penalize residual straddling the mean without fitting the next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // gen157: avoid overshooting into a wide gap beyond the next item
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // gen157: when the fleet is tight, strongly prefer bins whose post_residual stays near the next item's size
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // gen157: discourage creating residuals that neither fit next item nor stay small
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // gen157: exact next-item match with very low waste gets extra pull
        if next_item_size > 0 && post_residual == next_item_size && waste_ratio < 0.1 {
            score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
        }
        // gen157: compaction — when fleet is large, favor bins whose leftover stays below typical item size
        if open_bins_count > 6 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size / 2 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward scaled by how snugly it fits.
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 60.0 - slack_after_next.min(60.0);
        } else {
            // Next item won't fit here: penalize leaving a gap smaller than next item.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin candidate unless current bin is a poor fit (large post residual).
    if bin_residual == bin_capacity {
        // New bin baseline: keep it attractive only if no tight fit exists.
        score += 40.0 + 0.2 * mean_residual;
    }

    // Penalize large dead space non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;
    }

    // Late-stream preference to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Classic best-fit flavor: prefer tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward for a chain: post-residual close to next item size.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Wasted potential: residual too small for lookahead item.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just fill tightest.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(0.5) / 20.0);
    score += 0.02 * open_pressure * (post_residual as f64);

    // Mean residual coupling: prefer bins close to the mean residual (avoid fragmentation outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: be more willing to open new bins (score for empty bin relatively good);
    // late stream: penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 5.0 + 40.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0; // fresh bin can host lookahead too
        }
    }

    // Mild preference for bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
