        }
        // penalize residuals that can never be reused unless near zero.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // mid-stream compaction — keep the fleet's mean residual low.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // discourage near-miss gaps just below the next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen157: two-item chain bonus — residual that exactly fits next item twice is prime.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual == 2 * next_item_size {
            score -= 6.0;
        }
        // gen157: reward bins whose post-fit residual matches the fleet mean (keeps donors alive).
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if (rem - mean_residual).abs() < 2.0 {
                score -= 3.0;
            }
        }
        // gen157: penalize oversized leftover when fleet is fragmented.
        if next_item_size > 0 && post_residual >= next_item_size && open_bins_count > 5 {
            let rem = (post_residual - next_item_size) as f64;
            if rem > mean_residual * 1.5 {
                score += 2.0 + 0.05 * (rem - mean_residual * 1.5);
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
