}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth coupling: prefer small residuals early, tight fits late
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize residuals too small for the lookahead item (dead space)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += 30.0 * gap * gap;
        // Reward residuals that exactly or nearly fit the next item
        let fit_next = (pr - ns).max(0.0) / cap;
        score -= 15.0 * (1.0 - fit_next * cap) * (1.0 - fit_next * cap).max(0.0) / cap;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * (1.0 - norm_pr);

    // Mean-residual coupling: bins deviating above mean waste are less attractive
    score += 0.3 * (pr - mean_residual).max(0.0);

    // New-bin candidate: discourage unless current bins are poor fits
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 60.0 - 45.0 * scarcity * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bucket by capacity fraction (quarters).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Dead-space penalty: residual too small to hold even the smallest item.
    if post_residual < 10 {
        score += 60.0;
    }
    // Class-based dead-zone penalty: residuals in the "awkward" bottom quarter
    // (1..quarter) are hard to fill; the (quarter, half) band is more usable.
    if post_residual > 0 && post_residual <= quarter / 2 {
        score += 25.0;
    } else if post_residual > quarter / 2 && post_residual < quarter {
        score += 12.0;
    } else if post_residual >= quarter && post_residual <= half {
        score -= 8.0;
    } else if post_residual > half && post_residual <= three_quarter {
        score -= 14.0;
    } else if post_residual > three_quarter {
        score -= 18.0;
    }

    // Perfect-fit harmonic classes: post_residual exactly divisible by common
    // item granularities (10, 20, 25, 50) is likely fillable later.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

