pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Dead space penalty: residuals too small for the smallest plausible future item
    // (sizes can be as small as 1) are only dead if below typical small-item sizes.
