pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (low post residual), normalized.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: penalize if the next item cannot fit in the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Blocked lookahead: penalty grows if next item is large.
            score += 8.0 + (next_item_size as f64) * 0.25;
        } else {
            // Reward chains where the next item fits the remaining space.
            let chain_quality = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 * (1.0 - chain_quality);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global context: when many bins are open, prefer consolidating into
    // bins whose residual is close to the mean (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be slightly more willing to spread items;
    // late in the stream, tighten up to close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin grows with open bins and stream progress.
        let open_cost = 10.0 + 0.3 * open_bins_count as f64 + 10.0 * progress;
        // If current bin would leave very little room anyway, new bin is fine.
        let waste_here = post_residual as f64 / bin_capacity as f64;
        score = open_cost + 30.0 * waste_here;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // fresh bin always fits the lookahead
        }
    }

    score
}

