pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // dead space penalty
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward leaving a gap that can still host typical items.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Prefer bins whose residual was already small (dense packing).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.15;

    // Open-bin pressure: discourage spreading into many bins unless fit is tight.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 20.0; // gap too small for next item: extra dead-space penalty
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 1.2;
        score += 15.0 - pressure + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if post_residual == bin_capacity {
            score += 5.0; // slightly discourage new bin when a decent fit exists
        }
    }

    // Mean residual coupling: if open bins are mostly full, prefer reusing them.
    if mean_residual < 20.0 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/excellent match with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect follow-up: next item exactly fills the bin
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // Next item cannot fit here anyway; residual is dead space
        else if next_item_size > post_residual {
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Penalize residuals far from the mean residual (creating outliers)
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Mild reward for tight fits overall
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 4.0 * tightness;

    // Penalize large residual waste more than proportionally
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill is excellent
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin's
    // post-residual would be large dead space and other options exist
    if bin_residual == bin_capacity {
        // new bin baseline: residual = capacity - item_size
        if fitting_bins_count > 1 && post_residual as f64 > mean_residual + 15.0 {
            score += 20.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
