            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // gen161: compaction coupling — when several bins fit, prefer the one whose
        // post-fit residual is closest to a multiple of the next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // gen161: penalize bins whose residual can never be reused (residual < smallest
        // plausible item) unless it is near zero — force closure of dead tails.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // gen161: mid-stream compaction — prefer bins whose post-fit residual keeps the
        // fleet's mean residual low, so future items of typical size still fit.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // gen161: discourage leaving residuals that are just barely below the next item
        // (near-miss gaps) — these strand space that no future item can use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen161 NEW: dead-space absorption coupling — among bins whose leftover after
        // the next item is unusable (< mean_residual * 0.3), prefer the one that
        // minimizes stranded capacity, scaled by how much of the stream remains.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem > 0.0 && rem < mean_residual * 0.3 {
                let stranded_frac = rem / cap;
                score += 1.5 * stranded_frac * 10.0 * (1.0 - progress);
            }
        }
        // gen161 NEW: two-item lookahead chain — reward bins that can host the current
        // item AND still fit the next item's size again afterwards (double-donor).
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count >= 2 {
            score -= 2.0 + 1.5 * (1.0 - waste_ratio);
        }
        // gen161 NEW: fleet-level balance — penalize bins whose post-fit residual is far
        // above the fleet mean when many bins fit (keeps future typical items placeable).
        if fitting_bins_count >= 3 && post_residual as f64 > mean_residual * 1.4 {
            score += 1.5 + 0.02 * (post_residual as f64 - mean_residual * 1.4);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Lookahead (k=2): reward bins whose leftover can host the next item,
    // with an extra bonus for near-exact two-item chains.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 5.0 * (1.0 - slack);
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover likely dead for the next item: mild penalty scaled by dead size
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Dead-space penalty: tiny leftovers that almost nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bonus: if this is the only open bin that fits, use it
    // rather than opening a fresh bin (only applies to real open bins).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        // Base handicap: existing bins usually win.
        score += 10.0;
        // Large items benefit from a fresh bin (avoid awkward splits).
        score -= 0.15 * item_size as f64;
        // Early in the stream, consolidation matters less; be more willing to open.
        score -= 5.0 * (1.0 - progress);
        // If open bins are tight on average (mean residual below item size),
        // fits are poor -> opening a new bin is attractive.
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 8.0;
        }
        // Many open bins with slack: discourage adding more bins.
        if open_bins_count > 3 && mean_residual > 2.0 * item_size as f64 {
            score += 6.0;
        }
    }

    // Mild preference for bins with more headroom when post_residual ties,
    // and a tiny consolidation pressure as bins accumulate.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward
    if post_residual == 0 {
        score -= 1400.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Two-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            } else {
                let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
                if leftover_ratio < 0.05 {
                    score -= 5.0 * (1.0 - leftover_ratio / 0.05);
                }
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
            if post_residual < 8 {
                score += 40.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let waste_ratio = post_residual as f64 / cap;
    let dead_space = waste_ratio;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (3.0 + 2.5 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
            if progress > 0.55 {
                score += 7.0 * (progress - 0.55) / 0.45;
            }
        }
        if progress < 0.25 && open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
    } else {
        score -= 25.0 * progress;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
            let band = (waste_ratio - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem_ds = (post_residual - next_item_size) as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.15 {
                score -= 4.0 * (1.0 - rem_ds / 0.15);
            }
        }
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if waste_ratio > 0.5 && next_item_size > 0 && next_item_size as f64 > waste_ratio * cap {
            score += 3.0 * (waste_ratio - 0.5) * 10.0;
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * waste_ratio);
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && waste_ratio > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && waste_ratio > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if waste_ratio > 0.3 && waste_ratio < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        if next_item_size > 0 && post_residual == next_item_size && waste_ratio < 0.1 {
            score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
        }
        if open_bins_count > 6 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size / 2 {
            score += 3.0;
        }
        // gen161: combined fine-grained snugness + lookahead anticipation — reward bins whose
        // leftover after the next item stays proportional to mean residual (keeps fleet usable)
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            if leftover <= mean_residual {
                score -= 3.0 * (1.0 - leftover / mean_residual.max(1.0));
            }
            // anticipate the item after next: leftover should hold a typical item again
            if leftover as f64 >= mean_residual * 0.8 && fitting_bins_count <= 3 {
                score -= 2.0;
            }
        }
        // gen161: dead-space diagnosis — penalize bins whose waste ratio sits just below the
        // next item's footprint (almost-fitting residues are the worst stranders)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if near < 0.12 {
                score += 5.0 * (1.0 - near / 0.12);
            }
        }
        // gen161: mid-stream compaction — strong pull toward near-zero residues
        if progress > 0.35 && post_residual > 0 && waste_ratio < 0.03 {
            score -= 6.0 * (1.0 - waste_ratio / 0.03);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post residual, scaled non-linearly (dead space penalized super-linearly).
    let mut score = pr * (1.0 + (pr / cap).powi(2));

    // Stream-progress coupling: late in the stream, residuals matter more (less time to fill them).
    let late = progress * progress;
    score *= 1.0 + 1.5 * late * (pr / cap);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= cap * (1.0 + late);
    }

    // Reward tight fits (post residual near zero).
    score -= (1.0 - pr / cap).powi(3) * cap * 0.8;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= (1.0 - slack / cap) * cap * 0.5;
    } else if next_item_size as f64 > pr {
        // Next item can't follow into this bin: mild penalty growing with progress.
        score += 10.0 + 20.0 * late;
    }

    // Prefer bins below mean residual (consolidating loose space) via smooth coupling.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for fewer open bins when residuals are large.
    score += open_bins_count as f64 * (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Waste penalty grows super-linearly for small residual classes (dead space).
    score += (10 - class.min(10)) as f64 * 2.5;

    // Perfect fits and near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic coupling with next item: reward if next item fits exactly in the
    // post residual (chained perfect fit), penalize if next item cannot fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            let next_class = next_post / 10;
            score -= (10 - next_class.min(10)) as f64 * 1.5;
            if next_post == 0 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large awkward gaps.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin fits well (its raw residual score is
    // already high, so subtract a moderate amount to stay competitive but
    // not beat a good existing fit).
    if bin_residual == bin_capacity {
        score -= 15.0 + (open_bins_count as f64) * 0.5;
        // If stream is early, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer filling bins whose residual is far below the mean (consolidate).
    score += (mean_residual - post_residual as f64) * 0.2;

    // Small bonus for tight modulo classes: residual divisible by 5 tends to
    // pair well with typical item granularities.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead synergy: fit now AND leave room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
