    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits into this bin's post-residual, reward;
    // smooth quadratic coupling between post-residual and next item size.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let ng = gap / cap;
            score -= 30.0 * (1.0 - ng * ng) * (0.4 + progress);
        } else {
