        score += 55.0 * (1.0 - saturation) * (0.6 + progress) + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes (0..=10) are excellent; large leftovers are dead space.
    let cap_frac = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score += 5.0;
    } else {
        score += 10.0;
    }

    // Harmonic (modulo) class of post_residual: leftovers in multiples of 10
    // are reusable by common item sizes; odd/prime residues are less reusable.
    if post_residual > 0 {
        let mod10 = post_residual % 10;
