        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tight = mean_residual / cap_frac;
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        score = 70.0 + avg_tight * 20.0 + pressure - progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // fresh bin helps chain large items
        }
    }

    // Mild progression-based tightening: late in the stream, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (30.0 - pr.min(30.0));

    // Prefer bins below mean residual (balancing) slightly.
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
