pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize "dead space": small unusable gaps that no realistic item can fill.
        let max_item = 80u32.min(bin_capacity);
        if post_residual < 10 {
            // Tiny gap below the minimum item size: pure waste.
            score += 500.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot fit the known next item: likely dead space.
            score += 120.0 + 2.0 * (post_residual as f64);
        } else if post_residual > max_item {
            // Gap larger than any item: still potentially usable, mild bonus.
            score -= 30.0;
        } else {
            // Usable gap: mild reward proportional to how well next item fits.
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 15.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(40.0);
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual < 10 {
            score += 60.0; // still avoid creating tiny dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // encourage closing out bins with small residuals.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 10.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below average (consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten up: penalize any leftover residual more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current fits would create dead space.
    if bin_residual == bin_capacity {
        // Neutral baseline; slight penalty so it's chosen only when open bins score badly.
        score += 25.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with a large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
