        // cannot even host the next item twice are strongly penalized when the fleet
        // has alternatives, pushing compaction toward tight bins.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // gen162: harvest coupling — when nearing the end, residuals that can absorb
        // the item AND the next item exactly (post == 2*next) are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen164: two-step lookahead — after placing the item and the next item, the
        // leftover should still track the fleet mean (keeps donor slots reusable).
        if next_item_size > 0 && post_residual >= next_item_size && progress < 0.7 {
            let rem2 = post_residual as f64 - next_item_size as f64;
            let track = (rem2 - mean_residual).abs() / mean_residual.max(1.0);
            if track < 0.15 {
                score -= 3.5 * (1.0 - track / 0.15) * (1.0 - progress);
            }
        }
        // gen164: penalize creating residuals in the "stranded band" — larger than a
        // tiny tail but smaller than half the mean residual, nearly unusable later.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.4 && post_residual < 25 {
            score += 2.0 + 0.1 * post_residual as f64;
        }
        // gen164: when many bins fit, prefer the tightest post-fit residual strongly —
        // spread-out leftovers fragment the fleet.
        if fitting_bins_count >= 3 && post_residual > 0 {
            score += 0.08 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        // Perfect lookahead match: strong reward.
        if gap < 0.5 {
            score -= 45.0;
        } else if nxt <= post {
            // Next item fits into the residual: reward proportionally to tightness.
            let tightness = nxt / post.max(1.0);
            score -= 25.0 * tightness;
            // Penalize leaving a sliver that likely becomes dead space.
            if gap < 8.0 {
                score += 12.0 * (1.0 - gap / 8.0);
            }
        } else {
            // Next item does not fit here; mildly penalize large leftovers.
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize residuals relative to the mean residual across open bins.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave big waste.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If item nearly fills a fresh bin, opening is cheap.
        score -= 0.15 * item_size as f64;
        // Prefer new bin if existing bins are congested (few fitting bins).
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Mild penalty for leaving very small unusable residue (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference to fill bins tighter as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
