pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: perfect match where next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving awkward gaps.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
            // Small post_residual that nothing will use is dead space.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Compare against mean residual: bins with less residual than average are good targets.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit well, more so late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
        // New bin is attractive only if no open bin can fit the item.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

