    // gen166: penalize residuals that neither fit next item nor stay small
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && waste_ratio > 0.55 {
        score += 3.0 + 4.0 * (waste_ratio - 0.55);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into granularity buckets.
    // Small residuals (<=10) are near-perfect; large residuals are still useful.
    // The "danger zone" is 1..=9 for typical distributions where min item ~ 10,
    // but with unknown distribution (items 1..100) use a soft quadratic penalty
    // on mid-size dead space instead.
    let pr = post_residual;
    if pr > 0 {
        let prf = pr as f64;
        // class via integer division thresholds: 1-9 tiny, 10-24 small, 25-49 medium, 50+ large
        let class = if pr <= 9 { 0 } else if pr <= 24 { 1 } else if pr <= 49 { 2 } else { 3 };
        let class_penalty = match class {
            0 => 60.0,   // tiny dead space is wasted capacity
            1 => 10.0,
            2 => -5.0,   // medium residual still flexible
            _ => -15.0,  // large residual very flexible
        };
        score += class_penalty;

        // Nonlinear coupling: penalize dead space relative to mean residual —
        // leaving much more dead space than average is bad.
        score += 0.5 * (prf - mean_residual).max(0.0);
    }

    // Lookahead (k=2): reward if next item fits into the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        // exact lookahead fit is excellent
        if slack == 0.0 {
            score -= 400.0;
        } else {
            score -= 40.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > pr && pr > 0 {
        // next item cannot use this bin's leftover: penalize proportionally
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if pr > 0 && pr < 10 {
            score += 50.0; // but not if it creates unusable slivers
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; scaled by how many bins already open
        score = cap * 0.9 + open_bins_count as f64 * 5.0;
        // if lookahead is huge and nothing else known, slightly favor fresh bin late in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 20.0; // big next item may need a fresh bin anyway
        }
        // perfect fits elsewhere will beat this; poor fits (high scores) lose to it
    }

    // Modulo-arithmetic harmonic flavor: residual divisible by common item classes
    // (multiples of 10) are more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Slight tie-break toward bins with lower residual (tighter bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap_f = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap_f;
    let waste_ratio = dead_space;

    // Dead-space penalty for tiny residuals that strand space
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // mutated: small residuals near closure are good, flip part of penalty
    }

    let tightness = 1.0 - dead_space;
    score -= 25.0 * tightness * tightness;

    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
