    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space relative to smallest item size (10)
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny dead space is fine (nothing fits anyway)
    } else {
        score += (post_residual as f64) * 0.5; // extra penalty on wasted usable space
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            score -= 400.0;
        } else if nxt < post {
            // next item fits: reward proportionally to how well it fills leftover
            score -= 150.0 * (nxt / post);
        } else {
            // next item won't fit here: penalize large leftovers mildly
            score += 30.0 * ((nxt - post) / bin_capacity as f64);
        }
    }

    // Compare residual against mean residual across open bins
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        score += 40.0 * (ratio - 1.0); // prefer bins tighter than average
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized if many open bins exist
    if bin_residual == bin_capacity {
        score += 120.0 + 5.0 * open_bins_count as f64;
        // but allow new bin if current item would leave a huge gap in any existing bin
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 200.0;
        }
    }

    // Slight preference to fill older/scarcer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

