pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression ratio (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect / near-perfect fits strongly (non-linear)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness).powi(6) * 30.0;

    // Lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let lookahead_waste = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (lookahead_waste as f64 / bin_capacity as f64)).powi(4);
        } else {
            // next item won't fit here: penalize proportionally to dead space
            score += 6.0 + (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize, unless no good fit exists
    if bin_residual == bin_capacity {
        let mut penalty = 18.0;
        // Late in stream, or many open bins with high residual: discourage new bins more
        penalty += 20.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            penalty += 10.0;
        }
        // Very large items late in stream may justify fresh bins
        if item_size > bin_capacity / 2 && progress > 0.5 {
            penalty -= 8.0;
        }
        score += penalty;
    }

    // Prefer using bins whose residual is close to item size (waste-aware)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.4;

    // Global state coupling: with many open bins, favor consolidating into existing ones
    score += open_bins_count as f64 * 0.05 * (bin_residual == bin_capacity) as i32 as f64;

    // Mean-residual alignment: prefer bins near the mean residual (keeps balance)
    score -= 2.0 * (-((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64)).exp();

    // Early-stream exploration: allow slightly more freedom for new bins early on
    score -= 5.0 * (1.0 - progress);

    score
}

