pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Smooth non-linear waste penalty: quadratic in normalized post-residual,
    // amplified by stream progress (late waste is more costly).
    score += 6.0 * prn * prn * (0.5 + progress);

    // Reward near-perfect fits (small post residual) with a smooth exponential bonus.
    score -= 12.0 * (-3.0 * prn).exp();

    // Dead-space penalty when post residual is too small for the mean useful item.
    let mid_item = 0.5 * cap;
    if pr < mid_item {
        let unusable = (mid_item - pr) / cap;
        score += 8.0 * unusable * unusable * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin;
    // otherwise penalize proportionally to the gap.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 4.0 * (1.0 - prn) * (ni / cap);
        } else {
            score += 3.0 * ((ni - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating into bins with low residual relative to mean.
