        score += 4.0 + 3.0 * (open_bins_count as f64).ln();
        if next_item_size > 0 && (next_item_size as f64) / cap > 0.6 {
            score -= 2.0; // large upcoming item: fresh bin slightly more attractive
        }
    }

    score
}

