            let rem2 = post_residual - 2 * next_item_size;
            let band2 = ((rem2 as f64) - mean_residual).abs();
            if band2 < 5.0 {
                score -= 3.0 * (1.0 - band2 / 5.0) * (1.0 - 0.5 * progress);
            }
        }
        // gen168: cap-aware leftover smoothing — when the fleet is fragmented, mildly
        // prefer bins whose post-fit leftover lands in the 10..30 sweet spot where most
        // item sizes (1..100 distribution tail) can still be absorbed.
        if open_bins_count > 4 && post_residual >= 10 && post_residual <= 30 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 2.0 + 1.0 * (1.0 - progress);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear squaring
    // that punishes large dead space more than proportionally.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Harmonic class of post_residual: classify leftover space by integer
    // division thresholds. Residuals in the "tiny" class (<=10) are nearly
    // dead space; reward them. Mid-class residuals (11..30) are semi-useful;
    // penalize mildly. Large residuals are fine (already low score).
    let class = post_residual / 10; // 0..=10 harmonic buckets
    match class {
        0 => score -= 12.0,               // near-perfect fit
        1 => score -= 4.0,                // still very tight
        2 => score += 6.0,                // awkward mid residual
        3 => score += 10.0,               // worst "wasted" zone
        _ => {}
    }

    // Lookahead coupling: if the next item can reuse the post_residual,
    // this placement chains nicely; reward it. If next item is larger than
    // post_residual but this bin would be left with awkward space, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // reward perfect chaining, scaled by how tight the chain is
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // modulo harmonic: post_residual % next_item_size small => future
            // splits are easy
            if next_item_size != 0 && post_residual % next_item_size <= 3 {
                score -= 5.0;
            }
        } else if post_residual > 0 && post_residual < 15 {
            score += 8.0; // creates tiny dead space the next item can't use
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is horrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
        // but if the fit is terrible, soften the bonus so a new bin can win
        if post_residual > 50 {
            score += 25.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when no open bin gives a good fit: make the empty bin
    // look unattractive for decent fits by tying its score to mean_residual.
    if bin_residual == bin_capacity {
        // opening a new bin costs ~half a bin on average; reflect that
        score = 55.0 + 0.3 * mean_residual - 0.2 * open_bins_count as f64;
        // if next item is huge, opening fresh may be wise
        if next_item_size > 60 {
            score -= 15.0;
        }
        // late in the stream, avoid opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference for filling bins that are already low (consolidation),
    // using mean_residual as a reference point.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Harmonic modulo on bin_residual: bins whose residual is a multiple of
    // 10 tend to accept standard items cleanly; slight reward.
    if bin_residual % 10 == 0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
