pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // items (<= 10) are essentially lost capacity -> heavy penalty.
    if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Unusable dead space below the minimum item size.
        score += 60.0 * (10.0 - post_residual as f64);
    } else {
        // Gradually penalize residual that cannot fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Mild superlinear penalty on leftover space (waste grows quadratically).
        score += 0.05 * (post_residual as f64) * (post_residual as f64) / 100.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (handled implicitly since a new empty bin has post_residual == capacity),
    // and encourage consolidating into existing bins.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin has huge post_residual; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If current bin is the only fitting one, opening new bin is bad.
        if fitting_bins_count <= 1 {
            score += 50.0;
        }
        // If mean residual across open bins is small (fragmented bins),
        // opening a fresh bin is more acceptable.
        score -= (mean_residual / 10.0).min(15.0);
    }

    // Slight late-stream consolidation: as the stream progresses, prefer
    // filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
