        // compaction coupling — prefer bins whose post-fit residual is closest to a
        // multiple of the next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // penalize bins whose residual can never be reused unless near zero.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // mid-stream compaction — keep the fleet's mean residual low.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // near-miss gaps strand space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // dead-space sink.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // harvest coupling — post == 2*next residuals are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen168: two-fit anticipation — reward bins where the leftover after placing
        // the next item still fits a second copy, scaled by fleet scarcity.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && waste_ratio < 0.5 {
            let two_fit = post_residual >= 3 * next_item_size
                || ((post_residual - 2 * next_item_size) as f64) <= mean_residual;
            if two_fit {
                score -= 2.5 + 1.5 * (1.0 - progress);
            }
        }
        // gen168: dead-space overshoot penalty — a residual that cannot host the next
        // item despite large dead space is stranded capacity.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: bin becomes exactly filled by next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward tighter leftover after the pair.
            let after_pair = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_pair as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space proportionally.
            score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Penalize tiny unusable slivers (< 10) unless they were unavoidable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer bins tighter than the fleet average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline so it wins only over poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + 25.0 * progress - (if next_item_size > 0 && next_item_size <= bin_capacity { 5.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize awkward dead space: residuals that are small but nonzero
    // (too small to hold the smallest plausible item).
    if post_residual > 0 && post_residual < 12 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this bin; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_util = next_item_size as f64 / (item_size + next_item_size) as f64;
            score -= 22.0 * chain_util;
        } else {
            score += 8.0 * (next_item_size as f64 / 100.0);
        }
    } else {
        // Last item: strongly prefer exact completion.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just fill anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage
    // spreading waste; prefer filling bins below-average residual.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 12.0 * dev;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (i.e., residual far exceeds item) and stream is early enough to amortize.
    if bin_residual == bin_capacity {
        let waste_open = (bin_residual - item_size) as f64;
        score = 55.0 + waste_open - 40.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 90.0; // never open a new bin when one fits
        }
        if next_item_size > 0 && waste_open as u32 >= next_item_size {
            score -= 15.0; // fresh bin can chain the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
