        // cannot even host the next item twice are strongly penalized when the fleet
        // has alternatives, pushing compaction toward tight bins.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // harvest coupling — when nearing the end, residuals that can absorb
        // the item AND the next item exactly (post == 2*next) are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen169: dead-space diagonal — grade waste continuously instead of only
        // via band bonuses; a smooth quadratic penalty on mid-range dead space
        // steers compaction toward bins whose leftover stays usable.
        if post_residual > 0 {
            let ideal = (mean_residual / cap).clamp(0.02, 0.9);
            let dsq = (dead_space - ideal) * (dead_space - ideal);
            score += 2.0 * dsq;
            // gen169: two-step lookahead — reward residuals that can host the next
            // item AND still hold a typical future item afterwards.
            if next_item_size > 0 && post_residual >= next_item_size {
                let rem = post_residual - next_item_size;
                if rem as f64 >= mean_residual * 0.9 {
                    score -= 3.5 * (1.0 - progress);
                }
            }
            // gen169: penalize creating residuals in the "orphan band" — larger
            // than a small item but smaller than the next item, unusable soon.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual as f64 > mean_residual * 0.5 {
                score += 3.0 * (1.0 - progress);
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly coupled with stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Smooth polynomial coupling: penalize large residuals more as stream progresses.
    let quad = norm_pr * norm_pr;
    score += 30.0 * progress * quad;

    // Dead-space avoidance: residual too small for typical future items is bad.
    let dead = (1.0 - (pr / 80.0).min(1.0)).powi(2);
    score += 12.0 * dead;

    // Lookahead: reward bins whose post-residual fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 - progress);
        // Penalize leaving residual that exactly wastes vs next item slightly too big.
        let gap = (pr - nx).abs() / cap;
        score += 5.0 * gap * gap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into fuller bins.
    score -= 3.0 * (1.0 - norm_pr) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate handling: neutral baseline so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score = pr + 40.0 + 20.0 * progress;
    }

    score
}

