pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let pr_mod10 = pr % 10;
    let pr_mod20 = pr % 20;
    let pr_div10 = pr / 10;

    // Dead-space classes: residuals that are hard to fill get penalized
    // Small odd-ish residuals (1..9 mod 10) are near-unusable; multiples of 10/20 are reusable.
    if pr > 0 {
        if pr_mod10 == 0 {
            score -= 6.0; // perfectly harmonic residual, highly reusable
            if pr_mod20 == 0 {
                score -= 4.0; // half-capacity harmonic, even better
            }
        } else if pr_mod10 <= 2 {
            score += 3.0; // tiny sliver, likely dead space
        } else if pr_mod10 >= 8 {
            score += 1.5; // near-round but awkward
        }
    } else {
        score -= 12.0; // perfect closure of a bin
    }

    // Integer-division threshold classes on post_residual
    match pr_div10 {
        0 => score += 4.0,           // 0..9: nearly dead
        1 => score += 0.0,           // 10..19
        2 => score -= 1.0,           // 20..29: fits small items
        3 => score -= 2.0,           // 30..39
        4 => score -= 3.0,           // 40..49: half-bin class, very useful
        5 => score -= 2.0,
        _ => {}
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 8.0;
    } else if fill_ratio > 0.7 {
        score -= 4.0;
    } else if fill_ratio < 0.3 {
        score += 2.0; // loose fit wastes harmonic structure
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
