    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only prefer opening a new bin when current fits are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; harmonic classes of item size mod 10
        let item_mod10 = item_size % 10;
        let mut newbin = 55.0 - (item_mod10 == 0) as i32 as f64 * 10.0;
        if fitting_bins_count == 0 {
            newbin -= 60.0; // no alternative
        }
        if fill_ratio < 0.35 && fitting_bins_count > 2 {
            newbin -= 8.0; // all fits loose; fresh bin may pack better
        }
        score = score.min(newbin) + if bin_residual == bin_capacity { 0.0 } else { 0.0 };
        if bin_residual == bin_capacity {
            score = newbin;
        }
    }

    // Mild stream-progression pressure to close bins early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;

    // Tie-break toward consolidating into fewer bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
