        // gen162: mid-stream compaction — keep the fleet's mean residual low.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // gen162: discourage near-miss gaps just below the next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // gen162: dead-space sink for half-full bins that cannot host the next item twice.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // gen162: harvest coupling — post == 2*next is a premium target.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen170: lookahead anticipation — reward bins whose post-fit residual equals a
        // plausible future item size (near mean_residual), keeping donors alive.
        if post_residual > 0 && mean_residual > 1.0 {
            let dev = (post_residual as f64 - mean_residual).abs() / mean_residual;
            if dev < 0.15 && fitting_bins_count >= 2 {
                score -= 4.0 * (1.0 - dev / 0.15);
            }
        }
        // gen170: triple-chain reward — bins that can host item + next + one more copy
        // of a typical item are premium compaction targets.
        if next_item_size > 0 && post_residual >= item_size + 2 * next_item_size {
            score -= 5.0;
        }
        // gen170: penalize creating residuals in the awkward 60..90 band that neither fit
        // the next item nor close out the bin, unless it's the only fitting bin.
        if post_residual > 0 && post_residual > 60 && next_item_size > 0 && post_residual < next_item_size && fitting_bins_count >= 2 {
            score += 5.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..100 unknown
    // distribution, so treat sub-threshold gaps as likely dead). Penalize quadratically.
    if post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: the smaller the post_residual relative to bin capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones;
    // with few open bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current fit is poor (large post_residual) or no real bin fits well.
    if bin_residual == bin_capacity {
        score = 100.0 - pressure * 8.0;
        if fitting_bins_count == 1 {
            score += 70.0; // don't open new bin when a real last-chance bin exists
        }
        if post_residual as f64 > mean_residual {
            score -= 15.0; // poor fit elsewhere -> new bin more acceptable
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit in the gap -> the residual becomes dead space.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Mild stream progression term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

