                let k = r.round();
                if k >= 1.0 && (r - k).abs() < 0.08 && post_residual >= next_item_size {
                    score += 10.0 * (1.0 - (r - k).abs() / 0.08);
                }
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual == next_item_size {
                score -= 6.0;
            }
            // gen170: late-stream fresh bins are expensive — close out existing space
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if open_bins_count >= 2 && next_item_size > 0 && next_item_size as f64 <= mean_residual * 0.9 {
            score += 6.0;
        }
    } else {
        score -= 20.0 * progress;
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
            let two_fit = post_residual >= 2 * next_item_size || (leftover as f64) <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
            let rem_ds = leftover as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.15 {
                score += 9.0 * (1.0 - miss / 0.15);
            }
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if progress > 0.7 && next_item_size > 0 && post_residual == next_item_size {
            score -= 4.0 * (progress - 0.7) / 0.3;
        }
        if fitting_bins_count >= 4 && post_residual > 0 && item_size as f64 <= mean_residual {
            score += 1.5;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // chain anticipation — repeatable fills
        if next_item_size > 0 && post_residual > next_item_size {
            let chain = post_residual - next_item_size;
            let chain_gap = (chain as f64 - next_item_size.max(1) as f64).abs();
            if chain_gap <= 3.0 && dead_space < 0.35 {
                score -= 2.5 + 1.5 * (3.0 - chain_gap);
            }
            if chain > 0 && chain < next_item_size && chain < 8 {
                score += 2.0 + 0.5 * (8 - chain) as f64;
            }
        }
        // scarcity-aware snugness
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
            let snug = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if snug < 0.25 {
                score -= 3.0 * (1.0 - snug / 0.25);
            }
        }
        // fleet-balance term against piling into large-residual bins
        if open_bins_count >= 6 && dead_space > 0.55 && next_item_size > 0 && next_item_size <= post_residual {
            score += 1.0 + 0.02 * open_bins_count as f64;
        }
        // reward near-exact fill when the bin is one of few fitting
        if fitting_bins_count <= 3 && post_residual > 0 && post_residual as f64 <= mean_residual {
            score -= 1.5;
        }
        // penalize leaving residuals just below small-item thresholds
        if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
            score += 3.0;
        }
        // gen170: discourage creating residuals that neither fit next item nor stay small
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // gen170: keep donor slots alive when the fleet is tight
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space penalty (non-linear)
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;
    }

    // 2-step lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect chain: this placement sets up an exact fit for next item
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item still fits after placement
            score -= 150.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize wasted pairing opportunity
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Late in stream: prefer closing out bins (avoid many near-empty bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score -= 200.0 * progress;
    }

    // New empty bin candidate: penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // if next item is large, fresh bin is attractive
        if next_item_size > 60 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    let tightness = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
    score -= 25.0 * tightness * tightness;

    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Lookahead synergy: strong snug-fit reward (borrowed from best heuristic)
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Two-copy chain reward
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
    }

    // Stranded-space penalty (graded, dead-space aware)
    if post_residual > 0 && next_item_size > post_residual {
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;
        score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        // near-miss penalty scaled by closeness
        let gap = next_item_size - post_residual;
        if gap <= 6 {
            score += 9.0 + 1.5 * (6 - gap) as f64;
        } else if gap <= 12 {
            score += 3.0 + 0.4 * (12 - gap) as f64;
        }
    }

    // Waste-ratio bands
    let waste_ratio = (post_residual as f64) / (bin_capacity.max(1) as f64);
    if post_residual > 0 && waste_ratio < 0.08 && fitting_bins_count <= 2 {
        score -= 13.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // Small residual near mean is a good donor
    if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
        score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
    }

    // Leftover after next item nearly empty
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        let leftover_ratio = leftover as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // fresh bin as donor when its residual tracks the mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // late-stream fresh bins are expensive
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
    } else {
        // Avoid straddling residuals that can't host the next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // Drift control: keep donor slots alive when fleet is scarce
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = ((post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
    }

    // Late-stream: grab near-exact fits aggressively to close bins out
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    // Late-stream: discourage opening fresh bins
    if progress > 0.75 && bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * tightness;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted pairing
            score += 2.0;
        }
    }

    // Global state: when many bins are open with high mean residual,
    // discourage opening new bins (prefer consolidation into open bins).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when consolidation is viable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let consolidation_pressure = mean_residual / bin_capacity as f64;
        score += 15.0 + 20.0 * consolidation_pressure * (1.0 - progress);
        // Late in the stream, opening a fresh bin is less costly.
        score -= 10.0 * progress;
        // If no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward when open-bin count is high (avoid proliferation).
        score -= 0.5 * (open_bins_count as f64).min(20.0);
        // Prefer bins with residual below mean (fill the emptier-ish ones first
        // keeps some bins very full and closes them).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild time-horizon coupling: early stream favors flexibility (medium residuals),
    // late stream favors aggressive filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * dead - progress * 4.0 * dead;

    score
}

