    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // base: prefer tight fits (small post_residual), with non-linear curvature
    let mut score = r * (1.0 + 0.8 * rn * rn);

    // stream-progress coupling: later in stream, tolerate larger residuals less
    score += 30.0 * rn * t * (1.0 - t) * 4.0 * t;

    // dead-space penalty: residuals too small to ever be useful
    let dead = if r < 10.0 { (10.0 - r) as f64 * 2.5 } else { 0.0 };
    score += dead * (0.5 + 0.5 * t);

    // lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let d = (r - n) / cap;
        let k = (-d * d * 8.0).exp();
        score -= 12.0 * k;
    }

    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - rn);
    }

    // crowd penalty: many open bins -> prefer filling existing ones
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * rn;

    // alignment with mean residual (smooth coupling)
    score += 0.3 * (r - mean_residual).abs();

    // new-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * t;
    }

    score
}

