pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space is worse in certain classes.
    // Class 0: perfect fit (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small leftovers (1..=10) are nearly dead space; penalize extra.
        if post_residual <= 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 10.0;
        }
        // Harmonic bucket: leftover divisible by common item sizes (10,20,25,50)
        // means a future item could exactly fill it -> reward.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }
        if post_residual % 50 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another leftover; scale by class match.
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 15.0;
            }
            if nr == 0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot use this bin's leftover; leftover likely wasted.
            score += 12.0;
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit. Penalize the fresh bin mildly so existing
    // reasonable fits win, but keep it competitive when fits are bad.
    if bin_residual == bin_capacity {
        // Base handicap: existing bins with small residuals are better choices.
        score += 30.0;
        // If many bins already fit the item, opening a new bin is clearly bad.
        if fitting_bins_count > 1 {
            score += 40.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin gives flexibility.
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fits).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
        // Prefer bins with residual above the mean (keep small residuals for small items).
        if (bin_residual as f64) < mean_residual {
            score += 5.0;
        }
        // Spread load when too many bins are open.
        if open_bins_count > 8 {
            score += 2.0 * (open_bins_count as f64 - 8.0).min(6.0);
        }
    }

    // Integer-division threshold: leftovers in (0,10) are dead; leftovers >= 50
    // can host half-capacity items, mildly reward keeping them.
    if post_residual >= 50 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // Strong lookahead: exact-fit reward scaled by snugness
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 30.0 + 0.25 * next_item_size as f64 + 14.0 * snug;
        // room for a second copy of next item
        if post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        // graded stranded-space penalty
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        score += 3.0 * frag;
        // near-miss: next item barely misses fitting
        let miss = next_item_size - post_residual;
        if miss <= 6 {
            score += 4.0 + 1.5 * (6 - miss) as f64;
        }
    }

    // Dead-space penalty on residual
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }

    let tightness = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
    score -= 25.0 * tightness * tightness;

    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure
    score += pressure * 2.0;

    // Lookahead synergy: next item fits exactly into post_residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Waste-ratio bands
    let waste_ratio = (post_residual as f64) / (bin_capacity.max(1) as f64);
    if post_residual > 0 && waste_ratio < 0.05 && fitting_bins_count <= 2 {
        score -= 12.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 50.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // late-stream fresh bins are expensive
