                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
    } else {
        // mid-band dead space that can't host next item
        if dead_threshold > 0 && waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // residual near mean residual and fits next item: good donor slot
        if next_item_size > 0 && post_residual >= next_item_size {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // unusable space beyond next item
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = waste_ratio - (next_item_size as f64 / bin_capacity.max(1) as f64);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // small clean remainder after placing next item
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            let rem_ds = rem as f64 / bin_capacity.max(1) as f64;
            if rem_ds > 0.02 && rem_ds < 0.12 {
                score -= 4.0 * (1.0 - rem_ds / 0.12);
            }
        }
    }

    // Late-stream: grab near-exact fits aggressively to close bins out
