    // Stream progression: early on, be slightly more open to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (tighter bins get used first, keeping large residuals available).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

