        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // Keep the fleet's mean residual low.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // Near-miss gaps strand space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // Dead-space sink.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // Harvest coupling: post == 2*next is a premium target.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen172: large dead space that cannot host the next item even once is costly
        // when alternatives exist — push compaction toward tight bins.
        if next_item_size > 0 && dead_space > 0.5 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
    }

    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with a non-linear twist:
    // post_residual == 0 is a perfect fit, heavily reward it.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small-but-nonzero dead space quadratically (unusable slivers).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * (10.0 - pr) * 0.8;
        }
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the remaining space after this placement.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: next item fits perfectly => strong reward.
        if diff == 0.0 {
            score -= 55.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item also fits here: reward proportionally to closeness.
            score -= 25.0 * (1.0 - diff / 100.0);
        } else {
            // Next item won't fit after this placement: mild penalty,
            // stronger if we leave a large awkward residual.
            score += 5.0 + 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving more slack than average is wasteful; less than average tightens packing.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Make the empty-bin baseline costly
    // unless the item is large relative to capacity (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Large items (>70% capacity) justify a fresh bin; small ones don't.
        score += 70.0 - 60.0 * tightness;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // If many bins are open already, discourage spreading further.
        score += 2.0 * open_bins_count as f64;
        // Lookahead: if the next item could pair with this item in a fresh bin, soften.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }
    }

    // Slight preference to keep filling older bins as the stream progresses.
    score += 0.02 * (post_residual as f64).sqrt();

    score
}

