        // Prefer bins with residual close to mean (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early stream: be slightly greedy toward tight fits to build dense bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of residual with stream progress
    let poly = x * x * (1.0 - progress) - 0.5 * x * progress * (1.0 - x);
    score += 20.0 * poly;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * (30.0 + 40.0 * progress);

    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (nx - pr).max(0.0) / cap;
        score += 25.0 * unusable * unusable;
        // Reward leaving exactly enough room for the next item
        let gap = (pr - nx).abs() / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - x);
    } else {
        score += 10.0 * x; // last item: prefer fullest bin
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * x;

    // New-bin candidate: keep neutral baseline, slightly penalized early
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: items 1..100 mod 10 classes.
    let item_class = (item_size % 10) as f64;
    let next_class = (next_item_size % 10) as f64;

    // Penalize post_residual classes that are hard to fill (small dead space).
    let pr = post_residual as f64;
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * (10.0 - pr) * 2.0;
    }

    // Reward post_residual that is an integer-division-compatible slot for the
    // next item (next item fits exactly into post_residual's division class).
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_exact = (post_residual % next_item_size.max(1)) as f64;
        score -= 12.0 * (1.0 - fits_exact / (next_item_size.max(1) as f64));
        // Lookahead: prefer bins where next item also fits snugly.
        let post2 = post_residual - next_item_size;
        score += post2 as f64 * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a stranded residual.
        score += 8.0;
    }

    // Capacity fraction coupling: reward tight fills as fraction of capacity.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac * fill_frac;

    // Modulo thresholds on post_residual: harmonically "nice" leftovers.
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 6.0; // residual in multiples of 10 is reusable
    } else if pr_u % 5 == 0 && pr_u > 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - pr;
        score += 10.0 + fragmentation.max(0.0) * 0.5;
        // Early stream: opening bins is cheap; late stream: prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If item is large relative to capacity, a fresh bin is attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Class mismatch penalty: item class vs mean residual class harmony.
    let mean_class = (mean_residual as u32 % 10) as f64;
    score += 0.4 * (item_class - mean_class).abs();

    // Slight preference for bins with below-mean residual (compact bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful are heavily penalized.
    // Dead space threshold: below ~half of the smallest plausible item (1..100 range -> ~50).
    let dead_threshold = bin_capacity as f64 * 0.5;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // The smaller the dead gap, the worse (exponentially amplified).
        let deadness = 1.0 - (post_residual as f64) / dead_threshold;
