    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if (post_residual as f64) < 0.1 * bin_capacity as f64 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the item fits
    // poorly everywhere (large post_residual in existing bins) or few bins are open.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 2.0;
        if post_residual == bin_capacity {
            // item exactly fills a fresh bin
            score -= 80.0;
        }
    }

    // Lookahead coupling: if the next item would fit into this bin's post_residual,
    // reward the placement (keeps chains tight); otherwise mild penalty.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Early in the stream, tolerate more open bins (spread risk); late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Slight bonus for filling more of the bin relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
