        let item_rel = item_size as f64 / bin_capacity as f64;
        score += 22.0 * (1.0 - progress) - 15.0 * item_rel;
        // If open bins are on average quite full, a new bin is reasonable.
        score -= 0.15 * mean_residual;
    } else {
        // Prefer bins whose residual is below the mean (use up tighter bins first).
        score += 0.10 * (mean_residual - bin_residual as f64);
