        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space relative to lookahead item: penalize
            score += 2.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative residual vs mean residual: prefer bins tighter than average
    score -= 5.0 * (mean_residual - post_residual as f64);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins can fit decently
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * open_bins_count as f64;
        // but if current fit would leave large dead space, new bin is attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

