pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        let pr = post_residual as f64;
        // Penalize dead space that no plausible item can use.
        if pr < 10.0 {
            score -= 15.0 * (10.0 - pr);
        } else if pr > bin_capacity as f64 * 0.5 {
            score += 8.0; // wasteful leftover
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't chain here: penalize more if leftover is small & unusable.
        if post_residual < next_item_size && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (high mean residual) or this bin would leave a large dead gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        // Opening a bin is good when existing bins have little room left.
        score += (1.0 - crowded) * 45.0;
        // Early in the stream, slightly discourage hoarding new bins.
        score += 10.0 * (1.0 - progress);
        // If item barely fits a new bin (huge item), opening is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 3.0 + 0.5 * open_bins_count as f64;
    }

    // Slight preference for balancing residuals toward the mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
