pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear (quadratic) penalty on small residuals
    let mut score = pr as f64;
    score += 0.35 * cap * x * x * (1.0 - x); // penalize mid-range waste smoothly
    score -= 0.5 * cap * x * x * x; // reward tight fits super-linearly

    // Stream-progress coupling: early on prefer leaving usable space, late prefer tight packing
    let early = (1.0 - progress) * (1.0 - progress);
    score += 0.4 * cap * early * x * (1.0 - x);

    // Lookahead: reward residuals that fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * next_item_size as f64 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: make it slightly unattractive unless it would waste nothing
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress;
        if next_item_size > 0 && bin_residual >= next_item_size + item_size {
            score -= 1.0;
        }
    }

    // Mean-residual coupling: when open bins are loose, prefer using them over new bins
    score -= 0.15 * (mean_residual - x * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);

    // Core lookahead: reward residuals that can host the next item snugly
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Dead-space bands
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward
    let tightness = 1.0 - dead_space;
    score -= 25.0 * tightness * tightness;

    // Two-copy chain bonus
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        let snug = 1.0 - (leftover as f64 / next_item_size.max(1) as f64);
        score -= 6.0 * snug;
    }

    // Exact-fit lookahead
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Stranded-space penalty when next item won't fit
    if post_residual > 0 && next_item_size > post_residual {
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        let unusable = dead_space - (next_item_size as f64 / bin_capacity.max(1) as f64);
        if unusable > 0.0 {
            score += 2.0 + 6.0 * unusable;
        }
    }

    // Wide gap band penalty
    if dead_space > 0.25 && dead_space < 0.65 {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // Fleet tightness: keep donor slots alive
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = ((post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        if drift < 0.35 {
            score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure
    score += pressure * 2.0;

    // Waste-ratio bands
    let waste_ratio = dead_space;
    if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
        score -= 12.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            // scale new-bin penalty with scarcity and fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
