    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    // gen176: penalize residuals straddling the mean without fitting the next item
    if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
        score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
    }

    // gen176: reward tiny leftover after hosting next item
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "awkward" residue classes are penalized (dead space unlikely to be reused).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Modulo-style classes on post_residual (capacity 100 -> classes of 10).
    let class = post_residual % 10;
    // Dead-space classes: 1..=9 leftovers are hard to fill with items >=1
    // but especially bad for tiny residues that no realistic item fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0; // tiny unusable slivers
    } else if class != 0 && class <= 3 {
        score += 8.0; // awkward small class
    } else if class == 0 {
        score -= 6.0; // clean decade boundary: reusable chunk
    }

    // Perfect fit reward (harmonic zero class).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits generally: subtract proportional to how much of the
    // bin the item consumes.
    score -= (item_size as f64 / cap) * 20.0;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let chain = (post_residual - next_item_size) % 10;
            if chain == 0 {
                score -= 12.0; // chain leaves clean class
            } else {
                score += chain as f64 * 0.5;
            }
        }
        // If next item cannot fit here and this bin would be nearly empty after,
        // slight penalty (bin becomes stranded).
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid forcing a
    // bad new-bin decision unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize it relative to mean residual state.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or when
        // open bins are already fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 30.0 - 10.0 * progress;
        // If mean residual across open bins is small (fragmented), opening a
        // fresh bin is more attractive.
        new_bin_cost -= (mean_residual / cap).max(0.0) * 20.0;
        // If the item is large relative to typical residual space, new bin helps.
        if (item_size as f64) > mean_residual {
            new_bin_cost -= 8.0;
        }
        // Empty bin has post_residual == capacity; rebase so its natural
        // post_residual advantage doesn't dominate.
        score = score - pr + new_bin_cost + (cap - item_size as f64) * 0.3;
    }

    // Mild preference to fill bins with larger residuals when many bins open
    // (consolidation pressure via mean residual).
    if bin_residual != bin_capacity {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Slight pressure to reduce open bin count over time.
    score += open_bins_count as f64 * 0.05;

    score
}

