            score += 20.0; // small items should almost never open new bins
        }
    }

    // Open-bin pressure: mildly favor bins with below-mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Late in the stream, be more conservative: keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

