pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on large residuals
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (favor spreading); late, demand tight packing
