    score += 30.0 * coupling * cap.sqrt();

    // Dead-space quadratic penalty: residuals too small for any future item
    let dead = (1.0 - pr_norm / 0.1).max(0.0);
    score -= 25.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - progress) * (nxt / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across too many bins relative to stream progress
    score += (open_bins_count as f64).ln() * 4.0 * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - pr_norm) - 15.0 * (1.0 - progress);
    }

