pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can host next item: moderate reward proportional to snugness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack * 0.15;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable gap.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }

    // Snug fit overall: small post-residual is good, but avoid tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // sliver penalty
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be slightly more willing to open new bins (keep flexibility).
