        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host the next item too
        }
    }

    // Many open bins: discourage spreading, favor filling existing ones.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.2;
    }

    score
}

