pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Penalize small dead space that nothing can use (residual < 10, min item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // next item won't fit here; penalize wasting large residual
            score += 0.15 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64));
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer bins with below-mean residual (keep big bins open)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early on, be conservative; late, pack aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * fill_ratio;

    // New-bin candidate: penalize unless current bins are too full / few options
