    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them super-linearly.
    let poly = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score *= poly;

    // Reward tight fits: quadratic bonus when post_residual is small
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * (1.0 + progress);

    // Penalize dead space that is too small to be useful later (smooth trough)
    let dead = (norm_pr - 0.15) * (norm_pr - 0.15);
    score += 10.0 * (-dead * 40.0).exp() * (1.0 - progress);

