            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (1.0 + progress);
        } else {
            let miss = (nx - pr) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference for consolidating into bins with low mean residual
    let mr = mean_residual / cap;
    score += 5.0 * mr * mr;

    // Smooth new-bin penalty: opening a fresh bin is slightly discouraged,
    // more so early in the stream; decays as stream progresses.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    score
