    // Small post residuals are excellent (tight fit), but only if not zero-waste
    // blocking the next item. Dead zone: post_residual in (0..10) is fragile.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item almost fits but not quite, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
