            let slack = pr - next_item_size;
            score -= (20.0 - slack.min(20) as f64) * 0.5;
        } else {
            let over = next_item_size - pr;
            if over <= 10 {
                score += over as f64 * 1.5; // just-missed fit wastes this bin
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

