            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            if leftover_ratio > 0.02 && leftover_ratio < 0.12 {
                score -= 4.0 * (1.0 - leftover_ratio / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // Fine-grained residual fitting with lookahead anticipation: reward residuals
        // whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - (rem - next_item_size as f64).abs() / cap;
                score -= 2.0 + 3.0 * snug2;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // Compaction coupling: prefer residuals closest to a multiple of next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // Penalize residuals that can never be reused (residual < smallest plausible item)
        // unless near zero — force closure of dead tails.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // Mid-stream compaction: keep fleet's mean residual low so typical items still fit.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // Near-miss gaps strand unusable space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // Dead-space sink: large waste that cannot host the next item twice is penalized.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // Harvest coupling: post == 2*next is a premium target.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen181: two-step lookahead chain — strongly reward bins whose post-fit residual
        // is exactly the next item size (perfect two-item chain), scaled by remaining stream.
        if next_item_size > 0 && post_residual == next_item_size && progress < 0.7 {
            score -= 3.0 + 3.0 * (1.0 - progress);
        }
        // gen181: penalize residuals that strand space just above a multiple of next item
        // (large leftover after one fit that no further item of typical size can use).
        if next_item_size > 0 && post_residual > next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem > mean_residual * 1.5 && rem < next_item_size as f64 {
                score += 2.0 + 0.1 * (rem - mean_residual * 1.5);
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    let dead_space = post_residual as f64 / bin_capacity.max(1) as f64;

    // Dead-space penalty: small residuals are near-closed bins (good); mid-size gaps are waste
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward
    let tightness = 1.0 - dead_space;
    score -= 25.0 * tightness * tightness;

    // Strong snug lookahead: reward bins that host the next item snugly
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        let leftover = post_residual - next_item_size;
        if leftover >= next_item_size {
            score -= 7.5;
        }
        let leftover_ratio = leftover as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
        if post_residual >= 2 * next_item_size && dead_space < 0.45 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
    } else if next_item_size > 0 {
        // Item won't fit after placement: penalize by how close it came
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        if post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if post_residual > 0 && post_residual as f64 > mean_residual * 1.15 {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
    }

    // Exact-fit lookahead synergy
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // Waste-ratio bands
    if post_residual > 0 {
        if dead_space < 0.08 {
            score -= 13.0;
        } else if dead_space < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        } else if dead_space > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if dead_space > 0.55 && next_item_size > post_residual {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        if post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Fleet-tight donor-slot coupling
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if drift < 0.35 {
            score -= 1.5 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64);
        }
    }

    // Open-bins pressure
    score += pressure * 2.0;

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
    }

    // Late-stream: close out bins aggressively
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (min item size 1..100, but small gaps < 10
    // are nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps too small for the lookahead item are also dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits: waste ratio relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * tightness;

    // Reward using the last bin that can fit the item (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // If the bin is empty and residual equals mean residual closely, mild
    // penalty for spreading: new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
    }

    // If lookahead fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leftover after that matters
            score -= 200.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot follow: dead-space risk grows
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins tighter than the mean residual (good packing).
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Discard tiny unusable slivers (< 10 can never host min item).
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // New-bin candidate: only attractive when current fits are poor
    // (large post_residual elsewhere) or many bins already open.
    if bin_residual == bin_capacity {
        let best_alternative = mean_residual.min(bin_residual as f64);
        score = 250.0 + 0.5 * open_bins_count as f64
            - 0.3 * (mean_residual - 50.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.2 * next_item_size as f64;
        }
        let _ = best_alternative;
    }

    // Mild late-stream tightening: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Lookahead: fit now AND leave room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
