    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but zero post_residual (perfect close) is best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else {
            // Penalize leaving a gap that only wastes space relative to next item.
            let gap_waste = post_residual as f64 - (next_item_size as f64 * 0.0);
            score += 0.15 * gap_waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper (more future items to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many bins are open and mean residual is large, discourage more bins.
        score += 0.05 * open_bins_count as f64 + 0.2 * mean_residual;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins relative to global state.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    // Time-horizon coupling: late in stream, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

