        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen183: combined fine-grained residual fitting with lookahead anticipation —
        // reward bins whose post-fit residual can absorb the item after next too
        // (two-step chain), scaled by how early we are in the stream.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && (1.0 - progress) > 0.4 {
            let chain_slack = post_residual - 2 * next_item_size;
            if chain_slack as f64 <= mean_residual * 0.5 {
                score -= 3.0 * (1.0 - progress) * (1.0 - chain_slack as f64 / (mean_residual * 0.5).max(1.0));
            }
        }
        // gen183: dead-tail closure — a bin whose residual after this fit is tiny but
        // nonzero while a fresh bin could host the item exactly is wasteful.
        if post_residual > 0 && post_residual < 8 && next_item_size > 0 && next_item_size as f64 > mean_residual {
            score += 3.0 + 0.5 * (8 - post_residual) as f64;
        }
        // gen183: prefer bins whose post-fit residual matches the mean residual closely
        // when the fleet has many open bins (keeps future typical items placeable).
        if open_bins_count >= 5 && next_item_size > 0 && post_residual > 0 {
            let dev2 = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev2 < 0.15 {
                score -= 2.0 * (1.0 - dev2 / 0.15) * (open_bins_count.min(10) as f64) * 0.2;
            }
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Progress-dependent reward for tight fits: weight grows smoothly over stream
    let tight_reward = (1.0 - norm_pr).powi(3) * (60.0 + 140.0 * progress * progress);
    score -= tight_reward;

    // Penalize dead space with a smooth quartic term, stronger late in stream
    score += norm_pr.powi(4) * (40.0 + 120.0 * progress);

    // Mild penalty on fragmentation zone (post residual 1..15) via smooth bump
    let bump = (-(pr - 8.0).powi(2) / 50.0).exp();
    score += 25.0 * bump * (0.5 + progress);

    // Lookahead synergy: reward if next item fits smoothly in post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 20.0 * (1.0 - ((pr - ns) / cap)).exp();
        } else {
            score += 10.0 * ((ns - pr) / cap);
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (0.5 + progress);
    }

    // New-bin candidate: prefer it only when post residual is huge and stream is early
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 25.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins near the mean residual (smooth)
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: how well post_residual decomposes into typical item sizes (1..=100)
    // Dead space = post_residual that no plausible item class can use.
    let small_gap = post_residual.min(10);
    score += small_gap as f64 * 2.5; // tiny unusable slivers are bad

    // Modulo classes on post_residual: gaps in "nice" classes (multiples of 5, 10) are more reusable
    let mod5 = post_residual % 5;
    let mod10 = post_residual % 10;
    score += mod5 as f64 * 1.5;
    score += (mod10 == 0) as i32 as f64 * -8.0;

    // Integer-division thresholds: can the lookahead item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead chains perfectly: strong reward, scaled by how tight the chain is
            let chain_tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 30.0 + 25.0 * chain_tightness;
        } else {
            // lookahead cannot use this gap: penalize proportionally to wasted fraction
            let waste = (next_item_size - post_residual.min(next_item_size)) as f64;
            score += waste * 0.4;
        }
        // Harmonic pairing: post_residual exactly complements next item to a class boundary
        if (post_residual + next_item_size) % 25 == 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if this bin would leave large ugly residue
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // open a new bin if item is large and no good class exists among open bins
        if item_size >= bin_capacity / 2 {
            score -= 55.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer filling bins with low residual relative to the mean (balance consolidation)
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Early stream: be slightly more liberal with opening bins (better long-run packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Tight fit bonus: reward when item occupies most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: fit now AND leave room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
            if progress > 0.8 {
                score += 8.0 * (progress - 0.8) / 0.2;
            }
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // fresh bin competes only if the fleet cannot chain two items ahead.
            if next_item_size > 0 && post_residual >= 2 * next_item_size {
                score += 9.0;
            }
            // early stream — fresh bins are cheap insurance against fragmentation.
            if progress < 0.25 && next_item_size > 0 && item_size as f64 > mean_residual {
                score -= 4.0;
            }
            // when the fleet is fragmented (many open bins), a fresh bin is wasteful.
            if open_bins_count > 6 {
                score += 3.0 + 0.5 * (open_bins_count.min(14) as f64);
            }
            // mid/late stream, a fresh bin must be strongly discouraged if the
            // item already fits somewhere with a small leftover.
            if progress > 0.3 && fitting_bins_count >= 1 {
                score += 5.0 * (1.0 - progress).min(0.7);
            }
            // gen183: fresh-bin bonus scaled by how well the new bin's residual
            // (capacity - item) tracks the fleet mean — a donor slot in rhythm.
            if next_item_size > 0 {
                let new_res = (bin_capacity - item_size) as f64;
                let rhythm = 1.0 - ((new_res - mean_residual).abs() / mean_residual.max(1.0)).min(1.0);
                if rhythm > 0.7 && progress < 0.7 {
                    score -= 4.0 * (rhythm - 0.7) * 3.0;
                }
            }
            // gen183: endgame — never open bins late.
            if progress > 0.9 {
                score += 25.0 * (progress - 0.9) * 10.0;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            if leftover_ratio > 0.02 && leftover_ratio < 0.12 {
                score -= 4.0 * (1.0 - leftover_ratio / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // combined fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - (rem - next_item_size as f64).abs() / cap;
                score -= 2.0 + 3.0 * snug2;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // compaction coupling — when several bins fit, prefer the one whose
        // post-fit residual is closest to a multiple of the next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // penalize bins whose residual can never be reused (residual < smallest
        // plausible item) unless it is near zero — force closure of dead tails.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // mid-stream compaction — prefer bins whose post-fit residual keeps the
        // fleet's mean residual low, so future items of typical size still fit.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // discourage leaving residuals that are just barely below the next item
        // (near-miss gaps) — these strand space that no future item can use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // dead-space sink — bins with large residual-to-capacity waste that
        // cannot even host the next item twice are strongly penalized when the fleet
        // has alternatives, pushing compaction toward tight bins.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // harvest coupling — when nearing the end, residuals that can absorb
        // the item AND the next item exactly (post == 2*next) are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen183: two-step chain anticipation — reward bins whose post-fit residual
        // can host the next item twice (post >= 2*next) with a tight leftover,
        // blending lookahead depth with compaction.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let chain_left = (post_residual - 2 * next_item_size) as f64;
            if chain_left < next_item_size as f64 {
                score -= 3.5 * (1.0 - chain_left / next_item_size.max(1) as f64) * (1.0 - progress);
            }
        }
        // gen183: pair-sum coupling — bins whose residual is near the sum of the
        // current and next item are ideal two-item closers; prefer them.
        if next_item_size > 0 {
            let pair = (item_size + next_item_size) as f64;
            let d = (bin_residual as f64 - pair).abs();
            if d <= 4.0 {
                score -= 4.0 * (1.0 - d / 4.0);
            }
        }
        // gen183: fleet-count aware tiebreak — with many fitting bins, prefer the
        // smallest post_residual more aggressively (compaction over spread).
        if fitting_bins_count >= 4 && post_residual > 0 {
            score -= 1.2 * (fitting_bins_count.min(10) as f64) * (1.0 - post_residual as f64 / cap);
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are nearly unusable dead space.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: heavy penalty.
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 15.0; // gap won't fit next item either: dead space
        }
    }

    // Last chance: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream length remaining.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        // More attractive if open bins are already crowded (low mean residual).
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // And if the current item fits snugly into a fresh bin.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Open-bins pressure: prefer spreading across fewer bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than average (below-mean residual = good candidate).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: fit now AND leave room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
            if progress > 0.8 {
                score += 8.0 * (progress - 0.8) / 0.2;
            }
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // fresh bin competes only if the fleet cannot chain two items ahead.
            if next_item_size > 0 && post_residual >= 2 * next_item_size {
                score += 9.0;
            }
            // early stream — fresh bins are cheap insurance against fragmentation.
            if progress < 0.25 && next_item_size > 0 && item_size as f64 > mean_residual {
                score -= 4.0;
            }
            // when the fleet is fragmented (many open bins), a fresh bin is wasteful.
            if open_bins_count > 6 {
                score += 3.0 + 0.5 * (open_bins_count.min(14) as f64);
            }
            // mid/late stream, a fresh bin must be strongly discouraged if the
            // item already fits somewhere with a small leftover.
            if progress > 0.3 && fitting_bins_count >= 1 {
                score += 5.0 * (1.0 - progress).min(0.7);
            }
            // gen183: late-stream fresh bins are expensive — close out existing space.
            if progress > 0.75 && fitting_bins_count >= 1 {
                score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
            }
        }
    } else {
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if dead_space < 0.45 && waste_ratio > 0.05 {
                score -= 1.5 + 2.0 * (0.45 - dead_space);
            }
        }
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * dead_space);
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        if waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
            if waste_ratio < 0.1 {
                score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
            if leftover_ratio > 0.02 && leftover_ratio < 0.12 {
                score -= 4.0 * (1.0 - leftover_ratio / 0.12);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && next_item_size as f64 <= mean_residual {
            score -= 2.0;
        }
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let unusable = dead_space - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        if dead_space > 0.25 && dead_space < 0.65 {
            let band = (dead_space - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && dead_space > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && dead_space > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        if dead_space > 0.3 && dead_space < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        if next_item_size > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count <= 3 {
            score -= 3.0 * (4.0 - fitting_bins_count as f64);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            if miss < 0.25 {
                score += 6.0 * (1.0 - miss / 0.25);
            }
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // combined fine-grained residual fitting with lookahead anticipation —
        // reward residuals whose post-fit leftover still accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem >= next_item_size as f64 {
                let snug2 = 1.0 - (rem - next_item_size as f64).abs() / cap;
                score -= 2.0 + 3.0 * snug2;
            }
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let band = ((post_residual - next_item_size) as f64 - mean_residual).abs();
            if band < 3.0 {
                score -= 3.0 * (1.0 - band / 3.0);
            }
        }
        if dead_space > 0.35 && dead_space < 0.7 && open_bins_count > 3 {
            let fleet_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            score += 2.0 + 4.0 * fleet_tight * (dead_space - 0.35) / 0.35;
        }
        if post_residual > 0 && next_item_size > 0 {
            let dev = ((post_residual as f64) - mean_residual).abs() / mean_residual.max(1.0);
            if dev < 0.1 && (1.0 - progress) > 0.3 {
                score -= 2.5 * (1.0 - dev / 0.1) * (1.0 - progress);
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // compaction coupling — when several bins fit, prefer the one whose
        // post-fit residual is closest to a multiple of the next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
            if frac < 0.08 {
                score -= 2.5 * (1.0 - frac / 0.08) * (1.0 - progress);
            }
        }
        // penalize bins whose residual can never be reused (residual < smallest
        // plausible item) unless it is near zero — force closure of dead tails.
        if post_residual > 0 && post_residual < 4 && dead_space > 0.02 {
            score += 5.0 + 2.0 * (open_bins_count.min(8) as f64);
        }
        // mid-stream compaction — prefer bins whose post-fit residual keeps the
        // fleet's mean residual low, so future items of typical size still fit.
        if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < mean_residual * 0.6 && rem > 0.0 {
                score -= 2.0 * (1.0 - rem / (mean_residual * 0.6));
            }
        }
        // discourage leaving residuals that are just barely below the next item
        // (near-miss gaps) — these strand space that no future item can use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = next_item_size - post_residual;
            if near_miss <= 3 {
                score += 4.0 + 2.0 * (3 - near_miss) as f64;
            }
        }
        // dead-space sink — bins with large residual-to-capacity waste that
        // cannot even host the next item twice are strongly penalized when the fleet
        // has alternatives, pushing compaction toward tight bins.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // harvest coupling — when nearing the end, residuals that can absorb
        // the item AND the next item exactly (post == 2*next) are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen183: reward bins that can host a second copy of the next item while
        // keeping waste below half the capacity (donor-slot preservation).
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
        // gen183: penalize large dead space that cannot host the next item at all.
        if dead_space > 0.5 && next_item_size > 0 && next_item_size as f64 > dead_space * cap {
            score += 3.0 * (dead_space - 0.5) * 10.0;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect pair
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.05;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    // Small late-stream conservatism: keep bins tight near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

