pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual as u32) as f64 * 0.8;
        } else {
            // Reward bins that leave room for the lookahead item
            score -= 4.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins can fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 40.0;
        // cheaper to open new bin late in the stream or when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0;
        }
        // if no open bin fits, opening is natural
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Mild preference for filling fuller bins (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight penalty when bin residual deviates far from mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Time-horizon coupling: early stream -> conserve bins; late stream -> pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // Small lookahead coupling: prefer bins whose post residual pairs well with next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += gap * 0.03;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: early on, waste matters less;
    // later, tighten fits more aggressively.
    score *= 1.0 - 0.3 * t * t;

    // Reward bins whose residual aligns with the lookahead item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (gap / cap).powi(2);
        score -= (1.0 - fit_kernel) * 8.0 * (1.0 - t);
    }

    // Penalize creating dead space far from mean residual (non-linear dispersion term)
    let disp = (pr - mean_residual) / cap;
    score += 5.0 * disp * disp;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Smooth progress-based fill incentive
    score -= 4.0 * t * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Lookahead synergy: next item fits exactly into post_residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 15.0;
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        score += 3.0 * frag;
    }

    // Reward residuals that can host the next item AND keep a usable remainder
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover >= next_item_size {
            score -= 7.5;
        } else {
            let snug = 1.0 - (leftover as f64 / next_item_size.max(1) as f64);
            score -= 6.0 * snug;
        }
    }

    // Waste-ratio bands
    let waste_ratio = (post_residual as f64) / (bin_capacity.max(1) as f64);
    if post_residual > 0 && waste_ratio < 0.05 && fitting_bins_count <= 2 {
        score -= 12.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
            if progress > 0.75 && fitting_bins_count >= 1 {
                score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
            }
        }
    } else {
        // Open-bin lookahead: snug next-item fit is heavily rewarded
        if next_item_size > 0 && next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        } else if next_item_size > 0 {
            let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        }
        // Dead-space band penalty for stranded residual beyond next item
        let dead_space = waste_ratio;
        if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // Two-copy capacity bonus
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
        }
        // Stranded space relative to next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
        }
        // Near-exact single chain
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // Small residuals near the mean are good donors
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // Leftover after next item nearly empty
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
            if leftover_ratio < 0.05 {
                score -= 5.0 * (1.0 - leftover_ratio / 0.05);
            }
        }
        // Wide-gap penalty beyond next item
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if over > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // Fleet-tight: keep donor slots near next item size
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // Discourage residuals that neither fit next item nor stay small
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
    }

    // Late-stream — grab near-exact fits aggressively to close bins out
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 8.0 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..100, capacity 100.
    // Class 0: post_residual == 0 (perfect closure) -> reward heavily.
    // Class 1: post_residual in 1..=10 (dead space, nearly nothing fits) -> penalize.
    // Class 2: post_residual in 11..=30 (small gap) -> mild penalty unless next item fits.
    // Class 3: post_residual in 31..=60 (medium, flexible) -> mild reward.
    // Class 4: post_residual in 61..=99 (large, very flexible) -> reward.
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 60 { 3 }
        else { 4 };

    match class {
        0 => score -= 100.0,
        1 => score += 25.0,
        2 => score += 8.0,
        3 => score -= 6.0,
        _ => score -= 12.0,
    }

    // Modulo-style coupling: does next_item_size exactly divide the gap?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // next item closes this bin perfectly
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // harmonic class of the residual after the lookahead
            if next_post == 0 {
                score -= 30.0;
            } else if next_post <= 10 {
                score += 12.0; // would create dead space
            } else if next_post <= 30 {
                score += 3.0;
            } else {
                score -= 5.0;
            }
            // divisibility bonus: gap splits into integer multiples of next item
            let k = post_residual / next_item_size;
            if k >= 2 && post_residual % next_item_size == 0 {
                score -= 10.0 * (k.min(4) as f64 - 1.0);
            }
        } else {
            score += 6.0; // next item cannot reuse this gap at all
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): prefer it only when the best open fit is bad.
    if bin_residual == bin_capacity {
        // Baseline: an empty bin costs ~ (100 - item_size) wasted potential.
        score = 60.0 + (100 - item_size) as f64 * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // fresh bin can host item + lookahead together
        }
        if post_residual >= 40 {
            score -= 5.0;
        }
    }

    // Fraction-of-capacity structure: reward bins whose fill is near a "nice" fraction.
    let fill = bin_capacity - bin_residual;
    let fill_frac = fill as f64 / bin_capacity as f64;
    score -= 10.0 * (fill_frac * std::f64::consts::PI).sin().abs(); // harmonic ripple

    // Progress scaling: early in the stream, be more conservative about tight fits
    // (more future items to place), later commit harder to closure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if class == 0 || class == 1 {
        score *= 1.0 + 0.3 * (1.0 - progress);
    }

    // Mean residual pressure: many open bins with large residuals -> prefer reusing
    // existing space over opening new bins.
    if open_bins_count > 0 && mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

