pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, amplified for large items.
    let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
    score += 1.5 * tightness * (post_residual as f64).powi(2) * 0.05;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let dead = post_residual as f64;
            score += 0.6 * dead * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 8.0; // near-perfect: kills the bin cleanly
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Mild penalty so we prefer reusing open bins with decent fits,
        // but a big discount when existing fits are poor or many bins are open.
        score += 25.0;
        score -= 3.0 * open_bins_count as f64;
        score -= 0.15 * mean_residual;
        // Early in the stream, opening fresh bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items keep new bins useful.
        score -= 0.2 * item_size as f64;
    }

    // Prefer bins below the mean residual (rebalance toward fuller bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Late-stream consolidation: penalize leaving spread-out residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // --- Lookahead: snug fit of next item into post_residual ---
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
        let leftover = post_residual - next_item_size;
        if leftover >= next_item_size {
            score -= 7.5; // room for two copies of next item
        }
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
        // graded penalty on stranded space relative to next item
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        score += 3.0 * frag;
    }

    // Exact match bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }

    // --- Dead-space shaping ---
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    let dead_space = (post_residual as f64) / (bin_capacity.max(1) as f64);
    let waste_ratio = dead_space;

    // Tightness reward
    let tightness = 1.0 - dead_space;
    score -= 25.0 * tightness * tightness;

    // Waste-ratio bands
    if post_residual > 0 && waste_ratio < 0.05 && fitting_bins_count <= 2 {
        score -= 12.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // Mid-band dead space that can't host the next item
    if dead_space > 0.33 && dead_space < 0.57 && next_item_size > 0 && next_item_size > post_residual {
        let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        score += 6.0 + 8.0 * overshoot;
    }

    // Residual straddling the mean without fitting the next item
    if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
        score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
    }

    // Small leftover after next item placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_ratio = (post_residual - next_item_size) as f64 / bin_capacity.max(1) as f64;
        if leftover_ratio < 0.05 {
            score -= 5.0 * (1.0 - leftover_ratio / 0.05);
        }
        let rem_ds = leftover_ratio;
        if rem_ds > 0.02 && rem_ds < 0.12 {
            score -= 4.0 * (1.0 - rem_ds / 0.12);
        }
    }

    // --- Fleet pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }
    score += pressure * 2.0;

    // Keep donor slots alive when fleet is scarce
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = ((post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        if drift < 0.35 {
            score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
        }
    }

    // --- New-bin candidate (empty bin) ---
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64 + pressure;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let gap = next_item_size - post_residual;
                if gap <= 6 {
                    score += 9.0 + 1.5 * (6 - gap) as f64;
                } else if gap <= 12 {
                    score += 3.0 + 0.4 * (12 - gap) as f64;
                }
            }
            // scale new-bin penalty with fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // fresh bin as donor when its residual tracks the mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // late-stream fresh bins are expensive
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
    }

    // --- Late-stream: close bins aggressively ---
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space, quadratically (dead space is super-linearly bad).
    let mut score = post + (post * post) / (2.0 * cap);

    // Perfect-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item can fit exactly into the post residual,
    // this placement is excellent; if next item almost fits, it's risky.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            let over = (nxt - post) / cap;
            score += 6.0 * over * over;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty so the tightest fit wins.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): prefer it only when no open bin offers a good fit,
    // i.e., when post_residual of the empty bin would be large and stream is early.
    if bin_residual == bin_capacity {
        // Empty bin leaves residual = cap - item_size; make it competitive but biased
        // against opening bins late in the stream.
        score += 4.0 + 15.0 * progress + 0.05 * open_bins_count as f64;
        // But if the item is large, a fresh bin wastes little; reduce penalty.
        score -= 6.0 * (item_size as f64 / cap);
    }

    // Stream-progress coupling: late in the stream, tighten standards —
    // penalize any leftover space more aggressively to consolidate.
    score *= 1.0 + 0.5 * progress * (post / cap);

    // Mean-residual context: if this bin's residual is far below the mean,
    // it's already well-used; reward keeping it that way.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 2.0 * (1.0 - (bin_res / mean_residual).min(2.0) / 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (typical item granularity)
    let residue = (post_residual % 10) as f64;
    score += residue * 0.35; // penalize "off-class" dead space

    // Perfect closures: post_residual exactly 0 or a harmonic class value
    if post_residual == 0 {
        score -= 60.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Integer-division thresholds: post_residual in [0,10] is nearly unusable
    let k = post_residual / 10;
    if k == 0 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: can next item exactly fill post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: discourage opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * (1.0 - tightness * 0.9) + 10.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 25.0; // pair potential in fresh bin
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream consolidation: as stream ends, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer high-fill bins (small residual fraction of capacity)
    score += (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // Mild penalty for bin sprawl
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = post_residual as f64 / cap;
    let waste_ratio = dead_space;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead with snugness scaling
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0 + 20.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 220.0 * snug + 0.3 * next_item_size as f64;
            let leftover = post_residual - next_item_size;
            if leftover as f64 <= 0.05 * cap {
                score -= 5.0 * (1.0 - leftover as f64 / (0.05 * cap));
            }
            // leftover near mean residual keeps future options alive
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
        } else {
            let gap_ratio = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 40.0 * gap_ratio.min(1.0);
            // near-miss: overshoot small enough that next item almost fits
            if gap_ratio * next_item_size.max(1) as f64 <= 6.0 {
                score += 9.0 + 1.5 * (6.0 - gap_ratio * next_item_size.max(1) as f64);
            } else if gap_ratio * next_item_size.max(1) as f64 <= 12.0 {
                score += 3.0 + 0.4 * (12.0 - gap_ratio * next_item_size.max(1) as f64);
            }
        }
    }

    // Relative to mean residual: prefer tighter bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

