    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 26.0;
        } else {
            score += 150.0;
        }
    } else if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
        score += 8.0;
    }

    // Two-fit lookahead
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 7.5;
        if dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
