    }

    // Mid-band dead space penalty
    if dead_space > 0.25 && dead_space < 0.65 && next_item_size > post_residual {
        let band = (dead_space - 0.45) / 0.2;
        score += 3.5 * band * band;
    }

    // Coupling: when fleet is tight, keep donor residuals near next item size
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if drift < 0.35 {
            score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
        }
    }

    // Discourage residuals that neither fit next item nor stay small
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
        score += 3.0 + 4.0 * (dead_space - 0.55);
    }

    // New-bin candidate logic
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if post_residual > 0 && post_residual < 10 {
                score += 20.0;
            }
            // scale new-bin penalty with scarcity and fleet tightness
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            // fresh bin as donor when its residual tracks the mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // late-stream fresh bins are expensive
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
        if progress < 0.25 {
            score -= 6.0 * (1.0 - progress / 0.25);
        }
        if progress > 0.75 && fitting_bins_count >= 1 {
            score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        if open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
    } else {
        score -= 20.0 * progress;
        if post_residual > 0 && dead_space < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if (leftover as f64 - mean_residual).abs() / mean_residual.max(1.0) < 0.2 {
                score -= 3.0;
            }
        }
        // small residual slightly above mean stays usable
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item size (1) are pure waste; anything below a usable threshold is
    // heavily penalized non-linearly.
    let min_item = 1.0f64;
    let usable_threshold = 12.0f64;
    if (post_residual as f64) < usable_threshold {
        // dead space: steep quadratic penalty
        score += (usable_threshold - post_residual as f64).powi(2) * 2.5;
    }
    if post_residual == 0 {
        // perfect fit: large reward
        score -= 60.0;
    } else if (post_residual as f64) <= min_item {
        score -= 20.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; mild additive term.
    score += (open_bins_count as f64) * 0.6;

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit in post residual but fits in residual now,
    // slight penalty for wasting the space needed next.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are "fresher";
    // prefer packing into bins whose residual is close to item size
    // (i.e., near-mean residual bins get slight preference to consolidate).
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += residual_gap * 0.15;

    // Early in the stream, be more willing to open bins (less pressure);
    // late in the stream, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    score -= 0.5 * (cap - post_residual as f64) / cap * 10.0;

    // 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 25.0;
        } else if post_residual as i64 - next_item_size as i64 >= 0 {
            // next item fits too: mild reward proportional to how well it fills again
            let second_post = post_residual as f64 - nxt;
            score -= 10.0 * (1.0 - second_post / cap);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.15 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual of open bins: avoid creating
    // fragmented bins when other bins are tighter.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // default: slightly worse than a decent existing fit
        score = cap * 0.6 + 0.2 * post_residual as f64;
        if next_item_size > 0 && (next_item_size as f64 - (cap - item_size as f64)).abs() < 0.5 {
            score -= 30.0; // fresh bin perfectly chains with next item
        }
        if fitting_bins_count <= 1 {
            score -= 40.0; // no alternatives: opening new bin is fine
        }
    }

    // Progression: as stream ends, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;
    if open_bins_count > 8 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + 2.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Lookahead synergy: next item fits exactly into post_residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0 + 3.0 * (fitting_bins_count.min(4) as f64);
    }
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 15.0;
        let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
        score += 3.0 * frag * (1.0 + 0.5 * tightness);
    }

    // Reward residuals that can host the next item AND keep a usable remainder
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover >= next_item_size {
            score -= 7.5;
        } else {
            let snug = 1.0 - (leftover as f64 / next_item_size.max(1) as f64);
            score -= 6.0 * snug;
        }
        // strong snug lookahead: near-exact fill with next item
        let snug2 = 1.0 - (leftover as f64 / post_residual.max(1) as f64);
        score -= 0.35 * next_item_size as f64 * 0.1 + 4.0 * snug2;
    }

    // Waste-ratio bands
    let waste_ratio = (post_residual as f64) / (bin_capacity.max(1) as f64);
    if post_residual > 0 && waste_ratio < 0.05 && fitting_bins_count <= 2 {
        score -= 12.0;
    } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
        score += 6.0;
    }

    // Penalize residual straddling the mean without fitting the next item
    if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
        score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
    }

    // Keep donor slots alive when fleet is tight
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
        let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
        if drift < 0.35 {
            score -= 1.5 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64);
        }
    }

    // New-bin candidate (empty bin)
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        let scarce = fitting_bins_count <= 1;
        if lookahead_fits && scarce {
            score -= 37.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 50.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64 - 0.3 * item_size as f64;
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
                score += (2.5 + 2.0 * tight) * fitting_bins_count.min(6) as f64;
            }
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            if progress > 0.6 {
                score += 6.0 * (progress - 0.6) / 0.4;
            }
        }
    }

    // Late-stream — grab near-exact fits aggressively to close bins out
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    // Late-stream fresh bins extra expensive
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tightness: how well the item fills the bin (1.0 = perfect fit).
    let fill = item_size as f64 / bin_residual as f64;
    let waste_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to fill quality.
    score -= 30.0 * fill * fill;

    // Penalize large dead space nonlinearly (small residuals are hard to reuse).
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // If many bins can fit the item, prefer the tightest one; mild penalty
    // for looser fits spreads choice toward best-fit logic.
    if fitting_bins_count > 1 {
        score += 5.0 * (1.0 - fill);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward leaving that gap; if next item is large, penalize leaving gaps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chain fit: keep this gap for next item
        } else if next_item_size > post_residual {
            score += 0.05 * (next_item_size - post_residual) as f64; // gap useless for next
        } else {
            score -= 2.0; // gap at least reusable
        }
    }

    // Global state: penalize opening new bins when many open bins have
    // plenty of residual space (fragmentation signal).
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_gap = mean_residual / bin_capacity as f64;
        // New bin cost grows with number of open bins and mean residual availability.
        score += 35.0 + 2.0 * open_bins_count as f64 + 60.0 * mean_gap;
        // Late in the stream, opening new bins is more wasteful (less time to fill).
        score += 20.0 * progress;
        // But if the only alternative is a terrible fit (huge waste), allow new bin:
        // computed implicitly: tight fits elsewhere get big discounts above.
        if waste_ratio < 0.2 {
            score -= 50.0; // should not happen for empty bin; safety
        }
    }

    // Mild time-horizon modulation: early on, consolidate aggressively;
    // late, avoid leaving tiny residuals that can never be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (1.0 - progress); // early tiny gaps are worse
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
