pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: raw post-residual, smoothly warped (convex penalty on large dead space)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, large residuals become more costly (less time to fill them)
    let late = progress * progress;
    score += 40.0 * late * norm_pr * (1.0 - norm_pr) * 4.0; // smooth bump penalizing mid-size waste late

    // Reward tight fits: quadratic reward as post_residual -> 0
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: smooth reward if next item could fit into post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).max(0.0) / cap;
        let fits = if pr >= ns { 1.0 } else { 0.0 };
        // smooth compatibility term
        let compat = 1.0 / (1.0 + ((ns - pr) / 20.0).powi(2));
        score -= 25.0 * compat * fits;
        score += 15.0 * (1.0 - fits) * (1.0 - progress);
        score -= 10.0 * gap * gap * fits;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when open bins exist with reasonable fit
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let fit_pressure = 1.0 / (1.0 + (fitting_bins_count as f64).powi(2));
            score += 60.0 * fit_pressure * (1.0 - 0.5 * progress);
            // allow opening when mean residual across open bins is small
            score += (mean_residual / cap) * 20.0;
        } else {
            score -= 10.0;
        }
    }

    // Mild open-bins consolidation pressure
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

