pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic waste penalty.
    let waste = (post_residual as f64) / (bin_capacity as f64);
    score += waste * waste * 60.0;

    // Harmonic class: exact-fill bonus via integer division thresholds.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // post_residual too small for next item: penalize dead space
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with lower residual among equally tight options.
    score += (bin_residual as f64) * 0.05;

    // Modulo-class logic: small residual classes (residual % 20) that are hard
    // to fill later get penalized unless post_residual is tiny.
    let class = post_residual % 20;
    if class != 0 && post_residual > 10 {
        score += class as f64 * 0.4;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // bins fit poorly (post_residual large) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin: base penalty, reduced when item is large.
        let fresh_cost = 80.0 - (item_size as f64) * 0.4;
        // If many bins fit and this item fits well elsewhere, opening is bad.
        if fitting_bins_count > 1 && post_residual <= 20 {
            score += fresh_cost + 40.0;
        } else {
            score += fresh_cost;
        }
        // Early in stream, slightly discourage hoarding bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Slight preference to spread load when many bins are open.
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

