            // Leftover too small for lookahead: dead space penalty scaled.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and encourage filling existing ones tighter.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // currently open bins; make it costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        score += 15.0 + avg_waste * 0.5 + pressure * 4.0;
        // Late in the stream, closing out is cheaper; soften new-bin cost.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
        // If next item fits comfortably in a fresh bin anyway, slight relief.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let dead_space = (post_residual as f64) / cap;
    let waste_ratio = dead_space;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: fit now AND leave room for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
    } else if next_item_size > 0 {
        let gap_ratio = next_item_size as f64 / (post_residual.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 62.0;
    } else if post_residual < 10 {
        score -= 26.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Tightness reward.
    let tightness = 1.0 - waste_ratio;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin pressure.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bins pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
