                score += 8.0 * (progress - 0.8) / 0.2;
            }
            if next_item_size > 0 && fitting_bins_count >= 2 {
                let best_band = (mean_residual - next_item_size as f64).abs();
                if best_band < 4.0 {
                    score += 5.0;
                }
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                let chain = post_residual - next_item_size;
                if chain as f64 >= mean_residual * 0.5 {
                    score += 7.0;
                }
            }
            // gen188: fresh bin competes only if the fleet cannot chain two items ahead.
            if next_item_size > 0 && post_residual >= 2 * next_item_size {
                score += 9.0;
            }
            // gen188: early stream — fresh bins are cheap insurance against fragmentation.
            if progress < 0.25 && next_item_size > 0 && item_size as f64 > mean_residual {
                score -= 4.0;
            }
            // gen188: when the fleet is fragmented (many open bins), a fresh bin is wasteful.
            if open_bins_count > 6 {
                score += 3.0 + 0.5 * (open_bins_count.min(14) as f64);
            }
            // gen188: mid/late stream, a fresh bin must be strongly discouraged if the
            // item already fits somewhere with a small leftover.
            if progress > 0.3 && fitting_bins_count >= 1 {
                score += 5.0 * (1.0 - progress).min(0.7);
            }
            // gen188: combine scarcity + snugness — a fresh bin that would land the next
            // item exactly (post == next) is a good donor only when the fleet is fragmented.
            if next_item_size > 0 && post_residual == next_item_size {
                if open_bins_count > 4 { score -= 5.0; } else { score += 4.0; }
