        // the item AND the next item exactly (post == 2*next) are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen188 mutation: two-step lookahead chain — reward bins whose post-fit leftover
        // after placing the next item is an exact multiple of the next item (predicts a
        // perfect closing sequence), scaled by remaining stream length.
        if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 {
            score -= 2.0 + 3.0 * (1.0 - progress);
        }
        // gen188 mutation: dead-tail recycling — when the fleet mean residual is small
        // (fleet is nearly closed), a leftover just below mean_residual is nearly dead;
        // penalize it to push items into tighter fits instead.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
