            score -= 25.0;
            score -= 0.5 * chain_residual as f64;
            if chain_residual == 0 {
                score -= 20.0; // exact two-item fill
            }
        } else if next_item_size <= bin_residual {
            // Next item fits now but not after this placement: mild penalty
            score += 10.0;
        } else {
            // Next item won't fit this bin either way
            score += 5.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: avoid opening a new bin unnecessarily
