        // gen162: compaction coupling — when several bins fit, prefer the one whose
        // post-fit residual is closest to a multiple of the next item size.
        if next_item_size > 0 && fitting_bins_count >= 2 && post_residual >= next_item_size {
            let copies = (post_residual / next_item_size) as f64;
            let frac = copies - copies.floor();
            let frac = frac.min(1.0 - frac);
