        // cannot even host the next item twice are strongly penalized when the fleet
        // has alternatives, pushing compaction toward tight bins.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size && dead_space > 0.5 && fitting_bins_count >= 2 {
            score += 3.0 + 3.0 * (dead_space - 0.5);
        }
        // gen162: harvest coupling — when nearing the end, residuals that can absorb
        // the item AND the next item exactly (post == 2*next) are premium targets.
        if next_item_size > 0 && post_residual == 2 * next_item_size {
            score -= 6.0 + 2.0 * (1.0 - progress);
        }
        // gen189: perfect-harvest lookahead — reward bins where the post-fit residual
        // exactly equals the mean residual (a predictable future reuse slot).
        if post_residual > 0 && mean_residual > 1.0 && (post_residual as f64 - mean_residual).abs() < 1.0 {
            score -= 5.0 * (1.0 - progress);
        }
        // gen189: two-step chain — if post_residual fits the next item twice exactly,
        // this is a premium chain slot; scale with how early it appears in the stream.
        if next_item_size > 0 && post_residual > 0 && post_residual % next_item_size.max(1) == 0 && post_residual / next_item_size.max(1) >= 2 {
            score -= 3.0 * (1.0 - progress);
        }
        // gen189: fragmentation guard — penalize residuals in the awkward 25..40 band
        // that cannot host the next item, when the fleet has better options.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > 24 && post_residual < 40 && fitting_bins_count >= 2 {
            score += 3.5;
        }
    }

    // Late-stream pressure: endgame favors using up open bins.
    if progress > 0.85 && post_residual > 0 && post_residual < item_size {
        score -= 8.0 * (progress - 0.85) / 0.15;
    }
    if progress > 0.75 && bin_residual == bin_capacity && fitting_bins_count >= 1 {
        score += 4.0 + 6.0 * (progress - 0.75) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that are "harmonic"
    // with common item sizes (perfect fits for 10/20/25/50 divisors).
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50, 100].iter() {
            if pr % d == 0 {
                bonus += 4.0 * (pr as f64 / cap);
            }
        }
        score -= bonus;
    } else {
        // Perfect closure: excellent
        score -= 15.0;
    }

    // Penalize dead space that no plausible item can fill:
    // residual in (0,10) is unusable dead space.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Modulo threshold coupling with next item: if next item exactly fits
    // the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr && (pr - next_item_size) < 10 {
            score -= 8.0; // near-perfect chaining
        } else if next_item_size > pr {
            score += 6.0; // next item won't fit here anyway
        }
        // Harmonic divisibility: next item divides residual cleanly
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 5.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post < 10.0 && post > 0.0 {
            score += 15.0; // but avoid creating dead space
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline: waste equals capacity minus item
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if item_size >= 60 {
            score += 10.0; // big items: prefer existing bins with room
        }
    }

    // Slight preference to fill older/more-filled bins: compare to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (post_residual as f64 / cap);

    score
}

