    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or all fits are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let best_possible_waste = (bin_residual - item_size) as f64;
        // Base cost of a fresh bin, discounted for large items.
        score += 55.0 * (1.0 - 0.5 * fill_ratio);
        // If the new bin leaves little waste, it is more acceptable.
        score -= 10.0 * (1.0 - best_possible_waste / bin_capacity as f64);
        // Early in the stream, new bins are cheap (plenty of future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // Many open bins with high mean residual: discourage yet another bin.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Global pressure: when many open bins exist, prefer consolidating into
    // bins with below-average residual (to drain laggards).
    if bin_residual != bin_capacity && open_bins_count > 1 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * diff;
    }

    // Late in the stream, waste matters more; tighten selection.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.95;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual;
    let next = next_item_size as f64;

    // Base: quadratic waste coupling (dead space penalized super-linearly)
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth stream-progress coupling: early on tolerate larger residuals,
    // later push toward tight packing via stronger penalty growth.
    let tight = progress * progress;
    score += 14.0 * tight * (pr / cap);

    // Interaction of post_residual with mean residual across open bins:
    // favor bins whose residual is below-average (they are "special" fits).
    score += 4.0 * (pr - mean_r) / cap;

    // Lookahead coupling: smooth reward if next item can use the post residual.
    if next > 0.0 {
        let gap = pr - next;
        let usable = if gap >= 0.0 { gap } else { -gap * 1.5 };
        score -= 6.0 * (1.0 - usable / cap) * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * (1.0 - pr / cap);
    }

    // Penalize the new-bin candidate smoothly: empty bin has pr = cap - item,
    // which grows with small items; add friction scaled by open bins count.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 12.0 + 0.35 * open_bins_count as f64 + 10.0 * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fill: dominant reward (gen191: sharpened further)
    if post_residual == 0 {
        score -= 1600.0;
    } else if post_residual < 10 {
        score -= 32.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Two-step lookahead with snugness scaling (gen191: combined snug+scarcity coupling)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 42.0 + 0.35 * next_item_size as f64 + 17.0 * snug;
            if post_residual >= 2 * next_item_size {
                score -= 15.0;
            } else {
                let leftover_ratio = (post_residual - next_item_size) as f64 / cap;
                if leftover_ratio < 0.05 {
                    score -= 5.0 * (1.0 - leftover_ratio / 0.05);
                }
            }
            // gen191: scarcity-amplified snugness — when few bins fit, snug fits matter more
            if fitting_bins_count <= 2 {
                score -= 6.0 * snug;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            let gap_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score += 10.0 + 15.0 * (1.0 - gap_ratio).clamp(0.0, 1.0);
            if post_residual < 8 {
                score += 40.0;
            }
            // gen191: penalize near-miss gaps that waste most of the residue
            if gap <= 10.0 && post_residual as f64 > mean_residual {
                score += 4.0;
            }
        }
    }

    // Prefer bins tighter than the mean (non-linear pull)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev + 0.15 * dev.abs() * dev.signum();

    // Only fitting bin: take it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 350.0;
    } else if fitting_bins_count == 2 {
        score -= 60.0;
    }

    // Dead-space guard: avoid leaving unusably small residues
    if post_residual > 0 && post_residual < 10 {
        score += 180.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let waste_ratio = post_residual as f64 / cap;
    let dead_space = waste_ratio;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
        if lookahead_fits && fitting_bins_count <= 1 {
            score -= 100.0;
        } else if lookahead_fits {
            score -= 19.0;
        } else {
            let slack = (mean_residual - post_residual as f64).max(0.0);
            score += 57.0 + 0.25 * slack + 2.0 * open_bins_count.min(10) as f64;
            if next_item_size > 0 && next_item_size as f64 <= mean_residual {
                score += 13.0;
            }
            if fitting_bins_count >= 3 {
                score += 8.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
                score -= 6.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 6 {
                score += 9.0 + 1.5 * (6 - (next_item_size - post_residual)) as f64;
            }
            if next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual <= 12 && next_item_size - post_residual > 6 {
                score += 3.0 + 0.4 * (12 - (next_item_size - post_residual)) as f64;
            }
            // scale new-bin penalty with scarcity AND tightness of the fleet (gen191: sharper)
            if next_item_size > 0 && next_item_size > post_residual {
                let tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
                score += (3.0 + 2.5 * tight) * fitting_bins_count.min(6) as f64;
            }
            // fresh bin as donor when its residual tracks the mean
            if next_item_size > 0 && (post_residual as f64 - mean_residual).abs() < 2.0 {
                score -= 6.0;
            }
            // early stream: fresh bins are cheap
            if progress < 0.25 {
                score -= 6.0 * (1.0 - progress / 0.25);
            }
            // late stream: prefer existing bins strongly (gen191: earlier onset, stronger)
            if progress > 0.5 {
                score += 9.0 * (progress - 0.5) / 0.5;
            }
        }
        if progress < 0.25 && open_bins_count > 4 && item_size as f64 <= mean_residual {
            score += 10.0;
        }
        if progress > 0.8 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
        // gen191: late-stream fresh bins are expensive when any open bin could serve
        if progress > 0.7 && fitting_bins_count >= 1 {
            score += 5.0 + 7.0 * (progress - 0.7) / 0.3;
        }
    } else {
        score -= 25.0 * progress;
        if waste_ratio < 0.08 {
            score -= 13.0;
        } else if waste_ratio > 0.6 && item_size as f64 > mean_residual {
            score += 6.0;
        }
        // reward residues that can hold next item twice
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 7.5;
            if next_item_size as f64 <= mean_residual {
                score -= 2.0;
            }
        }
        // penalize stranding a residue smaller than half the next item
        if post_residual > 0 && next_item_size > post_residual {
            let stranded = post_residual as f64 / (next_item_size.max(1) as f64);
            if stranded < 0.5 {
                score += 5.0 * (1.0 - stranded);
            }
            let unusable = waste_ratio - (next_item_size as f64 / cap);
            if unusable > 0.0 {
                score += 2.0 + 6.0 * unusable;
            }
        }
        // near-exact next-item fit
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < 2 * next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64);
        }
        // exact next-item match: strong pull scaled by scarcity
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 3.0 * (fitting_bins_count.min(4) as f64);
        }
        // mid-band dead-space quadratic penalty
        if waste_ratio > 0.25 && waste_ratio < 0.65 {
            let band = (waste_ratio - 0.45) / 0.2;
            score += 3.5 * band * band;
        }
        // residue near mean residual: future flexibility
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let closeness = 1.0 - ((post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0));
            if closeness > 0.8 {
                score -= 2.0 + 4.0 * (closeness - 0.8) * 5.0;
            }
        }
        // endgame squeeze
        if progress > 0.85 && post_residual > 0 && post_residual < item_size {
            score -= 8.0 * (progress - 0.85) / 0.15;
        }
        // mid-stream: prefer small residues
        if progress > 0.5 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.5 {
            score -= 4.0;
        }
        // very tight fit with few alternatives: extra pull
        if post_residual > 0 && waste_ratio < 0.04 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // small stranded residue guard
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score += 4.0;
        }
        // two-fit check
        if next_item_size > 0 && post_residual >= next_item_size {
            let two_fit = post_residual >= 2 * next_item_size || (post_residual - next_item_size) as f64 <= mean_residual;
            if two_fit && waste_ratio < 0.5 {
                score -= 2.5;
            }
        }
        // leftover after placing next item lands in a tight, reusable band
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem_ds = (post_residual - next_item_size) as f64 / cap;
            if rem_ds > 0.02 && rem_ds < 0.15 {
                score -= 4.0 * (1.0 - rem_ds / 0.15);
            }
        }
        // dead-space overshoot penalty when next item cannot use residue
        if waste_ratio > 0.33 && waste_ratio < 0.57 && next_item_size > 0 && next_item_size > post_residual {
            let overshoot = (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
            score += 6.0 + 8.0 * overshoot;
        }
        // large dead space that next item cannot fill
        if waste_ratio > 0.5 && next_item_size > 0 && next_item_size as f64 > waste_ratio * cap {
            score += 3.0 * (waste_ratio - 0.5) * 10.0;
        }
        // fragment penalty scaled by dead space
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            let frag = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 3.0 * frag * (1.0 + 0.5 * waste_ratio);
        }
        // reward very small residues relative to mean (compaction)
        if post_residual > 0 && post_residual as f64 <= mean_residual.max(1.0) * 0.35 {
            score -= 3.0 + 2.0 * (1.0 - post_residual as f64 / (mean_residual.max(1.0) * 0.35));
        }
        // refined dead-space valley: reward residual bands matching typical next-item multiples
        if next_item_size > 0 && post_residual > 0 {
            let ratio = post_residual as f64 / next_item_size.max(1) as f64;
            if ratio >= 1.9 && ratio < 2.6 && waste_ratio > 0.15 {
                score -= 3.0 + 2.0 * (2.6 - ratio);
            } else if ratio >= 2.6 && ratio < 3.4 && waste_ratio > 0.2 {
                score -= 1.5 + 1.5 * (3.4 - ratio);
            }
        }
        // penalize mid-band dead space more sharply when few bins fit the item
        if waste_ratio > 0.3 && waste_ratio < 0.75 && fitting_bins_count <= 2 && next_item_size > post_residual {
            score += 4.0;
        }
        // reward residuals that leave room for a second copy of the next item
        if next_item_size > 0 && post_residual >= 2 * next_item_size && dead_space < 0.45 && waste_ratio > 0.05 {
            score -= 1.5 + 2.0 * (0.45 - dead_space);
        }
        // penalize residual straddling the mean without fitting the next item
        if next_item_size > 0 && post_residual > 0 && post_residual as f64 > mean_residual * 1.15 && post_residual < next_item_size {
            score += 2.5 + 0.05 * (post_residual as f64 - mean_residual);
        }
        // avoid overshooting into a wide gap beyond the next item
        if next_item_size > 0 && post_residual > next_item_size {
            let over = (post_residual - next_item_size) as f64;
            if over / next_item_size.max(1) as f64 > 1.5 && dead_space > 0.4 {
                score += 2.0 + 3.0 * (dead_space - 0.4);
            }
        }
        // when the fleet is tight, strongly prefer bins whose post_residual stays near the next item's size
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 3 {
            let drift = (post_residual - next_item_size) as f64 / next_item_size.max(1) as f64;
            if drift < 0.35 {
                score -= 3.0 * (1.0 - drift / 0.35) * (4.0 - fitting_bins_count.min(3) as f64) * 0.5;
            }
        }
        // discourage creating residuals that neither fit next item nor stay small
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && dead_space > 0.55 {
            score += 3.0 + 4.0 * (dead_space - 0.55);
        }
        // exact next-item match with very low waste gets extra pull
        if next_item_size > 0 && post_residual == next_item_size && waste_ratio < 0.1 {
            score -= 2.0 + 2.0 * (1.0 - waste_ratio / 0.1);
        }
        // compaction — when fleet is large, favor bins whose leftover stays below typical item size
        if open_bins_count > 6 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size / 2 {
            score += 3.0;
        }
        // gen191: combined coupling — reward bins where post_residual after next item still fits
        // a plausible follow-up item near the mean residual (chained lookahead)
        if next_item_size > 0 && post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem > 0 && (rem as f64 - mean_residual).abs() <= 3.0 {
                score -= 3.5;
            }
        }
        // gen191: endgame compaction — late stream, aggressively prefer tightest fits
        if progress > 0.7 && post_residual > 0 && post_residual as f64 <= mean_residual * 0.6 {
            score -= 2.0 + 3.0 * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space?
    // Residuals divisible by small common item sizes are more likely reusable.
    let pr = post_residual;
    let mut usability_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { usability_bonus += 6.0; }
        if pr % 20 == 0 { usability_bonus += 4.0; }
        if pr % 25 == 0 { usability_bonus += 3.0; }
        if pr % 5 == 0 { usability_bonus += 2.0; }
        // Integer-division thresholds: classify leftover into harmonic bands
        let band = pr / 10; // 0..10
        usability_bonus += match band {
            0 => 8.0,        // near-perfect fill
            1 => 5.0,
            2 => 3.0,
            3 | 4 => 1.0,    // awkward middle zone
            5 | 6 => 2.0,    // half-bin: still flexible
            7 | 8 => 0.5,
            _ => 0.0,
        } as f64;
    } else {
        usability_bonus += 12.0; // exact fill is ideal
    }
    score -= usability_bonus;

    // Fractional capacity coupling: item as fraction of capacity
    let item_frac = item_size as f64 / cap;
    if item_frac > 0.5 {
        score -= 4.0; // big items should go in sooner
    }

    // Lookahead: does the next item fit the post-residual? Strong reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
        // Harmonic match: next item leaves another clean residual
        let nr = post_residual - next_item_size;
        if nr % 10 == 0 { score -= 3.0; }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover: penalize dead space proportionally
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean-residual coupling: placing in a bin below mean residual tightens spread
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // no good fit exists among open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.6 + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin is good for a big follow-up item
        }
        if fitting_bins_count == 0 {
            score -= cap; // forced: no alternative
        }
    } else if fitting_bins_count <= 1 {
        // penalize opening a new bin when a fit exists
        score -= 5.0;
    }

    // Mild penalty for proliferating bins mid-stream
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}
